-- Content safety and consistency fixes (owner request 2026-11-12).
-- A) pregnancy texts / day notifications: the baby's current size and fruit comparison now match the hero
--    (Hadlock 1991 / CRL / crown-heel, one fruit per week; migration 20261112140000).
-- B) medical safety: folic acid mg->mcg, iron 15-20 g -> ~27 mg, vitamin D 4000 IU -> 400-600 IU, fever under
--    3 months -> see a doctor, NSAIDs in pregnancy (not after 20 weeks), tuna/king mackerel, postpartum blood loss,
--    fluoride from the first tooth, toddler calcium 700 mg, walnuts as allergen and choking risk.
-- Azerbaijani text and every translation where the same statement exists (minimal edits). Each update applies only
-- if the cells are unchanged since review (md5); the final check rolls everything back otherwise.
-- Tables already CDC enrolled and writer guarded: baby_daily_info, blog_posts, mommy_daily_messages, pregnancy_daily_content, pregnancy_day_notifications, trimester_tips. Applied with run-sql.py.
BEGIN;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '120s';
DO $$ BEGIN
  IF (SELECT count(*) FROM _anacan_gcp_migration.guarded_relations WHERE schema_name = 'public' AND table_name IN ('baby_daily_info', 'blog_posts', 'mommy_daily_messages', 'pregnancy_daily_content', 'pregnancy_day_notifications', 'trimester_tips')) <> 6 THEN
    RAISE EXCEPTION 'CONTENT_FIX_GUARD_MISSING'; END IF;
END $$;

UPDATE public.pregnancy_daily_content SET baby_message = 'Anacan, mən hələ çox kiçiyəm, bir xaşxaş dənəsi boydayam, amma içimdə böyük planlar var. İndi mən yastı formadayam, amma tezliklə qıvrılıb o şirin "C" formasını alacam. Sənin qarnın mənim evim, sənin qəlbin mənim sığınacağımdır. Bizim 9 aylıq səyahətimiz bu gündən etibarən rəsmi şəkildə başlayır!', baby_message_en = 'Mommy, I''m still so tiny, about the size of a poppy seed, but I have big plans inside me! Right now, I''m in a flat shape, but soon I''ll curl up into that sweet ''C'' form. Your belly is my home, and your heart is my refuge. Our 9-month journey officially begins today!', baby_message_ru = 'Мамочка, я пока совсем крошечный, размером с маковое зёрнышко, но у меня большие планы. Сейчас я плоский, но скоро свернусь и приму ту самую милую форму буквы «C». Твой живот — мой дом, а твоё сердце — моё убежище. С сегодняшнего дня наше 9-месячное путешествие начинается официально!', baby_message_tr = 'Anneciğim, ben henüz çok küçüğüm, bir haşhaş tanesi kadarıyım ama içimde büyük planlar var. Şimdi yassı bir biçimdeyim ama yakında kıvrılıp o sevimli "C" şeklini alacağım. Senin karnın benim evim, senin kalbin benim sığınağım. 9 aylık yolculuğumuz bugün itibarıyla resmen başlıyor!', baby_message_kk = 'Анашым, мен әлі өте кішкентаймын, көкнәр дәніндей ғанамын, бірақ менің үлкен жоспарларым бар. Қазір пішінім жалпақ, алайда көп ұзамай иіліп, сүйкімді "C" пішініне енемін. Сенің құрсағың — менің үйім, ал жүрегің — менің панам. Біздің 9 айлық сапарымыз бүгіннен бастап ресми түрде басталады!', baby_message_de = 'Mami, ich bin noch winzig klein, nur so groß wie ein Mohnkorn, aber ich habe große Pläne. Im Moment bin ich noch flach, doch schon bald werde ich mich krümmen und diese süße „C“-Form annehmen. Dein Bauch ist mein Zuhause und dein Herz ist mein Zufluchtsort. Unsere 9-monatige Reise beginnt ab heute ganz offiziell!', baby_message_ar = 'ماما، ما زلت صغيرًا جدًا، بحجم بذرة خشخاش، لكن لدي خطط كبيرة بداخلي. أنا الآن مسطح الشكل، لكنني سأنحني قريبًا لأتخذ ذلك الشكل اللطيف الشبيه بحرف "C". بطنكِ هو بيتي، وقلبكِ هو ملجئي. رحلتنا التي ستستمر 9 أشهر تبدأ رسميًا من اليوم!', baby_message_uz = 'Onajon, men hali juda kichkinaman, ko‘knori donasidekman, ammo katta rejalarim bor. Hozir men yassi shakldaman, lekin tez orada bukilib, o‘sha yoqimli "C" shaklini olaman. Sizning qorningiz — mening uyim, qalbingiz esa mening boshpanam. Bizning 9 oylik sayohatimiz bugundan rasman boshlanadi!', baby_message_ka = 'დედიკო, ჯერ ძალიან პატარა ვარ, ყაყაჩოს მარცვლის ზომის, მაგრამ დიდი გეგმები მაქვს. ახლა ბრტყელი ფორმა მაქვს, თუმცა მალე მოვიკუნტები და იმ საყვარელ "C" ფორმას მივიღებ. შენი მუცელი ჩემი სახლია, შენი გული კი — ჩემი თავშესაფარი. ჩვენი 9-თვიანი მოგზაურობა დღეიდან ოფიციალურად იწყება!', baby_message_zh = '妈妈，我还是那么小，只有一粒罂粟籽那么大，但我心里有着大大的计划！现在我的身体还是扁平的，不过很快就会蜷成可爱的“C”形。你的肚子是我的家，你的心是我的避风港。我们长达9个月的旅程今天正式开始啦！', baby_message_id = 'Mama, aku masih sangat kecil, kira-kira sebesar biji poppy, tetapi aku punya rencana besar dalam diriku! Saat ini bentukku masih pipih, tetapi sebentar lagi aku akan melengkung membentuk huruf ''C'' yang manis. Perut Anda adalah rumahku, dan hati Anda adalah tempat berlindungku. Perjalanan kita selama 9 bulan resmi dimulai hari ini!', baby_message_fr = 'Maman, je suis encore minuscule, à peu près de la taille d''une graine de pavot, mais j''ai déjà de grands projets ! Pour l''instant, je suis encore tout plat, mais bientôt, je me recroquevillerai pour prendre cette adorable forme en « C ». Votre ventre est ma maison et votre cœur, mon refuge. Notre aventure de 9 mois commence officiellement aujourd''hui !', baby_message_es = 'Mamá, todavía soy diminuto, más o menos del tamaño de una semilla de amapola, ¡pero tengo grandes planes dentro de mí! Ahora mismo tengo una forma plana, pero pronto me curvaré hasta adoptar esa tierna forma de «C». Tu vientre es mi hogar y tu corazón, mi refugio. ¡Nuestro viaje de 9 meses comienza oficialmente hoy!', baby_message_pt = 'Mamã, ainda sou tão pequenino, mais ou menos do tamanho de uma semente de papoila, mas tenho grandes planos dentro de mim! Neste momento, tenho uma forma achatada, mas em breve vou enrolar-me e assumir aquela adorável forma de «C». A tua barriga é a minha casa e o teu coração é o meu refúgio. A nossa viagem de 9 meses começa oficialmente hoje!', baby_message_vi = 'Mẹ ơi, con vẫn còn bé xíu, chỉ cỡ một hạt anh túc, nhưng bên trong con đang ấp ủ những kế hoạch lớn! Hiện giờ cơ thể con vẫn còn dẹt, nhưng chẳng bao lâu nữa con sẽ cuộn mình thành hình chữ “C” đáng yêu. Bụng mẹ là mái nhà của con, còn trái tim mẹ là nơi con nương náu. Hành trình 9 tháng của chúng ta chính thức bắt đầu từ hôm nay!', baby_message_hi = 'माँ, मैं अभी भी बहुत नन्हा/नन्ही हूँ, लगभग खसखस के दाने जितना/जितनी, लेकिन मेरे भीतर बड़े-बड़े इरादे हैं! अभी मेरा आकार चपटा है, लेकिन जल्द ही मैं मुड़कर उस प्यारे ''C'' आकार में आ जाऊँगा/जाऊँगी। आपका पेट मेरा घर है और आपका दिल मेरी पनाह। हमारी 9-महीने की यात्रा आज आधिकारिक रूप से शुरू हो रही है!', baby_message_ja = 'ママ、私はまだケシ粒ほどの小ささだけれど、体の中では大きな計画が進んでいます！ 今は平らな形ですが、もうすぐ丸まって、かわいい「C」の形になります。ママのおなかは私の家、ママの心は私の安らげる場所です。私たちの9か月の旅が、今日から正式に始まります！', baby_message_ko = '엄마, 저는 아직 양귀비씨 한 알만큼 아주 작지만 제 안에는 큰 계획이 있어요! 지금은 납작한 모양이지만 곧 사랑스러운 ‘C’자 모양으로 몸을 구부릴 거예요. 엄마의 배는 제 집이고, 엄마의 심장은 제 안식처예요. 우리의 9개월 여정이 오늘 공식적으로 시작돼요!', baby_message_pl = 'Mamo, wciąż jestem maleństwem mniej więcej wielkości ziarenka maku, ale mam wielkie plany! Moje ciałko jest teraz płaskie, lecz wkrótce zwinie się w uroczą literę „C”. Twój brzuch jest moim domem, a Twoje serce — moim schronieniem. Nasza 9-miesięczna podróż oficjalnie zaczyna się właśnie dziś!', baby_message_nl = 'Mama, ik ben nog piepklein, ongeveer zo groot als een maanzaadje, maar ik heb grootse plannen! Nu ben ik nog plat, maar binnenkort krul ik me op in die lieve C-vorm. Jouw buik is mijn thuis en jouw hart mijn veilige haven. Vandaag begint onze reis van 9 maanden officieel!', baby_message_sv = 'Mamma, jag är fortfarande pytteliten, ungefär lika stor som ett vallmofrö, men jag har stora planer! Just nu är jag platt, men snart böjer jag mig till den där fina C-formen. Din mage är mitt hem och ditt hjärta är min trygga plats. Vår 9 månader långa resa börjar officiellt i dag!' WHERE id = 'd1b2e180-b513-41eb-8922-8f2b0c7d3ee8' AND md5(coalesce(baby_message,'')) = '1db43da07b70fd5771def6e88f31bb20' AND md5(coalesce(baby_message_en,'')) = 'bd223873bb46abe8492ede1d4b4b656e' AND md5(coalesce(baby_message_ru,'')) = 'bd6797fb69d7d8352f6f58aa2e241802' AND md5(coalesce(baby_message_tr,'')) = 'd73daa185dae9ce3b9d43d94f5036f02' AND md5(coalesce(baby_message_kk,'')) = '81107b163cb29bb7258d2d501584f009' AND md5(coalesce(baby_message_de,'')) = '613f534740dc22f4bd4262d9322e526f' AND md5(coalesce(baby_message_ar,'')) = '906521b11ea23ea08a38b76d8a4858b9' AND md5(coalesce(baby_message_uz,'')) = '3fa8020efe6806075cdd95f5c0d6795c' AND md5(coalesce(baby_message_ka,'')) = 'fbdd3014f4961ae582506bd237b6298e' AND md5(coalesce(baby_message_zh,'')) = 'b4c09f7d55c89b754dc110fdf36c6c97' AND md5(coalesce(baby_message_id,'')) = '68b5d50f093aad8052e7033dc11f7b04' AND md5(coalesce(baby_message_fr,'')) = 'e02ee671bff164422f54972ca4a726de' AND md5(coalesce(baby_message_es,'')) = '8d678ac8079df3fab6e0e05e3caea12e' AND md5(coalesce(baby_message_pt,'')) = 'ebb80ad190282b800e6f8ceddccd7f5d' AND md5(coalesce(baby_message_vi,'')) = 'a3cded4dc6c6b3a0f9dc6264cefccfeb' AND md5(coalesce(baby_message_hi,'')) = '81e8fba985274c82fd89ee48803bd9c7' AND md5(coalesce(baby_message_ja,'')) = 'c32c881bb9f303e36a424cdf92136ab0' AND md5(coalesce(baby_message_ko,'')) = '7f3aa8d4ea4b489150b202a41b7c6843' AND md5(coalesce(baby_message_pl,'')) = '61d69d0148d6f0e4d695fa8cbfe3a787' AND md5(coalesce(baby_message_nl,'')) = '279ee8968e4ece59a68ddd57b123b8fa' AND md5(coalesce(baby_message_sv,'')) = '155f13b7079d37e4ae7cce58e0615b15';
UPDATE public.pregnancy_day_notifications SET title = 'Xaşxaş dənəsi boyda! 🌱', title_en = 'Size of a poppy seed! 🌱', title_ru = 'Размером с маковое зёрнышко! 🌱', title_tr = 'Bir haşhaş tanesi kadar! 🌱', title_kk = 'Көкнәр дәніндей! 🌱', title_de = 'So groß wie ein Mohnkorn! 🌱', title_ar = 'بحجم حبة خشخاش! 🌱', title_uz = 'Ko‘knori donasidek! 🌱', title_ka = 'ყაყაჩოს მარცვლის ზომისაა! 🌱' WHERE id = 'df6c4f91-28b1-4f7a-8ab6-64fb294a5ab9' AND md5(coalesce(title,'')) = '67d95b6c5e268751fe923272711b3c26' AND md5(coalesce(title_en,'')) = 'a3f121a13af664440386c048eadb629f' AND md5(coalesce(title_ru,'')) = '525fecd3d680ac782933d2b64f3eb387' AND md5(coalesce(title_tr,'')) = '0f43203ad9030d6ce80d46af52dbd231' AND md5(coalesce(title_kk,'')) = 'ed3ed0c015121f18e7238d974526b36a' AND md5(coalesce(title_de,'')) = 'd450227fa830250363b4b48011fa36f8' AND md5(coalesce(title_ar,'')) = 'db9f4d5ee1c04ebb0e08295e01387206' AND md5(coalesce(title_uz,'')) = '264c39f918e6cd190c623f502c076ae3' AND md5(coalesce(title_ka,'')) = 'c03054ccdb406415d72bd1e06a84c0f3';
UPDATE public.pregnancy_daily_content SET baby_development = 'Hamiləliyinizin bu mərhələsində körpəniz bir küncüt dənəsi böyüklüyündədir. Körpənizin bədənini formalaşdıracaq üç əsas rüşeym qatı mövcuddur. Bu qatlar; ən xaricdə ektoderm, ortada mezoderm və ən daxildə endoderm təbəqəsidir. Bu təbəqələr hamiləliyinizin növbəti həftələrində ardıcıllıqla toxumalara və orqanlara çevrilir. Ektoderm təbəqəsi körpənizin beyin və sinir sistemi ilə onurğasını formalaşdırmaq üçün fərqlənməyə başlamışdır. Bu qat, sözügedən strukturlardan başqa, həmçinin dəri, saç, dırnaq, tər vəziləri və diş minasının yaranmasını da təmin edir. Mezoderm təbəqəsi isə körpənizin ürək və qan dövranı sistemini şəkilləndirəcək ixtisaslaşmış hüceyrələrdən ibarətdir. Bu hüceyrələr körpənizin ürəyinin yerləşəcəyi nahiyəyə köç edərək orada toplanmağa başlayırlar. Toplanan hüceyrələr sürətli mitoz bölünmə mərhələləri keçərək özlərini çoxaldır və toxumaları yaradırlar. Yaranan toxumalar körpənizin ürəyinin təməlini qoyaraq qeyri-müntəzəm şəkildə döyünməyə başlayırlar.', baby_development_en = 'At this stage of your pregnancy, your baby is about the size of a sesame seed. There are three primary embryonic layers that will form your baby''s body: the outermost ectoderm, the middle mesoderm, and the innermost endoderm. These layers will sequentially transform into tissues and organs in the coming weeks of your pregnancy. The ectoderm layer has begun to differentiate to form your baby''s brain, nervous system, and spinal cord. This layer also gives rise to the skin, hair, nails, sweat glands, and tooth enamel. The mesoderm layer consists of specialized cells that will shape your baby''s heart and circulatory system. These cells migrate to the area where your baby''s heart will be located and begin to accumulate there. The accumulated cells undergo rapid mitotic divisions, multiplying themselves and creating tissues. The resulting tissues lay the foundation for your baby''s heart, which then begins to beat irregularly.', baby_development_ru = 'На этом этапе беременности ваш малыш размером с кунжутное семечко. Существуют три основных зародышевых листка, из которых сформируется тело малыша: наружный — эктодерма, средний — мезодерма и внутренний — энтодерма. В последующие недели беременности эти слои будут последовательно превращаться в ткани и органы. Эктодерма уже начала дифференцироваться, чтобы сформировать головной мозг, нервную систему и позвоночник малыша. Помимо этих структур, из неё также образуются кожа, волосы, ногти, потовые железы и зубная эмаль. Мезодерма состоит из специализированных клеток, которые сформируют сердце и кровеносную систему малыша. Эти клетки перемещаются к области, где будет располагаться сердце малыша, и начинают там скапливаться. Собравшиеся клетки быстро делятся путём митоза, размножаются и образуют ткани. Эти ткани закладывают основу сердца малыша, которое начинает нерегулярно сокращаться.', baby_development_tr = 'Hamileliğinizin bu aşamasında bebeğiniz bir susam tanesi büyüklüğündedir. Bebeğinizin vücudunu oluşturacak üç temel embriyonik tabaka vardır. Bunlar; en dışta ektoderm, ortada mezoderm ve en içte endoderm tabakasıdır. Bu tabakalar hamileliğinizin ilerleyen haftalarında sırasıyla dokulara ve organlara dönüşür. Ektoderm tabakası, bebeğinizin beyni, sinir sistemi ve omurgasını oluşturmak üzere farklılaşmaya başlamıştır. Bu tabaka, söz konusu yapıların yanı sıra cilt, saç, tırnak, ter bezleri ve diş minesinin oluşmasını da sağlar. Mezoderm tabakası ise bebeğinizin kalbini ve dolaşım sistemini şekillendirecek özelleşmiş hücrelerden oluşur. Bu hücreler bebeğinizin kalbinin bulunacağı bölgeye göç ederek orada toplanmaya başlar. Bir araya gelen hücreler hızlı mitoz bölünme aşamalarından geçerek çoğalır ve dokuları oluşturur. Oluşan dokular bebeğinizin kalbinin temelini atar ve düzensiz bir şekilde atmaya başlar.', baby_development_kk = 'Жүктіліктің осы кезеңінде бөпеңіздің көлемі күнжіт дәніндей. Бөпеңіздің денесін қалыптастыратын үш негізгі ұрық жапырақшасы бар. Олар: сыртқы қабат — эктодерма, ортаңғы қабат — мезодерма және ішкі қабат — эндодерма. Жүктіліктің келесі апталарында бұл қабаттар біртіндеп тіндер мен ағзаларға айналады. Эктодерма қабаты бөпеңіздің миын, жүйке жүйесін және омыртқасын қалыптастыру үшін мамандана бастады. Сонымен қатар бұл қабат терінің, шаштың, тырнақтың, тер бездерінің және тіс кіреукесінің түзілуін қамтамасыз етеді. Ал мезодерма қабаты бөпеңіздің жүрегі мен қанайналым жүйесін қалыптастыратын маманданған жасушалардан тұрады. Бұл жасушалар бөпеңіздің жүрегі орналасатын аймаққа қарай жылжып, сол жерде жинала бастайды. Жиналған жасушалар митоз арқылы жылдам бөлініп, көбейеді және тіндер түзеді. Түзілген тіндер бөпеңіздің жүрегінің негізін қалап, біркелкі емес ырғақпен соға бастайды.', baby_development_de = 'In dieser Phase deiner Schwangerschaft ist dein Baby etwa so groß wie ein Sesamkorn. Es besitzt drei grundlegende Keimblätter, aus denen sich sein Körper entwickeln wird: außen das Ektoderm, in der Mitte das Mesoderm und innen das Endoderm. In den kommenden Schwangerschaftswochen entwickeln sich diese Schichten nach und nach zu Geweben und Organen. Das Ektoderm beginnt bereits, sich auszudifferenzieren, um das Gehirn, das Nervensystem und die Wirbelsäule deines Babys zu bilden. Außerdem entstehen daraus die Haut, die Haare, die Nägel, die Schweißdrüsen und der Zahnschmelz. Das Mesoderm besteht aus spezialisierten Zellen, aus denen sich das Herz-Kreislauf-System deines Babys entwickeln wird. Diese Zellen wandern in den Bereich, in dem später das Herz liegen wird, und sammeln sich dort. Durch schnelle mitotische Zellteilungen vermehren sie sich und bilden Gewebe. Dieses Gewebe legt den Grundstein für das Herz deines Babys und beginnt, sich unregelmäßig zusammenzuziehen.', baby_development_ar = 'في هذه المرحلة من حملكِ، يبلغ حجم طفلكِ حجم حبة سمسم. توجد ثلاث طبقات جنينية أساسية ستُشكّل جسم طفلكِ، وهي الأديم الظاهر في الخارج، والأديم المتوسط في الوسط، والأديم الباطن في الداخل. خلال الأسابيع المقبلة من حملكِ، ستتحول هذه الطبقات تدريجيًا إلى أنسجة وأعضاء. بدأت طبقة الأديم الظاهر بالتمايز لتكوين دماغ طفلكِ وجهازه العصبي وعموده الفقري. وإضافةً إلى هذه البنى، تُسهم هذه الطبقة أيضًا في تكوين الجلد والشعر والأظافر والغدد العرقية ومينا الأسنان. أما طبقة الأديم المتوسط، فتتكوّن من خلايا متخصصة ستُشكّل قلب طفلكِ وجهازه الدوري. تنتقل هذه الخلايا إلى المنطقة التي سيتكوّن فيها قلب طفلكِ وتبدأ بالتجمع هناك. وتتكاثر الخلايا المتجمعة عبر مراحل سريعة من الانقسام المتساوي لتكوين الأنسجة. وتضع الأنسجة المتكوّنة الأساس لقلب طفلكِ، ثم تبدأ بالنبض بصورة غير منتظمة.', baby_development_uz = 'Homiladorligingizning ushbu bosqichida chaqalog‘ingiz kunjut donasidek kattalikda. Chaqalog‘ingiz tanasini shakllantiradigan uchta asosiy embrional qatlam mavjud. Bular: eng tashqarida ektoderma, o‘rtada mezoderma va eng ichkarida endoderma qatlamidir. Homiladorligingizning keyingi haftalarida bu qatlamlar ketma-ket ravishda to‘qima va organlarga aylanadi. Ektoderma qatlami chaqalog‘ingizning bosh miyasi, asab tizimi va umurtqa pog‘onasini shakllantirish uchun ixtisoslasha boshlagan. Bu qatlam ushbu tuzilmalardan tashqari teri, soch, tirnoq, ter bezlari va tish emalining hosil bo‘lishini ham ta’minlaydi. Mezoderma qatlami esa chaqalog‘ingizning yuragi va qon aylanish tizimini shakllantiradigan ixtisoslashgan hujayralardan iborat. Bu hujayralar chaqalog‘ingizning yuragi joylashadigan sohaga ko‘chib, u yerda to‘plana boshlaydi. To‘plangan hujayralar tezkor mitoz bo‘linish bosqichlaridan o‘tib ko‘payadi va to‘qimalarni hosil qiladi. Hosil bo‘lgan to‘qimalar chaqalog‘ingiz yuragining asosini yaratib, nomuntazam ura boshlaydi.', baby_development_ka = 'ორსულობის ამ ეტაპზე თქვენი ბავშვი სეზამის მარცვლის ზომისაა. არსებობს სამი ძირითადი ჩანასახოვანი შრე, რომლებიც თქვენი ბავშვის სხეულს ჩამოაყალიბებს. ეს შრეებია: გარეთა — ექტოდერმა, შუა — მეზოდერმა და შიდა — ენდოდერმა. ორსულობის მომდევნო კვირებში ეს შრეები თანდათან ქსოვილებად და ორგანოებად გარდაიქმნება. ექტოდერმის შრემ უკვე დაიწყო დიფერენცირება, რათა თქვენი ბავშვის თავის ტვინი, ნერვული სისტემა და ხერხემალი ჩამოყალიბდეს. გარდა აღნიშნული სტრუქტურებისა, ამ შრიდან ასევე წარმოიქმნება კანი, თმა, ფრჩხილები, საოფლე ჯირკვლები და კბილის მინანქარი. მეზოდერმის შრე კი სპეციალიზებული უჯრედებისგან შედგება, რომლებიც თქვენი ბავშვის გულსა და სისხლის მიმოქცევის სისტემას ჩამოაყალიბებს. ეს უჯრედები გადაადგილდება იმ უბნისკენ, სადაც თქვენი ბავშვის გული უნდა განთავსდეს, და იქ იწყებს თავმოყრას. თავმოყრილი უჯრედები სწრაფი მიტოზური გაყოფის ეტაპებს გადის, მრავლდება და ქსოვილებს ქმნის. წარმოქმნილი ქსოვილები თქვენი ბავშვის გულის საფუძველს აყალიბებს და არარეგულარულ შეკუმშვას იწყებს.', baby_development_zh = '在孕期的这个阶段，宝宝大约有一粒芝麻那么大。构成宝宝身体的胚胎主要有三个胚层：最外层的外胚层、中间的中胚层和最内层的内胚层。在接下来的几周里，这些胚层会依次发育成不同的组织和器官。外胚层已经开始分化，将形成宝宝的大脑、神经系统和脊髓。皮肤、毛发、指甲、汗腺和牙釉质也由这一胚层发育而来。中胚层由特殊细胞组成，这些细胞将形成宝宝的心脏和循环系统。它们会迁移到宝宝心脏将要形成的位置，并开始在那里聚集。聚集后的细胞会迅速进行有丝分裂，不断增殖并形成组织。这些组织为宝宝的心脏奠定基础，随后心脏开始不规律地跳动。', baby_development_id = 'Pada tahap kehamilan ini, ukuran bayi Anda kira-kira sebesar biji wijen. Ada tiga lapisan embrionik utama yang akan membentuk tubuh bayi Anda: ektoderm di bagian terluar, mesoderm di bagian tengah, dan endoderm di bagian terdalam. Lapisan-lapisan ini secara bertahap akan berkembang menjadi jaringan dan organ pada minggu-minggu kehamilan berikutnya. Lapisan ektoderm mulai berdiferensiasi untuk membentuk otak, sistem saraf, dan sumsum tulang belakang bayi Anda. Lapisan ini juga membentuk kulit, rambut, kuku, kelenjar keringat, dan email gigi. Lapisan mesoderm terdiri dari sel-sel khusus yang akan membentuk jantung dan sistem peredaran darah bayi Anda. Sel-sel ini berpindah ke area tempat jantung bayi Anda akan berada dan mulai berkumpul di sana. Sel-sel yang terkumpul mengalami pembelahan mitosis dengan cepat, memperbanyak diri, dan membentuk jaringan. Jaringan yang terbentuk menjadi dasar bagi jantung bayi Anda, yang kemudian mulai berdetak secara tidak teratur.', baby_development_fr = 'À ce stade de votre grossesse, votre bébé a environ la taille d’une graine de sésame. Son corps se formera à partir de trois feuillets embryonnaires principaux : l’ectoderme à l’extérieur, le mésoderme au milieu et l’endoderme à l’intérieur. Au cours des prochaines semaines de votre grossesse, ces feuillets se transformeront progressivement en tissus et en organes. Le feuillet ectodermique a commencé à se différencier pour former le cerveau, le système nerveux et la moelle épinière de votre bébé. Il donnera également naissance à la peau, aux cheveux, aux ongles, aux glandes sudoripares et à l’émail des dents. Le feuillet mésodermique est constitué de cellules spécialisées qui formeront le cœur et le système circulatoire de votre bébé. Ces cellules migrent vers la zone où son cœur se trouvera et commencent à s’y accumuler. Elles se multiplient rapidement par divisions mitotiques et créent des tissus. Les tissus ainsi formés constituent les bases du cœur de votre bébé, qui commence ensuite à battre de manière irrégulière.', baby_development_es = 'En esta etapa del embarazo, tu bebé tiene aproximadamente el tamaño de una semilla de sésamo. Hay tres capas embrionarias primarias que formarán su cuerpo: el ectodermo, la más externa; el mesodermo, la intermedia; y el endodermo, la más interna. Durante las próximas semanas del embarazo, estas capas se transformarán progresivamente en tejidos y órganos. La capa del ectodermo ha empezado a diferenciarse para formar el cerebro, el sistema nervioso y la médula espinal de tu bebé. Esta capa también da lugar a la piel, el pelo, las uñas, las glándulas sudoríparas y el esmalte dental. La capa del mesodermo está formada por células especializadas que darán forma al corazón y al sistema circulatorio de tu bebé. Estas células se desplazan hasta la zona donde se encontrará su corazón y empiezan a acumularse allí. Las células acumuladas experimentan rápidas divisiones mitóticas, multiplicándose y creando tejidos. Los tejidos resultantes sientan las bases del corazón de tu bebé, que después empieza a latir de forma irregular.', baby_development_pt = 'Nesta fase da gravidez, o seu bebé tem aproximadamente o tamanho de uma semente de sésamo. Existem três camadas embrionárias primárias que irão formar o corpo do bebé: a ectoderme, mais externa, a mesoderme, intermédia, e a endoderme, mais interna. Nas próximas semanas da gravidez, estas camadas irão transformar-se progressivamente em tecidos e órgãos. A camada da ectoderme começou a diferenciar-se para formar o cérebro, o sistema nervoso e a medula espinal do seu bebé. Esta camada também dá origem à pele, ao cabelo, às unhas, às glândulas sudoríparas e ao esmalte dentário. A camada da mesoderme é constituída por células especializadas que irão formar o coração e o sistema circulatório do bebé. Estas células deslocam-se para a área onde o coração ficará localizado e começam a acumular-se aí. As células acumuladas passam por rápidas divisões mitóticas, multiplicando-se e criando tecidos. Os tecidos resultantes formam a base do coração do seu bebé, que começa então a bater de forma irregular.', baby_development_vi = 'Ở giai đoạn này của thai kỳ, bé có kích thước tương đương một hạt vừng. Cơ thể bé sẽ được hình thành từ ba lớp phôi chính: ngoại bì ở ngoài cùng, trung bì ở giữa và nội bì ở trong cùng. Trong những tuần thai sắp tới, các lớp này sẽ lần lượt phát triển thành các mô và cơ quan. Lớp ngoại bì đã bắt đầu biệt hóa để hình thành não, hệ thần kinh và tủy sống của bé. Lớp này cũng tạo nên da, tóc, móng, tuyến mồ hôi và men răng. Lớp trung bì gồm các tế bào chuyên biệt sẽ tạo hình cho tim và hệ tuần hoàn của bé. Những tế bào này di chuyển đến vị trí tim của bé sẽ hình thành và bắt đầu tập trung tại đó. Các tế bào đã tập trung trải qua quá trình nguyên phân nhanh chóng, tự nhân lên và tạo thành các mô. Những mô này đặt nền móng cho tim của bé, sau đó tim bắt đầu đập với nhịp chưa đều.', baby_development_hi = 'गर्भावस्था के इस चरण में आपका शिशु लगभग तिल के एक दाने जितना है। भ्रूण की तीन प्राथमिक परतें होती हैं, जिनसे आपके शिशु का शरीर बनेगा: सबसे बाहरी एक्टोडर्म, बीच की मेसोडर्म और सबसे भीतरी एंडोडर्म। गर्भावस्था के आने वाले सप्ताहों में ये परतें क्रमशः ऊतकों और अंगों में बदलेंगी। एक्टोडर्म परत ने आपके शिशु के मस्तिष्क, तंत्रिका तंत्र और रीढ़ की हड्डी के निर्माण के लिए अलग-अलग रूप लेना शुरू कर दिया है। इसी परत से त्वचा, बाल, नाखून, पसीने की ग्रंथियाँ और दाँतों का इनेमल भी बनता है। मेसोडर्म परत में विशेष कोशिकाएँ होती हैं, जो आपके शिशु के हृदय और परिसंचरण तंत्र को आकार देंगी। ये कोशिकाएँ उस स्थान की ओर जाती हैं जहाँ आपके शिशु का हृदय बनेगा और वहाँ इकट्ठी होने लगती हैं। इकट्ठी हुई कोशिकाएँ तेजी से समसूत्री विभाजन करके अपनी संख्या बढ़ाती हैं और ऊतकों का निर्माण करती हैं। इनसे बने ऊतक आपके शिशु के हृदय की नींव रखते हैं, जो इसके बाद अनियमित रूप से धड़कना शुरू कर देता है।', baby_development_ja = '妊娠のこの段階では、赤ちゃんはゴマ粒ほどの大きさです。赤ちゃんの体を形成する胚葉には、最も外側の外胚葉、中央の中胚葉、最も内側の内胚葉という三つの主要な層があります。これらの層は、今後数週間のうちに次々と組織や臓器へ変化していきます。外胚葉は分化を始め、赤ちゃんの脳、神経系、脊髄を形成します。また、この層から皮膚、毛髪、爪、汗腺、歯のエナメル質も作られます。中胚葉は、赤ちゃんの心臓と循環器系を形作る特殊な細胞で構成されています。これらの細胞は、赤ちゃんの心臓ができる場所へ移動し、そこに集まり始めます。集まった細胞は急速に有糸分裂を繰り返して増殖し、組織を作ります。こうしてできた組織が赤ちゃんの心臓の基礎となり、やがて不規則に拍動し始めます。', baby_development_ko = '이 시기의 아기는 참깨 한 알만 한 크기예요. 아기의 몸을 형성할 세 가지 주요 배아층은 가장 바깥쪽의 외배엽, 중간의 중배엽, 가장 안쪽의 내배엽이에요. 이 층들은 앞으로 몇 주 동안 차례로 조직과 기관으로 발달해요. 외배엽은 아기의 뇌, 신경계, 척수를 만들기 위해 분화하기 시작했어요. 피부, 머리카락, 손발톱, 땀샘, 치아의 법랑질도 이 층에서 생겨요. 중배엽은 아기의 심장과 순환계를 형성할 특수 세포로 이루어져 있어요. 이 세포들은 심장이 자리 잡을 부위로 이동해 모이기 시작해요. 모인 세포들은 빠르게 유사분열을 거쳐 증식하고 조직을 만들어요. 이렇게 생긴 조직은 아기 심장의 기초가 되며, 이후 심장은 불규칙하게 뛰기 시작해요.', baby_development_pl = 'Na tym etapie ciąży Twoje dziecko jest mniej więcej wielkości ziarenka sezamu. Jego ciało powstanie z trzech podstawowych listków zarodkowych: najbardziej zewnętrznej ektodermy, środkowej mezodermy i najbardziej wewnętrznej endodermy. W kolejnych tygodniach ciąży warstwy te będą stopniowo przekształcać się w tkanki i narządy. Ektoderma zaczęła się już różnicować, dając początek mózgowi, układowi nerwowemu i rdzeniowi kręgowemu Twojego dziecka. Z warstwy tej powstaną również skóra, włosy, paznokcie, gruczoły potowe i szkliwo zębów. Mezoderma składa się z wyspecjalizowanych komórek, z których rozwiną się serce i układ krążenia dziecka. Komórki te przemieszczają się do miejsca, w którym znajdzie się serce, i zaczynają się tam gromadzić. Następnie przechodzą szybkie podziały mitotyczne, namnażając się i tworząc tkanki. Powstałe tkanki stanowią zaczątek serca Twojego dziecka, które zaczyna bić jeszcze nieregularnie.', baby_development_nl = 'In deze fase van je zwangerschap is je baby ongeveer zo groot als een sesamzaadje. Het lichaam van je baby ontstaat uit drie primaire kiemlagen: het buitenste ectoderm, het middelste mesoderm en het binnenste endoderm. In de komende weken van je zwangerschap ontwikkelen deze lagen zich achtereenvolgens tot weefsels en organen. Het ectoderm begint zich te differentiëren en vormt de hersenen, het zenuwstelsel en het ruggenmerg van je baby. Uit deze laag ontstaan ook de huid, het haar, de nagels, de zweetklieren en het tandglazuur. Het mesoderm bestaat uit gespecialiseerde cellen die het hart en de bloedsomloop van je baby gaan vormen. Deze cellen verplaatsen zich naar de plek waar het hart van je baby komt en hopen zich daar op. De verzamelde cellen delen zich snel door mitose, waardoor hun aantal toeneemt en er weefsels ontstaan. Deze weefsels vormen de basis van het hart van je baby, dat vervolgens onregelmatig begint te kloppen.', baby_development_sv = 'I det här skedet av graviditeten är ditt barn ungefär lika stort som ett sesamfrö. Det finns tre primära groddblad som ska bilda barnets kropp: det yttersta ektodermet, det mellersta mesodermet och det innersta endodermet. Under de kommande graviditetsveckorna kommer dessa lager stegvis att utvecklas till vävnader och organ. Ektodermet har börjat specialiseras för att bilda barnets hjärna, nervsystem och ryggmärg. Från detta lager utvecklas även hud, hår, naglar, svettkörtlar och tandemalj. Mesodermet består av specialiserade celler som ska forma barnets hjärta och cirkulationssystem. Cellerna vandrar till området där hjärtat ska bildas och börjar samlas där. De samlade cellerna genomgår snabba mitotiska delningar, förökar sig och bildar vävnader. Dessa vävnader lägger grunden till barnets hjärta, som sedan börjar slå oregelbundet.' WHERE id = '4937b5d7-78ca-4fd1-9c67-7e6fd29ba696' AND md5(coalesce(baby_development,'')) = 'baf1006524c1638d11ea095a4b094c3e' AND md5(coalesce(baby_development_en,'')) = 'b854ae9ee96f7d27fe64cae3c0a1cd03' AND md5(coalesce(baby_development_ru,'')) = '54f33e719feadca9a32ae24ca0178a6a' AND md5(coalesce(baby_development_tr,'')) = 'd2031710b26ee3b6a8a17aa6c91edfbd' AND md5(coalesce(baby_development_kk,'')) = '97932e0d83cbfb7455f4253c093c322b' AND md5(coalesce(baby_development_de,'')) = 'f7bf0f95543b5ad41441199ea787ee74' AND md5(coalesce(baby_development_ar,'')) = 'b7d0e0827fcdae61bc4d224591e174a1' AND md5(coalesce(baby_development_uz,'')) = '225ecc4470988bd997734f1d91b42cc4' AND md5(coalesce(baby_development_ka,'')) = '10a630d3423974dcf0bee3aa3ca53673' AND md5(coalesce(baby_development_zh,'')) = '66092a5f910a2a98309a1a685aaeee16' AND md5(coalesce(baby_development_id,'')) = '7e52c25d9ca95765464ef695daae20eb' AND md5(coalesce(baby_development_fr,'')) = '3d1bc54a1ba99f549d5c323c0f088330' AND md5(coalesce(baby_development_es,'')) = 'f32b821862dae7c2ccb21cc1d9b8af0b' AND md5(coalesce(baby_development_pt,'')) = 'ea8bed4f26e49a07ff35339022c4692a' AND md5(coalesce(baby_development_vi,'')) = 'ce49da57d50c3af4ca02b34952c1e2ad' AND md5(coalesce(baby_development_hi,'')) = 'a9959d11266489c32ae126d4a97fb605' AND md5(coalesce(baby_development_ja,'')) = '42be73432efd3d62c5dd30fc913ecdea' AND md5(coalesce(baby_development_ko,'')) = 'b68f5ee8d068bc512ea7378d149eac4a' AND md5(coalesce(baby_development_pl,'')) = 'acf438a584be1abbf0de6a8b85ccd5f7' AND md5(coalesce(baby_development_nl,'')) = '83deaa26cb71cdeb0851811316f369f4' AND md5(coalesce(baby_development_sv,'')) = '5a3e2167b085222b47d8eb225b8dc045';
UPDATE public.pregnancy_daily_content SET baby_message = 'Mən bir mərcimək boydayam! 🫘 İnanırsan? Keçən həftədən bəri ölçüm ikiqat artıb! Mən çox sürətlə böyüyürəm, Anacan. Sənin yediyin hər şey mənə tikinti materialı kimi gəlir. Mənim üçün sağlam qidalandığın üçün təşəkkür edirəm. Biz birlikdə böyüyürük, birlikdə güclənirik. Sən mənim ən yaxşı komanda yoldaşımsan!', baby_message_en = 'I''m the size of a lentil! 🫘 Can you believe it? I''ve doubled in size since last week! I''m growing so fast, Anacan. Everything you eat becomes building blocks for me. Thank you for nourishing yourself healthily for my sake. We''re growing together, getting stronger together. You''re my best teammate!', baby_message_ru = 'Я размером с чечевицу! 🫘 Можешь поверить? С прошлой недели мой размер увеличился вдвое! Я расту очень быстро, мамочка. Всё, что ты ешь, становится для меня строительным материалом. Спасибо, что питаешься правильно ради меня. Мы растём вместе и вместе становимся сильнее. Ты — мой лучший товарищ по команде!', baby_message_tr = 'Ben bir mercimek büyüklüğündeyim! 🫘 İnanabiliyor musun? Geçen haftadan beri boyutum iki katına çıktı! Çok hızlı büyüyorum, anneciğim. Yediğin her şey bana yapı malzemesi oluyor. Benim için sağlıklı beslendiğin için teşekkür ederim. Birlikte büyüyor, birlikte güçleniyoruz. Sen benim en iyi takım arkadaşımsın!', baby_message_kk = 'Мен жасымықтаймын! 🫘 Сенесіз бе? Өткен аптадан бері көлемім екі есе артты! Мен өте жылдам өсіп келемін, анашым. Сіз жеген тағамның бәрі маған құрылыс материалы сияқты жетеді. Мен үшін пайдалы тамақтанғаныңызға рақмет. Біз бірге өсіп, бірге күш жинап келеміз. Сіз менің ең керемет командаласымсыз!', baby_message_de = 'Ich bin so groß wie eine Linse! 🫘 Kannst du das glauben? Seit letzter Woche habe ich meine Größe verdoppelt! Ich wachse unglaublich schnell, Mami. Alles, was du isst, liefert mir wichtige Bausteine. Danke, dass du dich für mich gesund ernährst. Wir wachsen gemeinsam und werden gemeinsam stärker. Du bist meine allerbeste Teampartnerin!', baby_message_ar = 'أنا بحجم حبة عدس! 🫘 هل تصدقين ذلك؟ لقد تضاعف حجمي منذ الأسبوع الماضي! إنني أنمو بسرعة كبيرة يا ماما. كل ما تأكلينه يصل إليّ كأنه مواد بناء. شكرًا لأنكِ تتناولين طعامًا صحيًا من أجلي. نحن ننمو معًا ونزداد قوة معًا. أنتِ أفضل شريكة لي!', baby_message_uz = 'Men bir dona yasmiq kattaligidayman! 🫘 Ishonasizmi? O‘tgan haftadan beri o‘lchamim ikki baravar oshdi! Men juda tez o‘syapman, Onajon. Siz yegan har bir narsa men uchun qurilish materiali bo‘lib xizmat qiladi. Men uchun sog‘lom ovqatlanayotganingizga rahmat. Biz birga o‘syapmiz, birga kuchayib boryapmiz. Siz mening eng yaxshi jamoadoshimsiz!', baby_message_ka = 'მე ოსპის მარცვლის ზომის ვარ! 🫘 გჯერათ? გასული კვირის შემდეგ ჩემი ზომა გაორმაგდა! ძალიან სწრაფად ვიზრდები, დედიკო. ყველაფერი, რასაც მიირთმევთ, ჩემამდე სამშენებლო მასალასავით აღწევს. გმადლობთ, რომ ჩემთვის ჯანსაღად იკვებებით. ჩვენ ერთად ვიზრდებით და ერთად ვძლიერდებით. თქვენ ჩემი საუკეთესო თანაგუნდელი ხართ!', baby_message_zh = '我有一颗小扁豆那么大啦！🫘 你敢相信吗？和上周相比，我已经长到了两倍大！Anacan，我长得真快。你吃下的每一口食物，都会变成我成长的材料。谢谢你为了我健康地照顾和滋养自己。我们一起成长，一起变得更强壮。你是我最棒的队友！', baby_message_id = 'Ukuranku sebesar kacang lentil! 🫘 Bisakah Anda memercayainya? Ukuranku sudah dua kali lipat sejak minggu lalu! Aku tumbuh begitu cepat, Anacan. Semua yang Anda makan menjadi bahan pembentuk tubuhku. Terima kasih sudah mengonsumsi makanan sehat demi aku. Kita tumbuh bersama dan menjadi lebih kuat bersama. Anda adalah rekan terbaikku!', baby_message_fr = 'J''ai la taille d''une lentille ! 🫘 Vous vous rendez compte ? J''ai doublé de taille depuis la semaine dernière ! Je grandis si vite, Anacan. Tout ce que vous mangez devient pour moi un élément essentiel à ma croissance. Merci de vous nourrir sainement pour moi. Nous grandissons ensemble et devenons plus forts ensemble. Vous êtes ma meilleure coéquipière !', baby_message_es = '¡Tengo el tamaño de una lenteja! 🫘 ¿Te lo puedes creer? ¡He duplicado mi tamaño desde la semana pasada! Estoy creciendo rapidísimo, Anacan. Todo lo que comes se convierte en material para formar mi cuerpo. Gracias por alimentarte de forma saludable por mí. Crecemos y nos hacemos más fuertes juntos. ¡Eres mi mejor compañera de equipo!', baby_message_pt = 'Sou do tamanho de uma lentilha! 🫘 Consegues acreditar? Dupliquei de tamanho desde a semana passada! Estou a crescer tão depressa, Anacan. Tudo o que comes se transforma nos meus blocos de construção. Obrigado por cuidares da tua alimentação de forma saudável por mim. Estamos a crescer e a ficar mais fortes juntos. És a minha melhor companheira de equipa!', baby_message_vi = 'Con có kích thước bằng một hạt đậu lăng! 🫘 Mẹ có tin được không? Con đã lớn gấp đôi so với tuần trước! Con đang lớn nhanh lắm, Anacan. Mọi thứ mẹ ăn đều trở thành vật liệu xây dựng cơ thể con. Cảm ơn mẹ đã ăn uống lành mạnh vì con. Chúng ta cùng lớn lên, cùng trở nên mạnh mẽ hơn. Mẹ là đồng đội tuyệt vời nhất của con!', baby_message_hi = 'मैं मसूर के एक दाने जितना बड़ा हूँ! 🫘 क्या आप यकीन कर सकती हैं? पिछले हफ्ते से अब तक मेरा आकार दोगुना हो गया है! Anacan, मैं बहुत तेज़ी से बढ़ रहा हूँ। आप जो कुछ भी खाती हैं, वह मेरे शरीर के निर्माण की सामग्री बन जाता है। मेरे लिए पौष्टिक भोजन खाकर अपना ध्यान रखने के लिए धन्यवाद। हम साथ-साथ बढ़ रहे हैं और साथ-साथ मज़बूत हो रहे हैं। आप मेरी सबसे अच्छी साथी हैं!', baby_message_ja = 'レンズ豆くらいの大きさになりました！🫘 信じられますか？先週から大きさが二倍になりました！私はものすごい速さで成長しています、Anacan。あなたが食べたものはすべて、私の体をつくる材料になります。私のために健康的な食事をしてくれて、ありがとう。一緒に成長し、一緒に強くなっています。あなたは最高のチームメイトです！', baby_message_ko = '저는 렌틸콩만 해요! 🫘 믿어지나요? 지난주보다 몸집이 두 배나 커졌어요! 저는 아주 빠르게 자라고 있어요, Anacan. 엄마가 먹는 모든 음식이 제 몸을 만드는 재료가 돼요. 저를 위해 건강하게 챙겨 먹어 줘서 고마워요. 우리는 함께 자라고 함께 강해지고 있어요. 엄마는 최고의 한 팀이에요!', baby_message_pl = 'Jestem wielkości ziarenka soczewicy! 🫘 Możesz w to uwierzyć? Od zeszłego tygodnia moje rozmiary się podwoiły! Rosnę tak szybko, Anacan. Wszystko, co jesz, staje się dla mnie budulcem. Dziękuję, że zdrowo się odżywiasz z myślą o mnie. Rośniemy razem i razem nabieramy sił. Jesteś najlepszą osobą w mojej drużynie!', baby_message_nl = 'Ik ben zo groot als een linze! 🫘 Kun je het geloven? Sinds vorige week ben ik twee keer zo groot geworden! Ik groei zo snel, Anacan. Alles wat je eet, wordt bouwstof voor mij. Bedankt dat je voor mij gezond eet. We groeien samen en worden samen sterker. Jij bent mijn allerbeste teamgenoot!', baby_message_sv = 'Jag är stor som en lins! 🫘 Kan du fatta det? Sedan förra veckan har jag blivit dubbelt så stor! Jag växer så snabbt, Anacan. Allt du äter blir byggstenar åt mig. Tack för att du äter hälsosamt för min skull. Vi växer tillsammans och blir starkare tillsammans. Du är min bästa lagkamrat!' WHERE id = '8a7c667d-259c-4117-9c65-d0fc403d0248' AND md5(coalesce(baby_message,'')) = 'b81f55b94c26543c9b3959ed22fa5450' AND md5(coalesce(baby_message_en,'')) = 'cf14504cac4a0fb587ec4acc4b04bfb4' AND md5(coalesce(baby_message_ru,'')) = 'e4fd568b65c7996d6eae99fcf8061ca3' AND md5(coalesce(baby_message_tr,'')) = '15434d2f609b4fa2d235149c5c254127' AND md5(coalesce(baby_message_kk,'')) = '802f2e525d7f12a1a91cb303e3e1effd' AND md5(coalesce(baby_message_de,'')) = 'b5dc57c46fa38f53fe7120c9d89c359b' AND md5(coalesce(baby_message_ar,'')) = '0b48196936a5d8b13e0727a6135ffcc6' AND md5(coalesce(baby_message_uz,'')) = '5f7aad35e356a5b608da388ec7fdbe1d' AND md5(coalesce(baby_message_ka,'')) = '7b624890a47624a876fd7a787c7a417e' AND md5(coalesce(baby_message_zh,'')) = '8017e1aca9fca0e13763b0f932627341' AND md5(coalesce(baby_message_id,'')) = '17ac740db5d063914fe50c8b0b8b9297' AND md5(coalesce(baby_message_fr,'')) = '9d0c0c85a70de78ccfcb717c86dbe0a8' AND md5(coalesce(baby_message_es,'')) = '4dd73e634b2ace03d238004bc541add8' AND md5(coalesce(baby_message_pt,'')) = '287a42818e3501b1919ef0b3eb3402b5' AND md5(coalesce(baby_message_vi,'')) = '6c6780344311519eee21594e16f87cf8' AND md5(coalesce(baby_message_hi,'')) = '92cc79a9e2c9aa6df71c7c9cfbe5963d' AND md5(coalesce(baby_message_ja,'')) = 'cc34cc6c5ee6db2d9cc91eabd8109168' AND md5(coalesce(baby_message_ko,'')) = '1d3a2c1907d686b1d3f2efdde425bf83' AND md5(coalesce(baby_message_pl,'')) = '941143b9a3ce89e2d663eb68efa3464b' AND md5(coalesce(baby_message_nl,'')) = 'e1eba2fc10fbb372a8f4406bd429f636' AND md5(coalesce(baby_message_sv,'')) = '01b9c06fe391ffc985d1dc696b04b6df';
UPDATE public.pregnancy_daily_content SET baby_development = 'Bu həftədən etibarən körpənizin ürək döyüntülərini eşidə bilərsiniz. Körpənizin ürəyi ana bətninə tutunduqdan ən gec 3 həftə sonra döyünməyə başlayır. Bu da hamiləliyin 5-ci və 6-cı həftələrinə təsadüf edir. Bu səbəbdən hamiləliyin 7-ci həftəsində körpənizin ürək döyüntülərini eşitməyiniz artıq mümkündür.;;;
Yenə də gec mayalanma, nizamsız aybaşı və son aybaşı tarixini dəqiq bilməmək kimi hallarla əlaqədar olaraq hələ də ürək döyüntüsü eşitməmiş ola bilərsiniz. Bu vəziyyətdə ürək döyüntüsünü dinləmək üçün daha 1-2 həftəyə ehtiyac duyula bilər.;;;
Mərkəzi sinir sisteminin ən mühüm hissəsi olan beyin inkişafını sürətlə davam etdirir. Körpəniz artıq təxminən 1 sm uzunluğa və 1 qramdan az çəkiyə çatmışdır. Bu həftədə artıq körpənizin bədənində orqanların yerləri bəllidir. Bu orqanlardan biri də ağciyərdir. Lakin bu möcüzəvi orqanın inkişafı yalnız 38-ci həftədə tamamlanır.', baby_development_en = 'From this week, you might be able to hear your baby''s heartbeat. Your baby''s heart begins to beat at most 3 weeks after implantation in the womb, which usually falls between the 5th and 6th weeks of pregnancy. Therefore, it is now possible to hear your baby''s heartbeat in the 7th week of pregnancy.;;;
However, due to factors like late fertilization, irregular periods, or not knowing your last menstrual period accurately, you might still not have heard the heartbeat. In such cases, you may need another 1-2 weeks to hear it.;;;
The brain, the most important part of the central nervous system, continues its rapid development. Your baby has now reached a length of about 1 cm and a weight of less than 1 gram. This week, the locations of your baby''s organs are already distinct. One of these organs is the lungs, though the development of this miraculous organ is only completed by the 38th week.', baby_development_ru = 'Начиная с этой недели вы можете услышать сердцебиение малыша. Его сердце начинает биться не позднее чем через 3 недели после прикрепления к стенке матки. Это происходит на 5-й или 6-й неделе беременности. Поэтому уже на 7-й неделе беременности можно услышать сердцебиение малыша.;;;
Однако из-за позднего оплодотворения, нерегулярной менструации или неточно установленной даты последней менструации сердцебиение пока может не прослушиваться. В таком случае, чтобы услышать его, может потребоваться ещё 1-2 недели.;;;
Головной мозг — важнейшая часть центральной нервной системы — продолжает стремительно развиваться. Длина вашего малыша уже составляет около 1 см, а вес менее 1 грамма. На этой неделе уже определилось расположение органов в теле малыша. Один из них — лёгкие. Однако развитие этого удивительного органа завершится только на 38-й неделе.', baby_development_tr = 'Bu haftadan itibaren bebeğinizin kalp atışlarını duyabilirsiniz. Bebeğinizin kalbi, rahme tutunduktan sonra en geç 3 hafta içinde atmaya başlar. Bu da gebeliğin 5. ve 6. haftalarına denk gelir. Bu nedenle gebeliğin 7. haftasında bebeğinizin kalp atışlarını duymanız artık mümkündür.;;;
Yine de geç döllenme, düzensiz regl veya son regl tarihinizi tam olarak bilmemeniz gibi nedenlerle kalp atışlarını henüz duymamış olabilirsiniz. Bu durumda kalp atışlarını dinleyebilmek için 1-2 hafta daha beklemek gerekebilir.;;;
Merkezi sinir sisteminin en önemli bölümü olan beyin hızla gelişmeye devam ediyor. Bebeğiniz artık yaklaşık 1 cm uzunluğa ve 1 gramdan az ağırlığa ulaştı. Bu hafta bebeğinizin vücudundaki organların yerleri artık bellidir. Bu organlardan biri de akciğerlerdir. Ancak bu mucizevi organların gelişimi ancak 38. haftada tamamlanır.', baby_development_kk = 'Осы аптадан бастап бөпеңіздің жүрек соғысын ести аласыз. Бөпеңіздің жүрегі жатыр қабырғасына бекінгеннен кейін ең кеш дегенде 3 аптадан соң соға бастайды. Бұл жүктіліктің 5-ші және 6-шы аптасына сәйкес келеді. Сондықтан жүктіліктің 7-ші аптасында бөпеңіздің жүрек соғысын естуіңіз әбден мүмкін.;;;
Дегенмен кеш ұрықтану, етеккірдің тұрақсыз болуы немесе соңғы етеккіріңіздің нақты күнін білмеу сияқты жағдайларға байланысты жүрек соғысын әлі естімеуіңіз мүмкін. Мұндай жағдайда жүрек соғысын тыңдау үшін тағы 1-2 апта қажет болуы ықтимал.;;;
Орталық жүйке жүйесінің ең маңызды бөлігі саналатын ми қарқынды дамуын жалғастыруда. Бөпеңіздің ұзындығы шамамен 1 см-ге жетті, ал салмағы 1 граммнан аз. Осы аптада бөпеңіздің денесіндегі ағзалардың орны анықталып қалады. Сол ағзалардың бірі — өкпе. Алайда бұл таңғажайып ағзаның дамуы тек 38-ші аптада аяқталады.', baby_development_de = 'Ab dieser Woche kannst du möglicherweise den Herzschlag deines Babys hören. Spätestens 3 Wochen nachdem sich dein Baby in der Gebärmutter eingenistet hat, beginnt sein Herz zu schlagen. Das entspricht etwa der 5. oder 6. Schwangerschaftswoche. Daher ist es in der 7. Schwangerschaftswoche bereits möglich, den Herzschlag deines Babys zu hören.;;;
Bei einer späteren Befruchtung, einer unregelmäßigen Periode oder wenn das genaue Datum der letzten Periode nicht bekannt ist, kann es jedoch sein, dass noch kein Herzschlag zu hören ist. In diesem Fall kann es weitere 1-2 Wochen dauern, bis er wahrgenommen werden kann.;;;
Das Gehirn als wichtigster Bestandteil des zentralen Nervensystems entwickelt sich weiterhin rasant. Dein Baby ist nun etwa 1 cm groß und wiegt weniger als 1 Gramm. In dieser Woche sind die Positionen der Organe im Körper deines Babys bereits festgelegt. Eines dieser Organe ist die Lunge. Die Entwicklung dieses erstaunlichen Organs ist allerdings erst in der 38. Woche abgeschlossen.', baby_development_ar = 'اعتبارًا من هذا الأسبوع، قد تتمكنين من سماع نبضات قلب طفلكِ. يبدأ قلب طفلكِ بالنبض في موعد أقصاه 3 أسابيع بعد انغراسه في الرحم، وهو ما يتزامن مع الأسبوعين 5 و6 من الحمل. لذلك، يصبح من الممكن سماع نبضات قلب طفلكِ في الأسبوع 7 من الحمل.;;;
ومع ذلك، قد لا تكون نبضات القلب قد سُمعت بعد بسبب تأخر الإخصاب أو عدم انتظام الدورة الشهرية أو عدم معرفة تاريخ آخر دورة شهرية بدقة. في هذه الحالة، قد يلزم الانتظار من 1 إلى 2 أسبوع إضافي لسماع نبضات القلب.;;;
يواصل الدماغ، وهو أهم أجزاء الجهاز العصبي المركزي، نموه بوتيرة متسارعة. وقد بلغ طول طفلكِ الآن نحو 1 سم ووزنه أقل من 1 غرام. وفي هذا الأسبوع، أصبحت مواضع الأعضاء في جسم طفلكِ محددة، ومن بينها الرئتان. لكن نمو هذا العضو المذهل لا يكتمل إلا في الأسبوع 38.', baby_development_uz = 'Shu haftadan boshlab chaqalog‘ingizning yurak urishini eshitishingiz mumkin. Chaqalog‘ingizning yuragi bachadonga birikkanidan keyin ko‘pi bilan 3 hafta o‘tib ura boshlaydi. Bu homiladorlikning 5- va 6-haftalariga to‘g‘ri keladi. Shu sababli homiladorlikning 7-haftasida chaqalog‘ingizning yurak urishini eshitishingiz mumkin.;;;
Shunga qaramay, urug‘lanishning kech sodir bo‘lishi, hayzning nomuntazamligi yoki oxirgi hayz sanasini aniq bilmaslik tufayli yurak urishi hali eshitilmasligi mumkin. Bunday holatda yurak urishini eshitish uchun yana 1-2 hafta kutish talab etilishi mumkin.;;;
Markaziy asab tizimining eng muhim qismi bo‘lgan miya jadal rivojlanishda davom etmoqda. Chaqalog‘ingizning uzunligi endi taxminan 1 sm, vazni esa 1 grammdan kam. Shu haftada chaqalog‘ingiz tanasidagi a’zolarning joylashuvi allaqachon ma’lum bo‘ladi. Bu a’zolardan biri o‘pkadir. Biroq bu mo‘jizaviy a’zoning rivojlanishi faqat 38-haftada yakunlanadi.', baby_development_ka = 'ამ კვირიდან უკვე შეგიძლიათ თქვენი ბავშვის გულისცემა მოისმინოთ. ბავშვის გული დედის საშვილოსნოში მიმაგრებიდან არაუგვიანეს 3 კვირისა იწყებს ცემას. ეს ორსულობის მე-5 და მე-6 კვირებს ემთხვევა. ამიტომ ორსულობის მე-7 კვირაში ბავშვის გულისცემის მოსმენა უკვე შესაძლებელია.;;;
თუმცა, გვიანი განაყოფიერების, არარეგულარული მენსტრუაციის ან ბოლო მენსტრუაციის ზუსტი თარიღის არცოდნის გამო, შესაძლოა გულისცემა ჯერ კიდევ არ ისმოდეს. ასეთ შემთხვევაში მის მოსასმენად შესაძლოა კიდევ 1-2 კვირა იყოს საჭირო.;;;
ტვინი, რომელიც ცენტრალური ნერვული სისტემის უმნიშვნელოვანესი ნაწილია, სწრაფად განაგრძობს განვითარებას. თქვენი ბავშვის სიგრძე უკვე დაახლოებით 1 სმ-ს აღწევს, წონა კი 1 გრამზე ნაკლებია. ამ კვირაში ბავშვის სხეულში ორგანოების მდებარეობა უკვე განსაზღვრულია. ერთ-ერთი ასეთი ორგანოა ფილტვი. თუმცა ამ საოცარი ორგანოს განვითარება მხოლოდ 38-ე კვირაში სრულდება.', baby_development_zh = '从本周开始，你可能已经能听到宝宝的心跳。宝宝的心脏最迟会在胚胎着床后的3周开始跳动，这通常对应孕期的第5周至第6周。因此，现在到了孕期第7周，已经有可能听到宝宝的心跳。;;;
不过，由于受精较晚、月经不规律或末次月经日期记得不准确，你可能仍未听到宝宝的心跳。遇到这种情况，可能还需要再等1-2周。;;;
作为中枢神经系统最重要的部分，大脑仍在快速发育。宝宝现在的身长约为1 cm，体重不到1克。本周，宝宝各器官的位置已经清晰可辨，其中包括肺部，不过这一神奇器官要到第38周才会发育完成。', baby_development_id = 'Mulai minggu ini, Anda mungkin sudah dapat mendengar detak jantung bayi Anda. Jantung bayi mulai berdetak paling lambat 3 minggu setelah implantasi di dalam rahim, yang biasanya terjadi antara minggu ke-5 dan ke-6 kehamilan. Oleh karena itu, detak jantung bayi Anda kini mungkin sudah dapat terdengar pada minggu ke-7 kehamilan.;;;
Namun, karena beberapa faktor seperti pembuahan yang terlambat, menstruasi tidak teratur, atau tanggal menstruasi terakhir yang tidak diketahui secara pasti, detak jantung mungkin masih belum terdengar. Dalam kondisi tersebut, Anda mungkin perlu menunggu 1-2 minggu lagi untuk mendengarnya.;;;
Otak, bagian terpenting dari sistem saraf pusat, terus berkembang pesat. Bayi Anda kini telah mencapai panjang sekitar 1 cm dan berat kurang dari 1 gram. Pada minggu ini, letak organ-organ bayi Anda sudah terlihat jelas. Salah satunya adalah paru-paru, meskipun perkembangan organ yang menakjubkan ini baru selesai pada minggu ke-38.', baby_development_fr = 'À partir de cette semaine, vous pourrez peut-être entendre les battements du cœur de votre bébé. Son cœur commence à battre au plus tard 3 semaines après son implantation dans l’utérus, ce qui se situe généralement entre la 5e et la 6e semaine de grossesse. Il est donc désormais possible d’entendre les battements de son cœur au cours de la 7e semaine de grossesse.;;;
Cependant, en cas de fécondation tardive, de règles irrégulières ou d’incertitude sur la date de vos dernières règles, il est possible que vous ne les ayez pas encore entendus. Dans ce cas, il faudra peut-être attendre encore 1-2 semaines.;;;
Le cerveau, partie la plus importante du système nerveux central, poursuit son développement rapide. Votre bébé mesure maintenant environ 1 cm et pèse moins de 1 gramme. Cette semaine, l’emplacement de ses organes est déjà bien défini. Les poumons en font partie, même si le développement de cet organe extraordinaire ne s’achèvera qu’à la 38e semaine.', baby_development_es = 'A partir de esta semana, quizá puedas escuchar el latido de tu bebé. Su corazón comienza a latir, como máximo, 3 semanas después de la implantación en el útero, lo que suele ocurrir entre las semanas 5 y 6 de embarazo. Por tanto, ya es posible escuchar el latido de tu bebé en la semana 7 de embarazo.;;;
Sin embargo, debido a factores como una fecundación tardía, ciclos menstruales irregulares o no saber con exactitud la fecha de tu última menstruación, es posible que todavía no hayas oído el latido. En ese caso, quizá debas esperar otras 1-2 semanas para escucharlo.;;;
El cerebro, la parte más importante del sistema nervioso central, continúa desarrollándose rápidamente. Tu bebé ya ha alcanzado una longitud de aproximadamente 1 cm y un peso de menos de 1 gramo. Esta semana, la ubicación de sus órganos ya está bien definida. Uno de ellos son los pulmones, aunque el desarrollo de este órgano milagroso no se completa hasta la semana 38.', baby_development_pt = 'A partir desta semana, talvez já consiga ouvir os batimentos cardíacos do seu bebé. O coração do bebé começa a bater, no máximo, 3 semanas após a implantação no útero, o que geralmente acontece entre a 5.ª e a 6.ª semanas de gravidez. Por isso, já é possível ouvir os batimentos cardíacos do seu bebé na 7.ª semana de gravidez.;;;
No entanto, devido a fatores como uma fecundação tardia, ciclos menstruais irregulares ou a falta de certeza sobre a data da sua última menstruação, poderá ainda não ter ouvido os batimentos cardíacos. Nestes casos, poderá ser necessário aguardar mais 1-2 semanas para os ouvir.;;;
O cérebro, a parte mais importante do sistema nervoso central, continua a desenvolver-se rapidamente. O seu bebé já atingiu um comprimento de cerca de 1 cm e um peso inferior a 1 grama. Nesta semana, a localização dos órgãos do seu bebé já está bem definida. Um destes órgãos são os pulmões, embora o desenvolvimento deste órgão extraordinário só fique concluído na 38.ª semana.', baby_development_vi = 'Từ tuần này, bạn có thể nghe được nhịp tim của bé. Tim bé bắt đầu đập muộn nhất là 3 tuần sau khi làm tổ trong tử cung, thường rơi vào khoảng tuần thứ 5 đến tuần thứ 6 của thai kỳ. Vì vậy, giờ đây bạn có thể nghe được nhịp tim của bé ở tuần thai thứ 7.;;;
Tuy nhiên, do những yếu tố như thụ tinh muộn, chu kỳ kinh nguyệt không đều hoặc không nhớ chính xác ngày đầu của kỳ kinh cuối, bạn vẫn có thể chưa nghe thấy nhịp tim. Trong trường hợp này, bạn có thể cần chờ thêm 1-2 tuần nữa.;;;
Não bộ, phần quan trọng nhất của hệ thần kinh trung ương, tiếp tục phát triển nhanh chóng. Bé hiện có chiều dài khoảng 1 cm và cân nặng chưa đến 1 gam. Trong tuần này, vị trí các cơ quan của bé đã được phân định rõ ràng. Một trong số đó là phổi, dù cơ quan kỳ diệu này chỉ hoàn thiện quá trình phát triển vào tuần thứ 38.', baby_development_hi = 'इस सप्ताह से आप अपने शिशु के दिल की धड़कन सुन सकती हैं। गर्भाशय में आरोपण के अधिकतम 3 सप्ताह बाद आपके शिशु का दिल धड़कना शुरू कर देता है, जो आम तौर पर गर्भावस्था के 5वें से 6वें सप्ताह के बीच होता है। इसलिए अब गर्भावस्था के 7वें सप्ताह में आपके शिशु के दिल की धड़कन सुनना संभव है।;;;
हालाँकि, देर से निषेचन, अनियमित माहवारी या पिछली माहवारी की सही तारीख पता न होने जैसे कारणों से हो सकता है कि आपने अभी तक दिल की धड़कन न सुनी हो। ऐसे मामलों में इसे सुनने के लिए आपको और 1-2 सप्ताह इंतज़ार करना पड़ सकता है।;;;
केंद्रीय तंत्रिका तंत्र का सबसे महत्वपूर्ण हिस्सा, मस्तिष्क, तेज़ी से विकसित हो रहा है। अब आपके शिशु की लंबाई लगभग 1 cm और वज़न 1 gram से कम हो गया है। इस सप्ताह आपके शिशु के अंगों के स्थान स्पष्ट हो चुके हैं। इन्हीं अंगों में से एक फेफड़े हैं, हालाँकि इस अद्भुत अंग का विकास 38वें सप्ताह तक ही पूरा होता है।', baby_development_ja = '今週から、赤ちゃんの心拍を聞ける可能性があります。赤ちゃんの心臓は、子宮に着床してから遅くとも3週間以内に動き始めます。通常は妊娠5週から6週の間です。そのため、妊娠7週の今、赤ちゃんの心拍を聞ける可能性があります。;;;
ただし、受精が遅かった場合や月経周期が不規則な場合、最終月経日が正確に分からない場合などは、まだ心拍を確認できないこともあります。その場合、確認できるまでさらに1-2週間かかる可能性があります。;;;
中枢神経系で最も重要な脳は、引き続き急速に発達しています。赤ちゃんの身長は約1 cm、体重は1グラム未満になりました。今週には、各臓器の位置もはっきりしています。その一つが肺ですが、この驚異的な臓器が完成するのは妊娠38週です。', baby_development_ko = '이번 주부터 아기의 심장 박동을 들을 수도 있어요. 아기의 심장은 자궁에 착상한 뒤 늦어도 3주 이내에 뛰기 시작하며, 이는 보통 임신 5주에서 6주 사이예요. 따라서 이제 임신 7주에는 아기의 심장 박동을 들을 수 있어요.;;;
하지만 수정이 늦었거나 생리 주기가 불규칙하거나 마지막 생리 시작일을 정확히 모르는 경우에는 아직 심장 박동을 듣지 못했을 수도 있어요. 이럴 때는 심장 박동을 듣기까지 1-2주를 더 기다려야 할 수 있어요.;;;
중추신경계에서 가장 중요한 부분인 뇌는 빠르게 발달하고 있어요. 아기의 키는 이제 약 1cm, 몸무게는 1그램 미만이에요. 이번 주에는 아기의 장기가 자리 잡은 위치도 뚜렷해져요. 그중 하나가 폐이지만, 이 놀라운 장기의 발달은 38주가 되어야 완료돼요.', baby_development_pl = 'Od tego tygodnia możesz już usłyszeć bicie serca swojego dziecka. Serce dziecka zaczyna bić najpóźniej w ciągu 3 tygodni od zagnieżdżenia się zarodka w macicy, co zwykle przypada między 5. a 6. tygodniem ciąży. Oznacza to, że w 7. tygodniu ciąży usłyszenie bicia serca dziecka jest już możliwe.;;;
Jednak z powodu późnego zapłodnienia, nieregularnych miesiączek lub niedokładnej znajomości daty ostatniej miesiączki bicie serca może nadal nie być słyszalne. W takim przypadku może być potrzebne jeszcze 1-2 tygodni.;;;
Mózg, najważniejsza część ośrodkowego układu nerwowego, nadal intensywnie się rozwija. Dziecko ma teraz około 1 cm długości i waży mniej niż 1 gram. W tym tygodniu położenie jego narządów jest już wyraźnie określone. Jednym z nich są płuca, choć rozwój tego niezwykłego narządu zakończy się dopiero w 38. tygodniu.', baby_development_nl = 'Vanaf deze week kun je mogelijk de hartslag van je baby horen. Het hartje van je baby begint uiterlijk 3 weken na de innesteling in de baarmoeder te kloppen. Dit valt meestal tussen zwangerschapsweek 5 en 6. Het is daarom nu mogelijk om de hartslag van je baby in zwangerschapsweek 7 te horen.;;;
Door factoren zoals een late bevruchting, een onregelmatige menstruatie of onzekerheid over de datum van je laatste menstruatie heb je de hartslag misschien nog niet gehoord. In dat geval kan het nog 1-2 weken duren voordat je deze kunt horen.;;;
De hersenen, het belangrijkste onderdeel van het centrale zenuwstelsel, blijven zich snel ontwikkelen. Je baby is nu ongeveer 1 cm lang en weegt minder dan 1 gram. Deze week bevinden de organen van je baby zich al op duidelijk herkenbare plaatsen. Een van die organen zijn de longen, al is de ontwikkeling van dit bijzondere orgaan pas rond week 38 voltooid.', baby_development_sv = 'Från och med den här veckan kan du kanske höra ditt barns hjärtslag. Barnets hjärta börjar slå senast 3 veckor efter att det har fäst i livmodern, vilket vanligtvis infaller mellan graviditetsvecka 5 och 6. Därför är det nu möjligt att höra barnets hjärtslag i graviditetsvecka 7.;;;
På grund av exempelvis sen befruktning, oregelbunden mens eller osäkerhet om datumet för din senaste mens kanske hjärtslagen ändå inte har kunnat höras. I så fall kan du behöva vänta ytterligare 1-2 veckor.;;;
Hjärnan, den viktigaste delen av centrala nervsystemet, fortsätter att utvecklas snabbt. Ditt barn är nu ungefär 1 cm långt och väger mindre än 1 gram. Redan den här veckan har barnets organ fått sina tydliga placeringar. Ett av dessa organ är lungorna, men utvecklingen av detta fantastiska organ slutförs först i vecka 38.' WHERE id = 'c99602ee-b4cc-4358-a321-f5e26f5f82fb' AND md5(coalesce(baby_development,'')) = '055e6c6a6036a6b54291edf352b8eeec' AND md5(coalesce(baby_development_en,'')) = '8153e201d2b9b1ae127d35c9c91a37c7' AND md5(coalesce(baby_development_ru,'')) = '06e316647c195ae631afb1fc8bc8f294' AND md5(coalesce(baby_development_tr,'')) = '0df7b53f5b3eea93812d8641cc377210' AND md5(coalesce(baby_development_kk,'')) = '65799fc78bda25ced493c55def797a2b' AND md5(coalesce(baby_development_de,'')) = '000fdf77bad6d47b8d02b9197a5018e9' AND md5(coalesce(baby_development_ar,'')) = '64454cd567a63c4bb1878df087480728' AND md5(coalesce(baby_development_uz,'')) = 'c14fd70c863ad646ab5e0ba50f5c2cf1' AND md5(coalesce(baby_development_ka,'')) = '950c9f21a57c4cdf3a557aba6c087333' AND md5(coalesce(baby_development_zh,'')) = '3d323008ab9c291a9eebc9c45b1c5128' AND md5(coalesce(baby_development_id,'')) = '09d67963160b2a9ee4076ef8d59cf587' AND md5(coalesce(baby_development_fr,'')) = '8b87cc2e3ac09958139d6f113d81c781' AND md5(coalesce(baby_development_es,'')) = '6d33e4f6172519821bf55e23969e9b63' AND md5(coalesce(baby_development_pt,'')) = '08602582d90584f857dd362672fc2e37' AND md5(coalesce(baby_development_vi,'')) = '0d5166b76d085e2bcd36f1c08575c2ee' AND md5(coalesce(baby_development_hi,'')) = 'c0e4be1eb76f31456ccab2cfc4f9004f' AND md5(coalesce(baby_development_ja,'')) = '0520baf491f7f40dbee875102757f0d0' AND md5(coalesce(baby_development_ko,'')) = '4438dcec078dba5c80a0be9dff71b188' AND md5(coalesce(baby_development_pl,'')) = '6b64a584d258978eadbb7cb0e6519736' AND md5(coalesce(baby_development_nl,'')) = 'd1445216cd53ca0ce76028dedf396909' AND md5(coalesce(baby_development_sv,'')) = '3778227ed64a22858214db4dd2b5c4f0';
UPDATE public.pregnancy_daily_content SET baby_message = 'Mən bir qaragilə boydayam! 🫐 Ürəyim dəqiqədə 150-170 dəfə vurur. Bu, bir yarış atının ürəyi kimi sürətli və güclüdür! Sən zahirən sakit olsan da, mən içəridə marafon qaçıram. Sənin qəlbinlə mənim qəlbim eyni bədəndə, fərqli ritmlərlə, amma eyni sevgi ilə döyünür.', baby_message_en = 'I''m the size of a blueberry! 🫐 My heart beats 150-170 times a minute – as fast and strong as a racehorse! While you might seem calm on the outside, I''m running a marathon in here. Your heart and mine beat in the same body, with different rhythms but the same love.', baby_message_ru = 'Я размером с чернику! 🫐 Моё сердце бьётся 150-170 раз в минуту. Так же быстро и сильно, как сердце скаковой лошади! Хотя внешне вы спокойны, внутри я бегу марафон. Ваше сердце и моё сердце бьются в одном теле, в разных ритмах, но с одной любовью.', baby_message_tr = 'Ben bir yaban mersini büyüklüğündeyim! 🫐 Kalbim dakikada 150-170 kez atıyor. Bu, bir yarış atının kalbi kadar hızlı ve güçlü! Siz dışarıdan sakin görünseniz de ben içeride maraton koşuyorum. Sizin kalbinizle benim kalbim aynı bedende, farklı ritimlerle ama aynı sevgiyle atıyor.', baby_message_kk = 'Менің көлемім көкжидектей! 🫐 Жүрегім минутына 150-170 рет соғады. Бұл бәйге атының жүрегіндей жылдам әрі күшті! Сырттай Сіз тыныш көрінгеніңізбен, мен ішіңізде марафон жүгіріп жүрмін. Сіздің жүрегіңіз бен менің жүрегім бір денеде әртүрлі ырғақпен, бірақ бір махаббатпен соғып тұр.', baby_message_de = 'Ich bin so groß wie eine Heidelbeere! 🫐 Mein Herz schlägt 150-170 Mal pro Minute. Es ist so schnell und kräftig wie das Herz eines Rennpferdes! Auch wenn du von außen ruhig wirkst, laufe ich hier drinnen einen Marathon. Dein Herz und meines schlagen im selben Körper – in unterschiedlichen Rhythmen, aber mit derselben Liebe.', baby_message_ar = 'أنا بحجم حبة توت أزرق! 🫐 ينبض قلبي من 150-170 مرة في الدقيقة. إنه سريع وقوي مثل قلب حصان سباق! رغم أنكِ تبدين هادئة من الخارج، فإنني أركض في الداخل كما لو كنت أشارك في سباق ماراثون. قلبكِ وقلبي ينبضان داخل جسد واحد، بإيقاعين مختلفين، لكن بالحب نفسه.', baby_message_uz = 'Men ko‘k rezavor kattaligiman! 🫐 Yuragim daqiqasiga 150-170 marta urmoqda. Bu poyga otining yuragi kabi tez va kuchli! Siz tashqaridan xotirjam ko‘rinsangiz ham, men ichkarida marafon yuguryapman. Sizning qalbingiz va mening qalbim bir tanada, turli maromda, ammo bir xil mehr bilan urmoqda.', baby_message_ka = 'მე მოცვის ზომის ვარ! 🫐 ჩემი გული წუთში 150-170-ჯერ ცემს. ის ისეთივე სწრაფი და ძლიერია, როგორც სარბოლო ცხენის გული! გარეგნულად მშვიდად რომც იყოთ, მე შიგნით მარათონს გავრბივარ. შენი და ჩემი გული ერთ სხეულში, სხვადასხვა რიტმით, მაგრამ ერთნაირი სიყვარულით ცემს.', baby_message_zh = '我现在有蓝莓那么大了！🫐 我的心脏每分钟跳动 150-170 次，像赛马一样又快又有力！你外表看起来也许很平静，我却正在里面跑马拉松。你的心和我的心在同一个身体里跳动，节奏不同，爱却相同。', baby_message_id = 'Besarku sekarang seperti buah bluberi! 🫐 Jantungku berdetak 150-170 kali per menit—secepat dan sekuat kuda pacu! Meski dari luar Anda mungkin tampak tenang, di dalam sini aku sedang berlari maraton. Jantung Anda dan jantungku berdetak dalam tubuh yang sama, dengan irama berbeda tetapi cinta yang sama.', baby_message_fr = 'J’ai la taille d’une myrtille ! 🫐 Mon cœur bat 150 à 170 fois par minute, aussi vite et fort que celui d’un cheval de course ! Même si vous semblez calme de l’extérieur, moi, je cours un marathon ici. Votre cœur et le mien battent dans le même corps, à des rythmes différents, mais avec le même amour.', baby_message_es = '¡Tengo el tamaño de un arándano! 🫐 Mi corazón late entre 150 y 170 veces por minuto: ¡tan rápido y fuerte como un caballo de carreras! Aunque por fuera parezcas tranquila, aquí dentro estoy corriendo una maratón. Tu corazón y el mío laten en el mismo cuerpo, con ritmos diferentes, pero con el mismo amor.', baby_message_pt = 'Sou do tamanho de um mirtilo! 🫐 O meu coração bate 150-170 vezes por minuto — tão depressa e com tanta força como um cavalo de corrida! Embora pareças calma por fora, eu estou aqui dentro a correr uma maratona. O teu coração e o meu batem no mesmo corpo, com ritmos diferentes, mas com o mesmo amor.', baby_message_vi = 'Con lớn bằng một quả việt quất rồi! 🫐 Tim con đập 150-170 lần mỗi phút – nhanh và mạnh như một chú ngựa đua! Bên ngoài trông bạn có vẻ bình thản, nhưng trong này con đang chạy marathon đấy. Trái tim bạn và trái tim con cùng đập trong một cơ thể, khác nhịp nhưng chung một tình yêu.', baby_message_hi = 'मैं एक ब्लूबेरी जितना बड़ा हूँ! 🫐 मेरा दिल एक मिनट में 150-170 बार धड़कता है—दौड़ के घोड़े जितनी तेज़ी और ताकत से! बाहर से आप भले ही शांत दिखें, लेकिन मैं यहाँ अंदर मैराथन दौड़ रहा हूँ। आपका और मेरा दिल एक ही शरीर में धड़क रहे हैं—लय अलग है, लेकिन प्यार एक ही है।', baby_message_ja = 'ブルーベリーくらいの大きさになりました！🫐 心臓は一分間に150-170回も鼓動しています。競走馬のように速く、力強いです！ママは外から見ると穏やかでも、私は中でマラソンを走っています。ママと私の心臓は同じ体の中で、違うリズムを刻みながら、同じ愛でつながっています。', baby_message_ko = '저는 블루베리만 한 크기예요! 🫐 제 심장은 분당 150-170회 뛰어요. 경주마처럼 빠르고 힘차게요! 엄마는 겉으로 차분해 보여도 저는 이 안에서 마라톤을 뛰고 있어요. 엄마와 제 심장은 한 몸 안에서 서로 다른 리듬으로, 같은 사랑을 품고 뛰어요.', baby_message_pl = 'Jestem już wielkości borówki! 🫐 Moje serce bije 150-170 razy na minutę — szybko i mocno jak serce konia wyścigowego! Choć na zewnątrz możesz wyglądać spokojnie, tutaj w środku trwa mój maraton. Twoje serce i moje biją w jednym ciele — w różnych rytmach, ale z tą samą miłością.', baby_message_nl = 'Ik ben zo groot als een blauwe bes! 🫐 Mijn hart klopt 150-170 keer per minuut – zo snel en krachtig als dat van een renpaard! Jij lijkt vanbuiten misschien rustig, maar ik loop hierbinnen een marathon. Jouw hart en het mijne kloppen in hetzelfde lichaam, met een ander ritme maar dezelfde liefde.', baby_message_sv = 'Jag är stor som ett blåbär! 🫐 Mitt hjärta slår 150-170 gånger i minuten – lika snabbt och kraftfullt som hos en galopphäst! Du kanske ser lugn ut på utsidan, men här inne springer jag ett maraton. Ditt och mitt hjärta slår i samma kropp, med olika rytmer men samma kärlek.' WHERE id = '73404991-93fd-4ff5-9245-6a011e7e870b' AND md5(coalesce(baby_message,'')) = 'b47949959427be57b762729788c6458a' AND md5(coalesce(baby_message_en,'')) = '69629de60f3333635b2b214aaf226d6c' AND md5(coalesce(baby_message_ru,'')) = 'cd0db46e3eeebc7647ef3fd0ad8e9e17' AND md5(coalesce(baby_message_tr,'')) = '1d405e13f634075f29d0df481146fe77' AND md5(coalesce(baby_message_kk,'')) = 'ab61c0a76ff79fce1cfa9221d2e3117f' AND md5(coalesce(baby_message_de,'')) = 'aa6af2f4a67e1d7cc3d2e21b26090073' AND md5(coalesce(baby_message_ar,'')) = 'c9d80758dc68dd2aecdaa39f196a62b7' AND md5(coalesce(baby_message_uz,'')) = '17bd1f26f37bed3d467a79a9b962372b' AND md5(coalesce(baby_message_ka,'')) = 'ebf1b7d5c3081c0cfccb7d81fd0314f3' AND md5(coalesce(baby_message_zh,'')) = '2a472d4a698df878f639103bfe3460f3' AND md5(coalesce(baby_message_id,'')) = '07b838b458e7c1fe32451750786a6af5' AND md5(coalesce(baby_message_fr,'')) = '9a13f8ec7fb592d4627054dcd6db6464' AND md5(coalesce(baby_message_es,'')) = '6c6170fe92eadd8b20f7525212a85e0e' AND md5(coalesce(baby_message_pt,'')) = '7af5fdd821e7bf5be6be58c9236a2106' AND md5(coalesce(baby_message_vi,'')) = '01d1214296578f6b6989efadb993445e' AND md5(coalesce(baby_message_hi,'')) = '0bb9a76c7d4aa67760142c0e22b3eb51' AND md5(coalesce(baby_message_ja,'')) = '9881c5001eb49b4b0de1172a7ed36e2f' AND md5(coalesce(baby_message_ko,'')) = 'cd520716fff10c9c096190e935e67ec7' AND md5(coalesce(baby_message_pl,'')) = 'dd3d7197c83709bb9dfc238fd2856873' AND md5(coalesce(baby_message_nl,'')) = '43be08cd13c98e1437558a7790c8b528' AND md5(coalesce(baby_message_sv,'')) = 'cea24417e60962b1ba57308c42bf82f3';
UPDATE public.pregnancy_daily_content SET baby_message = 'Mən bir gilas boydayam! 🍒 Hər gün böyüyürəm və dəyişirəm. Qulaqlarım yavaş-yavaş başımın yanından yuxarıya, doğru yerlərinə qalxır. Gözlərim hələ bağlıdır, amma torlu qişam (retina) artıq işığı ayırd edə bilir. Sən günəşə çıxanda mən o istiliyi və parlaqlığı hiss edə biləcəm.', baby_message_en = 'I''m the size of a cherry! 🍒 I''m growing and changing every day. My ears are slowly moving from the side of my head upwards to their correct position. My eyes are still closed, but my retina can already distinguish light. When you go out in the sun, I''ll be able to feel that warmth and brightness.', baby_message_ru = 'Я размером с черешню! 🍒 Я расту и меняюсь каждый день. Мои уши постепенно перемещаются вверх по бокам головы, занимая правильное положение. Глаза пока закрыты, но сетчатка уже способна различать свет. Когда вы выйдете на солнце, я смогу почувствовать его тепло и яркость.', baby_message_tr = 'Ben bir kiraz büyüklüğündeyim! 🍒 Her gün büyüyor ve değişiyorum. Kulaklarım yavaş yavaş başımın yanlarından yukarıya, olmaları gereken yerlere doğru ilerliyor. Gözlerim hâlâ kapalı ama ağ tabakam (retina) artık ışığı ayırt edebiliyor. Sen güneşe çıktığında ben de o sıcaklığı ve parlaklığı hissedebileceğim.', baby_message_kk = 'Менің көлемім шиедей! 🍒 Күн сайын өсіп, өзгеріп келемін. Құлақтарым басымның жанынан біртіндеп жоғары көтеріліп, өз орындарына орналасып жатыр. Көздерім әлі жұмулы, бірақ торлы қабығым (ретина) жарықты ажырата алады. Сіз күнге шыққанда, мен оның жылуы мен жарығын сезе аламын.', baby_message_de = 'Ich bin so groß wie eine Kirsche! 🍒 Jeden Tag wachse und verändere ich mich. Meine Ohren wandern langsam von der Seite meines Kopfes nach oben an ihre richtige Position. Meine Augen sind noch geschlossen, aber meine Netzhaut (Retina) kann bereits Licht wahrnehmen. Wenn du in die Sonne gehst, werde ich diese Wärme und Helligkeit spüren können.', baby_message_ar = 'أنا بحجم حبة كرز! 🍒 أكبر وأتغير كل يوم. وتتحرك أذناي ببطء من جانبي رأسي إلى الأعلى حتى تصلا إلى موضعهما الصحيح. لا تزال عيناي مغلقتين، لكن شبكيتي (retina) أصبحت قادرة على تمييز الضوء. وعندما تخرجين إلى الشمس، سأتمكن من الشعور بدفئها وسطوعها.', baby_message_uz = 'Men bir dona gilosdek kattaman! 🍒 Har kuni o‘sib, o‘zgarib boryapman. Quloqlarim asta-sekin boshimning yon qismidan yuqoriga, o‘z joyiga ko‘tarilyapti. Ko‘zlarim hali yumuq, ammo to‘r pardam (retina) allaqachon yorug‘likni farqlay oladi. Siz quyoshga chiqqaningizda, men uning iliqligi va yorqinligini his qila olaman.', baby_message_ka = 'ბლის ზომის ვარ! 🍒 ყოველდღე ვიზრდები და ვიცვლები. ჩემი ყურები ნელ-ნელა თავის გვერდებიდან ზემოთ, თავიანთ სწორ ადგილას ინაცვლებს. თვალები ჯერ კიდევ დახუჭული მაქვს, მაგრამ ჩემს ბადურას (რეტინას) უკვე შეუძლია სინათლის გარჩევა. როდესაც მზეზე გახვალთ, ამ სითბოსა და სიკაშკაშეს ვიგრძნობ.', baby_message_zh = '我已经有一颗樱桃那么大啦！🍒 我每天都在成长和变化。我的耳朵正慢慢从头部两侧向上移动到正确的位置。虽然眼睛仍然闭着，但视网膜已经能分辨光线。你走到阳光下时，我也能感受到那份温暖和明亮。', baby_message_id = 'Ukuranku sebesar buah ceri! 🍒 Aku tumbuh dan berubah setiap hari. Telingaku perlahan bergerak naik dari sisi kepala menuju posisi yang tepat. Mataku masih tertutup, tetapi retinaku sudah dapat membedakan cahaya. Saat Anda berada di bawah sinar matahari, aku bisa merasakan kehangatan dan terangnya.', baby_message_fr = 'J’ai la taille d’une cerise ! 🍒 Je grandis et je change chaque jour. Mes oreilles remontent doucement depuis les côtés de ma tête pour atteindre leur position définitive. Mes yeux sont encore fermés, mais ma rétine peut déjà percevoir la lumière. Lorsque vous sortez au soleil, je peux en ressentir la chaleur et la luminosité.', baby_message_es = '¡Tengo el tamaño de una cereza! 🍒 Crezco y cambio cada día. Mis orejas se desplazan poco a poco desde los lados de la cabeza hacia arriba, hasta alcanzar su posición correcta. Mis ojos todavía están cerrados, pero mi retina ya puede distinguir la luz. Cuando salgas al sol, podré sentir su calor y su brillo.', baby_message_pt = 'Sou do tamanho de uma cereja! 🍒 Cresço e mudo todos os dias. As minhas orelhas estão a deslocar-se lentamente dos lados da cabeça para cima, até à posição correta. Os meus olhos continuam fechados, mas a retina já consegue distinguir a luz. Quando estiveres ao sol, conseguirei sentir o calor e a claridade.', baby_message_vi = 'Con có kích thước bằng một quả anh đào! 🍒 Con đang lớn lên và thay đổi mỗi ngày. Tai con đang từ từ dịch chuyển từ hai bên đầu lên đúng vị trí. Mắt con vẫn nhắm, nhưng võng mạc đã có thể phân biệt ánh sáng. Khi mẹ ra ngoài trời nắng, con sẽ cảm nhận được hơi ấm và ánh sáng ấy.', baby_message_hi = 'मैं एक चेरी जितना बड़ा हूँ! 🍒 मैं हर दिन बढ़ और बदल रहा हूँ। मेरे कान धीरे-धीरे सिर के किनारों से ऊपर अपनी सही जगह की ओर बढ़ रहे हैं। मेरी आँखें अभी भी बंद हैं, लेकिन मेरी रेटिना अभी से रोशनी पहचान सकती है। जब आप धूप में बाहर जाएँगी, तो मैं उसकी गर्माहट और चमक महसूस कर सकूँगा।', baby_message_ja = 'サクランボくらいの大きさだよ！🍒 毎日成長して、変化しているんだ。耳は頭の横から、正しい位置へ向かって少しずつ上に移動しているよ。目はまだ閉じているけれど、網膜はもう光を見分けられるんだ。ママが日の当たる場所に出ると、その暖かさと明るさを僕も感じられるよ。', baby_message_ko = '저는 체리만 해요! 🍒 날마다 자라고 변하고 있어요. 귀는 머리 옆쪽에서 올바른 위치로 천천히 올라가고 있어요. 눈은 아직 감겨 있지만 망막은 벌써 빛을 구별할 수 있어요. 엄마가 햇볕을 쬐러 나가면 저도 그 따뜻함과 밝음을 느낄 수 있어요.', baby_message_pl = 'Mam wielkość czereśni! 🍒 Każdego dnia rosnę i się zmieniam. Moje uszy powoli przesuwają się z boków głowy w górę, na właściwe miejsce. Oczy są jeszcze zamknięte, ale siatkówka potrafi już odróżnić światło od ciemności. Kiedy wychodzisz na słońce, czuję jego ciepło i blask.', baby_message_nl = 'Ik ben zo groot als een kers! 🍒 Ik groei en verander elke dag. Mijn oren verschuiven langzaam vanaf de zijkant van mijn hoofd omhoog naar de juiste plek. Mijn ogen zijn nog gesloten, maar mijn netvlies kan licht al onderscheiden. Als je in de zon komt, kan ik die warmte en helderheid voelen.', baby_message_sv = 'Jag är lika stor som ett körsbär! 🍒 Jag växer och förändras varje dag. Mina öron flyttar sig långsamt uppåt från sidorna av huvudet till rätt plats. Mina ögon är fortfarande slutna, men näthinnan kan redan skilja mellan ljus och mörker. När du går ut i solen kan jag känna värmen och ljuset.' WHERE id = '56fa6e29-fd7a-4a03-984e-0590d982556b' AND md5(coalesce(baby_message,'')) = '09eda6afd2b3c3906ab21f029cf9a63f' AND md5(coalesce(baby_message_en,'')) = 'dcd48da85d4f9033f7b588cab38c037a' AND md5(coalesce(baby_message_ru,'')) = '2b5680c22f36ec3ab75c68c0109bfa75' AND md5(coalesce(baby_message_tr,'')) = 'e9375a8e33a5e4c63e241fc1c67484dc' AND md5(coalesce(baby_message_kk,'')) = 'f3765059bd45f16508658438df332205' AND md5(coalesce(baby_message_de,'')) = '210620a8eca5147eb46bea8bd3a4e08c' AND md5(coalesce(baby_message_ar,'')) = '7a95c41d70ff245675d9029f175dd920' AND md5(coalesce(baby_message_uz,'')) = 'c188cf25357de83321b559cdcdf1f694' AND md5(coalesce(baby_message_ka,'')) = 'ea2c16ec873605cf027900a50ce51fb7' AND md5(coalesce(baby_message_zh,'')) = '05a7ac3bbe405daf07e3cc461fe2e7cf' AND md5(coalesce(baby_message_id,'')) = '52b1c4baa2db3196700991713efed429' AND md5(coalesce(baby_message_fr,'')) = '2f49f37f4c599965715e723f84f6b4f8' AND md5(coalesce(baby_message_es,'')) = '6eee1ddcae4158f9275744f2018cca3f' AND md5(coalesce(baby_message_pt,'')) = '39b555940ab4e24fb5dfe3bd7bd60c3c' AND md5(coalesce(baby_message_vi,'')) = '0cb9169cf82e4e741789eda62674126a' AND md5(coalesce(baby_message_hi,'')) = 'bf5a0f54bd0ef38b87849c55aad73837' AND md5(coalesce(baby_message_ja,'')) = '920f02da33263e71e9f9d205f37e6c60' AND md5(coalesce(baby_message_ko,'')) = 'd54bdab6af267fd8427643a787d8deee' AND md5(coalesce(baby_message_pl,'')) = '27f75d8caf26ce339796f81f239c7a81' AND md5(coalesce(baby_message_nl,'')) = '42aca577118bc6322fbe2e23543aeb79' AND md5(coalesce(baby_message_sv,'')) = '6a4b0ede2d445325b31bd829ece02672';
UPDATE public.pregnancy_daily_content SET baby_message = '10 HƏFTƏ! İKİ RƏQƏMLİ TƏQVİM! 🔟 Anacan, biz artıq 10-cu həftədəyik. Mən rəsmən böyüyürəm. İndi bir gilas boydayam. Ən vacib inkişaf mərhələlərini bitirdim. İndi sadəcə kökəlmək, uzanmaq və səninlə görüşə hazırlaşmaq qalıb. Biz yolun dörddə birini demək olar ki, bitirdik! Səninlə fəxr edirəm.', baby_message_en = '10 WEEKS! DOUBLE DIGITS! 🔟 Anacan, we''re already in our 10th week! I''m officially growing bigger. I''m now the size of a cherry. I''ve completed the most crucial developmental stages. Now, all that''s left is to gain weight, grow longer, and get ready to meet you. We''ve almost completed a quarter of the journey! I''m so proud of you.', baby_message_ru = '10 НЕДЕЛЬ! ДВУЗНАЧНОЕ ЧИСЛО В КАЛЕНДАРЕ! 🔟 мамочка, у нас уже 10-я неделя. Я официально становлюсь большим малышом. Сейчас я размером с черешню. Самые важные этапы развития уже позади. Теперь мне осталось лишь набирать вес, расти и готовиться к встрече с вами. Мы прошли уже почти четверть пути! Я горжусь вами.', baby_message_tr = '10 HAFTA! İKİ HANELİ TAKVİM! 🔟 anneciğim, artık 10. haftadayız. Resmen büyüyorum. Şimdi bir kiraz büyüklüğündeyim. En önemli gelişim aşamalarını tamamladım. Artık sadece kilo almak, uzamak ve sizinle buluşmaya hazırlanmak kaldı. Yolun neredeyse dörtte birini tamamladık! Sizinle gurur duyuyorum.', baby_message_kk = '10 АПТА! КҮНТІЗБЕДЕГІ ЕКІ ТАҢБАЛЫ САН! 🔟 анашым, біз 10-шы аптаға жеттік. Мен ресми түрде өсіп келемін. Қазір көлемім шиедей. Дамуымның ең маңызды кезеңдерін аяқтадым. Енді тек салмақ қосып, бойымды ұзартып, Сізбен кездесуге дайындалуым қалды. Біз жолдың төрттен бір бөлігін аяқтауға жақынбыз! Сізді мақтан тұтамын.', baby_message_de = '10 WOCHEN! ENDLICH ZWEISTELLIG! 🔟 Mami, wir sind jetzt schon in der 10. Woche. Ich werde offiziell immer größer. Im Moment bin ich so groß wie eine Kirsche. Die wichtigsten Entwicklungsphasen habe ich abgeschlossen. Jetzt muss ich nur noch zunehmen, wachsen und mich auf unser Treffen vorbereiten. Wir haben schon fast ein Viertel des Weges geschafft! Ich bin stolz auf dich.', baby_message_ar = '10 أسابيع! دخلنا الأرقام المزدوجة! 🔟 ماما، لقد وصلنا إلى الأسبوع 10. أنا أكبر رسميًا! أصبح حجمي الآن بحجم حبة كرز. لقد اجتزت أهم مراحل النمو، ولم يتبقَّ لي سوى اكتساب الوزن والطول والاستعداد للقائكِ. لقد قطعنا ما يقارب ربع الطريق! أنا فخور بكِ.', baby_message_uz = '10 HAFTA! TAQVIMDA IKKI XONALI SON! 🔟 Onajon, biz allaqachon 10-haftadamiz. Men rasman ulg‘ayyapman. Hozir gilosdek kattalikdaman. Rivojlanishning eng muhim bosqichlarini yakunladim. Endi faqat vazn yig‘ish, bo‘yim o‘sishi va siz bilan uchrashishga tayyorlanishim qoldi. Biz yo‘lning deyarli chorak qismini bosib o‘tdik! Siz bilan faxrlanaman.', baby_message_ka = '10 კვირა! უკვე ორნიშნა რიცხვია! 🔟 დედიკო, უკვე მე-10 კვირაში ვართ. ოფიციალურად ვიზრდები. ახლა ბლის ზომის ვარ. განვითარების ყველაზე მნიშვნელოვანი ეტაპები უკვე გავიარე. ახლა მხოლოდ წონის მომატება, სიგრძეში ზრდა და შენთან შესახვედრად მომზადება დამრჩა. გზის თითქმის მეოთხედი უკვე გავიარეთ! შენით ვამაყობ.', baby_message_zh = '10 周啦！进入两位数！🔟 Anacan，我们已经来到第 10 周了！我正式进入快速长大的阶段。现在的我有一颗樱桃那么大，也已经完成了最关键的发育阶段。接下来只需要增加体重、长高一些，并准备与你见面。我们的旅程已经快走完四分之一了！我真为你骄傲。', baby_message_id = '10 MINGGU! DUA DIGIT! 🔟 Anacan, kita sudah memasuki minggu ke-10! Aku resmi tumbuh semakin besar. Sekarang besarku seukuran buah ceri. Aku telah melewati tahap-tahap perkembangan yang paling penting. Kini, aku hanya perlu menambah berat badan, tumbuh lebih panjang, dan bersiap bertemu dengan Anda. Kita hampir menyelesaikan seperempat perjalanan! Aku sangat bangga kepada Anda.', baby_message_fr = '10 SEMAINES ! DEUX CHIFFRES ! 🔟 Anacan, nous sommes déjà dans notre 10e semaine ! Je grandis officiellement. J''ai maintenant la taille d''une cerise. J''ai franchi les étapes les plus cruciales de mon développement. Il ne me reste plus qu''à prendre du poids, à m''allonger et à me préparer à vous rencontrer. Nous avons presque parcouru un quart du chemin ! Je suis tellement fier de vous.', baby_message_es = '¡10 SEMANAS! ¡DOS DÍGITOS! 🔟 Anacan, ¡ya estamos en la semana 10! Oficialmente, cada vez soy más grande. Ahora tengo el tamaño de una cereza. He completado las etapas más importantes de mi desarrollo. Ya solo me queda ganar peso, crecer y prepararme para conocerte. ¡Casi hemos completado una cuarta parte del camino! Estoy muy orgulloso de ti.', baby_message_pt = '10 SEMANAS! DOIS DÍGITOS! 🔟 Anacan, já estamos na semana 10! Estou oficialmente a ficar maior. Agora sou do tamanho de uma cereja. Já completei as fases mais importantes do desenvolvimento. Agora, só falta ganhar peso, crescer em comprimento e preparar-me para te conhecer. Estamos quase a completar um quarto da viagem! Tenho tanto orgulho em ti.', baby_message_vi = '10 TUẦN! ĐÃ SANG HÀNG CHỤC RỒI! 🔟 Anacan ơi, chúng ta đã bước sang tuần thứ 10! Con chính thức lớn hơn rồi. Giờ con lớn bằng một quả anh đào. Con đã hoàn thành những giai đoạn phát triển quan trọng nhất. Giờ con chỉ cần tăng cân, dài thêm và sẵn sàng gặp mẹ. Chúng ta đã gần hoàn thành một phần tư hành trình rồi! Con tự hào về mẹ lắm.', baby_message_hi = '10 सप्ताह! दो अंकों में पहुँच गए! 🔟 Anacan, हम अपने 10वें सप्ताह में पहुँच चुके हैं! अब मैं आधिकारिक तौर पर बड़ा/बड़ी हो रहा/रही हूँ। मैं अब एक चेरी जितना/जितनी हूँ। मैंने विकास के सबसे महत्वपूर्ण चरण पूरे कर लिए हैं। अब बस वज़न बढ़ाना, लंबा होना और आपसे मिलने के लिए तैयार होना बाकी है। हमने सफ़र का लगभग एक-चौथाई हिस्सा पूरा कर लिया है! मुझे आप पर बहुत गर्व है।', baby_message_ja = '10週！ ついに二桁！ 🔟 Anacan、もう妊娠10週目だよ！ 正式にぐんぐん大きくなる時期に入ったんだ。今はサクランボくらいの大きさだよ。最も重要な発達段階は完了したんだ。これからは体重を増やし、身長を伸ばして、ママに会う準備をするだけ。旅のほぼ四分の一まで来たよ！ ママをとても誇りに思うよ。', baby_message_ko = '10주! 두 자릿수예요! 🔟 Anacan, 벌써 10주 차예요! 이제 공식적으로 더 크게 자라고 있어요. 지금 저는 체리만 해요. 가장 중요한 발달 단계도 모두 마쳤어요. 이제 몸무게를 늘리고, 몸이 더 길어지고, 엄마를 만날 준비만 하면 돼요. 여정의 사분의 일을 거의 마쳤어요! 엄마가 정말 자랑스러워요.', baby_message_pl = '10 TYGODNI! DWUCYFROWY WYNIK! 🔟 Anacan, jesteśmy już w 10. tygodniu! Oficjalnie robię się coraz większe. Teraz mam wielkość czereśni. Najważniejsze etapy mojego rozwoju są już za mną. Teraz pozostaje tylko przybierać na wadze, rosnąć i przygotowywać się na spotkanie z Tobą. Mamy za sobą już prawie jedną czwartą drogi! Rozpiera mnie duma z Ciebie.', baby_message_nl = '10 WEKEN! TWEE CIJFERS! 🔟 Anacan, we zitten al in week 10! Ik word nu officieel steeds groter. Ik ben zo groot als een kers. De belangrijkste ontwikkelingsfasen heb ik afgerond. Nu hoef ik alleen nog maar aan te komen, langer te worden en me voor te bereiden op onze ontmoeting. We hebben bijna een kwart van de reis afgelegd! Ik ben zo trots op je.', baby_message_sv = '10 VECKOR! TVÅSIFFRIGT! 🔟 Anacan, vi är redan i vecka 10! Nu växer jag verkligen och blir större. Jag är stor som ett körsbär. Jag har klarat av de allra viktigaste utvecklingsstadierna. Nu återstår bara att gå upp i vikt, bli längre och göra mig redo att träffa dig. Vi har nästan klarat en fjärdedel av resan! Jag är så stolt över dig.' WHERE id = '686eb070-eff8-4d42-a409-9b1b933ed8cf' AND md5(coalesce(baby_message,'')) = '034cc726d8997fe11d2b8a69b2c69da6' AND md5(coalesce(baby_message_en,'')) = 'f8c440ed2df901e75b059f3c843045b1' AND md5(coalesce(baby_message_ru,'')) = 'd5160afba9931e1f4f4fe916b98de869' AND md5(coalesce(baby_message_tr,'')) = '93d40f0bc35345b0bf81a0803000c315' AND md5(coalesce(baby_message_kk,'')) = '0ec4994a92e5804619944940259c0b43' AND md5(coalesce(baby_message_de,'')) = '9b752e0232eb0034340cb7d136ec80a2' AND md5(coalesce(baby_message_ar,'')) = 'a6e8c57f9c7a9d151e8230848e66d2fa' AND md5(coalesce(baby_message_uz,'')) = '1250a6a83309274f61e3b5a4bdfdde0b' AND md5(coalesce(baby_message_ka,'')) = '2a0b38838b827eb8c82af0ba2e495d83' AND md5(coalesce(baby_message_zh,'')) = '1b963e2f1adcf2f95f0ad1d797d64733' AND md5(coalesce(baby_message_id,'')) = 'ef0175ed66fb3674b87cb76710615522' AND md5(coalesce(baby_message_fr,'')) = '42feb8d67366ee54a1abf70be9e21619' AND md5(coalesce(baby_message_es,'')) = 'ad78f03723744446e4f1af6754c0d746' AND md5(coalesce(baby_message_pt,'')) = '23c3bed4e900c8f27dcafbb4b0757b85' AND md5(coalesce(baby_message_vi,'')) = '33f404f7e67eee49cba1508cee08eb57' AND md5(coalesce(baby_message_hi,'')) = 'a3f1041c76614cf205bfca4a21c35240' AND md5(coalesce(baby_message_ja,'')) = 'f38d9cfe48fbbda0a8e3f30654eacf12' AND md5(coalesce(baby_message_ko,'')) = 'c3ffe79df5f36262d295ef6fd0c9161d' AND md5(coalesce(baby_message_pl,'')) = 'c1b0722eafaac406d54626e53aa9d9e0' AND md5(coalesce(baby_message_nl,'')) = '0fc200c92dd2e7d2fb66be246ac79ad9' AND md5(coalesce(baby_message_sv,'')) = '4203cd0a30a976b76f8072dd7a5bf458';
UPDATE public.pregnancy_daily_content SET baby_development = 'Körpəniz artıq 4-5 sm boyunda və 7-8 qram çəkidədir. Quyruq hissəsi tamamilə yox olub və embrion dövrü başa çatıb. İndi bütün orqanlar öz yerindədir və sürətli böyümə mərhələsi başlayır. Növbəti 8 həftə ərzində o, indikindən 30 dəfə ağır və 3 dəfə uzun olacaq. Bu böyüməni dəstəkləmək üçün bədəninizdə qan miqdarı və damarların sayı artır. Hazırda başı bədəninə nisbətən böyük görünsə də, tezliklə bədən üzvləri daha mütənasib olacaq. Barmaqları artıq uzanıb; o, sadəcə yumruq sıxmır, həm də əllərini açaraq ətrafını kəşf etməyə başlayır.', baby_development_en = 'Your baby is now about 4-5 cm long and weighs 7-8 grams. The tail has completely disappeared, marking the end of the embryonic period. All organs are now in place, and a rapid growth phase is beginning. Over the next 8 weeks, your baby will become 30 times heavier and 3 times longer than they are now. To support this growth, the volume of blood in your body and the number of blood vessels are increasing. Although your baby''s head may appear large relative to their body at this stage, their body parts will soon become more proportionate. Their fingers have already lengthened; they''re not just making a fist, but also opening their hands and beginning to explore their surroundings.', baby_development_ru = 'Ваш малыш уже достиг 4-5 см в длину и весит 7-8 граммов. Хвостик полностью исчез, и эмбриональный период завершился. Теперь все органы находятся на своих местах, и начинается этап быстрого роста. В течение следующих 8 недель малыш станет в 30 раз тяжелее и в 3 раза длиннее, чем сейчас. Чтобы поддержать этот рост, в вашем организме увеличиваются объём крови и количество кровеносных сосудов. Сейчас голова малыша выглядит большой по сравнению с телом, но вскоре пропорции тела станут более гармоничными. Пальчики уже удлинились; теперь малыш не только сжимает кулачки, но и раскрывает ладони, начиная исследовать окружающее пространство.', baby_development_tr = 'Bebeğiniz artık 4-5 cm boyunda ve 7-8 gram ağırlığında. Kuyruk kısmı tamamen kayboldu ve embriyonik dönem sona erdi. Artık tüm organları yerli yerinde ve hızlı büyüme dönemi başlıyor. Önümüzdeki 8 hafta boyunca şu ankinden 30 kat daha ağır ve 3 kat daha uzun olacak. Bu büyümeyi desteklemek için vücudunuzdaki kan miktarı ve damarların sayısı artıyor. Şu anda başı vücuduna göre büyük görünse de çok yakında vücut bölümleri daha orantılı hâle gelecek. Parmakları artık uzadı; yalnızca yumruklarını sıkmakla kalmıyor, ellerini açarak çevresini keşfetmeye de başlıyor.', baby_development_kk = 'Бөпеңіздің бойы қазірдің өзінде 4-5 см, ал салмағы 7-8 грамм. Құйрық бөлігі толығымен жойылып, эмбриондық кезең аяқталды. Енді барлық ағзалары өз орнында және қарқынды өсу кезеңі басталады. Алдағы 8 апта ішінде оның салмағы қазіргіден 30 есе артып, бойы 3 есе ұзарады. Бұл өсуді қамтамасыз ету үшін ағзаңыздағы қан көлемі мен қан тамырларының саны көбейеді. Қазір басы денесіне қарағанда үлкен болып көрінгенімен, көп ұзамай дене мүшелерінің пропорциясы үйлесімді бола түседі. Саусақтары ұзарып қалды; енді ол жұдырығын түйіп қана қоймай, қолдарын ашып, айналасын зерттей бастайды.', baby_development_de = 'Dein Baby ist jetzt bereits 4-5 cm groß und wiegt 7-8 Gramm. Der kleine Schwanz ist vollständig verschwunden und die Embryonalphase ist abgeschlossen. Nun befinden sich alle Organe an ihrem Platz und die Phase des schnellen Wachstums beginnt. In den nächsten 8 Wochen wird dein Baby 30-mal so schwer und 3-mal so groß sein wie jetzt. Um dieses Wachstum zu unterstützen, nehmen die Blutmenge und die Anzahl der Blutgefäße in deinem Körper zu. Der Kopf wirkt im Verhältnis zum Körper momentan noch groß, doch schon bald werden die Körperteile proportionaler sein. Die Finger sind bereits länger geworden; dein Baby ballt nicht nur die Hände zu Fäusten, sondern beginnt auch, sie zu öffnen und seine Umgebung zu erkunden.', baby_development_ar = 'يبلغ طول طفلكِ الآن 4-5 سم ووزنه 7-8 غرامات. وقد اختفى الذيل تمامًا وانتهت المرحلة الجنينية المبكرة. أصبحت جميع أعضائه الآن في أماكنها، وبدأت مرحلة النمو السريع. خلال الأسابيع الـ8 المقبلة، سيصبح وزنه أكبر بـ30 مرة وطوله أكبر بـ3 مرات مما هو عليه الآن. ولدعم هذا النمو، تزداد كمية الدم وعدد الأوعية الدموية في جسمكِ. ورغم أن رأسه يبدو حاليًا كبيرًا مقارنة بجسمه، فسرعان ما ستصبح أعضاء جسمه أكثر تناسقًا. وقد طالت أصابعه الآن؛ فلم يعد يكتفي بقبض يديه، بل بدأ يفتحهما لاستكشاف ما حوله.', baby_development_uz = 'Chaqalog‘ingizning bo‘yi hozir 4-5 sm, vazni esa 7-8 gramm. Dum qismi butunlay yo‘qolgan va embrional davr yakunlangan. Endi barcha a’zolar o‘z joyida va jadal o‘sish bosqichi boshlanmoqda. Keyingi 8 hafta ichida uning vazni hozirgidan 30 baravar, bo‘yi esa 3 baravar ortadi. Bu o‘sishni ta’minlash uchun tanangizdagi qon miqdori va qon tomirlari soni ko‘payadi. Hozircha boshi tanasiga nisbatan katta ko‘rinsa-da, tez orada tana a’zolari mutanosiblashadi. Barmoqlari allaqachon uzaygan; endi u nafaqat mushtini tugadi, balki qo‘llarini ochib, atrofini o‘rganishni ham boshlaydi.', baby_development_ka = 'თქვენი ბავშვი უკვე 4-5 სმ სიგრძისაა და 7-8 გრამს იწონის. კუდისებრი ნაწილი მთლიანად გაქრა და ემბრიონული პერიოდი დასრულდა. ახლა ყველა ორგანო თავის ადგილზეა და სწრაფი ზრდის ეტაპი იწყება. მომდევნო 8 კვირის განმავლობაში ის ახლანდელთან შედარებით 30-ჯერ უფრო მძიმე და 3-ჯერ უფრო გრძელი გახდება. ამ ზრდის მხარდასაჭერად თქვენს ორგანიზმში სისხლის მოცულობა და სისხლძარღვების რაოდენობა იზრდება. ამჟამად თავი სხეულთან შედარებით დიდი ჩანს, თუმცა მალე სხეულის ნაწილები უფრო პროპორციული გახდება. თითები უკვე დაგრძელდა; ის მხოლოდ მუშტებს კი აღარ კრავს, არამედ ხელებსაც შლის და გარემოს შესწავლას იწყებს.', baby_development_zh = '宝宝现在身长约 4-5 cm，体重约 7-8 克。尾部已经完全消失，标志着胚胎期结束。所有器官现已就位，即将进入快速生长阶段。在接下来的 8 周内，宝宝的体重将增至现在的 30 倍，身长将增至现在的 3 倍。为了支持宝宝生长，你体内的血容量和血管数量都在增加。虽然现阶段宝宝的头部相对于身体看起来较大，但身体各部位很快会变得更加匀称。宝宝的手指已经变长，不仅会握拳，还会张开双手，开始探索周围的环境。', baby_development_id = 'Bayi Anda kini memiliki panjang sekitar 4-5 cm dan berat 7-8 gram. Ekornya telah menghilang sepenuhnya, menandai berakhirnya periode embrio. Semua organ kini sudah berada di tempatnya dan fase pertumbuhan pesat segera dimulai. Selama 8 minggu ke depan, berat bayi Anda akan menjadi 30 kali lipat dan panjangnya 3 kali lipat dibandingkan sekarang. Untuk mendukung pertumbuhan ini, volume darah dalam tubuh Anda dan jumlah pembuluh darah meningkat. Meskipun kepala bayi Anda mungkin tampak besar dibandingkan tubuhnya pada tahap ini, bagian-bagian tubuhnya akan segera menjadi lebih proporsional. Jari-jarinya sudah memanjang; ia tidak hanya mengepalkan tangan, tetapi juga membukanya dan mulai menjelajahi lingkungan sekitarnya.', baby_development_fr = 'Votre bébé mesure maintenant environ 4-5 cm et pèse entre 7 et 8 grammes. Sa queue a complètement disparu, marquant la fin de la période embryonnaire. Tous ses organes sont désormais en place et une phase de croissance rapide commence. Au cours des 8 prochaines semaines, votre bébé pèsera 30 fois plus et sera 3 fois plus long qu’aujourd’hui. Pour soutenir cette croissance, le volume de sang dans votre corps et le nombre de vaisseaux sanguins augmentent. Même si la tête de votre bébé peut sembler volumineuse par rapport à son corps à ce stade, les différentes parties de son corps deviendront bientôt plus proportionnées. Ses doigts se sont déjà allongés : votre bébé ne se contente plus de fermer le poing, il ouvre également les mains et commence à explorer son environnement.', baby_development_es = 'Tu bebé mide ahora unos 4-5 cm y pesa entre 7 y 8 gramos. La cola ha desaparecido por completo, lo que marca el final del periodo embrionario. Todos los órganos están ya en su sitio y comienza una fase de crecimiento rápido. Durante las próximas 8 semanas, tu bebé llegará a pesar 30 veces más y a medir 3 veces más que ahora. Para favorecer este crecimiento, están aumentando el volumen de sangre de tu cuerpo y el número de vasos sanguíneos. Aunque en esta etapa la cabeza de tu bebé pueda parecer grande en comparación con el cuerpo, pronto sus partes corporales serán más proporcionadas. Sus dedos ya se han alargado: no solo cierra los puños, sino que también abre las manos y empieza a explorar su entorno.', baby_development_pt = 'O seu bebé mede agora cerca de 4-5 cm e pesa entre 7 e 8 gramas. A cauda desapareceu por completo, assinalando o fim do período embrionário. Todos os órgãos já estão formados e começa agora uma fase de crescimento rápido. Durante as próximas 8 semanas, o seu bebé ficará 30 vezes mais pesado e 3 vezes mais comprido do que é atualmente. Para apoiar este crescimento, o volume de sangue no seu corpo e o número de vasos sanguíneos estão a aumentar. Embora, nesta fase, a cabeça do seu bebé possa parecer grande em relação ao corpo, em breve as diferentes partes do corpo ficarão mais proporcionais. Os dedos já se alongaram; o bebé não se limita a cerrar os punhos, também abre as mãos e começa a explorar o que o rodeia.', baby_development_vi = 'Bé hiện dài khoảng 4-5 cm và nặng 7-8 gram. Đuôi đã biến mất hoàn toàn, đánh dấu sự kết thúc của giai đoạn phôi thai. Tất cả các cơ quan giờ đã hình thành đúng vị trí và giai đoạn tăng trưởng nhanh đang bắt đầu. Trong 8 tuần tới, cân nặng của bé sẽ gấp 30 lần và chiều dài sẽ gấp 3 lần hiện tại. Để hỗ trợ sự tăng trưởng này, thể tích máu trong cơ thể bạn và số lượng mạch máu đang tăng lên. Mặc dù ở giai đoạn này, đầu của bé có thể trông lớn so với cơ thể, nhưng các bộ phận sẽ sớm trở nên cân đối hơn. Các ngón tay của bé đã dài ra; bé không chỉ nắm tay mà còn mở bàn tay và bắt đầu khám phá môi trường xung quanh.', baby_development_hi = 'आपका शिशु अब लगभग 4-5 सेमी लंबा है और उसका वजन 7-8 ग्राम है। पूंछ पूरी तरह गायब हो चुकी है, जो भ्रूणीय अवधि के अंत का संकेत है। अब सभी अंग अपनी जगह पर हैं और तेज़ी से बढ़ने का चरण शुरू हो रहा है। अगले 8 सप्ताहों में आपके शिशु का वजन अभी की तुलना में 30 गुना और लंबाई 3 गुना हो जाएगी। इस वृद्धि में मदद के लिए आपके शरीर में रक्त की मात्रा और रक्त वाहिकाओं की संख्या बढ़ रही है। इस चरण में आपके शिशु का सिर शरीर की तुलना में बड़ा दिख सकता है, लेकिन जल्द ही उसके शरीर के अंग अधिक समानुपातिक हो जाएंगे। उसकी उंगलियां पहले ही लंबी हो चुकी हैं; अब वह न केवल मुट्ठी बना रहा है, बल्कि हाथ खोलकर अपने आसपास की चीज़ों को समझना भी शुरू कर रहा है।', baby_development_ja = '赤ちゃんは現在、身長が約4-5 cm、体重が7-8 gramsです。しっぽは完全になくなり、胎芽期が終わりました。すべての臓器が所定の位置に整い、急速な成長期が始まります。今後8週間で、赤ちゃんの体重は現在の30倍、身長は3倍になります。この成長を支えるため、あなたの体内では血液量と血管の数が増えています。この時期は赤ちゃんの頭が体に比べて大きく見えますが、まもなく体の各部分の比率が整っていきます。指はすでに長くなり、握りこぶしを作るだけでなく、手を開いて周囲を探るようになっています。', baby_development_ko = '아기는 이제 키가 약 4-5 cm이고 몸무게는 7-8그램이에요. 꼬리가 완전히 사라지면서 배아기가 끝났어요. 모든 장기가 자리를 잡았고 이제 빠르게 성장하는 시기가 시작돼요. 앞으로 8주 동안 아기의 몸무게는 지금의 30배, 키는 3배가 돼요. 이러한 성장을 돕기 위해 엄마 몸의 혈액량과 혈관 수가 늘어나고 있어요. 이 시기에는 아기의 머리가 몸에 비해 커 보일 수 있지만, 곧 신체 각 부분의 비율이 점차 균형을 이루게 돼요. 손가락도 이미 길어져서 주먹만 쥐는 것이 아니라 손을 펴고 주변을 탐색하기 시작해요.', baby_development_pl = 'Twoje dziecko ma teraz około 4-5 cm długości i waży 7-8 gramów. Ogon całkowicie zanikł, co oznacza koniec okresu zarodkowego. Wszystkie narządy są już na swoim miejscu i rozpoczyna się faza szybkiego wzrostu. W ciągu kolejnych 8 tygodni Twoje dziecko stanie się 30 razy cięższe i 3 razy dłuższe niż obecnie. Aby wspierać ten wzrost, zwiększają się objętość krwi w Twoim organizmie oraz liczba naczyń krwionośnych. Chociaż na tym etapie głowa dziecka może wydawać się duża w stosunku do reszty ciała, jego proporcje wkrótce się wyrównają. Palce już się wydłużyły — dziecko nie tylko zaciska dłonie w piąstki, lecz także je otwiera i zaczyna poznawać swoje otoczenie.', baby_development_nl = 'Je baby is nu ongeveer 4-5 cm lang en weegt 7-8 gram. Het staartje is volledig verdwenen, wat het einde van de embryonale periode markeert. Alle organen bevinden zich nu op hun plaats en er begint een fase van snelle groei. In de komende 8 weken wordt je baby 30 keer zo zwaar en 3 keer zo lang als nu. Om deze groei te ondersteunen, nemen de hoeveelheid bloed in je lichaam en het aantal bloedvaten toe. Hoewel het hoofd van je baby in deze fase groot kan lijken ten opzichte van het lichaam, worden de lichaamsverhoudingen binnenkort evenwichtiger. De vingers zijn al langer geworden. Je baby maakt niet alleen vuistjes, maar opent ook de handen en begint de omgeving te verkennen.', baby_development_sv = 'Ditt barn är nu cirka 4–5 cm långt och väger 7–8 gram. Svansen har försvunnit helt, vilket markerar slutet på embryonalperioden. Alla organ finns nu på plats och en fas med snabb tillväxt börjar. Under de kommande 8 veckorna kommer ditt barn att bli 30 gånger tyngre och 3 gånger längre än nu. För att stödja tillväxten ökar blodvolymen i din kropp, och fler blodkärl bildas. Även om ditt barns huvud kan se stort ut i förhållande till kroppen i det här skedet blir proportionerna snart jämnare. Fingrarna har redan blivit längre. Ditt barn knyter inte bara händerna utan öppnar dem också och börjar utforska sin omgivning.' WHERE id = '8c65943a-4d31-4534-b028-6c3f95fa6988' AND md5(coalesce(baby_development,'')) = '04774685996854242b9c0036b18dfab6' AND md5(coalesce(baby_development_en,'')) = '1b3d0dc244c8afd9b57cec1e9fa74fb6' AND md5(coalesce(baby_development_ru,'')) = 'd2dad005746a1414dfa5036d29e2c072' AND md5(coalesce(baby_development_tr,'')) = 'f053d45a6717d4fa39f6ffaa0b1735c1' AND md5(coalesce(baby_development_kk,'')) = '450cd1a4c3d4e5e2ca8be3b105be67be' AND md5(coalesce(baby_development_de,'')) = 'ef52c97476769e90eceb5faefebae903' AND md5(coalesce(baby_development_ar,'')) = '6521e7abd4d62479b834ac55810370d4' AND md5(coalesce(baby_development_uz,'')) = 'dfe4633cece41925c8e617f9bd6290a6' AND md5(coalesce(baby_development_ka,'')) = 'efb2dc06113edf2641245921436c9fcc' AND md5(coalesce(baby_development_zh,'')) = 'a3a41e1e84ea347477c06701e918e715' AND md5(coalesce(baby_development_id,'')) = '7bdfa8d5b854881143939eee1d9ffdd5' AND md5(coalesce(baby_development_fr,'')) = '85fc0628042ed0f96831a779b1d325df' AND md5(coalesce(baby_development_es,'')) = 'fdee20995e830d461afb61f99e5f22f6' AND md5(coalesce(baby_development_pt,'')) = '9e80748dc61abdc35fd14369d3509e32' AND md5(coalesce(baby_development_vi,'')) = '1bffd1b9eaa84e6abfe818078dd8c921' AND md5(coalesce(baby_development_hi,'')) = '1bcb9aeecaccd61c72fcf766a495c3a5' AND md5(coalesce(baby_development_ja,'')) = '30b3f66702ac9d3a6c332e9ff5aebea4' AND md5(coalesce(baby_development_ko,'')) = '1cfc850171ab0d180d3fa64a70fd28c0' AND md5(coalesce(baby_development_pl,'')) = '819c43e27c22c7663d3e15ec43f43c27' AND md5(coalesce(baby_development_nl,'')) = '2e9901f7eb25bbf2be45540525b74c2a' AND md5(coalesce(baby_development_sv,'')) = '0dc5d119aef674ca40a1743975b07c83';
UPDATE public.pregnancy_daily_content SET baby_message = '13 HƏFTƏ! SALAM, 2-Cİ TRİMESTR! 🎉 Anacan, gözümüz aydın! Biz hamiləliyin üçdən birini (1/3) bitirdik. Ən çətin günlər geridə qaldı. İndi sənin də, mənim də daha rahat nəfəs alacağımız dövr başlayır. Mən artıq bir laym boydayam. Səs tellərim inkişaf edib. Səninlə danışa bilməsəm də, səsimi hazırlayıram. Bu yeni mərhələdə bizi daha gözəl günlər gözləyir.', baby_message_en = '13 WEEKS! HELLO, 2ND TRIMESTER! 🎉 Mommy, congratulations to us! We''ve completed one-third (1/3) of the pregnancy. The most challenging days are behind us. Now, a period begins where both you and I can breathe a little easier. I''m already about the size of a lime. My vocal cords have developed. Even though I can''t talk to you yet, I''m getting my voice ready! More wonderful days await us in this new phase.', baby_message_ru = '13 НЕДЕЛЬ! ПРИВЕТ, 2-Й ТРИМЕСТР! 🎉 мамочка, поздравляю нас! Мы прошли уже треть (1/3) беременности. Самые трудные дни остались позади. Теперь начинается период, когда и тебе, и мне будет легче дышать. Я уже размером с лайм. Мои голосовые связки сформировались. Хотя я пока не могу с тобой разговаривать, я уже готовлю свой голос. На этом новом этапе нас ждёт ещё больше прекрасных дней.', baby_message_tr = '13 HAFTA! MERHABA, 2. TRİMESTER! 🎉 anneciğim, gözümüz aydın! Hamileliğin üçte birini (1/3) tamamladık. En zor günler geride kaldı. Şimdi hem senin hem de benim daha rahat nefes alacağımız dönem başlıyor. Artık bir misket limonu büyüklüğündeyim. Ses tellerim gelişti. Seninle henüz konuşamasam da sesimi hazırlıyorum. Bu yeni dönemde bizi daha güzel günler bekliyor.', baby_message_kk = '13 АПТА! СӘЛЕМ, 2-ТРИМЕСТР! 🎉 анашым, қуанышты жаңалық! Біз жүктіліктің үштен бірін (1/3) аяқтадық. Ең қиын күндер артта қалды. Енді Сіз де, мен де еркінірек тыныстайтын кезең басталады. Мен қазір лаймдаймын. Дауыс байламдарым дамып қалды. Сізбен әлі сөйлесе алмасам да, дауысымды дайындап жатырмын. Осы жаңа кезеңде бізді одан да тамаша күндер күтіп тұр.', baby_message_de = '13 WOCHEN! HALLO, 2. TRIMESTER! 🎉 Mami, wir haben allen Grund zur Freude! Wir haben bereits ein Drittel (1/3) der Schwangerschaft geschafft. Die schwierigsten Tage liegen hinter uns. Jetzt beginnt eine Zeit, in der wir beide leichter durchatmen können. Ich bin schon so groß wie eine Limette. Meine Stimmbänder haben sich entwickelt. Auch wenn ich noch nicht mit dir sprechen kann, bereite ich meine Stimme schon darauf vor. In dieser neuen Phase erwarten uns noch schönere Tage.', baby_message_ar = '13 أسبوعًا! أهلًا بالثلث 2 من الحمل! 🎉 ماما، يا لها من أخبار رائعة! لقد أتممنا ثلث الحمل (1/3). أصبحت أصعب الأيام خلفنا، وبدأت الآن مرحلة سنتنفس فيها أنا وأنتِ براحة أكبر. لقد أصبح حجمي الآن بحجم حبة ليمون أخضر. كما تطورت أحبالي الصوتية. ورغم أنني لا أستطيع التحدث إليكِ بعد، فإنني أُعِد صوتي لذلك. تنتظرنا أيام أجمل في هذه المرحلة الجديدة.', baby_message_uz = '13 HAFTA! SALOM, 2-TRIMESTR! 🎉 Onajon, ko‘zimiz yorug‘ bo‘lsin! Biz homiladorlikning uchdan bir qismini (1/3) yakunladik. Eng qiyin kunlar ortda qoldi. Endi siz ham, men ham yengilroq nafas oladigan davr boshlanmoqda. Men hozir laymdek kattaman. Ovoz paychalarim rivojlandi. Hali siz bilan gaplasha olmasam-da, ovozimni tayyorlayapman. Bu yangi bosqichda bizni yanada go‘zal kunlar kutmoqda.', baby_message_ka = '13 კვირა! გამარჯობა, მე-2 ტრიმესტრო! 🎉 დედიკო, გილოცავ! ორსულობის ერთი მესამედი (1/3) უკვე გავიარეთ. ყველაზე რთული დღეები უკან დარჩა. ახლა იწყება პერიოდი, როცა ორივე უფრო თავისუფლად ამოვისუნთქებთ. უკვე ლაიმის ზომის ვარ. ჩემი ხმის იოგებიც განვითარდა. ჯერ ვერ გელაპარაკები, მაგრამ ჩემს ხმას ვამზადებ. ამ ახალ ეტაპზე კიდევ უფრო ლამაზი დღეები გველოდება.', baby_message_zh = '13周啦！第2孕期，你好！🎉 妈妈，恭喜我们！我们已经走过了整个孕期的三分之一（1/3）。最艰难的日子已经过去，现在开始进入你和我都能轻松一些的阶段。我已经有一颗青柠那么大，声带也发育好了。虽然还不能和你说话，但我正在为发声做准备！新的阶段里，还有更多美好的日子等着我们。', baby_message_id = '13 MINGGU! HALO, TRIMESTER KE-2! 🎉 Mama, selamat untuk kita! Kita telah melewati sepertiga (1/3) masa kehamilan. Hari-hari yang paling menantang sudah berlalu. Sekarang dimulailah masa ketika Anda dan aku bisa bernapas sedikit lebih lega. Ukuranku sudah kira-kira sebesar jeruk nipis. Pita suaraku sudah berkembang. Meski belum bisa berbicara dengan Anda, aku sedang menyiapkan suaraku! Masih banyak hari indah yang menanti kita di fase baru ini.', baby_message_fr = '13 SEMAINES ! BONJOUR, 2E TRIMESTRE ! 🎉 Maman, félicitations à nous deux ! Nous avons parcouru un tiers (1/3) de la grossesse. Les jours les plus difficiles sont derrière nous. Une période commence maintenant où vous et moi pourrons respirer un peu plus facilement. Je fais déjà à peu près la taille d''un citron vert. Mes cordes vocales se sont développées. Même si je ne peux pas encore vous parler, je prépare ma voix ! De très beaux jours nous attendent dans cette nouvelle étape.', baby_message_es = '¡13 SEMANAS! ¡HOLA, 2.º TRIMESTRE! 🎉 Mamá, ¡enhorabuena a los dos! Ya hemos completado un tercio (1/3) del embarazo. Los días más difíciles han quedado atrás. Ahora comienza una etapa en la que los dos podremos respirar con un poco más de tranquilidad. Ya tengo aproximadamente el tamaño de una lima. Mis cuerdas vocales se han desarrollado. Aunque todavía no puedo hablarte, ¡estoy preparando mi voz! En esta nueva etapa nos esperan muchos más días maravillosos.', baby_message_pt = '13 SEMANAS! OLÁ, 2.º TRIMESTRE! 🎉 Mamã, parabéns para nós! Já completámos um terço (1/3) da gravidez. Os dias mais difíceis ficaram para trás. Agora começa uma fase em que ambos podemos respirar um pouco melhor. Já tenho aproximadamente o tamanho de uma lima. As minhas cordas vocais desenvolveram-se. Embora ainda não consiga falar contigo, estou a preparar a minha voz! Nesta nova fase, esperam-nos ainda mais dias maravilhosos.', baby_message_vi = 'TRÒN 13 TUẦN! XIN CHÀO TAM CÁ NGUYỆT THỨ 2! 🎉 Mẹ ơi, chúc mừng chúng ta! Chúng ta đã hoàn thành một phần ba (1/3) thai kỳ. Những ngày khó khăn nhất đã ở lại phía sau. Giờ đây, một giai đoạn mới bắt đầu, khi cả bạn và con đều có thể thở phào nhẹ nhõm hơn. Con đã lớn bằng khoảng một quả chanh xanh. Dây thanh quản của con đã phát triển. Dù chưa thể trò chuyện với bạn, con đang chuẩn bị giọng nói của mình rồi! Còn rất nhiều ngày tuyệt vời đang chờ chúng ta trong chặng đường mới này.', baby_message_hi = '13 हफ्ते! नमस्ते, 2ND ट्राइमेस्टर! 🎉 मम्मी, हम दोनों को बधाई! हमने गर्भावस्था का एक-तिहाई (1/3) हिस्सा पूरा कर लिया है। सबसे चुनौतीपूर्ण दिन अब पीछे छूट चुके हैं। अब ऐसा समय शुरू हो रहा है, जब हम दोनों थोड़ी राहत की साँस ले सकते हैं। मेरा आकार अब लगभग एक हरे नींबू जितना है। मेरी स्वर-तंत्रियाँ विकसित हो चुकी हैं। भले ही मैं अभी आपसे बात नहीं कर सकता, लेकिन अपनी आवाज़ तैयार कर रहा हूँ! इस नए चरण में और भी शानदार दिन हमारा इंतज़ार कर रहे हैं।', baby_message_ja = '13週！妊娠第2期、こんにちは！🎉 ママ、私たち、おめでとう！妊娠期間の三分の一（1/3）を終えたよ。いちばん大変な時期は乗り越えたね。これからは、ママも私も少し楽に過ごせる時期が始まるよ。今の私は、もうライムくらいの大きさ。声帯もできたの。まだママとは話せないけれど、声を出す準備をしているよ！この新しい時期にも、すてきな日々がたくさん待っているね。', baby_message_ko = '13주! 2번째 임신 중기, 안녕! 🎉 엄마, 우리 함께 축하해요! 임신 기간의 삼분의 일(1/3)을 잘 마쳤어요. 가장 힘든 날들은 이제 지나갔어요. 이제 엄마와 나 모두 조금 더 편하게 숨 쉴 수 있는 시기가 시작돼요. 나는 벌써 라임만큼 자랐어요. 성대도 발달했어요. 아직 엄마에게 말할 수는 없지만, 목소리를 낼 준비를 하고 있어요! 새로운 시기에는 더 멋진 날들이 우리를 기다리고 있어요.', baby_message_pl = '13 TYGODNI! WITAJ, 2. TRYMESTRZE! 🎉 Mamusiu, gratulacje dla nas! Mamy za sobą jedną trzecią (1/3) ciąży. Najtrudniejsze dni są już za nami. Teraz zaczyna się okres, w którym oboje możemy odetchnąć nieco spokojniej. Mam już mniej więcej wielkość limonki. Moje struny głosowe są rozwinięte. Chociaż nie mogę jeszcze z Tobą rozmawiać, przygotowuję już swój głos! W tym nowym etapie czeka nas jeszcze wiele wspaniałych dni.', baby_message_nl = '13 WEKEN! HALLO, 2E TRIMESTER! 🎉 Mama, gefeliciteerd met ons! We hebben een derde (1/3) van de zwangerschap achter de rug. De zwaarste dagen liggen achter ons. Nu begint een periode waarin we allebei wat meer op adem kunnen komen. Ik ben al ongeveer zo groot als een limoen. Mijn stembanden zijn ontwikkeld. Hoewel ik nog niet met je kan praten, maak ik mijn stem alvast klaar! In deze nieuwe fase wachten ons nog veel prachtige dagen.', baby_message_sv = '13 VECKOR! HEJ, TRIMESTER 2! 🎉 Mamma, grattis till oss! Vi har klarat av en tredjedel (1/3) av graviditeten. De mest krävande dagarna ligger bakom oss. Nu börjar en period då både du och jag kan andas lite lättare. Jag är redan ungefär lika stor som en lime. Mina stämband har utvecklats. Även om jag inte kan prata med dig än håller jag på att göra rösten redo! Fler underbara dagar väntar oss i den här nya fasen.' WHERE id = 'aae70b4b-3e99-462b-94d0-88716afa0dd4' AND md5(coalesce(baby_message,'')) = 'da2d7c55ece80491c5ab7b93fe3aca4b' AND md5(coalesce(baby_message_en,'')) = '7c089fc505c266970b80704e6ebf2d02' AND md5(coalesce(baby_message_ru,'')) = 'bc32db7b736e9c5e8b220972c951fd38' AND md5(coalesce(baby_message_tr,'')) = '86ea167ade589924ea7d4056d83b6c4b' AND md5(coalesce(baby_message_kk,'')) = '54c033cad71fd88429d0f3a9d1b74ddd' AND md5(coalesce(baby_message_de,'')) = '1687993d5e9e9aa15a6efa4bda9f7442' AND md5(coalesce(baby_message_ar,'')) = 'b5a17d6e34ed3d6a03eee3947bc7811e' AND md5(coalesce(baby_message_uz,'')) = '977bc4fe1201e1e005548ac89dfdc268' AND md5(coalesce(baby_message_ka,'')) = '55e962cf403476d7463a5b72899631f8' AND md5(coalesce(baby_message_zh,'')) = '3d98e0812ab0ee45c9b818f306112999' AND md5(coalesce(baby_message_id,'')) = 'db19239ffac8d6e5f9e00bd0cbf8ad4f' AND md5(coalesce(baby_message_fr,'')) = '6ac14547db69a77db754de64797bb968' AND md5(coalesce(baby_message_es,'')) = '2d00d5bc9c5ea13fd01121a70e87c86c' AND md5(coalesce(baby_message_pt,'')) = '5d1c1a4426517b1eb3fd2efd63ee5a60' AND md5(coalesce(baby_message_vi,'')) = '3d6142435273c40c5cff9f32d2f11612' AND md5(coalesce(baby_message_hi,'')) = 'f981aaeff9a5dd6e7603700fb1e27cfa' AND md5(coalesce(baby_message_ja,'')) = '2d5a52f9afcf0b9b965c41a71d0571c7' AND md5(coalesce(baby_message_ko,'')) = '27e9db44f46c6b644b361a955ec654d5' AND md5(coalesce(baby_message_pl,'')) = '91d74b65f4488685f432e3f2df7450c5' AND md5(coalesce(baby_message_nl,'')) = '1c4007a54e96130c58530004e57b6187' AND md5(coalesce(baby_message_sv,'')) = 'd759866082077116a86e6939e8d336ab';
UPDATE public.pregnancy_daily_content SET baby_message = '14 HƏFTƏ! 📏 Mən bir limon boydayam! Artıq bədənim başımdan daha sürətlə böyüyür, ona görə də daha çox balaca bir uşağa bənzəyirəm. Boynum uzanıb, çənəm formalaşıb. Hər gün bir az daha böyüyürəm, hər gün sənə qovuşmağa bir az daha yaxınlaşıram.', baby_message_en = '14 WEEKS! 📏 I''m about the size of a lemon! My body is now growing faster than my head, so I''m starting to look much more like a little baby. My neck has lengthened, and my chin has formed. Every day I grow a little more, and every day I get a little closer to meeting you.', baby_message_ru = '14 НЕДЕЛЬ! 📏 Я размером с лимон! Теперь моё тело растёт быстрее головы, поэтому я всё больше похож на маленького ребёнка. Моя шея удлинилась, а подбородок сформировался. С каждым днём я понемногу расту и становлюсь всё ближе к встрече с вами.', baby_message_tr = '14 HAFTA! 📏 Ben bir limon büyüklüğündeyim! Artık vücudum başımdan daha hızlı büyüyor, bu yüzden küçük bir çocuğa daha çok benziyorum. Boynum uzadı, çenem şekillendi. Her gün biraz daha büyüyor, her gün size kavuşmaya biraz daha yaklaşıyorum.', baby_message_kk = '14 АПТА! 📏 Менің көлемім лимондай! Енді денем басыма қарағанда жылдамырақ өсіп жатыр, сондықтан кішкентай балаға көбірек ұқсаймын. Мойным ұзарып, иегім қалыптасты. Күн сайын аздап өсіп, күн сайын Сізбен қауышатын сәтке жақындай түсудемін.', baby_message_de = '14 WOCHEN! 📏 Ich bin so groß wie eine Zitrone! Mein Körper wächst jetzt schneller als mein Kopf, deshalb sehe ich immer mehr wie ein kleines Kind aus. Mein Hals ist länger geworden und mein Kinn hat sich geformt. Jeden Tag werde ich ein bisschen größer und komme dem Moment, an dem wir uns endlich begegnen, ein Stück näher.', baby_message_ar = '14 أُسْبُوعًا! 📏 أنا بحجم حبة ليمون! أصبح جسمي الآن ينمو أسرع من رأسي، لذلك صرت أشبه بطفل صغير أكثر. لقد استطالت رقبتي وتشكلت ذقني. أكبر قليلًا كل يوم، وأقترب كل يوم خطوة أخرى من لقائكِ.', baby_message_uz = '14 HAFTA! 📏 Men limondek kattaman! Endi tanam boshimdan tezroq o‘smoqda, shuning uchun tobora kichkina bolaga ko‘proq o‘xshab boryapman. Bo‘ynim uzaydi, iyagim shakllandi. Har kuni biroz kattalashyapman, har kuni sen bilan uchrashishga biroz yaqinlashyapman.', baby_message_ka = '14 კვირა! 📏 მე ლიმონის ზომის ვარ! ახლა ჩემი სხეული თავზე უფრო სწრაფად იზრდება, ამიტომ სულ უფრო მეტად ვემსგავსები პატარა ბავშვს. კისერი დამიგრძელდა, ნიკაპი კი ჩამომიყალიბდა. ყოველდღე ცოტათი უფრო ვიზრდები და ყოველდღე ცოტათი უფრო ვუახლოვდები შენთან შეხვედრას.', baby_message_zh = '14周啦！📏 我现在大约有一个柠檬那么大！我的身体长得比头更快，所以越来越像一个小宝宝了。我的脖子变长了，下巴也成形了。我每天都在长大一点，也每天都离见到你更近一点。', baby_message_id = '14 MINGGU! 📏 Besarku kira-kira seukuran buah lemon! Tubuhku kini tumbuh lebih cepat daripada kepalaku, jadi aku mulai terlihat semakin mirip bayi mungil. Leherku semakin panjang dan daguku telah terbentuk. Setiap hari aku tumbuh sedikit lebih besar, dan setiap hari aku semakin dekat untuk bertemu dengan Anda.', baby_message_fr = '14 SEMAINES ! 📏 J''ai à peu près la taille d''un citron ! Mon corps grandit maintenant plus vite que ma tête, alors je commence à ressembler beaucoup plus à un petit bébé. Mon cou s''est allongé et mon menton s''est formé. Chaque jour, je grandis un peu plus et je me rapproche un peu plus de notre rencontre.', baby_message_es = '¡14 SEMANAS! 📏 ¡Tengo aproximadamente el tamaño de un limón! Ahora mi cuerpo crece más rápido que mi cabeza, así que cada vez me parezco mucho más a un bebé pequeñito. Mi cuello se ha alargado y mi barbilla se ha formado. Cada día crezco un poco más y estoy un poco más cerca de conocerte.', baby_message_pt = '14 SEMANAS! 📏 Sou mais ou menos do tamanho de um limão! O meu corpo está agora a crescer mais depressa do que a cabeça, por isso começo a parecer-me muito mais com um bebé pequenino. O meu pescoço alongou-se e o meu queixo formou-se. Todos os dias cresço um pouco mais e fico um pouco mais perto de te conhecer.', baby_message_vi = '14 TUẦN! 📏 Con lớn bằng một quả chanh vàng rồi! Giờ cơ thể con phát triển nhanh hơn đầu nên con bắt đầu trông giống một em bé hơn nhiều. Cổ con đã dài ra và cằm cũng hình thành. Mỗi ngày con lớn thêm một chút và cũng tiến gần hơn một chút đến ngày được gặp mẹ.', baby_message_hi = '14 सप्ताह! 📏 मेरा आकार लगभग एक नींबू जितना है! अब मेरा शरीर मेरे सिर की तुलना में तेजी से बढ़ रहा है, इसलिए मेरा रूप एक नन्हे शिशु जैसा होने लगा है। मेरी गर्दन लंबी हो गई है और मेरी ठुड्डी बन चुकी है। हर दिन मैं थोड़ा और बढ़ता हूँ और आपसे मिलने के थोड़ा और करीब आ जाता हूँ।', baby_message_ja = '14週！📏 レモンくらいの大きさになったよ！今は頭よりも体のほうが速く成長しているので、ずっと赤ちゃんらしい姿になってきました。首が伸びて、あごもできています。毎日少しずつ成長して、ママに会える日へ少しずつ近づいているよ。', baby_message_ko = '14주예요! 📏 나는 레몬만 해요! 이제 몸이 머리보다 더 빠르게 자라서 아기다운 모습이 되어 가고 있어요. 목은 길어지고 턱도 생겼어요. 매일 조금씩 자라며 엄마를 만날 날에 하루하루 가까워지고 있답니다.', baby_message_pl = '14 TYG.! 📏 Jestem mniej więcej wielkości cytryny! Moje ciało rośnie teraz szybciej niż głowa, dlatego coraz bardziej przypominam maleńkie dziecko. Moja szyja się wydłużyła, a broda nabrała kształtu. Każdego dnia trochę rosnę i jestem coraz bliżej spotkania z tobą.', baby_message_nl = '14 WEKEN! 📏 Ik ben ongeveer zo groot als een citroen! Mijn lichaam groeit nu sneller dan mijn hoofd, waardoor ik steeds meer op een kleine baby begin te lijken. Mijn nek is langer geworden en mijn kin heeft vorm gekregen. Elke dag groei ik een beetje en kom ik iets dichter bij onze ontmoeting.', baby_message_sv = '14 VECKOR! 📏 Jag är ungefär lika stor som en citron! Min kropp växer nu snabbare än mitt huvud, så jag börjar se mycket mer ut som en liten bebis. Min hals har blivit längre och min haka har formats. Varje dag växer jag lite mer, och varje dag kommer jag lite närmare vårt första möte.' WHERE id = 'a6400bac-f975-43dc-a8f8-6c0a5411246c' AND md5(coalesce(baby_message,'')) = 'b09fe34b216d9188304b8fa1e8ad2684' AND md5(coalesce(baby_message_en,'')) = '7df320fa64c6f64b5fe90964ad48966a' AND md5(coalesce(baby_message_ru,'')) = '4baf6e06e608ffdf7e02f491c61082b6' AND md5(coalesce(baby_message_tr,'')) = '89b3f75c5fadc50a420a7c8df139c836' AND md5(coalesce(baby_message_kk,'')) = 'da6d53788f3fd424b43a82b81be09ab5' AND md5(coalesce(baby_message_de,'')) = '263c1fdead4dc537c880cfdd235e6f9d' AND md5(coalesce(baby_message_ar,'')) = '37092db845cf63d7636bdb191bb66337' AND md5(coalesce(baby_message_uz,'')) = '9d6a39a3facb22be5088ce497d0e06f2' AND md5(coalesce(baby_message_ka,'')) = '11378e7885ad2b9b617c13a2ee964e9f' AND md5(coalesce(baby_message_zh,'')) = 'a81851b69c249127e8cef2780320d8a8' AND md5(coalesce(baby_message_id,'')) = '2b065b653ba351b954b045a983f30eca' AND md5(coalesce(baby_message_fr,'')) = '9956d6b3fbf4647f7e7efa7e0a8c4be5' AND md5(coalesce(baby_message_es,'')) = '985f3ec6a6845e9cd3796fb688d569eb' AND md5(coalesce(baby_message_pt,'')) = '2c0119bbb76bec9928bba6f8b0dd0413' AND md5(coalesce(baby_message_vi,'')) = '3f037127726e3dc267f99e0d455c82d6' AND md5(coalesce(baby_message_hi,'')) = '083dee05533dbb81a842ac233ad08259' AND md5(coalesce(baby_message_ja,'')) = '691b35a3983ffdea4d411fce61e3744e' AND md5(coalesce(baby_message_ko,'')) = '0210df23f0f5f01b3d3c6f6b6e0d575e' AND md5(coalesce(baby_message_pl,'')) = '610cf5725aa6f132ef997b8b87b19f86' AND md5(coalesce(baby_message_nl,'')) = 'a4e5edd0221952f4822f0ad0cd7cde05' AND md5(coalesce(baby_message_sv,'')) = '8eb4bcf7e99c742fcaaedb7cbf89f5af';
UPDATE public.pregnancy_day_notifications SET title = 'Bir şaftalı boyda 🍑', title_en = 'About the size of a peach 🍑', title_ru = 'Размером с персик 🍑', title_tr = 'Bir şeftali büyüklüğünde 🍑', title_kk = 'Көлемі шабдалыдай 🍑', title_de = 'So groß wie ein Pfirsich 🍑', title_ar = 'بحجم حبة خوخ 🍑', title_uz = 'Bir dona shaftolidek 🍑', title_ka = 'ატმის ზომისაა 🍑' WHERE id = 'e7c711cf-139e-409a-9191-4e2baba06f95' AND md5(coalesce(title,'')) = '4270c85165f8c37486306d1ae4430f39' AND md5(coalesce(title_en,'')) = 'aae8809c6d8841edb526285af810ddac' AND md5(coalesce(title_ru,'')) = '3c2f9579eaf7a9dacc9ce72258094e42' AND md5(coalesce(title_tr,'')) = 'a7c886ae08eb95490224556a0ab7c8f3' AND md5(coalesce(title_kk,'')) = '26f6b811357b757a85b9df3a31e74298' AND md5(coalesce(title_de,'')) = '9e32a66d1c562c2a3ca342b356d22264' AND md5(coalesce(title_ar,'')) = 'a351897c720b3ade5b38ef915c2942ca' AND md5(coalesce(title_uz,'')) = '687843bb1548827c682cc553b3264d7c' AND md5(coalesce(title_ka,'')) = '06b7c542cc95c021096a37067c13217c';
UPDATE public.pregnancy_daily_content SET baby_development = 'Körpəniz bu həftə təxminən 65-70 qram çəkiyə və 10 sm boya sahibdir. O, artıq baş dərisindən qaşlarına qədər sıx lanuqo tükləri ilə örtülmüş, kiçik qulaqları və qapalı göz qapaqları ilə dincələn miniatür bir insan görünüşündədir. Körpənizin gözləri struktur olaraq tamamlansa da, funksional baxımdan ən son inkişaf edən orqanı olacaq. Bunun maraqlı bir səbəbi var: sinir hüceyrələri (neyronlar) çox olsa da, onların ətrafındakı mielin qişası hələ formalaşmayıb. Mielin qişası sinirləri bürüyən xüsusi bir yağ təbəqəsidir. Onu elektrik kabellərinin ətrafındakı izolyasiya qatına bənzətmək olar. Bu təbəqə olmadan elektrik siqnalları neyronlar arasında sürətlə ötürülə bilmir. Mielin qişası yarandıqca körpəniz xaricdən gələn görüntüləri və siqnalları daha sürətli qəbul edib mənalandıracaq.', baby_development_en = 'This week, your baby weighs approximately 65-70 grams and measures 10 cm in length. They now resemble a miniature human, covered in dense lanugo hair from scalp to eyebrows, resting with tiny ears and closed eyelids. While your baby''s eyes are structurally complete, they will be the last organ to fully develop functionally. There''s an interesting reason for this: although there are many nerve cells (neurons), the myelin sheath around them has not yet formed. The myelin sheath is a special fatty layer that insulates nerves. You can liken it to the insulation layer around electrical cables. Without this layer, electrical signals cannot be transmitted rapidly between neurons. As the myelin sheath develops, your baby will be able to process and interpret external images and signals more quickly.', baby_development_ru = 'На этой неделе ваш малыш весит около 65-70 граммов, а его рост составляет 10 см. Теперь он выглядит как миниатюрный человечек: от кожи головы до бровей его покрывает густой пушок лануго, у него маленькие ушки и закрытые веки. Хотя глаза малыша уже полностью сформированы структурно, с функциональной точки зрения они будут развиваться в последнюю очередь. Для этого есть любопытная причина: нервных клеток — нейронов — уже много, но окружающая их миелиновая оболочка ещё не сформировалась. Миелиновая оболочка — это особый жировой слой, покрывающий нервы. Его можно сравнить с изоляцией вокруг электрических проводов. Без этого слоя электрические сигналы не могут быстро передаваться между нейронами. По мере формирования миелиновой оболочки малыш сможет быстрее воспринимать и распознавать поступающие извне изображения и сигналы.', baby_development_tr = 'Bebeğiniz bu hafta yaklaşık 65-70 gram ağırlığında ve 10 cm boyundadır. Artık saçlı derisinden kaşlarına kadar yoğun lanugo tüyleriyle kaplı, küçük kulakları ve kapalı göz kapaklarıyla dinlenen minyatür bir insan görünümündedir. Bebeğinizin gözleri yapısal olarak tamamlanmış olsa da işlevsel açıdan en son gelişen organı olacaktır. Bunun ilginç bir nedeni var: Sinir hücreleri (nöronlar) çok sayıda olsa da çevrelerindeki miyelin kılıf henüz oluşmadı. Miyelin kılıf, sinirleri saran özel bir yağ tabakasıdır. Bunu elektrik kablolarının çevresindeki yalıtım katmanına benzetebilirsiniz. Bu tabaka olmadan elektrik sinyalleri nöronlar arasında hızlı bir şekilde iletilemez. Miyelin kılıf oluştukça bebeğiniz dışarıdan gelen görüntüleri ve sinyalleri daha hızlı algılayıp anlamlandıracak.', baby_development_kk = 'Осы аптада бөпеңіздің салмағы шамамен 65-70 грамм, ал бойы 10 см. Қазір ол бас терісінен қасына дейін қалың лануго түктерімен жабылған, кішкентай құлақтары мен жұмулы қабақтары бар, тынығып жатқан кішкентай адамға ұқсайды. Бөпеңіздің көздері құрылымдық жағынан толық қалыптасқанымен, қызметі жағынан ең соңғы болып жетілетін мүше саналады. Мұның қызықты себебі бар: жүйке жасушалары (нейрондар) көп болғанымен, олардың айналасындағы миелин қабығы әлі қалыптаспаған. Миелин қабығы — жүйкелерді қаптайтын арнайы майлы қабат. Оны электр сымдарының сыртындағы оқшаулағыш қабатпен салыстыруға болады. Бұл қабат болмаса, электрлік сигналдар нейрондар арасында жылдам беріле алмайды. Миелин қабығы қалыптасқан сайын бөпеңіз сырттан келетін бейнелер мен сигналдарды жылдамырақ қабылдап, түсіне бастайды.', baby_development_de = 'Dein Baby wiegt diese Woche etwa 65-70 Gramm und ist 10 cm groß. Es sieht bereits wie ein winziger Mensch aus: Von der Kopfhaut bis zu den Augenbrauen ist es dicht mit Lanugohaar bedeckt, es hat kleine Ohren und ruht mit geschlossenen Augenlidern. Die Augen deines Babys sind zwar anatomisch vollständig ausgebildet, werden funktionell jedoch zu den Organen gehören, deren Entwicklung zuletzt abgeschlossen wird. Dafür gibt es einen interessanten Grund: Obwohl bereits viele Nervenzellen (Neuronen) vorhanden sind, hat sich die Myelinscheide um sie herum noch nicht gebildet. Die Myelinscheide ist eine besondere Fettschicht, die die Nerven umhüllt. Du kannst sie dir wie die Isolierung um ein Stromkabel vorstellen. Ohne diese Schicht können elektrische Signale nicht schnell zwischen den Neuronen weitergeleitet werden. Mit der Bildung der Myelinscheide wird dein Baby äußere visuelle Reize und Signale schneller wahrnehmen und verarbeiten können.', baby_development_ar = 'يبلغ وزن طفلكِ هذا الأسبوع نحو 65-70 غرامًا وطوله 10 سم. وقد أصبح يبدو كإنسان مصغّر يستريح بأذنين صغيرتين وجفنين مغلقين، ويغطي جسمه شعر زغبي كثيف يُسمى اللانوغو، يمتد من فروة رأسه إلى حاجبيه. وعلى الرغم من اكتمال عيني طفلكِ من الناحية البنيوية، فإنهما ستكونان آخر عضو يكتمل تطوره وظيفيًا. ولهذا سبب مثير للاهتمام: فرغم كثرة الخلايا العصبية (العصبونات)، لم يتكوّن غمد الميالين المحيط بها بعد. وغمد الميالين طبقة دهنية خاصة تغلف الأعصاب، ويمكن تشبيهها بطبقة العزل المحيطة بالأسلاك الكهربائية. ومن دون هذه الطبقة، لا يمكن نقل الإشارات الكهربائية بسرعة بين العصبونات. ومع تكوّن غمد الميالين، سيتمكن طفلكِ من استقبال الصور والإشارات القادمة من الخارج وفهمها بسرعة أكبر.', baby_development_uz = 'Chaqalog‘ingiz bu haftada taxminan 65-70 gramm vaznga va 10 sm bo‘yga ega. Endi u bosh terisidan qoshlarigacha qalin lanugo tuklari bilan qoplangan, kichik quloqlari va yumuq qovoqlari bilan orom olayotgan mitti inson ko‘rinishida. Chaqalog‘ingizning ko‘zlari tuzilish jihatidan to‘liq shakllangan bo‘lsa-da, funksional jihatdan eng oxirida rivojlanadigan a’zo bo‘ladi. Buning qiziqarli sababi bor: asab hujayralari (neyronlar) ko‘p bo‘lsa-da, ularning atrofidagi miyelin qobig‘i hali shakllanmagan. Miyelin qobig‘i asablarni o‘rab turadigan maxsus yog‘ qatlamidir. Uni elektr simlari atrofidagi izolyatsiya qatlamiga o‘xshatish mumkin. Bu qatlamsiz elektr signallari neyronlar orasida tez uzatilmaydi. Miyelin qobig‘i shakllangani sari chaqalog‘ingiz tashqaridan kelayotgan tasvir va signallarni tezroq qabul qilib, anglay boshlaydi.', baby_development_ka = 'ამ კვირაში თქვენი ბავშვი დაახლოებით 65-70 გრამს იწონის და მისი სიგრძე 10 სმ-ია. ის უკვე მინიატიურულ ადამიანს ჰგავს: თავის კანიდან წარბებამდე ხშირი ლანუგოთია დაფარული, პატარა ყურები აქვს და დახუჭული ქუთუთოებით ისვენებს. მიუხედავად იმისა, რომ თქვენი ბავშვის თვალების სტრუქტურა უკვე სრულად ჩამოყალიბებულია, ფუნქციურად ისინი ყველაზე გვიან განვითარებული ორგანო იქნება. ამას საინტერესო მიზეზი აქვს: მიუხედავად იმისა, რომ ნერვული უჯრედები (ნეირონები) მრავლადაა, მათ გარშემო მიელინის გარსი ჯერ არ ჩამოყალიბებულა. მიელინის გარსი სპეციალური ცხიმოვანი შრეა, რომელიც ნერვებს ფარავს. ის შეიძლება ელექტროსადენების გარშემო არსებულ საიზოლაციო ფენას შევადაროთ. ამ შრის გარეშე ელექტრული სიგნალები ნეირონებს შორის სწრაფად ვერ გადაიცემა. მიელინის გარსის ჩამოყალიბებასთან ერთად თქვენი ბავშვი გარედან მიღებულ გამოსახულებებსა და სიგნალებს უფრო სწრაფად აღიქვამს და გააანალიზებს.', baby_development_zh = '本周，宝宝的体重约为 65-70 克，身长约 10 厘米。宝宝现在已经像一个迷你小人儿，从头皮到眉毛都覆盖着浓密的胎毛，小耳朵和闭合的眼睑清晰可见。虽然宝宝眼睛的结构已经完整，但眼睛将是功能最晚发育成熟的器官。这背后有一个有趣的原因：尽管已经有许多神经细胞（神经元），包裹在它们周围的髓鞘却尚未形成。髓鞘是一层为神经提供绝缘保护的特殊脂肪层，可以把它想象成电线外面的绝缘层。没有这层结构，电信号就无法在神经元之间快速传递。随着髓鞘逐渐形成，宝宝将能更快地处理和解读外界的图像与信号。', baby_development_id = 'Minggu ini, berat bayi Anda sekitar 65-70 gram dengan panjang 10 cm. Kini bayi Anda menyerupai manusia dalam ukuran mungil, diselimuti rambut lanugo lebat dari kulit kepala hingga alis, dengan telinga kecil dan kelopak mata yang tertutup. Meskipun struktur mata bayi Anda sudah lengkap, mata akan menjadi organ terakhir yang fungsi kerjanya berkembang sepenuhnya. Ada alasan menarik di balik hal ini: meskipun terdapat banyak sel saraf (neuron), selubung mielin di sekelilingnya belum terbentuk. Selubung mielin adalah lapisan lemak khusus yang mengisolasi saraf. Anda dapat membayangkannya seperti lapisan isolasi pada kabel listrik. Tanpa lapisan ini, sinyal listrik tidak dapat dihantarkan dengan cepat antarneuron. Seiring berkembangnya selubung mielin, bayi Anda akan mampu memproses dan menafsirkan gambar serta sinyal dari luar dengan lebih cepat.', baby_development_fr = 'Cette semaine, votre bébé pèse environ 65-70 grammes et mesure 10 cm. Il ressemble désormais à un être humain miniature, couvert d’un lanugo dense du cuir chevelu jusqu’aux sourcils, avec de petites oreilles et les paupières fermées. Bien que les yeux de votre bébé soient complètement formés sur le plan structurel, ils seront les derniers organes à achever leur développement fonctionnel. Cela s’explique par une raison intéressante : malgré la présence de nombreuses cellules nerveuses, appelées neurones, la gaine de myéline qui les entoure ne s’est pas encore formée. La gaine de myéline est une couche graisseuse particulière qui isole les nerfs. On peut la comparer à la couche isolante qui entoure les câbles électriques. Sans cette couche, les signaux électriques ne peuvent pas être transmis rapidement entre les neurones. À mesure que la gaine de myéline se développera, votre bébé pourra traiter et interpréter plus rapidement les images et les signaux extérieurs.', baby_development_es = 'Esta semana, tu bebé pesa aproximadamente 65-70 gramos y mide 10 cm de longitud. Ya parece un ser humano en miniatura, cubierto de un denso lanugo desde el cuero cabelludo hasta las cejas, con unas orejas diminutas y los párpados cerrados. Aunque los ojos de tu bebé están estructuralmente completos, serán el último órgano en desarrollarse plenamente desde el punto de vista funcional. Hay una razón interesante: aunque existen muchas células nerviosas (neuronas), todavía no se ha formado la vaina de mielina que las rodea. La vaina de mielina es una capa grasa especial que aísla los nervios. Puedes compararla con la capa aislante que recubre los cables eléctricos. Sin esta capa, las señales eléctricas no pueden transmitirse rápidamente entre las neuronas. A medida que se desarrolle la vaina de mielina, tu bebé podrá procesar e interpretar con mayor rapidez las imágenes y señales externas.', baby_development_pt = 'Esta semana, o seu bebé pesa aproximadamente 65-70 gramas e mede 10 cm de comprimento. Já se assemelha a um ser humano em miniatura, coberto por uma densa camada de lanugo desde o couro cabeludo até às sobrancelhas, com orelhas minúsculas e as pálpebras fechadas. Embora os olhos do seu bebé estejam estruturalmente completos, serão o último órgão a desenvolver plenamente as suas funções. Há uma razão interessante para isso: apesar de existirem muitas células nervosas (neurónios), a bainha de mielina que as envolve ainda não se formou. A bainha de mielina é uma camada especial de gordura que isola os nervos. Pode compará-la à camada isolante que envolve os cabos elétricos. Sem esta camada, os sinais elétricos não conseguem ser transmitidos rapidamente entre os neurónios. À medida que a bainha de mielina se desenvolve, o seu bebé conseguirá processar e interpretar mais rapidamente as imagens e os sinais externos.', baby_development_vi = 'Tuần này, em bé nặng khoảng 65-70 gam và dài khoảng 10 cm. Giờ đây, bé trông như một người tí hon, với lớp lông tơ dày bao phủ từ da đầu đến lông mày, đôi tai nhỏ xíu và mí mắt khép kín. Mặc dù mắt của bé đã hoàn thiện về cấu trúc, đây sẽ là cơ quan cuối cùng hoàn thiện đầy đủ về chức năng. Điều này có một nguyên nhân thú vị: tuy đã có nhiều tế bào thần kinh (nơron), lớp bao myelin quanh chúng vẫn chưa hình thành. Bao myelin là một lớp chất béo đặc biệt có tác dụng cách điện cho dây thần kinh. Bạn có thể hình dung lớp này giống như lớp cách điện bao quanh dây cáp điện. Nếu không có lớp bao này, các tín hiệu điện không thể truyền nhanh giữa các nơron. Khi bao myelin phát triển, em bé sẽ có thể xử lý và diễn giải hình ảnh cùng tín hiệu từ bên ngoài nhanh hơn.', baby_development_hi = 'इस सप्ताह आपके बच्चे का वजन लगभग 65-70 ग्राम और लंबाई 10 सेमी है। अब वे एक नन्हे इंसान जैसे दिखाई देते हैं। सिर की त्वचा से लेकर भौंहों तक उनका शरीर घने लैनुगो बालों से ढका है और उनके कान छोटे तथा पलकें बंद हैं। हालाँकि आपके बच्चे की आँखों की संरचना पूरी हो चुकी है, लेकिन कार्यात्मक रूप से पूरी तरह विकसित होने वाला यह अंतिम अंग होगा। इसका एक दिलचस्प कारण है: तंत्रिका कोशिकाएँ यानी न्यूरॉन बहुत अधिक संख्या में मौजूद हैं, लेकिन उनके चारों ओर माइलिन आवरण अभी तक नहीं बना है। माइलिन आवरण वसा की एक विशेष परत है, जो तंत्रिकाओं को सुरक्षित और पृथक रखती है। आप इसकी तुलना बिजली के तारों के चारों ओर मौजूद इन्सुलेशन की परत से कर सकते हैं। इस परत के बिना न्यूरॉनों के बीच विद्युत संकेत तेज़ी से संचारित नहीं हो सकते। माइलिन आवरण विकसित होने के साथ आपका बच्चा बाहरी दृश्यों और संकेतों को अधिक तेज़ी से समझ और संसाधित कर सकेगा।', baby_development_ja = '今週の赤ちゃんは、体重が約65-70グラム、身長が約10 cmです。今では小さな人間のような姿になり、頭皮から眉まで密な産毛に覆われ、小さな耳と閉じたまぶたを備えて静かに過ごしています。赤ちゃんの目は構造上ほぼ完成していますが、機能が完全に発達するのは最後になります。これには興味深い理由があります。神経細胞（ニューロン）は多数存在するものの、その周囲を包む髄鞘がまだ形成されていないためです。髄鞘とは、神経を絶縁する特殊な脂肪の層です。電気ケーブルを覆う絶縁体のようなものと考えると分かりやすいでしょう。この層がなければ、電気信号をニューロン間で素早く伝えることができません。髄鞘が発達するにつれて、赤ちゃんは外から届く映像や信号をより速く処理し、理解できるようになります。', baby_development_ko = '이번 주 아기의 몸무게는 약 65-70그램이고, 키는 약 10cm예요. 이제 아기는 작은 사람의 모습을 하고 있으며, 두피부터 눈썹까지 촘촘한 배냇솜털로 덮여 있고 작은 귀와 감긴 눈꺼풀을 가진 채 쉬고 있어요. 아기의 눈은 구조적으로 완성됐지만, 기능적으로는 가장 마지막에 완전히 발달하는 기관이에요. 여기에는 흥미로운 이유가 있어요. 신경세포인 뉴런은 많지만, 아직 그 주위를 감싸는 수초가 형성되지 않았기 때문이에요. 수초는 신경을 절연하는 특별한 지방층으로, 전선을 감싸는 절연층과 비슷해요. 이 층이 없으면 뉴런 사이에서 전기 신호가 빠르게 전달될 수 없어요. 수초가 발달할수록 아기는 외부의 이미지와 신호를 더 빠르게 처리하고 해석할 수 있게 돼요.', baby_development_pl = 'W tym tygodniu Twoje dziecko waży około 65-70 gramów i ma 10 cm długości. Wygląda już jak miniaturowy człowiek. Jego ciało pokrywa gęsty meszek płodowy, obecny od skóry głowy aż po brwi, ma też maleńkie uszy i zamknięte powieki. Chociaż oczy Twojego dziecka są już w pełni ukształtowane, pod względem funkcjonalnym będą ostatnim narządem, który osiągnie pełną dojrzałość. Jest ku temu ciekawy powód: mimo że istnieje już wiele komórek nerwowych, czyli neuronów, nie utworzyła się jeszcze otaczająca je osłonka mielinowa. To specjalna warstwa tłuszczowa, która izoluje nerwy. Można ją porównać do izolacji otaczającej przewody elektryczne. Bez tej warstwy sygnały elektryczne nie mogą być szybko przekazywane między neuronami. W miarę rozwoju osłonki mielinowej Twoje dziecko będzie coraz szybciej przetwarzać i interpretować obrazy oraz sygnały z otoczenia.', baby_development_nl = 'Deze week weegt je baby ongeveer 65-70 gram en is hij of zij 10 cm lang. Je baby lijkt nu op een piepklein mensje en is van de hoofdhuid tot de wenkbrauwen bedekt met dicht lanugohaar. De kleine oortjes zijn zichtbaar en de oogleden zijn gesloten. Hoewel de ogen van je baby qua structuur compleet zijn, zullen ze functioneel als laatste volledig tot ontwikkeling komen. Daar is een interessante reden voor: er zijn al veel zenuwcellen (neuronen), maar de myelineschede eromheen is nog niet gevormd. De myelineschede is een speciale vetlaag die zenuwen isoleert. Je kunt deze vergelijken met de isolatielaag rond elektriciteitskabels. Zonder deze laag kunnen elektrische signalen niet snel tussen neuronen worden doorgegeven. Naarmate de myelineschede zich ontwikkelt, kan je baby beelden en signalen van buitenaf sneller verwerken en interpreteren.', baby_development_sv = 'Den här veckan väger ditt barn cirka 65-70 gram och är 10 cm långt. Barnet ser nu ut som en människa i miniatyr och är täckt av tät lanugobehåring från hjässan till ögonbrynen, med små öron och slutna ögonlock. Även om barnets ögon är färdigbildade rent strukturellt blir de det sista organet som utvecklas fullt ut funktionellt. Det finns en intressant förklaring: trots att det finns många nervceller, så kallade neuroner, har myelinskidan runt dem ännu inte bildats. Myelinskidan är ett särskilt fettlager som isolerar nerverna. Du kan jämföra den med isoleringen runt elektriska kablar. Utan detta lager kan elektriska signaler inte överföras snabbt mellan neuronerna. I takt med att myelinskidan utvecklas kommer ditt barn snabbare att kunna bearbeta och tolka bilder och signaler från omgivningen.' WHERE id = '6bfad434-2bc6-4bb0-9834-16dd77e6fbe8' AND md5(coalesce(baby_development,'')) = 'c09b68c1b22e3334295d9afacc9254ca' AND md5(coalesce(baby_development_en,'')) = '512faeb0651d55685ce4871988c9b7b6' AND md5(coalesce(baby_development_ru,'')) = '9971fa214398120d337a61212b15f8ec' AND md5(coalesce(baby_development_tr,'')) = '7e22c796269dc64d0331301fc9ba64b9' AND md5(coalesce(baby_development_kk,'')) = '0bd3e2ed4fef9db009ee0284587a61a5' AND md5(coalesce(baby_development_de,'')) = '4e49928db53e86c7868b015ecc4402b9' AND md5(coalesce(baby_development_ar,'')) = '135d7cdd96bc0738c14ba7af6eef51c7' AND md5(coalesce(baby_development_uz,'')) = '2250076cb43a02da1b9aa19d11cb29aa' AND md5(coalesce(baby_development_ka,'')) = '8acf31f4d805a46e0a62e71c5fb2fd08' AND md5(coalesce(baby_development_zh,'')) = 'c8056973b901c71b984bdbe13bd76c0b' AND md5(coalesce(baby_development_id,'')) = 'b58f6db63b425f056ead947f32e9d293' AND md5(coalesce(baby_development_fr,'')) = '16573d4a1867e46191b767bbd73da88e' AND md5(coalesce(baby_development_es,'')) = '698557b3d988b2dc98a1b2bf4fe61a96' AND md5(coalesce(baby_development_pt,'')) = '803712240dab68fc6484fb30954ffbbb' AND md5(coalesce(baby_development_vi,'')) = 'f05f9bec01053e05009519c6c006c4f1' AND md5(coalesce(baby_development_hi,'')) = '9dc7ff38c4de701f5e0a0e68f1b1bf14' AND md5(coalesce(baby_development_ja,'')) = 'fd76d5c6857b3aef7880b97a3c021b33' AND md5(coalesce(baby_development_ko,'')) = '5ab2edbd2ec9b0c150d8dc057e1023b8' AND md5(coalesce(baby_development_pl,'')) = 'aec2123f132ab2ef6028ef04d03358f7' AND md5(coalesce(baby_development_nl,'')) = 'f3e0a1c4109b6a7f93155ffece351f43' AND md5(coalesce(baby_development_sv,'')) = 'e7896d7ff8d336fc5817d79101b57cdf';
UPDATE public.pregnancy_daily_content SET baby_message = '16 HƏFTƏ BİTDİ! 🍎 Mən bir alma boydayam! Mənim üçün ən vacib xəbər: qan dövranım mükəmməl işləyir. Mənim kiçik ürəyim hər gün litrlərlə qan pompalayır. Mən böyüyürəm, güclənirəm və səninlə görüşəcəyim günü gözləyirəm. Sən mənim dünyamsan!', baby_message_en = '16 WEEKS COMPLETE! 🍎 I''m about the size of an apple! The most important news for me is that my blood circulation is working perfectly. My tiny heart is pumping liters of blood every single day. I''m growing, getting stronger, and eagerly awaiting the day I meet you. You are my world!', baby_message_ru = '16 НЕДЕЛЬ ПОЗАДИ! 🍎 Я размером с яблоко! Самая важная новость обо мне: моё кровообращение работает превосходно. Моё маленькое сердечко ежедневно перекачивает литры крови. Я расту, становлюсь сильнее и жду дня нашей встречи. Вы — весь мой мир!', baby_message_tr = '16 HAFTA TAMAMLANDI! 🍎 Ben bir elma büyüklüğündeyim! Benim için en önemli haber: Kan dolaşımım mükemmel çalışıyor. Küçük kalbim her gün litrelerce kan pompalıyor. Büyüyor, güçleniyor ve sizinle buluşacağım günü bekliyorum. Siz benim dünyamsınız!', baby_message_kk = '16 АПТА АЯҚТАЛДЫ! 🍎 Менің көлемім алмадай! Мен үшін ең маңызды жаңалық: қан айналымым керемет жұмыс істеп тұр. Кішкентай жүрегім күн сайын бірнеше литр қан айдайды. Мен өсіп, күш жинап, Сізбен кездесетін күнімді күтіп жүрмін. Сіз менің бүкіл әлемімсіз!', baby_message_de = '16 WOCHEN SIND GESCHAFFT! 🍎 Ich bin so groß wie ein Apfel! Die wichtigste Neuigkeit für mich: Mein Blutkreislauf funktioniert hervorragend. Mein kleines Herz pumpt jeden Tag literweise Blut. Ich wachse, werde stärker und freue mich auf den Tag, an dem ich dich endlich kennenlerne. Du bist meine Welt!', baby_message_ar = 'اكتمل الأسبوع 16! 🍎 أنا الآن بحجم تفاحة! أهم خبر بالنسبة إليّ هو أن دورتي الدموية تعمل على نحو مثالي. يضخ قلبي الصغير لترات من الدم كل يوم. أنا أنمو وأزداد قوة، وأنتظر اليوم الذي سألتقي فيه بكِ. أنتِ عالمي!', baby_message_uz = '16 HAFTA TUGADI! 🍎 Men olmadek kattalikdaman! Men uchun eng muhim yangilik: qon aylanish tizimim a’lo darajada ishlayapti. Mitti yuragim har kuni bir necha litr qonni haydaydi. Men o‘sib, kuchayib boryapman va siz bilan uchrashadigan kunimni kutyapman. Siz mening butun dunyomsiz!', baby_message_ka = '16 კვირა დასრულდა! 🍎 მე ვაშლის ზომის ვარ! ჩემთვის ყველაზე მნიშვნელოვანი ამბავი ის არის, რომ ჩემი სისხლის მიმოქცევა შესანიშნავად მუშაობს. ჩემი პატარა გული ყოველდღე ლიტრობით სისხლს გადატუმბავს. ვიზრდები, ვძლიერდები და მოუთმენლად ველი შენთან შეხვედრის დღეს. შენ ჩემი სამყარო ხარ!', baby_message_zh = '满 16 周啦！🍎 我现在大约有一个苹果那么大！对我来说，最重要的消息是，我的血液循环已经运转得非常顺畅。小小的心脏每天都在泵送数升血液。我不断长大、变强，满心期待着与你见面的那一天。你就是我的全世界！', baby_message_id = '16 MINGGU TELAH LENGKAP! 🍎 Ukuranku kira-kira sebesar apel! Kabar terpenting bagiku adalah sirkulasi darahku bekerja dengan sempurna. Jantung mungilku memompa berliter-liter darah setiap hari. Aku terus tumbuh, semakin kuat, dan tak sabar menantikan hari saat bertemu dengan Anda. Anda adalah duniaku!', baby_message_fr = '16 SEMAINES RÉVOLUES ! 🍎 J’ai à peu près la taille d’une pomme ! La grande nouvelle pour moi, c’est que ma circulation sanguine fonctionne parfaitement. Mon petit cœur pompe des litres de sang chaque jour. Je grandis, je deviens plus fort et j’attends avec impatience le jour où je vous rencontrerai. Vous êtes mon monde !', baby_message_es = '¡16 SEMANAS COMPLETAS! 🍎 ¡Tengo aproximadamente el tamaño de una manzana! La noticia más importante para mí es que mi circulación sanguínea funciona perfectamente. Mi diminuto corazón bombea litros de sangre todos los días. Estoy creciendo, haciéndome más fuerte y esperando con muchísima ilusión el día en que te conozca. ¡Eres mi mundo!', baby_message_pt = '16 SEMANAS COMPLETAS! 🍎 Tenho mais ou menos o tamanho de uma maçã! A notícia mais importante para mim é que a minha circulação sanguínea está a funcionar na perfeição. O meu pequeno coração bombeia litros de sangue todos os dias. Estou a crescer, a ficar mais forte e aguardo ansiosamente pelo dia em que te vou conhecer. Tu és o meu mundo!', baby_message_vi = 'ĐÃ TRÒN 16 TUẦN! 🍎 Mình có kích thước tương đương một quả táo! Tin quan trọng nhất là hệ tuần hoàn máu của mình đang hoạt động hoàn hảo. Trái tim bé xíu của mình bơm nhiều lít máu mỗi ngày. Mình đang lớn lên, khỏe mạnh hơn và háo hức chờ ngày được gặp bạn. Bạn là cả thế giới của mình!', baby_message_hi = '16 हफ़्ते पूरे! 🍎 मैं लगभग एक सेब जितना बड़ा हूँ! मेरे लिए सबसे अहम ख़बर यह है कि मेरा रक्त संचार बिल्कुल सही तरह से काम कर रहा है। मेरा नन्हा-सा दिल हर दिन कई लीटर रक्त पंप कर रहा है। मैं बढ़ रहा हूँ, मज़बूत हो रहा हूँ और आपसे मिलने के दिन का बेसब्री से इंतज़ार कर रहा हूँ। आप ही मेरी दुनिया हैं!', baby_message_ja = '16週完了！🍎 私はリンゴくらいの大きさです！一番大切なお知らせは、私の血液循環がしっかり機能していることです。小さな心臓は、毎日何リットルもの血液を送り出しています。私は成長して強くなり、あなたに会える日を心待ちにしています。あなたは私の世界です！', baby_message_ko = '16주 완료! 🍎 나는 사과만 해요! 가장 중요한 소식은 내 혈액순환이 아주 원활하게 이루어지고 있다는 거예요. 조그만 심장은 매일 수 리터의 피를 힘차게 내보내요. 나는 자라고 튼튼해지며 엄마를 만날 날을 손꼽아 기다리고 있어요. 엄마는 나의 세상이에요!', baby_message_pl = 'TYDZIEŃ 16 UKOŃCZONY! 🍎 Jestem mniej więcej wielkości jabłka! Najważniejsza wiadomość jest taka, że moje krążenie działa doskonale. Moje maleńkie serce każdego dnia pompuje litry krwi. Rosnę, nabieram sił i z niecierpliwością czekam na dzień naszego spotkania. Jesteś całym moim światem!', baby_message_nl = '16 WEKEN VOLBRACHT! 🍎 Ik ben ongeveer zo groot als een appel! Het belangrijkste nieuws is dat mijn bloedsomloop perfect werkt. Mijn piepkleine hart pompt elke dag liters bloed rond. Ik groei, word sterker en kijk reikhalzend uit naar de dag waarop ik je ontmoet. Jij bent mijn wereld!', baby_message_sv = '16 VECKOR KLARA! 🍎 Jag är ungefär lika stor som ett äpple! Den viktigaste nyheten är att min blodcirkulation fungerar perfekt. Mitt lilla hjärta pumpar flera liter blod varje dag. Jag växer, blir starkare och längtar efter dagen då jag får träffa dig. Du är hela min värld!' WHERE id = '4db5e35d-0bef-4624-aa7c-2dbb50189eef' AND md5(coalesce(baby_message,'')) = '568f6f91deedcc8e63a02b39342a7613' AND md5(coalesce(baby_message_en,'')) = '8838964d780072e62a6e9a0c6520f90c' AND md5(coalesce(baby_message_ru,'')) = '547c65c64cf16428531714de9dfbe24d' AND md5(coalesce(baby_message_tr,'')) = '94a58cbbc62e4c4fc4495dcd4427a14a' AND md5(coalesce(baby_message_kk,'')) = '1aabee09520d022fe17d8ec7ed89046d' AND md5(coalesce(baby_message_de,'')) = '517eef06cfe82fdbd3642816587d51cf' AND md5(coalesce(baby_message_ar,'')) = '73f5cc3fbd1a3483c55493bd4c740866' AND md5(coalesce(baby_message_uz,'')) = '6962e7eb8f6ca4015feafbea83b0b84e' AND md5(coalesce(baby_message_ka,'')) = 'e908a70c99b71a5fecb64efa0a72dd77' AND md5(coalesce(baby_message_zh,'')) = '275174f573dd61be1232ecf14f6dd657' AND md5(coalesce(baby_message_id,'')) = '3698c130fc2773dce62e545ce92358be' AND md5(coalesce(baby_message_fr,'')) = '92ff67ad8a3a8a92ee4340eb3de9611e' AND md5(coalesce(baby_message_es,'')) = '094163e84661696d96b29f41dbb40d63' AND md5(coalesce(baby_message_pt,'')) = '6c8cf19708d354d9f8bccdfa2b0a83dc' AND md5(coalesce(baby_message_vi,'')) = 'b1ef181c6dd8b743f5d826451c4df77c' AND md5(coalesce(baby_message_hi,'')) = '5793efe7b05bd25a3e23d2cbaee8e106' AND md5(coalesce(baby_message_ja,'')) = '2a12fb42da4cd55dc2bd0007b2ef5f91' AND md5(coalesce(baby_message_ko,'')) = '01131c6a86037020748ef91e3e5ef878' AND md5(coalesce(baby_message_pl,'')) = '2a878d99deb92a9f584de4cee4bc00db' AND md5(coalesce(baby_message_nl,'')) = '7221ce70121acd54b0f8d4fc6911caa7' AND md5(coalesce(baby_message_sv,'')) = 'a288250bc924f4e74166cad752d98100';
UPDATE public.pregnancy_daily_content SET baby_message = 'Salam, Anacan! Mən bir armud boydayam. Mənim sinirlərim inkişaf edir. "Mielin" adlanan xüsusi bir maddə sinirlərimin ətrafını sarıyır. Bu, mənim beynimdən bədənimə gedən mesajların daha sürətli çatmasını təmin edəcək. Mən hər gün daha ağıllı oluram!', baby_message_en = 'Hello, Mom! I''m about the size of a pear. My nerves are developing. A special substance called "myelin" is coating my nerves. This will ensure that messages from my brain reach my body faster. I''m getting smarter every day!', baby_message_ru = 'Здравствуйте, мамочка! Сейчас я размером с грушу. Моя нервная система развивается. Особое вещество под названием «миелин» покрывает мои нервные волокна. Благодаря ему сигналы от мозга к телу будут передаваться быстрее. С каждым днём я становлюсь умнее!', baby_message_tr = 'Merhaba, anneciğim! Ben bir armut büyüklüğündeyim. Sinirlerim gelişiyor. "Miyelin" adı verilen özel bir madde sinirlerimin etrafını sarıyor. Bu, beynimden vücuduma giden mesajların daha hızlı iletilmesini sağlayacak. Her gün daha akıllı oluyorum!', baby_message_kk = 'Сәлем, анашым! Менің көлемім алмұрттай. Жүйкелерім дамып келеді. «Миелин» деп аталатын ерекше зат жүйкелерімді қоршап жатыр. Соның арқасында миымнан денеме жіберілетін хабарлар жылдамырақ жететін болады. Мен күн сайын ақылдырақ болып келемін!', baby_message_de = 'Hallo, Mami! Ich bin so groß wie eine Birne. Meine Nerven entwickeln sich weiter. Eine besondere Substanz namens „Myelin“ umhüllt meine Nerven. Dadurch können die Signale von meinem Gehirn schneller zu meinem Körper gelangen. Ich werde jeden Tag schlauer!', baby_message_ar = 'مرحبًا يا ماما! أصبح حجمي الآن بحجم حبة كمثرى. تتطور أعصابي، وتلتف حولها مادة خاصة تُسمى "الميالين". وستساعد هذه المادة الرسائل المنطلقة من دماغي إلى جسمي على الوصول بسرعة أكبر. أنا أزداد ذكاءً كل يوم!', baby_message_uz = 'Salom, Onajon! Men bir dona nok kattaligiman. Nervlarim rivojlanmoqda. "Miyelin" deb ataladigan maxsus modda nervlarimni o‘rab olmoqda. Bu miyamdan tanamga boradigan xabarlarning tezroq yetib borishini ta’minlaydi. Men kundan kunga aqlliroq bo‘lib boryapman!', baby_message_ka = 'გამარჯობა, დედიკო! მე მსხლის ზომის ვარ. ჩემი ნერვები ვითარდება. სპეციალური ნივთიერება, სახელად „მიელინი“, ჩემს ნერვებს გარს ეხვევა. მისი წყალობით ჩემი ტვინიდან სხეულისკენ გაგზავნილი სიგნალები უფრო სწრაფად მიაღწევს დანიშნულების ადგილს. მე ყოველდღე უფრო ჭკვიანი ვხდები!', baby_message_zh = '妈妈，你好呀！我现在大约有一个梨那么大。我的神经正在发育，一种叫作“髓鞘”的特殊物质正包裹着神经。这样，大脑发出的信息就能更快传遍全身。我一天比一天聪明啦！', baby_message_id = 'Halo, Bunda! Ukuranku kira-kira sebesar buah pir. Sarafku sedang berkembang. Zat khusus yang disebut "mielin" sedang melapisi sarafku. Lapisan ini akan memastikan pesan dari otakku sampai ke tubuhku dengan lebih cepat. Setiap hari aku semakin pintar!', baby_message_fr = 'Bonjour, Maman ! J’ai à peu près la taille d’une poire. Mes nerfs se développent. Une substance spéciale appelée « myéline » les enveloppe. Elle permettra aux messages envoyés par mon cerveau d’atteindre mon corps plus rapidement. Je deviens plus intelligent chaque jour !', baby_message_es = '¡Hola, mamá! Tengo aproximadamente el tamaño de una pera. Mis nervios se están desarrollando. Una sustancia especial llamada «mielina» los está recubriendo. Esto permitirá que los mensajes de mi cerebro lleguen más rápido a mi cuerpo. ¡Cada día soy más inteligente!', baby_message_pt = 'Olá, mamã! Tenho mais ou menos o tamanho de uma pera. Os meus nervos estão a desenvolver-se. Uma substância especial chamada «mielina» está a revesti-los. Isto vai permitir que as mensagens do meu cérebro cheguem mais depressa ao meu corpo. Estou a ficar mais inteligente a cada dia!', baby_message_vi = 'Chào mẹ! Con có kích thước tương đương một quả lê. Các dây thần kinh của con đang phát triển. Một chất đặc biệt gọi là "myelin" đang bao bọc các dây thần kinh, giúp tín hiệu từ não truyền đến cơ thể con nhanh hơn. Mỗi ngày con lại thông minh hơn!', baby_message_hi = 'नमस्ते, मम्मी! मैं लगभग एक नाशपाती जितना बड़ा हूँ। मेरी नसें विकसित हो रही हैं। "माइलिन" नाम का एक खास पदार्थ मेरी नसों पर परत बना रहा है। इससे मेरे मस्तिष्क के संदेश मेरे शरीर तक अधिक तेजी से पहुँच सकेंगे। मैं हर दिन और समझदार हो रहा हूँ!', baby_message_ja = 'こんにちは、ママ！今の私は洋梨くらいの大きさだよ。神経が発達しているところなんだ。「ミエリン」という特別な物質が神経を覆い始めているよ。これによって、脳からの信号がもっと速く体に届くようになるんだ。毎日どんどん賢くなっているよ！', baby_message_ko = '안녕하세요, 엄마! 저는 배만 한 크기예요. 신경이 발달하고 있고, "미엘린"이라는 특별한 물질이 신경을 감싸고 있어요. 덕분에 뇌의 신호가 몸에 더 빨리 전달될 거예요. 저는 매일 더 똑똑해지고 있어요!', baby_message_pl = 'Cześć, Mamo! Jestem mniej więcej wielkości gruszki. Rozwija się mój układ nerwowy. Moje nerwy pokrywa specjalna substancja zwana „mieliną”. Dzięki niej sygnały z mózgu będą szybciej docierać do mojego ciała. Z każdym dniem jestem coraz mądrzejszym maleństwem!', baby_message_nl = 'Hallo, mama! Ik ben ongeveer zo groot als een peer. Mijn zenuwen ontwikkelen zich. Een speciale stof, ‘myeline’, vormt een laagje rond mijn zenuwen. Daardoor komen signalen van mijn hersenen sneller bij mijn lichaam aan. Ik word elke dag slimmer!', baby_message_sv = 'Hej, mamma! Jag är ungefär lika stor som ett päron. Mina nerver utvecklas. Ett särskilt ämne som kallas "myelin" lägger sig runt nerverna. Det gör att signalerna från min hjärna når kroppen snabbare. Jag blir smartare för varje dag!' WHERE id = 'b73aa0c0-fb01-4c2d-abb0-69a88e7c97e4' AND md5(coalesce(baby_message,'')) = '722e580618406a54382deebc5d273fa5' AND md5(coalesce(baby_message_en,'')) = 'd30a0fa9c436e9eb748bbe44cc9be4c2' AND md5(coalesce(baby_message_ru,'')) = '83a04c7f2c9373e1364bd7c5cf9e5679' AND md5(coalesce(baby_message_tr,'')) = '12755cbcf104b37544d1b70fe70eda64' AND md5(coalesce(baby_message_kk,'')) = '544327069238543e52767c3c2ecfbf3e' AND md5(coalesce(baby_message_de,'')) = '4c744ed2bfc27f922325ab4e0a12b9e6' AND md5(coalesce(baby_message_ar,'')) = '0f1184d1f7045f1fb9fe74d83170c37e' AND md5(coalesce(baby_message_uz,'')) = 'a246b7bdec036499941cfc8e874f0f8a' AND md5(coalesce(baby_message_ka,'')) = 'b060c52047b380760955c4140114ba1b' AND md5(coalesce(baby_message_zh,'')) = 'e7b1dec8970f6ecf9816ebf8bbd3689c' AND md5(coalesce(baby_message_id,'')) = 'a466e61dafe7174f24f3ddd62aab858d' AND md5(coalesce(baby_message_fr,'')) = '7550578799d56f3c07bffa8fe2974088' AND md5(coalesce(baby_message_es,'')) = '7bac8b148d8603140a4d91a8ee2a959b' AND md5(coalesce(baby_message_pt,'')) = '67f377fb6fbac6ff9702bb80a1fe472f' AND md5(coalesce(baby_message_vi,'')) = '27b01d31e6f08e5f71084f960189aa38' AND md5(coalesce(baby_message_hi,'')) = 'b9cc33a8ae625bb5ede281e20a5124a9' AND md5(coalesce(baby_message_ja,'')) = '5b9e3af8090b617fafbaa7880e9e72fe' AND md5(coalesce(baby_message_ko,'')) = '7d600f7769a111b463578b853fb1b987' AND md5(coalesce(baby_message_pl,'')) = '35c7a3e3a45514d7a5d98bdc2495df5b' AND md5(coalesce(baby_message_nl,'')) = '5a2bd8a2de2ccb20e41c4aecefefdfab' AND md5(coalesce(baby_message_sv,'')) = '5098a91c584e890b3b5c308b7a230999';
UPDATE public.pregnancy_daily_content SET baby_message = 'Salam, Anacan! Mən bir şirin bibər boydayam. Mənim qollarım və ayaqlarım artıq bədənimlə mütənasibdir. Mən kiçik bir insanam! İndi sənə daha güclü təpiklər ata bilirəm. Hazır ol!', baby_message_en = 'Hello, Mom! I''m about the size of a sweet pepper now. My arms and legs are already proportionate to my body. I''m a little human! Now I can give you even stronger kicks. Get ready!', baby_message_ru = 'Привет, мамочка! Я уже размером со сладкий перец. Мои ручки и ножки теперь пропорциональны телу. Я маленький человечек! Теперь я могу толкаться сильнее. Будьте готовы!', baby_message_tr = 'Merhaba, anneciğim! Ben bir tatlı biber büyüklüğündeyim. Kollarım ve bacaklarım artık vücudumla orantılı. Ben küçük bir insanım! Artık sana daha güçlü tekmeler atabiliyorum. Hazır ol!', baby_message_kk = 'Сәлем, анашым! Менің көлемім тәтті бұрыштай. Қолдарым мен аяқтарым енді денеме сай қалыптасты. Мен кішкентай адаммын! Енді саған қаттырақ тебе аламын. Дайын бол!', baby_message_de = 'Hallo, Mami! Ich bin so groß wie eine Paprika. Meine Arme und Beine passen jetzt schon zu den Proportionen meines Körpers. Ich bin ein kleiner Mensch! Jetzt kann ich dich noch kräftiger treten. Mach dich bereit!', baby_message_ar = 'مرحبًا يا ماما! أنا بحجم حبة فلفل حلو. أصبح ذراعاي وساقاي الآن متناسبين مع جسمي. أنا إنسان صغير! ويمكنني الآن أن أركلكِ بقوة أكبر. كوني مستعدة!', baby_message_uz = 'Salom, Onajon! Men shirin qalampirdek kattalikdaman. Qo‘llarim va oyoqlarim endi tanamga mutanosib. Men kichkina insonman! Endi sizni yanada kuchliroq tepishim mumkin. Tayyor turing!', baby_message_ka = 'გამარჯობა, დედიკო! მე ტკბილი წიწაკის ზომის ვარ. ჩემი ხელები და ფეხები უკვე სხეულის პროპორციულია. მე პატარა ადამიანი ვარ! ახლა უკვე უფრო ძლიერად შემიძლია დაგარტყა ფეხები. მზად იყავი!', baby_message_zh = '妈妈，你好！我现在大约有一个甜椒那么大。我的胳膊和腿已经与身体很协调了。我是个小小的人啦！现在我能更用力地踢你了。准备好哦！', baby_message_id = 'Halo, Mama! Sekarang ukuranku kira-kira sebesar paprika. Lengan dan kakiku sudah proporsional dengan tubuhku. Aku manusia mungil! Kini aku bisa menendang Anda lebih kuat lagi. Bersiaplah!', baby_message_fr = 'Bonjour, Maman ! Je fais maintenant à peu près la taille d''un poivron. Mes bras et mes jambes sont déjà bien proportionnés par rapport à mon corps. Je suis un petit être humain ! Maintenant, je peux vous donner des coups de pied encore plus forts. Préparez-vous !', baby_message_es = '¡Hola, mamá! Ahora tengo aproximadamente el tamaño de un pimiento. Mis brazos y piernas ya guardan proporción con mi cuerpo. ¡Soy un pequeño ser humano! Ya puedo darte patadas aún más fuertes. ¡Prepárate!', baby_message_pt = 'Olá, mamã! Agora tenho mais ou menos o tamanho de um pimento. Os meus braços e pernas já são proporcionais ao meu corpo. Sou um ser humano pequenino! Agora consigo dar-te pontapés ainda mais fortes. Prepara-te!', baby_message_vi = 'Chào mẹ! Giờ con có kích thước cỡ một quả ớt chuông. Tay và chân con đã cân đối với cơ thể. Con là một em bé tí hon rồi! Giờ con có thể đạp mẹ mạnh hơn nữa đấy. Mẹ chuẩn bị nhé!', baby_message_hi = 'नमस्ते, माँ! अब मेरा आकार लगभग एक मीठी शिमला मिर्च जितना है। मेरे हाथ और पैर अब मेरे शरीर के अनुपात में हैं। मैं एक नन्हा इंसान हूँ! अब मैं आपको पहले से भी ज़्यादा ज़ोरदार किक मार सकता/सकती हूँ। तैयार रहिए!', baby_message_ja = 'こんにちは、ママ！ 今の私はパプリカくらいの大きさです。腕と脚は、もう体に合ったバランスになっています。小さな人間です！ これからは、もっと力強くキックできます。準備していてね！', baby_message_ko = '안녕하세요, 엄마! 이제 저는 피망만 해요. 팔과 다리는 벌써 몸에 맞는 비율로 자랐어요. 저는 작은 사람이에요! 이제 엄마에게 더 힘찬 발차기를 할 수 있어요. 준비하세요!', baby_message_pl = 'Cześć, Mamo! Jestem teraz mniej więcej wielkości słodkiej papryki. Moje rączki i nóżki są już proporcjonalne do reszty ciała. Jestem maleńkim człowiekiem! Teraz mogę kopać Cię jeszcze mocniej. Przygotuj się!', baby_message_nl = 'Hallo, mama! Ik ben nu ongeveer zo groot als een paprika. Mijn armen en benen staan al in verhouding tot mijn lichaam. Ik ben een klein mensje! Nu kan ik je nog stevigere schopjes geven. Zet je maar schrap!', baby_message_sv = 'Hej, mamma! Nu är jag ungefär lika stor som en paprika. Mina armar och ben är redan proportionerliga till kroppen. Jag är en liten människa! Nu kan jag sparka ännu kraftigare. Gör dig redo!' WHERE id = 'c0a11fee-73af-4684-98a2-4425bd830ba9' AND md5(coalesce(baby_message,'')) = '038e57cbd203fafef750770ad2a91aa4' AND md5(coalesce(baby_message_en,'')) = '52bc784a2da8eb6fa327c9e95b891aa9' AND md5(coalesce(baby_message_ru,'')) = '353b077ce60e1935179fb50d6a5be31c' AND md5(coalesce(baby_message_tr,'')) = '460a874a7ee1d3ae189e2f0afb4b3897' AND md5(coalesce(baby_message_kk,'')) = '7f35b7109b0fcaa599d824fde59aff46' AND md5(coalesce(baby_message_de,'')) = '34838abc4ad9ec0e1eecfa70266c1fda' AND md5(coalesce(baby_message_ar,'')) = 'f2366cef59e86cb0aa4256f58f3945a3' AND md5(coalesce(baby_message_uz,'')) = 'e6cb63c4b86db9d2c6e26cd35591c161' AND md5(coalesce(baby_message_ka,'')) = '22822a0f02f076c36b8e50ef9817f539' AND md5(coalesce(baby_message_zh,'')) = 'a177fab3cc75437fc59cb3560de7b56a' AND md5(coalesce(baby_message_id,'')) = '3de435e1bcea90056c1bff34b01cb516' AND md5(coalesce(baby_message_fr,'')) = '37461c89363cd0d30e010120776ca3d0' AND md5(coalesce(baby_message_es,'')) = 'b05b436d7fd2c89652656a08c03d4978' AND md5(coalesce(baby_message_pt,'')) = 'ee5cde0447fc5dcc2bf99b3c5b51744e' AND md5(coalesce(baby_message_vi,'')) = '1fbe255d4eebfea8c9856aff4ac9fd28' AND md5(coalesce(baby_message_hi,'')) = '26a1126b806d944577d7ad9b08d8f243' AND md5(coalesce(baby_message_ja,'')) = '9cf595298b292f85c73d168383a81f5a' AND md5(coalesce(baby_message_ko,'')) = '36b114cdf6ebcdd5bc58bbe2aa0f715a' AND md5(coalesce(baby_message_pl,'')) = '738335ae8a368b77ac72b0861727f29e' AND md5(coalesce(baby_message_nl,'')) = '35f1fc101cc2b80e6f7c71c318fb460a' AND md5(coalesce(baby_message_sv,'')) = 'a3b7d11c3f947ede95f4bc670bce2291';
UPDATE public.pregnancy_day_notifications SET title = 'Bir pomidor boyda! 🍅', title_en = 'The size of a tomato! 🍅', title_ru = 'Я размером с помидор! 🍅', title_tr = 'Bir domates boyundayım! 🍅', title_kk = 'Бір қызанақтаймын! 🍅', title_de = 'So groß wie eine Tomate! 🍅', title_ar = 'بحجم حبة طماطم! 🍅', title_uz = 'Bir pomidor kattaligida! 🍅', title_ka = 'პომიდვრის ზომის ვარ! 🍅' WHERE id = '6fb4f290-31ce-473d-a17d-ea607c5d055d' AND md5(coalesce(title,'')) = '10209c92d14a4ed5a8265a71c93ae65b' AND md5(coalesce(title_en,'')) = 'b7969c9220db6b38cc1dc8ced091d4b4' AND md5(coalesce(title_ru,'')) = '283f4fbcefc15ec26353db9e3de29c92' AND md5(coalesce(title_tr,'')) = 'ec36a574af6cfed729d2f06dcc2ee60c' AND md5(coalesce(title_kk,'')) = 'e5c6f70fe29d233abbefebc35a02a496' AND md5(coalesce(title_de,'')) = '9b974bfdd0224ae2c957a19238645126' AND md5(coalesce(title_ar,'')) = '46de3474482e83bd0302c980bd1ed0d6' AND md5(coalesce(title_uz,'')) = 'b92c76a237fd43d29d369ab6ddf13146' AND md5(coalesce(title_ka,'')) = 'be27eb69f1f1c4c2f131ef25023bb1f1';
UPDATE public.pregnancy_daily_content SET baby_message = 'YOLUN YARISI! 🏁 Təbriklər, Anacan! Biz 40 həftəlik marafonun düz yarısını (50%-ni) bitirdik. Mən bir pomidor boydayam! İnanılmazdır, elə deyilmi? İndiyə qədər necə böyüdüyümə bax. Sənin qarnın artıq göbək səviyyəsinə çatıb. Biz finişə doğru gedirik!', baby_message_en = 'HALFWAY THERE! 🏁 Congratulations, Mommy! We''ve completed exactly half (50%) of our 40-week marathon. I''m the size of a tomato! Isn''t that incredible? Look at how much I''ve grown already. Your bump has reached your belly button. We''re heading towards the finish line!', baby_message_ru = 'ПОЛОВИНА ПУТИ! 🏁 Поздравляю, мамочка! Мы преодолели ровно половину (50%) нашего 40-недельного марафона. Я уже размером с помидор! Невероятно, правда? Только посмотрите, как я вырос! Ваш живот уже поднялся до уровня пупка. Мы движемся к финишу!', baby_message_tr = 'YOLUN YARISI! 🏁 Tebrikler, anneciğim! 40 haftalık maratonun tam yarısını (50%''sini) tamamladık. Ben bir domates büyüklüğündeyim! İnanılmaz, değil mi? Şimdiye kadar ne kadar büyüdüğüme bakın. Karnınız artık göbek deliğinizin hizasına ulaştı. Bitişe doğru ilerliyoruz!', baby_message_kk = 'ЖОЛДЫҢ ЖАРТЫСЫ! 🏁 Құттықтаймын, анашым! Біз 40 апталық марафонның тура жартысын (50%-ын) аяқтадық. Менің бойым қызанақтай болды! Керемет, солай емес пе? Осы уақытқа дейін қалай өскеніме қараңызшы. Жатырыңыз енді кіндік деңгейіне жетті. Біз мәреге қарай бет алып келеміз!', baby_message_de = 'DIE HÄLFTE IST GESCHAFFT! 🏁 Herzlichen Glückwunsch, Mami! Wir haben genau die Hälfte (50%) unseres 40-wöchigen Marathons geschafft. Ich bin so groß wie eine Tomate! Unglaublich, oder? Schau nur, wie sehr ich bisher gewachsen bin. Deine Gebärmutter reicht jetzt bis auf Höhe deines Bauchnabels. Wir sind auf dem Weg ins Ziel!', baby_message_ar = 'قطعنا نصف الطريق! 🏁 تهانينا يا ماما! لقد أتممنا نصف ماراثون الأسابيع الـ40 بالضبط (50%). أصبح حجمي بحجم حبة طماطم! أمر مذهل، أليس كذلك؟ انظري كم كبرت حتى الآن. لقد وصل رحمكِ الآن إلى مستوى سرتكِ. إننا نتجه نحو خط النهاية!', baby_message_uz = 'YO‘LNING YARMI! 🏁 Tabriklayman, Onajon! Biz 40 haftalik marafonning qoq yarmini (50%-ni) bosib o‘tdik. Men pomidordek kattaman! Ajoyib, shunday emasmi? Shu paytgacha qanchalik o‘sganimga qarang. Qorningiz endi kindik darajasiga yetdi. Biz marraga tomon ketyapmiz!', baby_message_ka = 'გზის ნახევარი გავიარეთ! 🏁 გილოცავთ, დედიკო! 40-კვირიანი მარათონის ზუსტად ნახევარი (50%) დავასრულეთ. უკვე პომიდვრის ზომის ვარ! დაუჯერებელია, არა? შეხედეთ, აქამდე რამდენად გავიზარდე. თქვენი მუცელი უკვე ჭიპის დონემდეა გაზრდილი. ფინიშისკენ მივიწევთ!', baby_message_zh = '已经走完一半啦！🏁 恭喜你，妈妈！这场为期40周的马拉松，我们已经正好完成了一半（50%）。我现在有一个番茄那么大！是不是很不可思议？看看我已经长大了多少。你的孕肚也已经长到肚脐的位置。我们正在向终点前进！', baby_message_id = 'SUDAH SETENGAH JALAN! 🏁 Selamat, Mama! Kita telah menyelesaikan tepat setengah (50%) dari maraton selama 40 minggu. Ukuranku sebesar tomat! Menakjubkan, bukan? Lihat betapa besarnya aku sekarang. Perut Anda sudah mencapai pusar. Kita sedang menuju garis akhir!', baby_message_fr = 'À MI-CHEMIN ! 🏁 Félicitations, Maman ! Nous avons parcouru exactement la moitié (50%) de notre marathon de 40 semaines. J’ai la taille d’une tomate ! N’est-ce pas incroyable ? Regardez comme j’ai déjà grandi. Votre ventre arrondi atteint maintenant votre nombril. Nous nous dirigeons vers la ligne d’arrivée !', baby_message_es = '¡YA ESTAMOS A MITAD DE CAMINO! 🏁 ¡Enhorabuena, mamá! Hemos completado exactamente la mitad (50%) de nuestro maratón de 40 semanas. ¡Tengo el tamaño de un tomate! ¿No es increíble? Mira cuánto he crecido ya. Tu barriguita ya llega a la altura del ombligo. ¡Nos dirigimos hacia la meta!', baby_message_pt = 'JÁ VAMOS A MEIO! 🏁 Parabéns, mamã! Completámos exatamente metade (50%) da nossa maratona de 40 semanas. Sou do tamanho de um tomate! Não é incrível? Olha como já cresci tanto. A tua barriga já chegou ao nível do umbigo. Estamos a caminho da meta!', baby_message_vi = 'ĐÃ ĐI ĐƯỢC NỬA CHẶNG ĐƯỜNG! 🏁 Chúc mừng mẹ! Chúng ta đã hoàn thành chính xác một nửa (50%) chặng đường kéo dài 40 tuần. Giờ con lớn bằng một quả cà chua rồi! Thật khó tin phải không? Hãy xem con đã lớn biết bao. Bụng bầu của bạn đã cao đến rốn. Chúng ta đang tiến về vạch đích!', baby_message_hi = 'आधा सफ़र पूरा हुआ! 🏁 बधाई हो, मम्मी! हमने अपनी 40-सप्ताह की मैराथन का ठीक आधा (50%) हिस्सा पूरा कर लिया है। अब मेरा आकार एक टमाटर जितना है! है न कमाल की बात? देखिए, मैं कितना बड़ा/बड़ी हो गया/गई हूँ। आपका पेट अब आपकी नाभि तक उभर आया है। हम मंज़िल की ओर बढ़ रहे हैं!', baby_message_ja = 'ついに折り返し地点！ 🏁 ママ、おめでとう！ 40週間のマラソンのちょうど半分（50%）を走り終えたよ。今の私はトマトくらいの大きさ！ すごいでしょう？ もうこんなに大きくなったんだよ。おなかのふくらみは、おへそのあたりまで来ているよ。さあ、ゴールを目指そう！', baby_message_ko = '절반까지 왔어요! 🏁 축하해요, 엄마! 40주간의 여정 중 정확히 절반(50%)을 완주했어요. 저는 토마토만 한 크기예요! 정말 놀랍지 않나요? 제가 벌써 얼마나 자랐는지 보세요. 엄마의 배도 배꼽 높이까지 나왔어요. 이제 결승선을 향해 가고 있어요!', baby_message_pl = 'POŁOWA DROGI ZA NAMI! 🏁 Gratulacje, Mamo! Mamy za sobą dokładnie połowę (50%) naszego 40-tygodniowego maratonu. Jestem wielkości pomidora! Niesamowite, prawda? Zobacz, jak wiele już udało mi się urosnąć. Twój brzuszek sięga już pępka. Zmierzamy prosto do mety!', baby_message_nl = 'WE ZIJN HALVERWEGE! 🏁 Gefeliciteerd, mama! We hebben precies de helft (50%) van onze marathon van 40 weken voltooid. Ik ben zo groot als een tomaat! Ongelooflijk, toch? Kijk eens hoeveel ik al ben gegroeid. Je buik komt nu tot je navel. We gaan richting de finish!', baby_message_sv = 'HALVVÄGS! 🏁 Grattis, mamma! Vi har klarat exakt hälften (50 %) av vårt 40 veckor långa maraton. Jag är lika stor som en tomat! Visst är det otroligt? Titta så mycket jag redan har vuxit. Din mage når nu upp till naveln. Vi är på väg mot mållinjen!' WHERE id = 'ce6d14e2-2cef-47b0-bf61-c80d97194d99' AND md5(coalesce(baby_message,'')) = 'b07000bac78f539ae59c1595cf116ac1' AND md5(coalesce(baby_message_en,'')) = '9cbd4d2a9a7b0e8faacfaf3424cda40f' AND md5(coalesce(baby_message_ru,'')) = 'bed80b888e02a482daf062da0a7e9358' AND md5(coalesce(baby_message_tr,'')) = 'ef16aae7584316db9b2f148bd5ef9b31' AND md5(coalesce(baby_message_kk,'')) = 'dfd1cb87ba2ed502d38665aafbcf5ca3' AND md5(coalesce(baby_message_de,'')) = '8e807d9045e90846ca980f08918fdcab' AND md5(coalesce(baby_message_ar,'')) = '2143c943e98b5175aa7a137c2d8b45b8' AND md5(coalesce(baby_message_uz,'')) = 'e0dc70c96d4ccca7ce0bc3a7c9aa5196' AND md5(coalesce(baby_message_ka,'')) = '6a703460b79f5f40a8f62e1056f8a804' AND md5(coalesce(baby_message_zh,'')) = 'bac4178fd838ced82b69ae25209f6a3c' AND md5(coalesce(baby_message_id,'')) = 'aec9e96a506ca4fcccab78541173eb7d' AND md5(coalesce(baby_message_fr,'')) = 'd113a2760adaecdcf69b58e548fdca6a' AND md5(coalesce(baby_message_es,'')) = '3a0882b37ee47d8cb354988adced9256' AND md5(coalesce(baby_message_pt,'')) = '6e9429d7cd191437fcc6e6656db7cd44' AND md5(coalesce(baby_message_vi,'')) = 'd30d727ebdbeac3be76e9b1530ea3f19' AND md5(coalesce(baby_message_hi,'')) = '13e254de0fe57da1bad4e516a4bbb18c' AND md5(coalesce(baby_message_ja,'')) = '9d09e2c48ce1a37be0a7e6f08460357a' AND md5(coalesce(baby_message_ko,'')) = '4fb09c97cb2d7a1b83b09fe54116b117' AND md5(coalesce(baby_message_pl,'')) = 'f89553082299ed65a37fbb0c46029a3a' AND md5(coalesce(baby_message_nl,'')) = '39c8199001317c94f7507c11e09c506b' AND md5(coalesce(baby_message_sv,'')) = '5bfaac83b96bd6cb57871efe9d8d1f28';
UPDATE public.pregnancy_daily_content SET baby_development = 'Körpənizin çəkisi isə təxminən 330 qramdır. Nə qədər sürətlə böyüyür, deyilmi?İnanılmaz sürətlə böyüyən körpənizin bədəninə ürəyi daha çox qan pompalaya bilmək üçün bir an belə dayanmadan çalışmağa davam edir. Bu sayədə ürək əzələləri inkişaf etməyə və güclənməyə davam edir.;;;
Ürəkdə baş verən əzələ hərəkətləri sayəsində körpənizin bədəninin hər bir hüceyrəsinə oksigen və qida daşına bilir. Yəni, bu hərəkətlər yaşam üçün zəruri olan funksiyaların yerinə yetirilməsi üçün vacibdir.', baby_development_en = 'Your baby now weighs about 330 grams. Growing so fast, aren''t they? To pump more blood to your incredibly fast-growing baby''s body, their heart continues to work tirelessly, not resting for a moment. This constant effort allows the heart muscles to continue developing and strengthening.;;;
Thanks to the muscular contractions within the heart, oxygen and nutrients can be delivered to every cell in your baby''s body. These movements are essential for carrying out vital life functions.', baby_development_ru = 'Вес вашего малыша составляет около 330 граммов. Как же быстро он растёт, правда? Сердце вашего стремительно растущего малыша продолжает работать без остановки, чтобы перекачивать больше крови по всему его организму. Благодаря этому сердечная мышца продолжает развиваться и укрепляться.;;;
Благодаря сокращениям сердца кислород и питательные вещества поступают к каждой клетке организма малыша. Эти сокращения необходимы для поддержания жизненно важных функций.', baby_development_tr = 'Bebeğinizin ağırlığı yaklaşık 330 gramdır. Ne kadar hızlı büyüyor, değil mi? İnanılmaz bir hızla büyüyen bebeğinizin vücuduna daha fazla kan pompalayabilmek için kalbi bir an bile durmadan çalışmaya devam ediyor. Bu sayede kalp kasları gelişmeyi ve güçlenmeyi sürdürüyor.;;;
Kalpte gerçekleşen kas hareketleri sayesinde bebeğinizin vücudundaki her hücreye oksijen ve besin taşınabilir. Yani bu hareketler, yaşam için gerekli işlevlerin yerine getirilmesi açısından büyük önem taşır.', baby_development_kk = 'Бөпеңіздің салмағы шамамен 330 грамм. Неткен жылдам өсу, солай емес пе?Керемет жылдамдықпен өсіп жатқан бөпеңіздің денесіне көбірек қан айдау үшін жүрегі бір сәт те тоқтамай жұмысын жалғастыруда. Соның арқасында жүрек бұлшықеттері дамып, нығая береді.;;;
Жүрек бұлшықетінің жиырылуы арқылы бөпеңіздің денесіндегі әрбір жасушаға оттегі мен қоректік заттар жеткізіледі. Яғни, бұл қозғалыстар өмірге қажетті қызметтердің орындалуы үшін аса маңызды.', baby_development_de = 'Dein Baby wiegt inzwischen etwa 330 Gramm. Es wächst unglaublich schnell, nicht wahr? Das Herz deines rasant wachsenden Babys arbeitet ohne Pause weiter, damit es mehr Blut durch seinen Körper pumpen kann. Dadurch entwickelt sich der Herzmuskel weiter und wird kräftiger.;;;
Dank der Muskelbewegungen des Herzens können Sauerstoff und Nährstoffe zu jeder einzelnen Zelle im Körper deines Babys transportiert werden. Diese Bewegungen sind also unverzichtbar, damit alle lebenswichtigen Funktionen erfüllt werden können.', baby_development_ar = 'يبلغ وزن طفلكِ نحو 330 غرامًا. إنه ينمو بسرعة كبيرة، أليس كذلك؟ يواصل قلب طفلكِ، الذي ينمو بسرعة مذهلة، العمل بلا توقف ولو للحظة كي يضخ مزيدًا من الدم إلى جسمه. وبفضل ذلك، تستمر عضلة قلبه في النمو واكتساب القوة.;;;
وبفضل انقباضات عضلة القلب، يصل الأكسجين والعناصر الغذائية إلى كل خلية في جسم طفلكِ. أي إن هذه الانقباضات ضرورية لأداء الوظائف اللازمة للحياة.', baby_development_uz = 'Chaqalog‘ingizning vazni esa taxminan 330 gramm. U qanchalik tez o‘smoqda, shunday emasmi?Nihoyatda tez o‘sayotgan chaqalog‘ingiz tanasiga ko‘proq qon haydash uchun uning yuragi bir lahza ham to‘xtamasdan ishlashda davom etmoqda. Shu tariqa yurak mushaklari rivojlanib, kuchayishda davom etadi.;;;
Yurak mushaklarining harakati tufayli chaqalog‘ingiz tanasidagi har bir hujayraga kislorod va oziq moddalar yetkaziladi. Ya’ni, bu harakatlar hayot uchun zarur vazifalarning bajarilishida muhimdir.', baby_development_ka = 'თქვენი ბავშვის წონა დაახლოებით 330 გრამია. რა სწრაფად იზრდება, არა? წარმოუდგენელი სისწრაფით მზარდი ბავშვის სხეულისთვის მეტი სისხლის მისაწოდებლად მისი გული წამითაც არ ჩერდება და მუშაობას განაგრძობს. ამის წყალობით გულის კუნთები კვლავ ვითარდება და ძლიერდება.;;;
გულის კუნთის შეკუმშვების მეშვეობით ჟანგბადი და საკვები ნივთიერებები ბავშვის სხეულის თითოეულ უჯრედამდე აღწევს. ეს მოძრაობები სიცოცხლისთვის აუცილებელი ფუნქციების შესრულებას უზრუნველყოფს.', baby_development_zh = '宝宝现在的体重约为330克。长得真快，对吧？为了向飞速成长的宝宝全身泵送更多血液，宝宝的心脏一刻不停地持续工作。这种不间断的活动让心肌得以继续发育并变得更加强壮。;;;
通过心脏内部的肌肉收缩，氧气和营养物质能够输送到宝宝身体的每一个细胞。这些运动对于维持重要的生命活动必不可少。', baby_development_id = 'Bayi Anda kini memiliki berat sekitar 330 gram. Pertumbuhannya cepat sekali, bukan? Untuk memompa lebih banyak darah ke seluruh tubuh bayi Anda yang tumbuh begitu pesat, jantungnya terus bekerja tanpa lelah dan tidak beristirahat sesaat pun. Upaya tanpa henti ini memungkinkan otot-otot jantungnya untuk terus berkembang dan menguat.;;;
Berkat kontraksi otot di dalam jantung, oksigen dan nutrisi dapat disalurkan ke setiap sel dalam tubuh bayi Anda. Gerakan ini sangat penting untuk menjalankan fungsi-fungsi vital tubuh.', baby_development_fr = 'Votre bébé pèse désormais environ 330 grammes. Il grandit si vite, n’est-ce pas ? Pour envoyer davantage de sang dans l’organisme de votre bébé, qui se développe à une vitesse incroyable, son cœur continue à travailler sans relâche, sans se reposer un seul instant. Cet effort constant permet aux muscles cardiaques de poursuivre leur développement et de se renforcer.;;;
Grâce aux contractions musculaires du cœur, l’oxygène et les nutriments peuvent parvenir à chaque cellule de l’organisme de votre bébé. Ces mouvements sont indispensables à l’accomplissement des fonctions vitales.', baby_development_es = 'Tu bebé ya pesa unos 330 gramos. ¡Está creciendo muy rápido! Para bombear más sangre al cuerpo de tu bebé, que crece a un ritmo increíble, su corazón sigue trabajando sin descanso, sin detenerse ni un instante. Este esfuerzo constante permite que los músculos del corazón continúen desarrollándose y fortaleciéndose.;;;
Gracias a las contracciones musculares del corazón, el oxígeno y los nutrientes pueden llegar a todas las células del cuerpo de tu bebé. Estos movimientos son esenciales para llevar a cabo las funciones vitales.', baby_development_pt = 'O seu bebé pesa agora cerca de 330 gramas. Está a crescer tão depressa, não está? Para bombear mais sangue para o corpo do seu bebé, que cresce a um ritmo incrível, o coração continua a trabalhar incansavelmente, sem parar um único instante. Este esforço constante permite que os músculos cardíacos continuem a desenvolver-se e a fortalecer-se.;;;
Graças às contrações musculares do coração, o oxigénio e os nutrientes chegam a todas as células do corpo do seu bebé. Estes movimentos são essenciais para o desempenho das funções vitais.', baby_development_vi = 'Em bé hiện nặng khoảng 330 gram. Em bé lớn nhanh quá phải không? Để bơm thêm máu đến cơ thể đang phát triển với tốc độ đáng kinh ngạc của em bé, tim vẫn hoạt động không ngừng nghỉ, không ngơi dù chỉ một lúc. Nỗ lực liên tục này giúp cơ tim tiếp tục phát triển và khỏe hơn.;;;
Nhờ các cơn co cơ trong tim, oxy và chất dinh dưỡng có thể được đưa đến từng tế bào trong cơ thể em bé. Những chuyển động này rất cần thiết để duy trì các chức năng sống quan trọng.', baby_development_hi = 'अब आपके शिशु का वजन लगभग 330 ग्राम है। वह कितनी तेजी से बढ़ रहा है, है न? आपके बेहद तेजी से बढ़ते शिशु के शरीर तक अधिक रक्त पंप करने के लिए उसका हृदय बिना एक पल रुके लगातार काम कर रहा है। इस निरंतर प्रयास से हृदय की मांसपेशियां विकसित और मजबूत होती रहती हैं।;;;
हृदय के भीतर होने वाले मांसपेशियों के संकुचन की बदौलत ऑक्सीजन और पोषक तत्व आपके शिशु के शरीर की प्रत्येक कोशिका तक पहुंच पाते हैं। जीवन के लिए आवश्यक महत्वपूर्ण कार्यों को पूरा करने हेतु ये गतिविधियां अनिवार्य हैं।', baby_development_ja = '赤ちゃんの体重は現在、約330グラムです。本当に成長が早いですね。驚くほど速く成長する赤ちゃんの体へより多くの血液を送り出すため、心臓は一瞬も休まず働き続けています。この絶え間ない働きによって、心筋はさらに発達し、強くなります。;;;
心臓の筋肉が収縮することで、酸素と栄養が赤ちゃんの体のすべての細胞へ届けられます。この動きは、生命を維持するために欠かせません。', baby_development_ko = '이제 아기의 몸무게는 약 330그램이에요. 정말 빠르게 자라고 있죠? 놀라운 속도로 성장하는 아기의 몸에 더 많은 혈액을 보내기 위해 심장은 한순간도 쉬지 않고 계속 일하고 있어요. 이러한 지속적인 활동 덕분에 심장 근육도 계속 발달하고 튼튼해져요.;;;
심장 근육이 수축하면서 산소와 영양분이 아기 몸의 모든 세포에 전달돼요. 이러한 움직임은 생명 유지에 필수적인 기능을 수행하는 데 꼭 필요해요.', baby_development_pl = 'Twoje dziecko waży teraz około 330 gramów. Ale szybko rośnie, prawda? Serce ani na chwilę nie odpoczywa i nadal niestrudzenie pracuje, aby pompować więcej krwi do niezwykle szybko rosnącego organizmu dziecka. Ten ciągły wysiłek sprawia, że mięsień sercowy nadal się rozwija i wzmacnia.;;;
Dzięki skurczom mięśnia sercowego tlen i składniki odżywcze mogą docierać do każdej komórki organizmu dziecka. Ruchy te są niezbędne do podtrzymywania podstawowych funkcji życiowych.', baby_development_nl = 'Je baby weegt nu ongeveer 330 gram. Wat groeit je baby snel, hè? Om meer bloed door het lichaam van je razendsnel groeiende baby te pompen, blijft het hart onvermoeibaar werken, zonder ook maar even te rusten. Door deze voortdurende inspanning kunnen de hartspieren zich verder ontwikkelen en sterker worden.;;;
Dankzij de spiersamentrekkingen in het hart kunnen zuurstof en voedingsstoffen naar elke cel in het lichaam van je baby worden vervoerd. Deze bewegingen zijn onmisbaar voor de vitale lichaamsfuncties.', baby_development_sv = 'Ditt barn väger nu ungefär 330 gram. Visst växer barnet snabbt? För att pumpa mer blod till den otroligt snabbt växande kroppen fortsätter barnets hjärta att arbeta outtröttligt, utan att vila ett ögonblick. Det ständiga arbetet gör att hjärtmuskeln fortsätter att utvecklas och bli starkare.;;;
Tack vare hjärtats muskelsammandragningar kan syre och näringsämnen transporteras till varje cell i ditt barns kropp. Dessa rörelser är nödvändiga för kroppens livsviktiga funktioner.' WHERE id = '2f4c880c-7bdd-4dec-acbd-cd0e6c8859e0' AND md5(coalesce(baby_development,'')) = '44c4bc7241c7a8030c40689cef5d419c' AND md5(coalesce(baby_development_en,'')) = 'c7610059ec975ba985bee98ea614c837' AND md5(coalesce(baby_development_ru,'')) = '8b1289af9ad3fc195f9a6f13ade6e065' AND md5(coalesce(baby_development_tr,'')) = 'b0792874078f60a831e8f2c19afdabd6' AND md5(coalesce(baby_development_kk,'')) = 'a0dacf739ced6ff19204e1aeef47befd' AND md5(coalesce(baby_development_de,'')) = '32897c0640fd1e0e34f379d8d59bbf9d' AND md5(coalesce(baby_development_ar,'')) = '5daa0caedcce677acec38080fddd2e5f' AND md5(coalesce(baby_development_uz,'')) = '0fca6c69b1ffe3d0d306c248d176a3ea' AND md5(coalesce(baby_development_ka,'')) = '3c196c05207e38d966655c809cf66800' AND md5(coalesce(baby_development_zh,'')) = 'a84559634100c0e8e50a54228735d9b2' AND md5(coalesce(baby_development_id,'')) = 'c9e184f0dae18ae37846984ded4d4458' AND md5(coalesce(baby_development_fr,'')) = '07674390a717e9a85408f14cb8136d10' AND md5(coalesce(baby_development_es,'')) = '8b3117e1fb964cd2ab6e744a8afe246c' AND md5(coalesce(baby_development_pt,'')) = '98e4d1ee3c066121a191d1f3d5b212dc' AND md5(coalesce(baby_development_vi,'')) = '4ab2e234a73a6c8f6a4f2e6d0339d15e' AND md5(coalesce(baby_development_hi,'')) = '0a478d6a3403856d0e63acc355dd08a4' AND md5(coalesce(baby_development_ja,'')) = 'fff9e6ef37b3f34513c0eea2b24bfe13' AND md5(coalesce(baby_development_ko,'')) = 'ad564f69bd8be3db7e0ec7b8d3773fa3' AND md5(coalesce(baby_development_pl,'')) = '4994d7f92812eb9da4a9accdb93713de' AND md5(coalesce(baby_development_nl,'')) = 'fab4817f4d1997a8367989d7de6d329d' AND md5(coalesce(baby_development_sv,'')) = 'b0a38d739ef3805ba0cf2938770c1cfd';
UPDATE public.pregnancy_daily_content SET baby_message = '🍌 Mən bir banan boydayam! Mən indi daha çox yatıram və daha güclü təpik atıram. Mənim yuxu rejimim sənin rejiminlə tərs ola bilər. Sən yatanda mən oyanıram, çünki sən hərəkətsiz qalanda mənə "yelləncək" dayanmış kimi gəlir və oyanıram.', baby_message_en = '🍌 I''m the size of a banana! I''m sleeping more now and kicking stronger. My sleep schedule might be the opposite of yours. When you sleep, I wake up, because when you stop moving, it feels like my "swing" has stopped, and I wake up.', baby_message_ru = '🍌 Я размером с банан! Теперь я больше сплю и сильнее пинаюсь. Мой режим сна может не совпадать с вашим. Когда вы засыпаете, я просыпаюсь, потому что, когда вы не двигаетесь, мне кажется, будто мои "качели" остановились, и я просыпаюсь.', baby_message_tr = '🍌 Bir muz boyundayım! Artık daha çok uyuyor ve daha güçlü tekmeler atıyorum. Benim uyku düzenim sizinkiyle ters olabilir. Siz uyuduğunuzda ben uyanıyorum; çünkü siz hareketsiz kaldığınızda bana "salıncağım" durmuş gibi geliyor ve uyanıyorum.', baby_message_kk = '🍌 Мен бір бананның көлеміндеймін! Қазір көбірек ұйықтаймын әрі күштірек тебемін. Менің ұйқы тәртібім сенікіне қарама-қарсы болуы мүмкін. Сен ұйықтағанда, мен оянамын, өйткені сен қимылсыз жатқанда мені тербететін "әткеншек" тоқтап қалғандай сезіледі де, мен оянып кетемін.', baby_message_de = '🍌 Ich bin so groß wie eine Banane! Ich schlafe jetzt mehr und trete kräftiger. Mein Schlafrhythmus kann deinem genau entgegengesetzt sein. Wenn du schläfst, wache ich auf, denn sobald du dich nicht mehr bewegst, fühlt es sich für mich so an, als hätte meine "Schaukel" angehalten – und dann werde ich wach.', baby_message_ar = '🍌 أنا بحجم موزة! أنام الآن وقتًا أطول وأركل بقوة أكبر. وقد يكون نمط نومي معاكسًا لنمطكِ. فعندما تنامين أستيقظ، لأن توقفكِ عن الحركة يجعلني أشعر كما لو أن "الأرجوحة" قد توقفت، فأستيقظ.', baby_message_uz = '🍌 Men bir banandekman! Endi men ko‘proq uxlayman va kuchliroq tepaman. Mening uyqu tartibim siznikiga teskari bo‘lishi mumkin. Siz uxlaganingizda men uyg‘onaman, chunki siz harakatsiz qolganingizda menga "belanchak" to‘xtagandek tuyuladi va men uyg‘onib ketaman.', baby_message_ka = '🍌 ერთი ბანანის ზომის ვარ! ახლა უფრო მეტხანს მძინავს და უფრო ძლიერად ვურტყამ ფეხებს. ჩემი ძილის რეჟიმი შეიძლება შენს რეჟიმს არ დაემთხვეს. როცა შენ გძინავს, მე ვიღვიძებ, რადგან როცა აღარ მოძრაობ, მგონია, რომ ჩემი „საქანელა“ გაჩერდა, და მეღვიძება.', baby_message_zh = '🍌 我现在有一根香蕉那么大啦！我睡得更多了，踢得也更有力。我的作息可能正好和你相反。你睡觉时，我却醒了，因为你不动以后，我的“摇篮”就像停了下来，于是我就会醒来。', baby_message_id = '🍌 Besarku sekarang seukuran pisang! Aku kini lebih sering tidur dan menendang lebih kuat. Jadwal tidurku mungkin berkebalikan dengan jadwal Anda. Saat Anda tidur, aku terbangun, karena ketika Anda berhenti bergerak, rasanya seperti "ayunanku" berhenti sehingga aku pun bangun.', baby_message_fr = '🍌 J’ai la taille d’une banane ! Je dors davantage maintenant et mes coups sont plus forts. Mon rythme de sommeil est peut-être à l’opposé du vôtre. Quand vous dormez, je me réveille, car lorsque vous ne bougez plus, j’ai l’impression que ma « balançoire » s’est arrêtée, et cela me réveille.', baby_message_es = '🍌 ¡Tengo el tamaño de un plátano! Ahora duermo más y doy patadas más fuertes. Puede que mi horario de sueño sea opuesto al tuyo. Cuando tú duermes, yo me despierto, porque cuando dejas de moverte siento que mi «columpio» se ha detenido, y eso me despierta.', baby_message_pt = '🍌 Sou do tamanho de uma banana! Agora durmo mais e dou pontapés mais fortes. O meu horário de sono pode ser o oposto do teu. Quando dormes, eu acordo, porque, quando deixas de te mexer, parece que o meu «baloiço» parou e eu desperto.', baby_message_vi = '🍌 Con lớn bằng một quả chuối rồi! Giờ con ngủ nhiều hơn và đạp mạnh hơn. Lịch ngủ của con có thể trái ngược với mẹ. Khi mẹ ngủ, con lại thức, vì lúc mẹ ngừng cử động, con cảm thấy chiếc "xích đu" của mình cũng dừng lại nên con tỉnh giấc.', baby_message_hi = '🍌 मैं एक केले जितना हूँ! अब मैं ज़्यादा सोता हूँ और पहले से ज़्यादा ज़ोर से लात मारता हूँ। हो सकता है मेरी सोने की दिनचर्या आपकी दिनचर्या से बिल्कुल उलट हो। जब आप सोती हैं, तो मैं जाग जाता हूँ, क्योंकि आपके हिलना बंद करते ही मुझे लगता है कि मेरा "झूला" रुक गया है और मेरी नींद खुल जाती है।', baby_message_ja = '🍌 バナナくらいの大きさになったよ！ 今は前より長く眠り、力強く蹴るようになったんだ。私の睡眠リズムは、ママと反対かもしれないよ。ママが眠ると私は目を覚ますんだ。ママの動きが止まると、私の「ブランコ」も止まったように感じて目が覚めるの。', baby_message_ko = '🍌 저는 바나나만 해요! 이제 잠을 더 많이 자고 발차기도 더 힘차게 해요. 제 수면 시간은 엄마와 반대일지도 몰라요. 엄마가 잠들면 저는 깨어나요. 엄마가 움직임을 멈추면 제 "그네"도 멈춘 것처럼 느껴져서 잠에서 깨거든요.', baby_message_pl = '🍌 Jestem wielkości banana! Teraz więcej śpię i mocniej kopię. Mój rytm snu może być odwrotny do Twojego. Kiedy Ty śpisz, ja się budzę, bo gdy przestajesz się ruszać, czuję, jakby moja „huśtawka” się zatrzymała — i wtedy otwieram oczy.', baby_message_nl = '🍌 Ik ben zo groot als een banaan! Ik slaap nu meer en schop harder. Mijn slaapritme is misschien precies het tegenovergestelde van dat van jou. Als jij slaapt, word ik wakker. Wanneer jij niet meer beweegt, voelt het namelijk alsof mijn "schommel" stopt en word ik wakker.', baby_message_sv = '🍌 Jag är lika stor som en banan! Nu sover jag mer och sparkar kraftigare. Min dygnsrytm kan vara motsatsen till din. När du sover vaknar jag, för när du slutar röra dig känns det som om min ”gunga” har stannat, och då vaknar jag.' WHERE id = '4291c964-97b5-4aa4-a48e-b3cb8e0fe5cb' AND md5(coalesce(baby_message,'')) = '584afd9173f325b75902c685a0aeedb9' AND md5(coalesce(baby_message_en,'')) = 'f71b84bbb00be579a60d243b9ed34f5d' AND md5(coalesce(baby_message_ru,'')) = '242174ed1bf30515ff301852f1f06e72' AND md5(coalesce(baby_message_tr,'')) = '46c5921ede8f61e9490c248b8a98603c' AND md5(coalesce(baby_message_kk,'')) = '4bf0dd0f086ca76519414273d85b2de7' AND md5(coalesce(baby_message_de,'')) = '9bbb9e0bef346eafeb6201d17e6dc90c' AND md5(coalesce(baby_message_ar,'')) = 'f7e6e4098882d53da02c56561a6950bc' AND md5(coalesce(baby_message_uz,'')) = 'f13bcebc5bf4fbc9206210e5ccd2848f' AND md5(coalesce(baby_message_ka,'')) = '42fd3e8fb9f81eb70346d3df862d1779' AND md5(coalesce(baby_message_zh,'')) = 'f67d664d62d4d9b20ecb5b2f2b641405' AND md5(coalesce(baby_message_id,'')) = 'bdbed1cfb286bdb5aeb631ecec1b2515' AND md5(coalesce(baby_message_fr,'')) = '9f6080606da3089ae20da7978a138663' AND md5(coalesce(baby_message_es,'')) = '52d180c55efbf44f5858c5220f23ff8d' AND md5(coalesce(baby_message_pt,'')) = '46d44470db1da09b485d04d811034898' AND md5(coalesce(baby_message_vi,'')) = 'ec026f27975ca13a706c68e03eac7dcb' AND md5(coalesce(baby_message_hi,'')) = 'acca00e7f57ff1f3beb427b44d2a5d57' AND md5(coalesce(baby_message_ja,'')) = '43bcda7339109747d029d6c9e9461eb4' AND md5(coalesce(baby_message_ko,'')) = '466da03f802a910c507e65478d72a274' AND md5(coalesce(baby_message_pl,'')) = '22376408bcc9ae83d110bef7dc914eb0' AND md5(coalesce(baby_message_nl,'')) = '8e47457764feb28f078b9b5efcf25111' AND md5(coalesce(baby_message_sv,'')) = '5b5149538d274ecbf2f186bd5d141f3b';
UPDATE public.pregnancy_daily_content SET baby_message = '🥕 Mən bir yerkökü boydayam! Mən indi miniatür bir körpəyəm. Qaşlarım, kirpiklərim, dırnaqlarım – hər şeyim var. İndi əsas məqsədim kökəlmək və ağciyərlərimi hazırlamaqdır. Mən hələ çox arığam, amma sən məni yaxşı bəsləyirsən.', baby_message_en = '🥕 I''m about the size of a carrot! I''m a miniature baby now. My eyebrows, eyelashes, nails – I have everything. My main goal now is to gain weight and prepare my lungs. I''m still very thin, but you''re feeding me well.', baby_message_ru = '🥕 Я размером с морковь! Сейчас я уже похож на миниатюрного малыша. У меня есть всё: брови, ресницы, ногти. Теперь моя главная цель — набрать вес и подготовить лёгкие. Я пока ещё очень худенький, но ты хорошо меня питаешь.', baby_message_tr = '🥕 Bir havuç büyüklüğündeyim! Artık minyatür bir bebeğim. Kaşlarım, kirpiklerim, tırnaklarım – her şeyim var. Şimdi asıl amacım kilo almak ve akciğerlerimi hazırlamak. Henüz çok zayıfım ama siz beni çok iyi besliyorsunuz.', baby_message_kk = '🥕 Менің көлемім сәбіздей! Қазір мен кішкентай ғана бөпемін. Қастарым, кірпіктерім, тырнақтарым — бәрі бар. Ендігі негізгі мақсатым — салмақ қосып, өкпемді дайындау. Мен әлі өте арықпын, бірақ сен мені жақсы қоректендіріп жүрсің.', baby_message_de = '🥕 Ich bin so groß wie eine Karotte! Jetzt bin ich ein Baby im Miniaturformat. Ich habe Augenbrauen, Wimpern, Nägel – einfach alles. Mein wichtigstes Ziel ist es jetzt, zuzunehmen und meine Lunge auf das Atmen vorzubereiten. Ich bin noch sehr dünn, aber du versorgst mich gut.', baby_message_ar = '🥕 أنا بحجم جزرة! أصبحت الآن طفلًا مصغرًا. لدي حاجبان ورموش وأظافر، وكل أعضائي موجودة. هدفي الأساسي الآن هو اكتساب الوزن وتجهيز رئتيّ. ما زلت نحيفًا جدًا، لكنكِ تغذينني جيدًا.', baby_message_uz = '🥕 Men sabzidek kattalikdaman! Hozir men mittigina chaqaloqman. Qoshlarim, kipriklarim, tirnoqlarim — hammasi bor. Endi asosiy maqsadim vazn to‘plash va o‘pkamni tayyorlash. Men hali juda ozg‘inman, ammo siz meni yaxshi oziqlantiryapsiz.', baby_message_ka = '🥕 მე სტაფილოს ზომის ვარ! ახლა უკვე მინიატიურული ბავშვი ვარ. წარბები, წამწამები, ფრჩხილები – ყველაფერი მაქვს. ახლა ჩემი მთავარი მიზანი წონის მომატება და ფილტვების მომზადებაა. ჯერ კიდევ ძალიან გამხდარი ვარ, მაგრამ თქვენ კარგად მკვებავთ.', baby_message_zh = '🥕 我现在大约有一根胡萝卜那么大！我已经是个迷你小宝宝了。眉毛、睫毛、指甲——我什么都有了。现在我的主要任务是增加体重，让肺部做好准备。我还很瘦，不过你把我喂养得很好。', baby_message_id = '🥕 Ukuranku kira-kira sebesar wortel! Sekarang aku adalah bayi dalam ukuran mini. Alis, bulu mata, kuku—semuanya sudah kumiliki. Tujuan utamaku sekarang adalah menambah berat badan dan mempersiapkan paru-paruku. Aku masih sangat kurus, tetapi Anda memberiku nutrisi dengan baik.', baby_message_fr = '🥕 J’ai à peu près la taille d’une carotte ! Je suis maintenant un bébé miniature. J’ai tout : des sourcils, des cils et des ongles. Mon principal objectif est désormais de prendre du poids et de préparer mes poumons. Je suis encore très mince, mais vous me nourrissez bien.', baby_message_es = '🥕 ¡Tengo aproximadamente el tamaño de una zanahoria! Ahora soy un bebé en miniatura. Tengo de todo: cejas, pestañas y uñas. Mi principal objetivo ahora es ganar peso y preparar mis pulmones. Todavía estoy muy delgado, pero me alimentas bien.', baby_message_pt = '🥕 Sou mais ou menos do tamanho de uma cenoura! Agora já sou um bebé em miniatura. Tenho tudo: sobrancelhas, pestanas e unhas. O meu principal objetivo agora é ganhar peso e preparar os pulmões. Ainda sou muito magro, mas estás a alimentar-me bem.', baby_message_vi = '🥕 Con có kích thước tương đương một củ cà rốt! Giờ con đã là một em bé thu nhỏ. Lông mày, lông mi, móng tay – con có đủ cả rồi. Mục tiêu chính của con lúc này là tăng cân và chuẩn bị cho phổi. Con vẫn còn rất gầy, nhưng mẹ đang nuôi dưỡng con thật tốt.', baby_message_hi = '🥕 मैं लगभग एक गाजर जितना बड़ा हूँ! अब मैं एक नन्हे शिशु जैसा हूँ। मेरी भौंहें, पलकें, नाखून—सब कुछ है। अब मेरा मुख्य लक्ष्य वज़न बढ़ाना और अपने फेफड़ों को तैयार करना है। मैं अभी भी बहुत दुबला हूँ, लेकिन आप मुझे अच्छी तरह पोषण दे रही हैं।', baby_message_ja = '🥕 ニンジンくらいの大きさだよ！もう小さな赤ちゃんの姿になったんだ。眉毛も、まつ毛も、爪も、全部そろっているよ。これからの主な目標は、体重を増やして肺を整えること。まだとても細いけれど、ママがしっかり栄養を届けてくれているよ。', baby_message_ko = '🥕 저는 당근만 해요! 이제 작은 아기의 모습을 모두 갖췄어요. 눈썹, 속눈썹, 손발톱까지 전부 있어요. 이제 가장 중요한 목표는 체중을 늘리고 폐를 준비하는 거예요. 아직 많이 말랐지만 엄마가 영양을 잘 공급해 주고 있어요.', baby_message_pl = '🥕 Mam mniej więcej wielkość marchewki! Jestem już miniaturowym dzieckiem. Mam wszystko — brwi, rzęsy i paznokcie. Teraz moim głównym celem jest przybieranie na wadze i przygotowanie płuc. Wciąż mam bardzo szczupłe ciałko, ale dobrze mnie odżywiasz.', baby_message_nl = '🥕 Ik ben ongeveer zo groot als een wortel! Ik ben nu een baby in het klein. Wenkbrauwen, wimpers, nagels: ik heb alles al. Mijn belangrijkste doel is nu aankomen en mijn longen voorbereiden. Ik ben nog heel dun, maar jij voedt me goed.', baby_message_sv = '🥕 Jag är ungefär lika stor som en morot! Nu är jag en liten miniatyrbebis. Jag har allt – ögonbryn, ögonfransar och naglar. Mitt viktigaste mål nu är att gå upp i vikt och förbereda lungorna. Jag är fortfarande väldigt smal, men du ger mig gott om näring.' WHERE id = '0192bd32-2239-497b-af81-dc9dc504732a' AND md5(coalesce(baby_message,'')) = '15837759d7f1a45a019afe85cb79dce1' AND md5(coalesce(baby_message_en,'')) = 'e0d957a1d692b6255462b2f4dd35fc42' AND md5(coalesce(baby_message_ru,'')) = 'e8c1a8113facececde36351cdaa147c7' AND md5(coalesce(baby_message_tr,'')) = 'f735aa6820839e882d2af5ccb7f5089e' AND md5(coalesce(baby_message_kk,'')) = '547c73d9219eedddc0d034c2f6a9c294' AND md5(coalesce(baby_message_de,'')) = '583f77b465b1a64ff7d8dca318526e31' AND md5(coalesce(baby_message_ar,'')) = 'a5b68ec6238a1004e406b90ff1095992' AND md5(coalesce(baby_message_uz,'')) = '71c6569b849f06f28d6e57c3fc9099ac' AND md5(coalesce(baby_message_ka,'')) = '95e987f8c4abd917e33346d3af6b58ba' AND md5(coalesce(baby_message_zh,'')) = '3796708037b5dd03d0ff0678b5079ddb' AND md5(coalesce(baby_message_id,'')) = '232468d063815ceaaca09acec7d2b1d3' AND md5(coalesce(baby_message_fr,'')) = '96eb3d38e5e699b14bfdcdf2b6bf6166' AND md5(coalesce(baby_message_es,'')) = '31c8607c262fa470ba2f4af1d1771ece' AND md5(coalesce(baby_message_pt,'')) = '9f4f6ca548337a7fa94f78e5b75a6e40' AND md5(coalesce(baby_message_vi,'')) = '851aa6aa8c387c85982e2d2dc7164ab6' AND md5(coalesce(baby_message_hi,'')) = '166c19421e9f62d1cfb8830b6d2704da' AND md5(coalesce(baby_message_ja,'')) = '80a82f1ec62904d2ce89c577a0c2bbf9' AND md5(coalesce(baby_message_ko,'')) = 'e001f47bd4d6e3f64f5a833a39faebf3' AND md5(coalesce(baby_message_pl,'')) = 'e317902589a56c7c5c83750e9d7a6b2a' AND md5(coalesce(baby_message_nl,'')) = '11c0dcebb36ed2fa8f9e52bc0f364055' AND md5(coalesce(baby_message_sv,'')) = '25cc6da07f8877c0b4b66b4ad14a4613';
UPDATE public.pregnancy_daily_content SET baby_message = 'Mən bir yerkökü boydayam! Çəkim təxminən 470 qram, boyum isə 27.6 sm-dir. Mənim dərim hələ qırışıqdır, çünki çox sürətlə böyüyürəm və piy qatım hələ dərini doldurmayıb. Amma narahat olma, doğulana qədər o şirin, toppuş körpə olacam. İndi əsas işim kökəlməkdir!', baby_message_en = 'I''m the size of a carrot! I weigh about 470 grams and am 27.6 cm long. My skin is still a bit wrinkled because I''m growing so fast and my fat layer hasn''t completely filled it out yet. But don''t worry, by the time I''m born, I''ll be a sweet, chubby baby. Right now, my main job is to gain weight!', baby_message_ru = 'Я размером с морковь! Мой вес составляет примерно 470 грамм, а рост 27.6 см. Моя кожа пока ещё морщинистая, потому что я расту очень быстро, а жировой слой ещё не успел её заполнить. Но не волнуйся, к рождению я стану тем самым милым пухленьким малышом. Сейчас моя главная задача — набирать вес!', baby_message_tr = 'Ben bir havuç büyüklüğündeyim! Ağırlığım yaklaşık 470 gram, boyum ise 27.6 cm. Cildim hâlâ kırışık, çünkü çok hızlı büyüyorum ve yağ tabakam henüz cildimi doldurmadı. Ama merak etme, doğana kadar o tatlı, tombul bebek olacağım. Şimdi asıl işim kilo almak!', baby_message_kk = 'Менің көлемім сәбіздей! Салмағым шамамен 470 грамм, ал бойым 27.6 см. Терім әлі де әжімді, өйткені мен өте жылдам өсіп жатырмын, ал май қабатым терімді әлі толық толтырған жоқ. Бірақ уайымдамаңыз, дүниеге келгенше сүйкімді, томпақ бөпе боламын. Қазір менің басты міндетім — салмақ қосу!', baby_message_de = 'Ich bin so groß wie eine Karotte! Ich wiege ungefähr 470 Gramm und bin 27.6 cm groß. Meine Haut ist noch faltig, weil ich sehr schnell wachse und meine Fettschicht sie noch nicht ausfüllt. Aber keine Sorge, bis zur Geburt werde ich ein süßes, rundliches Baby sein. Jetzt ist meine wichtigste Aufgabe, an Gewicht zuzulegen!', baby_message_ar = 'أنا بحجم جزرة! يبلغ وزني نحو 470 غرامًا، وطولي 27.6 سم. لا تزال بشرتي مجعّدة لأنني أنمو بسرعة كبيرة، ولم تمتلئ بعدُ بطبقة الدهون. لكن لا تقلقي، فسأصبح ذلك الطفل اللطيف الممتلئ قبل ولادتي. مهمتي الأساسية الآن هي اكتساب الوزن!', baby_message_uz = 'Men sabzidek kattaman! Vaznim taxminan 470 gramm, bo‘yim esa 27.6 sm. Terim hali burishgan, chunki men juda tez o‘syapman va yog‘ qatlamim hali terimni to‘ldirmagan. Ammo xavotir olmang, tug‘ilgunimcha o‘sha yoqimtoy, do‘mboqqina chaqaloqqa aylanaman. Hozirgi asosiy vazifam vazn yig‘ish!', baby_message_ka = 'მე სტაფილოს ზომის ვარ! დაახლოებით 470 გრამს ვიწონი, ჩემი სიგრძე კი 27.6 სმ-ია. ჩემი კანი ჯერ კიდევ დანაოჭებულია, რადგან ძალიან სწრაფად ვიზრდები და ცხიმოვანი შრე კანს ჯერ ბოლომდე არ ავსებს. მაგრამ ნუ ღელავთ, დაბადებამდე საყვარელი, ფუმფულა ბავშვი გავხდები. ახლა ჩემი მთავარი საქმე წონის მომატებაა!', baby_message_zh = '我有胡萝卜那么大啦！我的体重大约是 470 克，身长 27.6 厘米。因为我长得太快，脂肪层还没有完全填充起来，所以皮肤仍然有点皱。不过别担心，等出生时，我会变成一个可爱又胖乎乎的宝宝。现在，我的主要任务就是增加体重！', baby_message_id = 'Ukuranku sebesar wortel! Beratku sekitar 470 gram dan panjangku 27.6 cm. Kulitku masih agak keriput karena aku tumbuh begitu cepat dan lapisan lemakku belum mengisinya sepenuhnya. Namun jangan khawatir, saat lahir nanti, aku akan menjadi bayi manis yang montok. Saat ini, tugas utamaku adalah menambah berat badan!', baby_message_fr = 'J’ai la taille d’une carotte ! Je pèse environ 470 grammes et mesure 27.6 cm. Ma peau est encore un peu fripée, car je grandis très vite et ma couche de graisse ne l’a pas encore complètement remplie. Mais ne vous inquiétez pas : à ma naissance, je serai un adorable bébé bien potelé. Pour l’instant, ma principale mission est de prendre du poids !', baby_message_es = '¡Tengo el tamaño de una zanahoria! Peso unos 470 gramos y mido 27.6 cm. Mi piel todavía está un poco arrugada porque crezco muy rápido y mi capa de grasa aún no la ha rellenado por completo. Pero no te preocupes: cuando nazca, seré un bebé adorable y regordete. Ahora mismo, ¡mi tarea principal es ganar peso!', baby_message_pt = 'Tenho o tamanho de uma cenoura! Peso cerca de 470 gramas e meço 27.6 cm. A minha pele ainda está um pouco enrugada porque estou a crescer muito depressa e a minha camada de gordura ainda não a preencheu totalmente. Mas não te preocupes: quando nascer, vou ser um bebé querido e rechonchudo. Por agora, a minha principal tarefa é ganhar peso!', baby_message_vi = 'Mình có kích thước tương đương một củ cà rốt! Mình nặng khoảng 470 gram và dài 27.6 cm. Da mình vẫn còn hơi nhăn vì mình lớn quá nhanh và lớp mỡ chưa lấp đầy hoàn toàn. Nhưng đừng lo, đến khi chào đời, mình sẽ là một em bé bụ bẫm, đáng yêu. Lúc này, nhiệm vụ chính của mình là tăng cân!', baby_message_hi = 'मैं एक गाजर जितना बड़ा हूँ! मेरा वज़न लगभग 470 ग्राम है और मेरी लंबाई 27.6 cm है। मेरी त्वचा अभी थोड़ी झुर्रीदार है, क्योंकि मैं बहुत तेज़ी से बढ़ रहा हूँ और वसा की परत ने अभी इसे पूरी तरह भरा नहीं है। लेकिन चिंता न करें, जन्म के समय तक मैं एक प्यारा, गोल-मटोल बच्चा बन जाऊँगा। अभी मेरा मुख्य काम वज़न बढ़ाना है!', baby_message_ja = 'ニンジンくらいの大きさです！体重は約470グラム、身長は27.6 cmです。急速に成長していて、脂肪の層がまだ十分についていないため、肌には少ししわがあります。でも心配しないでね。生まれるころには、かわいくてふっくらした赤ちゃんになります。今の私の一番大切な仕事は、体重を増やすことです！', baby_message_ko = '당근만큼 커졌어요! 몸무게는 약 470그램이고 키는 27.6cm예요. 아주 빠르게 자라는 데다 지방층이 아직 피부를 완전히 채우지 못해서 피부가 조금 주름져 있어요. 하지만 걱정하지 마세요. 태어날 때쯤에는 사랑스럽고 통통한 아기가 될 거예요. 지금 내 가장 중요한 일은 몸무게를 늘리는 거예요!', baby_message_pl = 'Jestem wielkości marchewki! Ważę około 470 gramów i mam 27.6 cm długości. Moja skóra nadal jest trochę pomarszczona, bo ciało rośnie bardzo szybko, a warstwa tłuszczu jeszcze jej całkowicie nie wypełniła. Ale nie martw się — do dnia narodzin zmienię się w słodkiego, pulchnego maluszka. Teraz moim najważniejszym zadaniem jest przybieranie na wadze!', baby_message_nl = 'Ik ben zo groot als een wortel! Ik weeg ongeveer 470 gram en ben 27.6 cm lang. Mijn huid is nog wat gerimpeld omdat ik zo snel groei en mijn vetlaag haar nog niet helemaal heeft opgevuld. Maar maak je geen zorgen: tegen de tijd dat ik geboren word, ben ik een lief, mollig baby’tje. Mijn belangrijkste taak is nu aankomen!', baby_message_sv = 'Jag är lika stor som en morot! Jag väger ungefär 470 gram och är 27.6 cm lång. Min hud är fortfarande lite skrynklig eftersom jag växer så snabbt och fettlagret ännu inte har fyllt ut den helt. Men oroa dig inte – när jag föds kommer jag att vara en söt, knubbig bebis. Just nu är min viktigaste uppgift att gå upp i vikt!' WHERE id = 'dcc1b63f-cc53-4d60-9050-ad76c211d2c4' AND md5(coalesce(baby_message,'')) = '3be9e838c8c9c82aef5bcdd5861f315b' AND md5(coalesce(baby_message_en,'')) = 'e88c1803ed15555bdc2136e9053438ec' AND md5(coalesce(baby_message_ru,'')) = 'cb89341e6dee497519936faf8550ec83' AND md5(coalesce(baby_message_tr,'')) = '68ed5d5cf76cedccf55b68027e6f7507' AND md5(coalesce(baby_message_kk,'')) = '08152d89d1627916ecd53c133e01d264' AND md5(coalesce(baby_message_de,'')) = '14da23312eb57586a76c5414a7650de1' AND md5(coalesce(baby_message_ar,'')) = 'e543f8235b20cf8e8ae78c74a2689560' AND md5(coalesce(baby_message_uz,'')) = 'd926cf7a3d3c8aa4afbabbf06f2ecdc4' AND md5(coalesce(baby_message_ka,'')) = 'caa467c860cbe9cee2ade5a56b66d62b' AND md5(coalesce(baby_message_zh,'')) = '126e307c2ed4f49ade505cfdeca56119' AND md5(coalesce(baby_message_id,'')) = '875d61181f28eeaf33fdb468db6aa0dd' AND md5(coalesce(baby_message_fr,'')) = 'b15ae53dd9f3edfe894707f41edf8654' AND md5(coalesce(baby_message_es,'')) = '5ac9fe93d7ba7549b85ceb2ca0bbc797' AND md5(coalesce(baby_message_pt,'')) = '6ab07d637c6a32311ac9a6a37cfd9c1c' AND md5(coalesce(baby_message_vi,'')) = '1ae46414c5aeafc12ca210a6fed4dfa3' AND md5(coalesce(baby_message_hi,'')) = 'b0a21d66507e7dc7d367512bd50c7a08' AND md5(coalesce(baby_message_ja,'')) = '379c43703cfbb76648d5e73e4a26b72f' AND md5(coalesce(baby_message_ko,'')) = 'd69ea7b2338c5d1aea77213f5577172b' AND md5(coalesce(baby_message_pl,'')) = 'd43728800b11a1aa060ac56e19af795a' AND md5(coalesce(baby_message_nl,'')) = '74c0f9a67a8318784769976e93485741' AND md5(coalesce(baby_message_sv,'')) = '6841bc90f2dbe5c9d2f78f98bcaec1ec';
UPDATE public.pregnancy_daily_content SET baby_message = '🥭 Mən bir böyük manqo boydayam! Bu həftə çox vacibdir, Anacan. Həkimlər deyir ki, indi mən "həyat qabiliyyətli" sayılıram. Yəni indi doğulsam belə, müasir tibbin köməyi ilə yaşamaq şansım var (amma hələ çox erkəndir, mən qalmaq istəyirəm!). Bu böyük bir mərhələdir!', baby_message_en = '🥭 I''m the size of a large mango! This week is super important, Anacan. Doctors say that I am now considered "viable." This means that even if I were born now, I would have a chance to survive with the help of modern medicine (but it''s still too early, I want to stay in here!). This is a huge milestone!', baby_message_ru = '🥭 Я уже размером с большое манго! Эта неделя очень важна, мамочка. Врачи говорят, что теперь я считаюсь «жизнеспособным». Это означает, что даже если я сейчас появлюсь на свет, благодаря современной медицине у меня будет шанс выжить (но пока ещё слишком рано, я хочу остаться здесь!). Это важнейший этап!', baby_message_tr = '🥭 Ben büyük bir mango büyüklüğündeyim! Bu hafta çok önemli, anneciğim. Doktorlar artık benim "yaşayabilir" kabul edildiğimi söylüyor. Yani şimdi doğsam bile modern tıbbın yardımıyla yaşama şansım var (ama henüz çok erken, ben içeride kalmak istiyorum!). Bu çok büyük bir dönüm noktası!', baby_message_kk = '🥭 Менің бойым бір үлкен мангодай! Бұл апта өте маңызды, анашым. Дәрігерлер қазір мені «өмір сүруге қабілетті» деп санайтынын айтады. Яғни қазір дүниеге келсем де, заманауи медицинаның көмегімен өмір сүруге мүмкіндігім бар (бірақ әлі тым ерте, мен осында қала тұрғым келеді!). Бұл — үлкен белес!', baby_message_de = '🥭 Ich bin so groß wie eine große Mango! Diese Woche ist sehr wichtig, Mami. Die Ärzte sagen, dass ich jetzt als „lebensfähig“ gelte. Das bedeutet, dass ich selbst dann, wenn ich jetzt geboren würde, mithilfe der modernen Medizin eine Überlebenschance hätte (aber es ist noch viel zu früh und ich möchte noch bleiben!). Das ist ein großer Meilenstein!', baby_message_ar = '🥭 أنا بحجم حبة مانجو كبيرة! هذا الأسبوع مهم جدًا يا ماما. يقول الأطباء إنني أُعد الآن "قابلًا للحياة". وهذا يعني أنه حتى لو وُلدت الآن، فلدي فرصة للبقاء على قيد الحياة بمساعدة الطب الحديث (لكن الوقت ما زال مبكرًا جدًا، وأنا أريد البقاء هنا!). إنها مرحلة فارقة كبيرة!', baby_message_uz = '🥭 Men katta mangodek kattaman! Bu hafta juda muhim, Onajon. Shifokorlarning aytishicha, endi men "yashash qobiliyatiga ega" deb hisoblanaman. Ya’ni hozir tug‘ilsam ham, zamonaviy tibbiyot yordamida yashab qolish imkoniyatim bor (ammo hali juda erta, men qolishni xohlayman!). Bu juda muhim bosqich!', baby_message_ka = '🥭 მე დიდი მანგოს ზომის ვარ! ეს კვირა ძალიან მნიშვნელოვანია, დედიკო. ექიმები ამბობენ, რომ ახლა უკვე „სიცოცხლისუნარიანად“ ვითვლები. ანუ ახლა რომ დავიბადო, თანამედროვე მედიცინის დახმარებით გადარჩენის შანსი მაქვს (მაგრამ ჯერ ძალიან ადრეა, აქ დარჩენა მინდა!). ეს ძალიან მნიშვნელოვანი ეტაპია!', baby_message_zh = '🥭 我已经有一个大芒果那么大啦！这一周非常重要，Anacan。医生说，现在的我已经被认为“具有存活能力”。这意味着，即使我现在出生，在现代医疗技术的帮助下也有机会存活下来（但现在还是太早了，我想继续待在这里！）。这是一个重要的里程碑！', baby_message_id = '🥭 Besarku sekarang seukuran mangga besar! Minggu ini sangat penting, Anacan. Dokter mengatakan bahwa sekarang aku dianggap "mampu bertahan hidup di luar rahim." Artinya, meskipun aku lahir sekarang, aku memiliki peluang untuk bertahan hidup dengan bantuan pengobatan modern (tetapi ini masih terlalu dini, aku ingin tetap di dalam sini!). Ini pencapaian yang sangat besar!', baby_message_fr = '🥭 J''ai la taille d''une grosse mangue ! Cette semaine est très importante, Anacan. Les médecins disent que je suis désormais considéré comme « viable ». Cela signifie que même si je naissais maintenant, j''aurais une chance de survivre grâce à la médecine moderne, mais c''est encore trop tôt et je veux rester ici ! C''est une étape majeure !', baby_message_es = '🥭 ¡Tengo el tamaño de un mango grande! Esta semana es muy importante, Anacan. Los médicos dicen que ahora se considera que soy «viable». Esto significa que, aunque naciera ahora, tendría posibilidades de sobrevivir con la ayuda de la medicina moderna (pero aún es demasiado pronto, ¡quiero seguir aquí dentro!). ¡Es un hito enorme!', baby_message_pt = '🥭 Sou do tamanho de uma manga grande! Esta semana é extremamente importante, Anacan. Os médicos dizem que agora já sou considerado «viável». Isto significa que, mesmo que nascesse agora, teria possibilidade de sobreviver com a ajuda da medicina moderna (mas ainda é demasiado cedo, quero ficar aqui dentro!). É um marco enorme!', baby_message_vi = '🥭 Con lớn bằng một quả xoài lớn rồi! Tuần này vô cùng quan trọng, Anacan. Các bác sĩ cho biết giờ đây con được xem là "có khả năng sống sót ngoài tử cung". Điều này có nghĩa là ngay cả khi chào đời vào lúc này, con vẫn có cơ hội sống nhờ sự hỗ trợ của y học hiện đại (nhưng vẫn còn quá sớm, con muốn ở lại trong này thêm!). Đây là một cột mốc vô cùng lớn!', baby_message_hi = '🥭 मेरा आकार एक बड़े आम जितना है! Anacan, यह सप्ताह बेहद महत्वपूर्ण है। डॉक्टरों के अनुसार, अब मुझे "गर्भ के बाहर जीवित रहने योग्य" माना जाता है। इसका मतलब है कि अगर मेरा जन्म अभी हो जाए, तो आधुनिक चिकित्सा की मदद से मेरे जीवित रहने की संभावना होगी (लेकिन अभी भी बहुत जल्दी है, मैं अभी यहीं रहना चाहता हूँ!)। यह एक बहुत बड़ी उपलब्धि है!', baby_message_ja = '🥭 大きなマンゴーくらいの大きさになったよ！Anacan、今週はとても大切です。お医者さんによると、今のぼく／わたしは「子宮の外でも生存できる可能性がある」と考えられる時期に入りました。つまり、もし今生まれても、現代医療の助けを受ければ生きられる可能性があるということです（でも、まだ早いから、もう少しここにいたいよ！）。これはとても大きな節目だよ！', baby_message_ko = '🥭 나는 커다란 망고만 해요! Anacan, 이번 주는 정말 중요해요. 의사 선생님들은 이제 내가 "생존 가능 시기"에 들어섰다고 해요. 지금 태어나더라도 현대 의학의 도움을 받으면 살아남을 가능성이 있다는 뜻이에요. 하지만 아직 너무 이르니 더 머물고 싶어요! 정말 큰 이정표를 넘었어요!', baby_message_pl = '🥭 Jestem wielkości dużego mango! Ten tydzień jest niezwykle ważny, Anacan. Lekarze mówią, że od tego momentu uznaje się mnie za dziecko „zdolne do przeżycia”. Oznacza to, że gdyby poród nastąpił już teraz, dzięki pomocy współczesnej medycyny mam szansę przeżyć — ale wciąż jest za wcześnie, wolę jeszcze zostać w środku! To ogromny kamień milowy!', baby_message_nl = '🥭 Ik ben zo groot als een grote mango! Deze week is ontzettend belangrijk, Anacan. Artsen zeggen dat ik nu als "levensvatbaar" word beschouwd. Dat betekent dat ik, zelfs als ik nu geboren zou worden, met hulp van de moderne geneeskunde een kans heb om te overleven. Maar het is nog te vroeg, dus ik blijf liever hierbinnen! Dit is een enorme mijlpaal!', baby_message_sv = '🥭 Jag är lika stor som en stor mango! Den här veckan är jätteviktig, Anacan. Läkarna säger att jag nu betraktas som ”livsduglig”. Det betyder att jag skulle ha en chans att överleva med hjälp av modern sjukvård även om jag föddes nu (men det är fortfarande för tidigt – jag vill stanna här inne!). Det här är en enorm milstolpe!' WHERE id = '88964348-70ed-4f53-a6a4-d8d7da7286ff' AND md5(coalesce(baby_message,'')) = '863674a8edd20628ed350f9798e0be41' AND md5(coalesce(baby_message_en,'')) = '80a54d08974fc9f28417bc452cc73343' AND md5(coalesce(baby_message_ru,'')) = '6f38b571f00eaf2ba694f95f3a63f530' AND md5(coalesce(baby_message_tr,'')) = '6c72978e8af0ee4a58128fb990373507' AND md5(coalesce(baby_message_kk,'')) = '1b1781b6431cdad0b1a247f15d62967a' AND md5(coalesce(baby_message_de,'')) = '82ce9782846b79f4608df562c0225a0a' AND md5(coalesce(baby_message_ar,'')) = '3e66ac2536ac02be82f5204e4c58ed5b' AND md5(coalesce(baby_message_uz,'')) = '0c3815ea53e47a91ac4a65d4296151aa' AND md5(coalesce(baby_message_ka,'')) = '7b74831bf476e76ab99d8aa7d604958b' AND md5(coalesce(baby_message_zh,'')) = '6fc823c4fb3fe68d6842511534f4ff85' AND md5(coalesce(baby_message_id,'')) = '191b92e73e2051fb7b414251c9474df2' AND md5(coalesce(baby_message_fr,'')) = 'ac4b4c1768b84fcddb1cf674a1bf805e' AND md5(coalesce(baby_message_es,'')) = '79e75c31adbcb14351fba55d09aa777b' AND md5(coalesce(baby_message_pt,'')) = '3b46a4a19c95c846c303a0a8652f3ad7' AND md5(coalesce(baby_message_vi,'')) = '9b21049da248e6aa0c8a81359661433e' AND md5(coalesce(baby_message_hi,'')) = '83925ee14f8ceda4f4fc1dd729f706e9' AND md5(coalesce(baby_message_ja,'')) = 'bfeef5e1dfac16305027e146892c6abf' AND md5(coalesce(baby_message_ko,'')) = '7bb7367830c712a6e50067c17d5cf623' AND md5(coalesce(baby_message_pl,'')) = '17c7dbd0f90e3b100c3d5434dfda59e2' AND md5(coalesce(baby_message_nl,'')) = '71db9f193a72d76cde18816d30c07d95' AND md5(coalesce(baby_message_sv,'')) = 'c5690f5b8952fb7bbdcfff02cd5b7495';
UPDATE public.pregnancy_day_notifications SET title = 'Qarğıdalı boyda oldum! 🌽', title_en = 'I''m the size of an ear of corn! 🌽', title_ru = 'Я уже размером с кукурузу! 🌽', title_tr = 'Mısır kadar oldum! 🌽', title_kk = 'Жүгерідей болдым! 🌽', title_de = 'Ich bin so groß wie ein Maiskolben! 🌽', title_ar = 'أصبحت بحجم كوز ذرة! 🌽', title_uz = 'Makkajo‘xoridek bo‘ldim! 🌽', title_ka = 'სიმინდისოდენა გავხდი! 🌽' WHERE id = 'db0c5fae-71f1-477b-b321-634c423e0906' AND md5(coalesce(title,'')) = '5b2911e4e5b25ef84d9c0affde978b24' AND md5(coalesce(title_en,'')) = 'f6c073f61884d3fbe6adce4192abb3c9' AND md5(coalesce(title_ru,'')) = '341b5876f54654953bec3a3532320678' AND md5(coalesce(title_tr,'')) = 'cca0ed65d303e7947ecd8891402edee2' AND md5(coalesce(title_kk,'')) = '0603da5cf2a4206288f8c403cfb487d3' AND md5(coalesce(title_de,'')) = 'f4eee1cff211b7dc7c4a7c402e89d259' AND md5(coalesce(title_ar,'')) = 'e2b9153c13c62d8b88fa482eadfd5dab' AND md5(coalesce(title_uz,'')) = 'e727ea1e9221e84fd2bc5da40d1a695d' AND md5(coalesce(title_ka,'')) = 'f3053451abfc8c50208fcecc9c671dd9';
UPDATE public.pregnancy_daily_content SET baby_message = 'Mən bir qarğıdalı boydayam! Mən indi sürətlə kökəlirəm. Dərimdəki qırışlar azalır, yanaqlarım dolur. Artıq şirin bir körpəyə bənzəyirəm. Saçlarımın rəngi və quruluşu artıq müəyyənləşib.', baby_message_en = 'I''m the size of an ear of corn! I''m gaining weight rapidly now. The wrinkles on my skin are smoothing out, and my cheeks are getting plump. I''m starting to look like a sweet baby! My hair color and texture are already determined.', baby_message_ru = 'Я размером с кукурузу! Сейчас я быстро набираю вес. Морщинки на моей коже разглаживаются, а щёчки становятся пухлее. Я уже похож на милого малыша. Цвет и структура моих волос уже определились.', baby_message_tr = 'Ben bir mısır büyüklüğündeyim! Şimdi hızla kilo alıyorum. Cildimdeki kırışıklıklar azalıyor, yanaklarım dolgunlaşıyor. Artık sevimli bir bebeğe benziyorum. Saçlarımın rengi ve yapısı artık belli oldu.', baby_message_kk = 'Менің бойым жүгерідей! Қазір менің салмағым жылдам артып жатыр. Терімдегі әжімдер азайып, бетім толыса бастады. Енді мен сүйкімді бөпеге ұқсаймын. Шашымның түсі мен құрылымы да қалыптасып қойды.', baby_message_de = 'Ich bin so groß wie ein Maiskolben! Jetzt nehme ich schnell an Gewicht zu. Die Falten auf meiner Haut werden weniger und meine Wangen runder. Ich sehe schon wie ein süßes kleines Baby aus. Farbe und Struktur meiner Haare stehen bereits fest.', baby_message_ar = 'أصبح حجمي بحجم كوز ذرة! يزداد وزني الآن بسرعة. تقل التجاعيد في بشرتي ويمتلئ خدّاي. لقد بدأت أبدو كطفل لطيف. كما أصبح لون شعري وملمسه محددين بالفعل.', baby_message_uz = 'Men makkajo‘xoridek kattaman! Hozir vaznim tez ortyapti. Terimdagi ajinlar kamayib, yonoqlarim to‘lishyapti. Endi men yoqimtoy chaqaloqqa o‘xshayman. Sochlarimning rangi va tuzilishi allaqachon belgilangan.', baby_message_ka = 'მე სიმინდის ზომის ვარ! ახლა სწრაფად ვიმატებ წონას. ჩემს კანზე ნაოჭები მცირდება, ლოყები კი მევსება. უკვე საყვარელ ბავშვს ვგავარ. ჩემი თმის ფერი და სტრუქტურაც უკვე განსაზღვრულია.', baby_message_zh = '我现在有一根玉米那么大啦！我的体重正在快速增加，皮肤上的皱纹逐渐变平，脸颊也越来越圆润。我开始像一个可爱的小宝宝了！我的发色和发质也已经确定。', baby_message_id = 'Ukuranku sebesar tongkol jagung! Berat badanku kini bertambah pesat. Kerutan di kulitku mulai menghalus dan pipiku semakin berisi. Aku mulai terlihat seperti bayi yang menggemaskan! Warna dan tekstur rambutku juga sudah ditentukan.', baby_message_fr = 'J’ai la taille d’un épi de maïs ! Je prends maintenant rapidement du poids. Les plis de ma peau s’estompent et mes joues s’arrondissent. Je commence à ressembler à un adorable bébé ! La couleur et la texture de mes cheveux sont déjà déterminées.', baby_message_es = '¡Tengo el tamaño de una mazorca de maíz! Ahora estoy ganando peso rápidamente. Las arrugas de mi piel se están alisando y mis mejillas están cada vez más regordetas. ¡Empiezo a parecer un bebé adorable! El color y la textura de mi pelo ya están determinados.', baby_message_pt = 'Sou do tamanho de uma maçaroca de milho! Agora estou a ganhar peso rapidamente. As rugas da minha pele estão a desaparecer e as minhas bochechas estão a ficar rechonchudas. Estou a começar a parecer um bebé amoroso! A cor e a textura do meu cabelo já estão definidas.', baby_message_vi = 'Con lớn bằng một bắp ngô rồi! Giờ con đang tăng cân nhanh chóng. Những nếp nhăn trên da con đang dần phẳng ra, còn đôi má thì ngày càng bầu bĩnh. Con bắt đầu trông giống một em bé đáng yêu rồi! Màu sắc và kết cấu tóc của con cũng đã được định hình.', baby_message_hi = 'मेरा आकार मक्के की एक बाली जितना है! अब मेरा वज़न तेज़ी से बढ़ रहा है। मेरी त्वचा की झुर्रियाँ समतल हो रही हैं और मेरे गाल गोल-मटोल हो रहे हैं। अब मैं एक प्यारे से शिशु जैसा/जैसी दिखने लगा/लगी हूँ! मेरे बालों का रंग और उनकी बनावट पहले ही तय हो चुकी है।', baby_message_ja = 'とうもろこしくらいの大きさだよ！ 今はどんどん体重が増えているんだ。皮膚のしわが伸びて、ほっぺもふっくらしてきたよ。かわいい赤ちゃんらしい姿になってきたんだ！ 髪の色や質はもう決まっているよ。', baby_message_ko = '저는 옥수수만 한 크기예요! 이제 빠르게 체중이 늘고 있어요. 피부의 주름이 펴지고 볼도 통통해지고 있어요. 점점 사랑스러운 아기 모습이 되어가고 있답니다! 제 머리카락 색과 결도 이미 정해졌어요.', baby_message_pl = 'Jestem wielkości kolby kukurydzy! Teraz szybko przybieram na wadze. Zmarszczki na mojej skórze się wygładzają, a policzki stają się pulchne. Wyglądam już jak słodkie maleństwo! Kolor i struktura moich włosów są już ustalone.', baby_message_nl = 'Ik ben zo groot als een maïskolf! Ik kom nu snel aan. De rimpeltjes in mijn huid worden gladder en mijn wangetjes worden voller. Ik begin op een schattige baby te lijken! Mijn haarkleur en haarstructuur liggen al vast.', baby_message_sv = 'Jag är lika stor som en majskolv! Nu går jag snabbt upp i vikt. Rynkorna i min hud slätas ut och mina kinder blir rundare. Jag börjar se ut som en söt liten bebis! Min hårfärg och hårtyp är redan bestämda.' WHERE id = '3d485358-4a99-4889-8e24-ba3824e8665d' AND md5(coalesce(baby_message,'')) = 'a1e8c9e6ccdc1e02ee80960c80174b27' AND md5(coalesce(baby_message_en,'')) = '2dd177902fe1567222ab8c2744cc434b' AND md5(coalesce(baby_message_ru,'')) = 'ef356c448c6fa4b9736ade85f4cd2a72' AND md5(coalesce(baby_message_tr,'')) = '635d2878005707eb06c8f4473615dcca' AND md5(coalesce(baby_message_kk,'')) = '93e0e12b1dda1ee57a304fe89012a68d' AND md5(coalesce(baby_message_de,'')) = '774b6467f0c61733784992ed4186bd61' AND md5(coalesce(baby_message_ar,'')) = '51a4ce5e6b61069ab072af0184f05037' AND md5(coalesce(baby_message_uz,'')) = '2931271c85fcdc16b8853075cd40e87b' AND md5(coalesce(baby_message_ka,'')) = 'a2c4da850f5406fe10f06f336cf9acf5' AND md5(coalesce(baby_message_zh,'')) = '9fe12aaec143e0085579f4751c0c4d38' AND md5(coalesce(baby_message_id,'')) = '24fffb14067c38d59b61565b2e70d3fa' AND md5(coalesce(baby_message_fr,'')) = '8b0af6e25f0c3ae2258cd96f3894247b' AND md5(coalesce(baby_message_es,'')) = '1348cb65bdd5457e5247ff4bff72ebef' AND md5(coalesce(baby_message_pt,'')) = '13a4263fe2696429db9f38b8a1e365a7' AND md5(coalesce(baby_message_vi,'')) = 'a18a15eabe2057c65ffb0e9d33e8b4f7' AND md5(coalesce(baby_message_hi,'')) = 'c6e52edbe6ece4c5716809fa66a4a093' AND md5(coalesce(baby_message_ja,'')) = 'e37704117f9f7341af5d65efbb2f0901' AND md5(coalesce(baby_message_ko,'')) = '0b3e32e10e5e21fe2a6efcc77a1ac312' AND md5(coalesce(baby_message_pl,'')) = '15335c1df6cebedcad249dc7154d0b45' AND md5(coalesce(baby_message_nl,'')) = '4ff2093e68ae28e58138aba68c4bfe0a' AND md5(coalesce(baby_message_sv,'')) = '070f431b51feaf0299b426a00aef2b87';
UPDATE public.pregnancy_daily_content SET baby_development = 'Bu mərhələdə körpənizin çəkisi 950 qram ola biləcəyi kimi, 1300 qram da ola bilər. Əgər körpəniz orta çəkidən aşağı və ya yuxarıdırsa, narahat olmamalısınız. Bütün körpələrin eyni çəkidə doğulmadığını, sağlam doğulan körpələrin çəkisinin 2500-4000 qram kimi geniş bir diapazonda ola biləcəyini unutmayın. Son trimestr dövrünə daxil olduğunuz bu günlərdə körpənizin əsas çəki artımı məhz bu mərhələdən sonra başlayır.;;;
Körpələr son trimestr dövründə həftədə orta hesabla 250 qram çəki alırlar. Hər hansı bir sağlamlıq problemi yoxdursa, körpəniz hətta doğumun gecikdiyi hallarda belə çəki almağa davam edir. Əgər sizdən və ya körpənizdən qaynaqlanan bir problem mövcuddursa, çəki artımı sürəti yavaşlaya və ya dayana bilər. Vaxtında doğulan bir körpə üçün 2500-4000 qram arası normal doğum çəkisi hesab olunur. Körpələr tez-tez 3000-3500 qram arası doğulurlar. Bu vəziyyət qız və oğlan körpələr arasında orta hesabla 10 faizlik bir fərqlilik göstərə bilər.;;;
Bundan əlavə, genetik faktorlar da körpənizin doğum çəkisini müəyyən edən ən vacib amillərdən biridir. Körpənizi yalnız çəkisinə baxaraq qiymətləndirmək yanlış olar. Sağlam qidalanmağınıza baxmayaraq, körpəyə aid problemlər, xroniki xəstəliklər, siqaret istifadəsi və genetik faktorlar aşağı doğum çəkisinə səbəb ola bilər.', baby_development_en = 'At this stage, your baby''s weight might range from around 950 grams to 1300 grams. Don''t worry if your baby is slightly below or above average weight. Remember that not all babies are born at the same weight; healthy full-term babies can weigh anywhere from 2500 to 4000 grams. As you enter the final trimester, your baby''s most significant growth spurt in weight is just beginning.;;;
Babies typically gain about 250 grams per week during the last trimester. Unless there are underlying health concerns, your baby will continue to gain weight, even if delivery is delayed. However, if there''s a problem related to you or your baby, this weight gain might slow down or stop. For a full-term baby, a birth weight between 2500 and 4000 grams is considered normal. Many babies are born weighing between 3000 and 3500 grams. There can be an average difference of about 10% in weight between baby girls and boys.;;;
Additionally, genetic factors also play a crucial role in determining your baby''s birth weight. It would be inaccurate to assess your baby''s health based solely on their weight. Even with a healthy diet, certain factors like fetal problems, chronic illnesses, smoking during pregnancy, and genetic predispositions can lead to a lower birth weight.', baby_development_ru = 'На этом этапе вес вашего малыша может составлять как 950 граммов, так и 1300 граммов. Если вес малыша ниже или выше среднего, не стоит беспокоиться. Помните, что не все дети рождаются с одинаковым весом: вес здорового новорождённого может варьироваться в широком диапазоне — от 2500 до 4000 граммов. Сейчас, когда вы вступаете в последний триместр, начинается период наиболее активного набора веса малышом.;;;
В последнем триместре малыши в среднем набирают по 250 граммов в неделю. Если нет никаких проблем со здоровьем, малыш продолжает набирать вес даже при переношенной беременности. Если же есть проблема, связанная с вашим здоровьем или состоянием малыша, набор веса может замедлиться или прекратиться. Нормальным весом доношенного малыша при рождении считается 2500–4000 граммов. Чаще всего дети рождаются с весом 3000–3500 граммов. При этом средняя разница в весе между девочками и мальчиками может составлять около 10 процентов.;;;
Кроме того, генетические факторы являются одними из важнейших факторов, определяющих вес малыша при рождении. Было бы неправильно оценивать состояние малыша только по его весу. Несмотря на ваше здоровое питание, низкий вес при рождении могут вызвать проблемы со здоровьем малыша, хронические заболевания, курение и генетические факторы.', baby_development_tr = 'Bu aşamada bebeğinizin ağırlığı 950 gram olabileceği gibi 1300 gram da olabilir. Bebeğiniz ortalama ağırlığın altında veya üstündeyse endişelenmemelisiniz. Tüm bebeklerin aynı ağırlıkta doğmadığını, sağlıklı doğan bebeklerin ağırlığının 2500-4000 gram gibi geniş bir aralıkta olabileceğini unutmayın. Son trimester dönemine girdiğiniz bu günlerde bebeğinizin asıl kilo artışı, bu aşamadan sonra başlar.;;;
Bebekler son trimester döneminde haftada ortalama 250 gram alırlar. Herhangi bir sağlık sorunu yoksa bebeğiniz, doğumun geciktiği durumlarda bile kilo almaya devam eder. Sizden veya bebeğinizden kaynaklanan bir sorun varsa kilo alma hızı yavaşlayabilir ya da durabilir. Zamanında doğan bir bebek için 2500-4000 gram arası normal doğum ağırlığı olarak kabul edilir. Bebekler çoğunlukla 3000-3500 gram arasında doğarlar. Bu durum kız ve erkek bebekler arasında ortalama yüzde 10''luk bir farklılık gösterebilir.;;;
Ayrıca genetik faktörler de bebeğinizin doğum ağırlığını belirleyen en önemli etkenlerden biridir. Bebeğinizi yalnızca ağırlığına bakarak değerlendirmek yanlış olur. Sağlıklı beslenmenize rağmen bebeğe ait sorunlar, kronik hastalıklar, sigara kullanımı ve genetik faktörler düşük doğum ağırlığına neden olabilir.', baby_development_kk = 'Бұл кезеңде бөпеңіздің салмағы 950 грамм да, 1300 грамм да болуы мүмкін. Егер бөпеңіздің салмағы орташа көрсеткіштен төмен немесе жоғары болса, алаңдамаңыз. Барлық бөпелердің бірдей салмақпен дүниеге келмейтінін және дені сау туған бөпелердің салмағы 2500-4000 грамм аралығында болуы мүмкін екенін ұмытпаңыз. Соңғы триместрге аяқ басқан осы күндерден бастап бөпеңіздің салмағы негізгі қарқынмен өсе бастайды.;;;
Соңғы триместрде бөпелер аптасына орта есеппен 250 грамм салмақ қосады. Денсаулығында қандай да бір мәселе болмаса, босану мерзімі кешіккен жағдайда да бөпеңіз салмақ қосуды жалғастырады. Егер Сізге немесе бөпеңізге байланысты қандай да бір мәселе болса, салмақ қосу қарқыны баяулауы немесе тоқтауы мүмкін. Мерзімінде туған бөпе үшін 2500-4000 грамм қалыпты туу салмағы болып саналады. Бөпелер көбіне 3000-3500 грамм салмақпен дүниеге келеді. Бұл көрсеткіш қыздар мен ұлдар арасында орта есеппен 10 пайызға ерекшеленуі мүмкін.;;;
Сонымен қатар, генетикалық факторлар да бөпеңіздің туу салмағын анықтайтын ең маңызды себептердің бірі. Бөпеңіздің жағдайын тек салмағына қарап бағалау дұрыс емес. Дұрыс тамақтанғаныңызға қарамастан, бөпеге қатысты мәселелер, созылмалы аурулар, темекі шегу және генетикалық факторлар туу салмағының төмен болуына әкелуі мүмкін.', baby_development_de = 'In dieser Phase kann dein Baby 950 Gramm wiegen, aber auch schon 1300 Gramm. Wenn sein Gewicht unter oder über dem Durchschnitt liegt, musst du dir keine Sorgen machen. Denk daran, dass nicht alle Babys mit demselben Gewicht geboren werden und das Geburtsgewicht gesunder Babys in einem breiten Bereich von 2500-4000 Gramm liegen kann. Jetzt, da du ins letzte Trimester eintrittst, beginnt die wichtigste Phase der Gewichtszunahme deines Babys.;;;
Im letzten Trimester nehmen Babys durchschnittlich 250 Gramm pro Woche zu. Solange keine gesundheitlichen Probleme vorliegen, nimmt dein Baby selbst dann weiter zu, wenn sich die Geburt verzögert. Besteht jedoch bei dir oder deinem Baby ein Problem, kann sich die Gewichtszunahme verlangsamen oder ganz aufhören. Bei einem termingerecht geborenen Baby gilt ein Geburtsgewicht von 2500-4000 Gramm als normal. Häufig kommen Babys mit einem Gewicht zwischen 3000-3500 Gramm zur Welt. Dabei kann es zwischen Mädchen und Jungen im Durchschnitt einen Unterschied von 10 Prozent geben.;;;
Darüber hinaus gehören genetische Faktoren zu den wichtigsten Einflüssen auf das Geburtsgewicht deines Babys. Es wäre falsch, dein Baby ausschließlich anhand seines Gewichts zu beurteilen. Trotz einer gesunden Ernährung können Probleme beim Baby, chronische Erkrankungen, Rauchen und genetische Faktoren zu einem niedrigen Geburtsgewicht führen.', baby_development_ar = 'قد يبلغ وزن طفلكِ في هذه المرحلة 950 غرامًا، وقد يبلغ أيضًا 1300 غرام. إذا كان وزن طفلكِ أقل أو أعلى من المتوسط، فلا داعي للقلق. تذكّري أن الأطفال لا يولدون جميعًا بالوزن نفسه، وأن وزن الأطفال الأصحاء عند الولادة قد يتراوح ضمن نطاق واسع بين 2500 و4000 غرام. في هذه الأيام التي تدخلين فيها الثلث الأخير من الحمل، تبدأ الزيادة الأساسية في وزن طفلكِ بعد هذه المرحلة تحديدًا.;;;
يزداد وزن الأطفال خلال الثلث الأخير بمعدل 250 غرامًا أسبوعيًا. وإذا لم توجد أي مشكلة صحية، فسيستمر طفلكِ في اكتساب الوزن حتى في حالات تأخر الولادة. أما إذا كانت هناك مشكلة صحية لديكِ أو لدى طفلكِ، فقد تتباطأ وتيرة زيادة الوزن أو تتوقف. ويُعد الوزن الذي يتراوح بين 2500 و4000 غرام وزنًا طبيعيًا عند ولادة الطفل في موعده. وغالبًا ما يولد الأطفال بوزن يتراوح بين 3000 و3500 غرام. وقد يظهر في هذا الصدد فرق يبلغ في المتوسط 10 في المئة بين الإناث والذكور.;;;
بالإضافة إلى ذلك، تُعد العوامل الوراثية من أهم العوامل التي تحدد وزن طفلكِ عند الولادة. ومن الخطأ تقييم طفلكِ اعتمادًا على وزنه وحده. فعلى الرغم من اتباعكِ نظامًا غذائيًا صحيًا، قد تؤدي المشكلات المتعلقة بالطفل، والأمراض المزمنة، والتدخين، والعوامل الوراثية إلى انخفاض الوزن عند الولادة.', baby_development_uz = 'Bu bosqichda chaqalog‘ingizning vazni 950 gramm bo‘lishi ham, 1300 gramm bo‘lishi ham mumkin. Agar chaqalog‘ingizning vazni o‘rtacha ko‘rsatkichdan past yoki yuqori bo‘lsa, xavotir olmang. Barcha chaqaloqlar bir xil vaznda tug‘ilmasligini, sog‘lom tug‘ilgan chaqaloqlarning vazni 2500-4000 gramm kabi keng oraliqda bo‘lishi mumkinligini unutmang. So‘nggi trimestrga kirgan shu kunlarda chaqalog‘ingiz vaznining asosiy ortishi aynan ushbu bosqichdan keyin boshlanadi.;;;
Chaqaloqlar so‘nggi trimestrda haftasiga o‘rtacha 250 gramm vazn yig‘adi. Agar biror-bir salomatlik muammosi bo‘lmasa, chaqalog‘ingiz hatto tug‘ruq kechikkan hollarda ham vazn yig‘ishda davom etadi. Agar siz yoki chaqalog‘ingiz bilan bog‘liq muammo mavjud bo‘lsa, vazn ortish sur’ati sekinlashishi yoki to‘xtashi mumkin. O‘z vaqtida tug‘ilgan chaqaloq uchun 2500-4000 gramm oralig‘i me’yoriy tug‘ilish vazni hisoblanadi. Chaqaloqlar ko‘pincha 3000-3500 gramm vaznda tug‘iladi. Bu ko‘rsatkich qiz va o‘g‘il chaqaloqlar o‘rtasida o‘rtacha 10 foiz farq qilishi mumkin.;;;
Bundan tashqari, genetik omillar ham chaqalog‘ingizning tug‘ilish vaznini belgilaydigan eng muhim omillardan biridir. Chaqalog‘ingizni faqat vazniga qarab baholash noto‘g‘ri bo‘ladi. Sog‘lom ovqatlanishingizga qaramay, chaqaloq bilan bog‘liq muammolar, surunkali kasalliklar, chekish va genetik omillar tug‘ilish vaznining past bo‘lishiga sabab bo‘lishi mumkin.', baby_development_ka = 'ამ ეტაპზე თქვენი ბავშვის წონა შეიძლება იყოს როგორც 950 გრამი, ისე 1300 გრამიც. თუ ბავშვის წონა საშუალოზე ნაკლები ან მეტია, არ უნდა ინერვიულოთ. გახსოვდეთ, რომ ყველა ბავშვი ერთნაირი წონით არ იბადება და ჯანმრთელი ახალშობილის წონა შეიძლება 2500-4000 გრამის ფარგლებში მერყეობდეს. ახლა, როცა მესამე ტრიმესტრში შედიხართ, თქვენი ბავშვის წონის ძირითადი მატება სწორედ ამ ეტაპის შემდეგ დაიწყება.;;;
მესამე ტრიმესტრში ბავშვები კვირაში საშუალოდ 250 გრამს იმატებენ. თუ ჯანმრთელობის პრობლემა არ არსებობს, ბავშვი წონის მატებას მაშინაც განაგრძობს, როდესაც მშობიარობა გვიანდება. თუ თქვენთან ან ბავშვთან დაკავშირებული პრობლემა არსებობს, წონის მატების ტემპი შეიძლება შენელდეს ან შეჩერდეს. დროულად დაბადებული ბავშვისთვის 2500-4000 გრამი დაბადების ნორმალურ წონად ითვლება. ბავშვები ხშირად 3000-3500 გრამის წონით იბადებიან. გოგო და ბიჭ ბავშვებს შორის საშუალო წონის სხვაობა შეიძლება დაახლოებით 10 პროცენტი იყოს.;;;
გარდა ამისა, გენეტიკური ფაქტორები ბავშვის დაბადების წონის განმსაზღვრელი ერთ-ერთი უმნიშვნელოვანესი ფაქტორია. ბავშვის მდგომარეობის მხოლოდ წონის მიხედვით შეფასება არასწორია. მიუხედავად იმისა, რომ ჯანსაღად იკვებებით, ბავშვთან დაკავშირებულმა პრობლემებმა, ქრონიკულმა დაავადებებმა, სიგარეტის მოხმარებამ და გენეტიკურმა ფაქტორებმა შეიძლება დაბადების დაბალი წონა გამოიწვიოს.', baby_development_zh = '现阶段，宝宝的体重可能在约950克到1300克之间。如果宝宝的体重略低于或高于平均值，不必担心。请记住，并非所有宝宝出生时的体重都相同；健康足月宝宝的体重可以在2500克至4000克之间。进入孕晚期后，宝宝体重增长最快的阶段才刚刚开始。;;;
孕晚期，宝宝通常每周会增重约250克。如果不存在潜在的健康问题，即使分娩推迟，宝宝也会继续增重。但如果你或宝宝存在相关问题，体重增长可能会放缓或停止。对于足月宝宝，出生体重在2500克至4000克之间通常被视为正常。许多宝宝出生时的体重在3000克至3500克之间。女宝宝和男宝宝的体重平均可能相差约10%。;;;
此外，遗传因素也会对宝宝的出生体重产生重要影响。仅凭体重判断宝宝是否健康并不准确。即使饮食健康，胎儿问题、慢性疾病、孕期吸烟和遗传倾向等因素仍可能导致出生体重偏低。', baby_development_id = 'Pada tahap ini, berat bayi Anda mungkin berkisar dari sekitar 950 gram hingga 1300 gram. Jangan khawatir jika berat bayi Anda sedikit di bawah atau di atas rata-rata. Ingatlah bahwa tidak semua bayi lahir dengan berat yang sama; berat bayi cukup bulan yang sehat dapat berkisar antara 2500 hingga 4000 gram. Saat Anda memasuki trimester terakhir, lonjakan pertumbuhan berat badan terbesar bayi Anda baru saja dimulai.;;;
Bayi biasanya bertambah berat sekitar 250 gram per minggu selama trimester terakhir. Selama tidak ada masalah kesehatan yang mendasarinya, berat bayi Anda akan terus bertambah, meskipun persalinan tertunda. Namun, jika ada masalah yang berkaitan dengan Anda atau bayi, pertambahan berat ini mungkin melambat atau berhenti. Untuk bayi cukup bulan, berat lahir antara 2500 dan 4000 gram dianggap normal. Banyak bayi lahir dengan berat antara 3000 dan 3500 gram. Berat bayi perempuan dan laki-laki rata-rata dapat berbeda sekitar 10%.;;;
Selain itu, faktor genetik juga berperan penting dalam menentukan berat lahir bayi Anda. Menilai kesehatan bayi hanya berdasarkan berat badannya tidaklah tepat. Bahkan dengan pola makan sehat, faktor tertentu seperti masalah pada janin, penyakit kronis, merokok selama kehamilan, dan kecenderungan genetik dapat menyebabkan berat lahir yang lebih rendah.', baby_development_fr = 'À ce stade, le poids de votre bébé peut aller d’environ 950 grammes à 1300 grammes. Ne vous inquiétez pas si son poids est légèrement inférieur ou supérieur à la moyenne. Tous les bébés ne naissent pas avec le même poids : les bébés nés à terme et en bonne santé peuvent peser entre 2500 et 4000 grammes. Alors que vous entrez dans le dernier trimestre, la plus importante phase de prise de poids de votre bébé ne fait que commencer.;;;
Au cours du dernier trimestre, les bébés prennent généralement environ 250 grammes par semaine. En l’absence de problème de santé sous-jacent, votre bébé continuera à prendre du poids, même si l’accouchement est retardé. Toutefois, en cas de problème vous concernant ou concernant votre bébé, cette prise de poids peut ralentir ou s’arrêter. Pour un bébé né à terme, un poids de naissance compris entre 2500 et 4000 grammes est considéré comme normal. De nombreux bébés naissent avec un poids situé entre 3000 et 3500 grammes. Le poids moyen peut varier d’environ 10% entre les filles et les garçons.;;;
Par ailleurs, les facteurs génétiques jouent également un rôle essentiel dans le poids de naissance de votre bébé. Il serait inexact d’évaluer sa santé uniquement en fonction de son poids. Même avec une alimentation saine, certains facteurs, comme des problèmes fœtaux, des maladies chroniques, le tabagisme pendant la grossesse et des prédispositions génétiques, peuvent entraîner un poids de naissance plus faible.', baby_development_es = 'En esta etapa, el peso de tu bebé puede oscilar entre unos 950 gramos y 1300 gramos. No te preocupes si está ligeramente por debajo o por encima del peso medio. Recuerda que no todos los bebés nacen con el mismo peso; los bebés sanos nacidos a término pueden pesar entre 2500 y 4000 gramos. Al entrar en el último trimestre, está a punto de comenzar el periodo de mayor aumento de peso de tu bebé.;;;
Durante el último trimestre, los bebés suelen ganar unos 250 gramos por semana. A menos que haya algún problema de salud subyacente, tu bebé seguirá ganando peso, aunque el parto se retrase. Sin embargo, si surge algún problema relacionado contigo o con tu bebé, este aumento de peso puede ralentizarse o detenerse. En un bebé nacido a término, se considera normal un peso al nacer de entre 2500 y 4000 gramos. Muchos bebés nacen con un peso de entre 3000 y 3500 gramos. Puede haber una diferencia media de alrededor del 10% entre el peso de las niñas y el de los niños.;;;
Además, los factores genéticos también desempeñan un papel fundamental a la hora de determinar el peso de tu bebé al nacer. No sería correcto evaluar su salud basándose únicamente en su peso. Incluso con una alimentación saludable, ciertos factores, como los problemas fetales, las enfermedades crónicas, fumar durante el embarazo y las predisposiciones genéticas, pueden dar lugar a un peso más bajo al nacer.', baby_development_pt = 'Nesta fase, o peso do seu bebé pode variar entre cerca de 950 gramas e 1300 gramas. Não se preocupe se o seu bebé estiver ligeiramente abaixo ou acima do peso médio. Lembre-se de que nem todos os bebés nascem com o mesmo peso; os bebés saudáveis nascidos de termo podem pesar entre 2500 e 4000 gramas. Agora que está a entrar no último trimestre, o período de maior aumento de peso do seu bebé está apenas a começar.;;;
Durante o último trimestre, os bebés ganham normalmente cerca de 250 gramas por semana. A menos que existam problemas de saúde subjacentes, o seu bebé continuará a ganhar peso, mesmo que o parto se atrase. No entanto, se houver algum problema relacionado consigo ou com o seu bebé, este aumento de peso pode abrandar ou parar. Para um bebé de termo, um peso à nascença entre 2500 e 4000 gramas é considerado normal. Muitos bebés nascem com um peso entre 3000 e 3500 gramas. Pode existir uma diferença média de cerca de 10% no peso entre meninas e meninos.;;;
Além disso, os fatores genéticos também desempenham um papel crucial na determinação do peso do seu bebé à nascença. Seria incorreto avaliar a saúde do seu bebé apenas com base no peso. Mesmo com uma alimentação saudável, determinados fatores, como problemas fetais, doenças crónicas, tabagismo durante a gravidez e predisposições genéticas, podem resultar num peso mais baixo à nascença.', baby_development_vi = 'Ở giai đoạn này, cân nặng của bé có thể dao động từ khoảng 950 gram đến 1300 gram. Đừng lo nếu bé nhẹ hoặc nặng hơn mức trung bình một chút. Hãy nhớ rằng không phải em bé nào cũng có cân nặng khi sinh giống nhau; những em bé đủ tháng khỏe mạnh có thể nặng từ 2500 đến 4000 gram. Khi bạn bước vào tam cá nguyệt cuối, giai đoạn tăng cân mạnh mẽ nhất của bé cũng vừa bắt đầu.;;;
Trong tam cá nguyệt cuối, bé thường tăng khoảng 250 gram mỗi tuần. Nếu không có vấn đề sức khỏe tiềm ẩn, bé sẽ tiếp tục tăng cân ngay cả khi sinh muộn hơn dự kiến. Tuy nhiên, nếu bạn hoặc bé gặp vấn đề, tốc độ tăng cân này có thể chậm lại hoặc dừng lại. Với em bé đủ tháng, cân nặng khi sinh từ 2500 đến 4000 gram được xem là bình thường. Nhiều em bé chào đời với cân nặng từ 3000 đến 3500 gram. Cân nặng trung bình giữa bé gái và bé trai có thể chênh lệch khoảng 10%.;;;
Ngoài ra, yếu tố di truyền cũng đóng vai trò quan trọng trong việc quyết định cân nặng khi sinh của bé. Sẽ không chính xác nếu chỉ dựa vào cân nặng để đánh giá sức khỏe của bé. Ngay cả khi bạn có chế độ ăn uống lành mạnh, một số yếu tố như vấn đề ở thai nhi, bệnh mạn tính, hút thuốc trong thai kỳ và khuynh hướng di truyền vẫn có thể khiến bé có cân nặng khi sinh thấp hơn.', baby_development_hi = 'इस चरण में आपके शिशु का वज़न लगभग 950 ग्राम से लेकर 1300 ग्राम तक हो सकता है। यदि आपके शिशु का वज़न औसत से थोड़ा कम या अधिक है, तो चिंता न करें। याद रखें कि सभी शिशु एक ही वज़न के साथ पैदा नहीं होते; स्वस्थ, पूर्ण अवधि के शिशुओं का वज़न 2500 से 4000 ग्राम के बीच कुछ भी हो सकता है। अंतिम तिमाही में प्रवेश करने के साथ ही आपके शिशु के वज़न में सबसे तेज़ बढ़ोतरी अब शुरू हो रही है।;;;
अंतिम तिमाही के दौरान शिशुओं का वज़न आमतौर पर प्रति सप्ताह लगभग 250 ग्राम बढ़ता है। यदि कोई अंतर्निहित स्वास्थ्य समस्या न हो, तो प्रसव में देरी होने पर भी आपके शिशु का वज़न बढ़ता रहेगा। हालांकि, यदि आपको या आपके शिशु को कोई समस्या हो, तो वज़न बढ़ने की गति धीमी हो सकती है या रुक सकती है। पूर्ण अवधि के शिशु के लिए जन्म के समय 2500 से 4000 ग्राम के बीच वज़न सामान्य माना जाता है। कई शिशुओं का जन्म के समय वज़न 3000 से 3500 ग्राम के बीच होता है। बालिका और बालक शिशुओं के वज़न में औसतन लगभग 10% का अंतर हो सकता है।;;;
इसके अलावा, आनुवंशिक कारक भी आपके शिशु का जन्म के समय वज़न निर्धारित करने में अहम भूमिका निभाते हैं। केवल वज़न के आधार पर आपके शिशु के स्वास्थ्य का आकलन करना सही नहीं होगा। पौष्टिक आहार लेने के बावजूद भ्रूण संबंधी समस्याएँ, पुरानी बीमारियाँ, गर्भावस्था के दौरान धूम्रपान और आनुवंशिक प्रवृत्तियाँ जैसे कुछ कारक जन्म के समय कम वज़न का कारण बन सकते हैं।', baby_development_ja = 'この時期の赤ちゃんの体重は、約950グラムから1300グラム程度まで幅があります。赤ちゃんの体重が平均を少し下回ったり上回ったりしていても、心配する必要はありません。すべての赤ちゃんが同じ体重で生まれるわけではなく、健康な正期産児の体重は2500～4000グラムとさまざまです。妊娠後期に入ると、赤ちゃんの体重が最も大きく増える時期が始まります。;;;
妊娠後期には通常、赤ちゃんの体重は一週間に約250グラム増えます。健康上の問題がない限り、出産が遅れても赤ちゃんの体重は増え続けます。ただし、お母さんや赤ちゃんに問題がある場合、体重の増加が緩やかになったり止まったりすることがあります。正期産児では、出生体重が2500～4000グラムの範囲であれば正常とされます。多くの赤ちゃんは3000～3500グラムで生まれます。女の子と男の子では、体重に平均約10%の差が見られることがあります。;;;
また、赤ちゃんの出生体重には遺伝的要因も重要な役割を果たします。体重だけで赤ちゃんの健康状態を判断することは適切ではありません。健康的な食生活を送っていても、胎児の問題、慢性疾患、妊娠中の喫煙、遺伝的素因などにより、出生体重が低くなることがあります。', baby_development_ko = '이 시기 아기의 체중은 약 950그램에서 1300그램일 수 있어요. 아기가 평균 체중보다 조금 적거나 많아도 걱정하지 마세요. 모든 아기가 같은 체중으로 태어나는 것은 아니며, 건강한 만삭아의 체중은 2500~4000그램까지 다양할 수 있어요. 임신 후기에 접어들면서 아기의 체중이 가장 크게 늘어나는 시기가 이제 시작돼요.;;;
아기는 일반적으로 임신 후기에 일주일에 약 250그램씩 체중이 늘어요. 기저 질환이 없다면 출산이 늦어져도 아기의 체중은 계속 증가해요. 하지만 산모나 아기에게 문제가 있으면 체중 증가가 느려지거나 멈출 수 있어요. 만삭아는 출생 체중이 2500~4000그램이면 정상으로 간주해요. 많은 아기가 3000~3500그램의 체중으로 태어나요. 여아와 남아의 체중은 평균적으로 약 10% 차이가 날 수 있어요.;;;
또한 유전적 요인도 아기의 출생 체중을 결정하는 데 중요한 역할을 해요. 체중만으로 아기의 건강 상태를 판단하는 것은 정확하지 않아요. 건강하게 식사하더라도 태아 문제, 만성 질환, 임신 중 흡연, 유전적 소인 등의 요인으로 출생 체중이 적을 수 있어요.', baby_development_pl = 'Na tym etapie masa ciała Twojego dziecka może wynosić od około 950 gramów do 1300 gramów. Nie martw się, jeśli dziecko waży nieco mniej lub więcej niż wynosi średnia. Pamiętaj, że nie wszystkie dzieci rodzą się z taką samą masą ciała — zdrowe dzieci urodzone o czasie mogą ważyć od 2500 do 4000 gramów. Wraz z początkiem ostatniego trymestru rozpoczyna się okres najbardziej intensywnego przyrostu masy ciała Twojego dziecka.;;;
W ostatnim trymestrze dzieci przybierają zwykle około 250 gramów tygodniowo. Jeśli nie występują żadne problemy zdrowotne, Twoje dziecko będzie nadal przybierać na wadze, nawet gdy poród nastąpi po terminie. Jeśli jednak pojawi się problem dotyczący Ciebie lub dziecka, przyrost masy ciała może zwolnić albo się zatrzymać. W przypadku dziecka urodzonego o czasie masa urodzeniowa od 2500 do 4000 gramów jest uznawana za prawidłową. Wiele dzieci rodzi się z masą ciała od 3000 do 3500 gramów. Średnia różnica w masie ciała między dziewczynkami a chłopcami może wynosić około 10%.;;;
Istotną rolę w określaniu masy urodzeniowej dziecka odgrywają również czynniki genetyczne. Ocenianie jego zdrowia wyłącznie na podstawie masy ciała byłoby niemiarodajne. Nawet przy zdrowej diecie niektóre czynniki, takie jak problemy zdrowotne płodu, choroby przewlekłe, palenie tytoniu w czasie ciąży czy predyspozycje genetyczne, mogą prowadzić do niższej masy urodzeniowej.', baby_development_nl = 'In deze fase kan je baby ongeveer 950 gram tot 1300 gram wegen. Maak je geen zorgen als je baby iets minder of meer weegt dan gemiddeld. Niet alle baby''s hebben bij de geboorte hetzelfde gewicht; gezonde voldragen baby''s kunnen tussen de 2500 en 4000 gram wegen. Nu je het laatste trimester ingaat, begint de grootste gewichtstoename van je baby.;;;
Tijdens het laatste trimester komen baby''s doorgaans ongeveer 250 gram per week aan. Als er geen onderliggende gezondheidsproblemen zijn, blijft je baby aankomen, ook als de bevalling later plaatsvindt. Is er echter een probleem bij jou of je baby, dan kan deze gewichtstoename vertragen of stoppen. Voor een voldragen baby wordt een geboortegewicht tussen 2500 en 4000 gram als normaal beschouwd. Veel baby''s wegen bij de geboorte tussen 3000 en 3500 gram. Tussen meisjes en jongens kan het gewicht gemiddeld ongeveer 10% verschillen.;;;
Daarnaast spelen erfelijke factoren een belangrijke rol bij het geboortegewicht van je baby. Het is niet juist om de gezondheid van je baby alleen op basis van het gewicht te beoordelen. Zelfs bij een gezond voedingspatroon kunnen bepaalde factoren, zoals problemen bij de foetus, chronische aandoeningen, roken tijdens de zwangerschap en erfelijke aanleg, tot een lager geboortegewicht leiden.', baby_development_sv = 'I det här skedet kan ditt barn väga från omkring 950 gram till 1300 gram. Oroa dig inte om ditt barn ligger något under eller över genomsnittsvikten. Kom ihåg att alla barn inte väger lika mycket när de föds. Friska, fullgångna barn kan väga allt från 2500 till 4000 gram. När du går in i den sista trimestern börjar ditt barns största viktuppgång.;;;
Under den sista trimestern går barn vanligtvis upp omkring 250 gram i veckan. Om det inte finns några bakomliggande hälsoproblem fortsätter ditt barn att gå upp i vikt, även om förlossningen dröjer. Om det däremot finns ett problem som rör dig eller ditt barn kan viktuppgången sakta ner eller avstanna. För ett fullgånget barn räknas en födelsevikt på mellan 2500 och 4000 gram som normal. Många barn föds med en vikt på mellan 3000 och 3500 gram. I genomsnitt kan vikten skilja sig med omkring 10% mellan flickor och pojkar.;;;
Även genetiska faktorer har stor betydelse för ditt barns födelsevikt. Det går inte att bedöma barnets hälsa enbart utifrån vikten. Trots en hälsosam kost kan faktorer som problem hos fostret, kroniska sjukdomar, rökning under graviditeten och genetiska anlag leda till lägre födelsevikt.' WHERE id = 'd388c035-3ae4-451c-bcce-e8ae700cd74b' AND md5(coalesce(baby_development,'')) = '653b428afbd164848bc5e65797cb5774' AND md5(coalesce(baby_development_en,'')) = '5f558fd905b0aac7b57606ab4f648b34' AND md5(coalesce(baby_development_ru,'')) = 'a385efccd67df514ab00b1acb43f5904' AND md5(coalesce(baby_development_tr,'')) = 'bdfc56f186322507aaf983f90dbefec0' AND md5(coalesce(baby_development_kk,'')) = 'f28bc25983b0366fb0840e481eae93a9' AND md5(coalesce(baby_development_de,'')) = '46f43c5f405260770535dfa43e413432' AND md5(coalesce(baby_development_ar,'')) = 'e057beb6f3d32c48b3455c69fbd7bbd4' AND md5(coalesce(baby_development_uz,'')) = '442a55e370bc52e7298b67f85d29c937' AND md5(coalesce(baby_development_ka,'')) = 'faa62d8d10cdac7f6996282a944fd3c0' AND md5(coalesce(baby_development_zh,'')) = '3e00fe6261d2e23ddae59b35b90f1430' AND md5(coalesce(baby_development_id,'')) = '9438b3e7778413c040a92381e454f4a6' AND md5(coalesce(baby_development_fr,'')) = '44c70388894d9201f5669a5e2f37691b' AND md5(coalesce(baby_development_es,'')) = '476acdb1a657f1e773fc4735a2522faf' AND md5(coalesce(baby_development_pt,'')) = 'db093fe8aebaf933f5187308dcce4abd' AND md5(coalesce(baby_development_vi,'')) = 'ae4070d0785226758440b9852e43f144' AND md5(coalesce(baby_development_hi,'')) = '4722c1e466b06241628bcc5688e06885' AND md5(coalesce(baby_development_ja,'')) = 'f1a2e8c02e1dd9fb25eeb9560ebab58d' AND md5(coalesce(baby_development_ko,'')) = '4fa60d99dbdb1c894ab66a5961e5b842' AND md5(coalesce(baby_development_pl,'')) = '728e20b64b4959b551542bf490cf8fe1' AND md5(coalesce(baby_development_nl,'')) = 'd495ae57aadcf6bf6f8cf555d89cb112' AND md5(coalesce(baby_development_sv,'')) = '4c5f2baeb1f898da7a223275e85e0d12';
UPDATE public.pregnancy_daily_content SET baby_message = '200 GÜN! 🎉 Anacan, inanılmazdır! Biz artıq 200 gündür ki, bir yerdəyik. Mən bir badımcan boydayam. İndi mən çox güclüyəm. Təpiklərim bəzən səni incidə bilər, amma bil ki, mən sadəcə gücümü yoxlayıram. Sənə qovuşmağa az qaldı!', baby_message_en = '200 DAYS! 🎉 Mama, it''s incredible! We''ve already been together for 200 days. I''m now the size of an eggplant. I''m very strong these days! My kicks might sometimes hurt you, but know that I''m just testing my strength. It won''t be long until we meet!', baby_message_ru = '200 ДНЕЙ! 🎉 мамочка, это невероятно! Мы вместе уже 200 дней. Я размером с баклажан. Теперь я очень сильный малыш. Иногда мои толчки могут причинять тебе боль, но знай: я просто проверяю свои силы. До нашей встречи осталось совсем немного!', baby_message_tr = '200 GÜN! 🎉 anneciğim, inanılmaz! Tam 200 gündür birlikteyiz. Ben artık bir patlıcan büyüklüğündeyim. Şimdi çok güçlüyüm. Tekmelerim bazen canınızı acıtabilir ama bilin ki sadece gücümü deniyorum. Size kavuşmama çok az kaldı!', baby_message_kk = '200 КҮН! 🎉 анашым, сенгісіз! Бірге болғанымызға 200 күн болды. Мен баклажандаймын. Қазір мен өте күштімін. Тебуім кейде Сізге ауыр тиюі мүмкін, бірақ мен жай ғана күшімді сынап жатқанымды біліңіз. Кездесуімізге аз қалды!', baby_message_de = '200 TAGE! 🎉 Mami, es ist unglaublich! Wir sind schon seit 200 Tagen zusammen. Ich bin so groß wie eine Aubergine. Inzwischen bin ich richtig stark. Meine Tritte können dir manchmal wehtun, aber du sollst wissen, dass ich nur meine Kräfte teste. Es dauert nicht mehr lange, bis wir uns endlich kennenlernen!', baby_message_ar = '200 يوم! 🎉 ماما، هذا لا يُصدق! لقد مضى على وجودنا معًا 200 يوم. أنا الآن بحجم حبة باذنجان، وقد أصبحت قويًا جدًا. قد تؤلمكِ ركلاتي أحيانًا، لكن اعلمي أنني أختبر قوتي فحسب. لم يتبقَّ الكثير حتى ألقاكِ!', baby_message_uz = '200 KUN! 🎉 Onajon, aql bovar qilmaydi! Biz 200 kundan beri birgamiz. Men baqlajondek bo‘lib qoldim. Hozir juda kuchliman. Tepishlarim ba’zan sizga og‘riq yetkazishi mumkin, ammo bilingki, men shunchaki kuchimni sinab ko‘ryapman. Siz bilan uchrashishimga juda oz qoldi!', baby_message_ka = '200 დღე! 🎉 დედიკო, დაუჯერებელია! ჩვენ უკვე 200 დღეა ერთად ვართ. მე ბადრიჯნის ზომის ვარ. ახლა ძალიან ძლიერი ვარ. ჩემმა ბიძგებმა შეიძლება ზოგჯერ გატკინოს, მაგრამ იცოდე, რომ უბრალოდ ჩემს ძალას ვამოწმებ. ჩვენს შეხვედრამდე ცოტა დარჩა!', baby_message_zh = '200天啦！🎉 妈妈，太不可思议了！我们已经相伴200天了。现在我有一个茄子那么大。最近我可有力气啦！有时我踢得可能会让你觉得疼，但那只是我在试试自己的力气。再过不久，我们就能见面啦！', baby_message_id = '200 HARI! 🎉 Mama, luar biasa! Kita sudah bersama selama 200 hari. Kini ukuranku sebesar terong. Akhir-akhir ini aku sangat kuat! Tendanganku mungkin terkadang terasa sakit, tetapi ketahuilah bahwa aku hanya sedang menguji kekuatanku. Sebentar lagi kita akan bertemu!', baby_message_fr = '200 JOURS ! 🎉 Maman, c’est incroyable ! Cela fait déjà 200 jours que nous sommes ensemble. J’ai maintenant la taille d’une aubergine. Je suis très fort en ce moment ! Mes coups de pied peuvent parfois vous faire mal, mais sachez que je ne fais que tester ma force. Nous allons bientôt nous rencontrer !', baby_message_es = '¡200 DÍAS! 🎉 Mamá, ¡es increíble! Ya llevamos 200 días juntos. Ahora tengo el tamaño de una berenjena. ¡Estos días estoy muy fuerte! Puede que mis patadas te duelan a veces, pero piensa que solo estoy poniendo a prueba mi fuerza. ¡Ya falta poco para que nos conozcamos!', baby_message_pt = '200 DIAS! 🎉 Mamã, é incrível! Já estamos juntos há 200 dias. Agora tenho o tamanho de uma beringela. Estou muito forte nestes dias! Por vezes, os meus pontapés podem magoar-te, mas fica a saber que estou apenas a testar a minha força. Já falta pouco para nos conhecermos!', baby_message_vi = '200 NGÀY! 🎉 Mẹ ơi, thật không thể tin được! Chúng ta đã ở bên nhau suốt 200 ngày rồi. Giờ con lớn bằng một quả cà tím. Dạo này con khỏe lắm! Những cú đạp của con đôi khi có thể khiến mẹ đau, nhưng mẹ hãy biết rằng con chỉ đang thử sức mình thôi. Chẳng bao lâu nữa chúng ta sẽ gặp nhau!', baby_message_hi = '200 दिन! 🎉 मम्मी, यह अविश्वसनीय है! हमें साथ रहते हुए पूरे 200 दिन हो गए हैं। अब मेरा आकार एक बैंगन जितना है। इन दिनों मुझमें बहुत ताकत है! मेरी लातों से कभी-कभी आपको दर्द हो सकता है, लेकिन समझिए कि मैं बस अपनी ताकत परख रहा हूँ। अब हमारे मिलने में ज़्यादा समय नहीं बचा है!', baby_message_ja = '200日！🎉 ママ、すごいね！私たちはもう200日も一緒にいるよ。今の私は、ナスくらいのサイズ。最近はとっても力持ちなんだ！キックで痛いこともあるかもしれないけれど、自分の力を試しているだけだからね。会える日まで、もうすぐだよ！', baby_message_ko = '200일째예요! 🎉 엄마, 정말 놀라워요! 우리가 함께한 지 벌써 200일이나 됐어요. 이제 저는 가지만 해요. 요즘 힘이 아주 세졌어요! 발차기가 가끔 아플 수도 있지만, 제 힘을 시험해 보는 것뿐이라는 걸 알아주세요. 머지않아 만날 거예요!', baby_message_pl = '200 DNI! 🎉 Mamo, to niesamowite! Jesteśmy razem już od 200 dni. Mam teraz rozmiar bakłażana. W ostatnich dniach mam naprawdę dużo siły! Moje kopnięcia mogą czasem sprawiać Ci ból, ale wiedz, że tylko sprawdzam swoją siłę. Już niedługo się spotkamy!', baby_message_nl = '200 DAGEN! 🎉 Mama, het is ongelooflijk! We zijn al 200 dagen samen. Ik ben nu zo groot als een aubergine. Ik ben tegenwoordig heel sterk! Mijn schopjes kunnen soms pijn doen, maar weet dat ik gewoon mijn kracht uitprobeer. Het duurt niet lang meer voordat we elkaar ontmoeten!', baby_message_sv = '200 DAGAR! 🎉 Mamma, det är otroligt! Vi har redan varit tillsammans i 200 dagar. Nu är jag lika stor som en aubergine. Jag är väldigt stark nu! Mina sparkar kan göra ont ibland, men jag testar bara mina krafter. Snart får vi träffas!' WHERE id = 'dc4e8ae4-b5e0-48d5-8713-248744b76ec6' AND md5(coalesce(baby_message,'')) = 'c9849d3c8263c1b0cfcb929056e8117a' AND md5(coalesce(baby_message_en,'')) = '99a99ebab7e107c49c475f4863523001' AND md5(coalesce(baby_message_ru,'')) = '82dbc1653502922229a68583e49f10ed' AND md5(coalesce(baby_message_tr,'')) = '7e866f91e5c99b68d7fa18a8515f4af8' AND md5(coalesce(baby_message_kk,'')) = 'dda188dbff04c8fe2a1ec482c1ec2430' AND md5(coalesce(baby_message_de,'')) = 'f61c02d791c9545fb58ba7f96688cbce' AND md5(coalesce(baby_message_ar,'')) = '2b9b62aef0fa4d47bd0bb7eed23f5d51' AND md5(coalesce(baby_message_uz,'')) = 'b629ecd5fb779ee5e0ef60697288c8d5' AND md5(coalesce(baby_message_ka,'')) = 'dde86219c123d9683a7180290897c463' AND md5(coalesce(baby_message_zh,'')) = 'df7f4d3c8e8793eb8f2ddd3d892670a7' AND md5(coalesce(baby_message_id,'')) = '2a46f6628551e3ba5ee3ba3e1d636e1f' AND md5(coalesce(baby_message_fr,'')) = '4ddee627ec691263b093c0a0317212ca' AND md5(coalesce(baby_message_es,'')) = '40cc47dbaa21317cac3deda52c9433f4' AND md5(coalesce(baby_message_pt,'')) = '32b54d89a7cdb8efacbeee044ecbad14' AND md5(coalesce(baby_message_vi,'')) = '3b654421ac9313fefaa03ede0745e3f7' AND md5(coalesce(baby_message_hi,'')) = '535b30d402a461b3a53d96ad090ad8ff' AND md5(coalesce(baby_message_ja,'')) = '5fc51075ad649e75b11d93d62a47ee9c' AND md5(coalesce(baby_message_ko,'')) = '5bf00738b7517d6208ae775484c5ab25' AND md5(coalesce(baby_message_pl,'')) = '8909dcc7db67d9514fab5193d5e3041d' AND md5(coalesce(baby_message_nl,'')) = 'f361a563ad0f7885194be50cd2edabee' AND md5(coalesce(baby_message_sv,'')) = 'cf1568912d82c6612bc1ce64ce0e8386';
UPDATE public.pregnancy_daily_content SET baby_message = '29 HƏFTƏ! 🍆 Mən bir badımcan boydayam! Mən hər gün daha da "insan"a bənzəyirəm. Başım bədənimə mütənasibdir. İndi əsas məqsədim çəki yığmaqdır. Sənə təpik atanda artıq gücümü daha yaxşı hiss edirsən, elə deyilmi?', baby_message_en = '29 WEEKS! 🍆 I''m the size of an eggplant! Every day I look more and more ''human''. My head is now proportionate to my body. My main goal now is to gain weight. You can really feel my strength when I kick you now, can''t you?', baby_message_ru = '29 НЕДЕЛЬ! 🍆 Я размером с баклажан! С каждым днём я всё больше становлюсь похожим на человека. Моя голова уже пропорциональна телу. Теперь моя главная задача — набрать вес. Когда я пинаюсь, вы уже гораздо лучше чувствуете мою силу, правда?', baby_message_tr = '29 HAFTA! 🍆 Ben bir patlıcan boyutundayım! Her geçen gün daha fazla "insan"a benziyorum. Başım artık vücudumla orantılı. Şimdi asıl hedefim kilo almak. Sana tekme attığımda artık gücümü daha iyi hissediyorsun, değil mi?', baby_message_kk = '29 АПТА! 🍆 Менің көлемім баклажандай! Күн сайын адамға көбірек ұқсап келемін. Басым денеме сай пропорцияға жетті. Ендігі басты мақсатым — салмақ қосу. Мен тепкен кезде күшімді бұрынғыдан да жақсырақ сезесіз, солай емес пе?', baby_message_de = '29. WOCHE! 🍆 Ich bin so groß wie eine Aubergine! Jeden Tag sehe ich mehr wie ein kleiner Mensch aus. Mein Kopf passt nun proportional zu meinem Körper. Mein wichtigstes Ziel ist es jetzt, an Gewicht zuzunehmen. Wenn ich dich trete, kannst du meine Kraft schon viel deutlicher spüren, oder?', baby_message_ar = 'الأسبوع 29! 🍆 أنا بحجم حبة باذنجان! أبدو كل يوم أقرب إلى هيئة "الإنسان". أصبح رأسي متناسبًا مع جسمي. وهدفي الأساسي الآن هو اكتساب الوزن. عندما أركلكِ، تشعرين بقوتي بصورة أوضح الآن، أليس كذلك؟', baby_message_uz = '29 HAFTA! 🍆 Men baqlajondekman! Har kuni tobora ko‘proq "inson"ga o‘xshab boryapman. Boshim tanamga mutanosib. Endi asosiy maqsadim vazn yig‘ish. Sizga tepganimda kuchimni ancha yaxshiroq his qilyapsiz, shundaymi?', baby_message_ka = '29 კვირა! 🍆 მე ბადრიჯნის ზომის ვარ! ყოველდღე სულ უფრო მეტად ვემსგავსები "ადამიანს". ჩემი თავი სხეულის პროპორციულია. ახლა ჩემი მთავარი მიზანი წონის მომატებაა. როცა გირტყამ, ჩემს ძალას უკვე უკეთ გრძნობ, ხომ ასეა?', baby_message_zh = '29周啦！🍆 我现在有一个茄子那么大！我每天都变得越来越有“人样”了。现在，我的头部和身体比例已经很协调。接下来的主要目标就是增加体重。现在我踢你的时候，你真的能感受到我的力气了，对吧？', baby_message_id = '29 MINGGU! 🍆 Ukuranku sebesar terong! Setiap hari aku tampak semakin seperti ''manusia''. Kini ukuran kepalaku sudah proporsional dengan tubuhku. Tujuan utamaku sekarang adalah menambah berat badan. Saat aku menendang, Anda benar-benar bisa merasakan betapa kuatnya aku sekarang, bukan?', baby_message_fr = '29 SEMAINES ! 🍆 J’ai la taille d’une aubergine ! Chaque jour, j’ai une apparence de plus en plus « humaine ». Ma tête est désormais proportionnée à mon corps. Mon principal objectif est maintenant de prendre du poids. Vous sentez vraiment ma force quand je vous donne des coups de pied, n’est-ce pas ?', baby_message_es = '¡29 SEMANAS! 🍆 ¡Tengo el tamaño de una berenjena! Cada día tengo un aspecto más «humano». Mi cabeza ya guarda proporción con mi cuerpo. Ahora mi principal objetivo es ganar peso. Cuando te doy pataditas ya puedes sentir de verdad mi fuerza, ¿a que sí?', baby_message_pt = '29 SEMANAS! 🍆 Sou do tamanho de uma beringela! A cada dia pareço cada vez mais «humano». A minha cabeça já é proporcional ao meu corpo. Agora, o meu principal objetivo é ganhar peso. Já consegues mesmo sentir a minha força quando te dou pontapés, não consegues?', baby_message_vi = '29 TUẦN! 🍆 Con lớn bằng một quả cà tím rồi! Mỗi ngày trông con càng giống một em bé hơn. Đầu con giờ đã cân đối với cơ thể. Mục tiêu chính của con lúc này là tăng cân. Giờ mỗi khi con đạp, mẹ có thể cảm nhận rõ sức mạnh của con rồi, đúng không?', baby_message_hi = '29 सप्ताह! 🍆 मेरा आकार एक बैंगन जितना है! हर दिन मेरा रूप और भी ज्यादा ''इंसान जैसा'' दिखने लगा है। अब मेरा सिर मेरे शरीर के अनुपात में है। फिलहाल मेरा मुख्य लक्ष्य वजन बढ़ाना है। अब जब मैं आपको लात मारता हूँ, तो आप सच में मेरी ताकत महसूस कर सकती हैं, है न?', baby_message_ja = '29週！🍆 ナスくらいの大きさになったよ！日に日に「人間らしい」姿になっています。頭と体のバランスも整いました。今のいちばんの目標は、体重を増やすことです。今はキックすると、ぼく／わたしの力強さがしっかり伝わるよね？', baby_message_ko = '29주예요! 🍆 나는 가지만 해요! 날마다 점점 더 ''사람다운'' 모습이 되어 가고 있어요. 이제 머리와 몸의 비율도 균형이 잡혔어요. 지금 내 가장 큰 목표는 몸무게를 늘리는 거예요. 이제 내가 발로 찰 때 힘이 정말 잘 느껴지지요?', baby_message_pl = '29 TYG.! 🍆 Jestem wielkości bakłażana! Z każdym dniem coraz bardziej przypominam małego człowieka. Moja głowa jest już proporcjonalna do reszty ciała. Teraz moim głównym celem jest przybieranie na wadze. Kiedy kopię, naprawdę czujesz już moją siłę, prawda?', baby_message_nl = '29 WEKEN! 🍆 Ik ben zo groot als een aubergine! Elke dag zie ik er steeds ''menselijker'' uit. Mijn hoofd is nu in verhouding met mijn lichaam. Mijn belangrijkste doel is nu aankomen. Als ik je schop, kun je mijn kracht nu echt voelen, hè?', baby_message_sv = '29 VECKOR! 🍆 Jag är lika stor som en aubergine! För varje dag ser jag alltmer ”mänsklig” ut. Mitt huvud är nu proportionerligt till kroppen. Mitt viktigaste mål är att gå upp i vikt. Nu känner du verkligen hur stark jag är när jag sparkar, eller hur?' WHERE id = 'cad83eb0-58a7-4d1b-bb76-60f58c14c58f' AND md5(coalesce(baby_message,'')) = '199117d57e609f54fa68bc8272c13dab' AND md5(coalesce(baby_message_en,'')) = 'c57eba06210776fbf0a2b25ada94195b' AND md5(coalesce(baby_message_ru,'')) = 'edd93c6e3a726e24e5110b05131c459d' AND md5(coalesce(baby_message_tr,'')) = '62130121753ef1a969354f3620344d93' AND md5(coalesce(baby_message_kk,'')) = 'a3dae4b2fdf6cfe9360629e626325b7d' AND md5(coalesce(baby_message_de,'')) = 'a7b9b12ff2d14c34b7c565cf03ccb538' AND md5(coalesce(baby_message_ar,'')) = 'accdbb38803da484f4b536eb98bd2eb1' AND md5(coalesce(baby_message_uz,'')) = '581681dbbb6ebb27913a9eeebc40122e' AND md5(coalesce(baby_message_ka,'')) = 'fc01c463d0ae5d8a0e532a9e7d3c8122' AND md5(coalesce(baby_message_zh,'')) = 'c628e9fbc44803c197b72cb96b038151' AND md5(coalesce(baby_message_id,'')) = '754c49dff782a07758c8c9f69969d9c1' AND md5(coalesce(baby_message_fr,'')) = '846adc695d4e2ffb734b41fbf5de8320' AND md5(coalesce(baby_message_es,'')) = '64b5e1a30d59a7fa783d7517a8578735' AND md5(coalesce(baby_message_pt,'')) = 'd413ab0b9d38ffb356fa3ea45f99139b' AND md5(coalesce(baby_message_vi,'')) = '33ed7802598581947c5ab277c316f893' AND md5(coalesce(baby_message_hi,'')) = '15151b29ca99bb48819d6b1ca93f3d9d' AND md5(coalesce(baby_message_ja,'')) = 'acd7321501f5d010bc58d60891e296fc' AND md5(coalesce(baby_message_ko,'')) = 'e0d3e4bfa207f344a2fc49db281ae6f8' AND md5(coalesce(baby_message_pl,'')) = '413df5edc698e616f2e2587b2955a1a7' AND md5(coalesce(baby_message_nl,'')) = '109d44f0fa289eb5b6d5d23b41514dba' AND md5(coalesce(baby_message_sv,'')) = 'ec675f5a433f67e791531c1960c20a40';
UPDATE public.pregnancy_day_notifications SET title = 'Badımcan boydayam! 🍆', body = 'Təxminən 38-39 sm. Çəkim 1.35 kq oldu! Sənə ağır gəlirəm? Bağışla, Ana, amma mən kökəlməliyəm.', title_en = 'I''m the size of an eggplant! 🍆', body_en = 'I''m about 38-39 cm long. I weigh 1.35 kg! Am I getting heavy for you? Sorry, Mama, but I need to gain more weight.', title_ru = 'Я размером с баклажан! 🍆', body_ru = 'Примерно 38-39 см. Я вешу уже 1.35 кг! Вам тяжело меня носить? Простите, мама, но мне нужно набирать вес.', title_tr = 'Patlıcan büyüklüğündeyim! 🍆', body_tr = 'Yaklaşık 38-39 cm. Ağırlığım 1.35 kg oldu! Size ağır mı geliyorum? Affet Anne, ama kilo almam gerekiyor.', title_kk = 'Көлемім баклажандай! 🍆', body_kk = 'Шамамен 38-39 см. Салмағым 1.35 кг болды! Сізге ауыр болып жүрмін бе? Кешіріңіз, Анашым, бірақ мен салмақ қосуым керек.', title_de = 'Ich bin so groß wie eine Aubergine! 🍆', body_de = 'Ungefähr 38-39 cm. Ich wiege jetzt 1.35 kg! Bin ich dir schon zu schwer? Entschuldige, Mami, aber ich muss zunehmen.', title_ar = 'أصبحت بحجم حبة باذنجان! 🍆', body_ar = 'يبلغ طولي نحو 38-39 سم، وبلغ وزني 1.35 كغ! هل أصبحت ثقيلًا عليكِ؟ سامحيني يا ماما، لكن يجب أن أزداد وزنًا.', title_uz = 'Baqlajondek bo‘ldim! 🍆', body_uz = 'Taxminan 38-39 sm. Vaznim 1.35 kg bo‘ldi! Sizga og‘irlik qilyapmanmi? Kechiring, Onajon, ammo men vazn yig‘ishim kerak.', title_ka = 'ბადრიჯნის ზომის ვარ! 🍆', body_ka = 'დაახლოებით 38-39 სმ. უკვე 1.35 კგ-ს ვიწონი! მძიმე ვარ თქვენთვის? ბოდიში, დედიკო, მაგრამ წონაში უნდა მოვიმატო.' WHERE id = '88619dd2-a8e1-47a0-8257-5ec0eff6998d' AND md5(coalesce(title,'')) = 'cda5d076b571fc4b5f233f2cef9c7c3c' AND md5(coalesce(body,'')) = '7334b0b0ae8a199fa9b26705c26b5b5f' AND md5(coalesce(title_en,'')) = '2903efadec62ae166fc3bea93fd27556' AND md5(coalesce(body_en,'')) = 'b88dfaf0675b197c2e9f4181047abcb5' AND md5(coalesce(title_ru,'')) = '97ad57eda579c9e752ad7870520ac324' AND md5(coalesce(body_ru,'')) = '9966f629466f7fc314f00808f01ed444' AND md5(coalesce(title_tr,'')) = 'c01b0e43f9baa6c794b9b9239e2d7e26' AND md5(coalesce(body_tr,'')) = '7796e7a321a0f8db87bdc86aa3b9d646' AND md5(coalesce(title_kk,'')) = 'ff7702499d1dd51d83c0b3949c9be258' AND md5(coalesce(body_kk,'')) = 'c74651806ffd740db4c8f156e209c57a' AND md5(coalesce(title_de,'')) = '9a0ac7cb1073e8e110c6cc2e68f10c9d' AND md5(coalesce(body_de,'')) = '6c2988dca4ad08fc002f1fc63762cd94' AND md5(coalesce(title_ar,'')) = '1a2c16b4093d2c9310baa33d56a2ea18' AND md5(coalesce(body_ar,'')) = '68877bab29fdb6b39f7d36a7230ab820' AND md5(coalesce(title_uz,'')) = '1a9d6d316ed042df218f981d28ff0a46' AND md5(coalesce(body_uz,'')) = '242a7889ebc90289566eba89d31c586d' AND md5(coalesce(title_ka,'')) = '04b805cd1bdbb2c6e013c04e235d49dc' AND md5(coalesce(body_ka,'')) = '9c601cff7c58c84bf1f626c348323117';
UPDATE public.pregnancy_daily_content SET baby_message = 'Mən bir armudvari balqabaq boydayam! Anacan, inanılmazdır, biz yolun 3/4 hissəsini (75%-ni) bitirdik! Qaldı cəmi 10 həftə (təxminən). Mən artıq böyük bir körpəyəm, sadəcə hələ ağciyərlərim və beynim tam yetişməlidir. Finişə az qaldı!', baby_message_en = 'I''m the size of a butternut squash! Anacan, it''s incredible – we''ve completed three-quarters (75%) of the journey! Only about 10 weeks left. I''m already a big baby; it''s just my lungs and brain that still need to fully mature. We''re almost at the finish line!', baby_message_ru = 'Я размером с мускатную тыкву! Мамочка, невероятно, мы уже прошли 3/4 пути (75%)! Осталось всего 10 недель (примерно). Я уже большой малыш, просто моим лёгким и мозгу нужно ещё немного созреть. Финиш уже близко!', baby_message_tr = 'Ben bir butternut kabağı kadarıyım! Anneciğim, inanılmaz ama yolun 3/4 kısmını (75%''ini) tamamladık! Yalnızca 10 hafta (yaklaşık) kaldı. Artık büyük bir bebeğim; sadece akciğerlerimin ve beynimin biraz daha olgunlaşması gerekiyor. Bitişe çok az kaldı!', baby_message_kk = 'Менің өлшемім мускат асқабағындай! Анашым, сену қиын, біз жолдың 3/4 бөлігін (75%-ын) аяқтадық! Енді небәрі 10 апта қалды (шамамен). Мен қазірдің өзінде үлкен бөпемін, тек өкпем мен миым әлі толық жетілуі керек. Мәреге аз қалды!', baby_message_de = 'Ich bin so groß wie ein Butternusskürbis! Mami, unglaublich, wir haben bereits 3/4 des Weges (75%) geschafft! Es sind nur noch 10 Wochen (ungefähr). Ich bin schon ein großes Baby, nur meine Lunge und mein Gehirn müssen noch vollständig ausreifen. Die Ziellinie ist ganz nah!', baby_message_ar = 'أصبح حجمي بحجم ثمرة قرع عسلي! ماما، لا يُصدَّق، لقد قطعنا 3/4 الطريق (75%)! لم يتبقَّ سوى 10 أسابيع (تقريبًا). لقد أصبحت طفلًا كبيرًا، لكن رئتيّ ودماغي لا يزالان بحاجة إلى اكتمال النضج. اقتربنا من خط النهاية!', baby_message_uz = 'Men noksimon qovoqdek bo‘ldim! Onajon, ishonish qiyin, biz yo‘lning 3/4 qismini (75%-ni) bosib o‘tdik! Atigi 10 hafta qoldi (taxminan). Men endi katta chaqaloqman, faqat o‘pkam va miyam hali to‘liq yetilishi kerak. Marraga oz qoldi!', baby_message_ka = 'მე ერთი მსხლისებრი გოგრის ზომის ვარ! დედიკო, დაუჯერებელია — გზის 3/4 (75%) უკვე გავიარეთ! სულ რაღაც 10 კვირა დაგვრჩა (დაახლოებით). მე უკვე დიდი ბავშვი ვარ, უბრალოდ ჩემს ფილტვებსა და ტვინს ჯერ კიდევ სჭირდება სრულად მომწიფება. ფინიშამდე სულ ცოტა დარჩა!', baby_message_zh = '我已经有一个奶油南瓜那么大啦！Anacan，太不可思议了——我们已经走完了四分之三（75%）的旅程！只剩大约 10 周了。我已经是个大宝宝，现在只需要让肺和大脑继续发育成熟。我们就快到终点啦！', baby_message_id = 'Besarku sekarang seukuran labu butternut! Anacan, luar biasa—kita telah menyelesaikan tiga perempat (75%) perjalanan! Tinggal sekitar 10 minggu lagi. Aku sudah menjadi bayi yang besar; hanya paru-paru dan otakku yang masih perlu matang sepenuhnya. Kita hampir mencapai garis akhir!', baby_message_fr = 'J''ai la taille d''une courge butternut ! Anacan, c''est incroyable : nous avons parcouru les trois quarts (75 %) du chemin ! Il ne reste plus qu''environ 10 semaines. Je suis déjà un grand bébé ; seuls mes poumons et mon cerveau doivent encore arriver à pleine maturité. Nous approchons de la ligne d''arrivée !', baby_message_es = '¡Tengo el tamaño de una calabaza moscada! Anacan, es increíble: ¡ya hemos completado tres cuartas partes (75%) del camino! Solo quedan unas 10 semanas. Ya soy un bebé grande; solo falta que mis pulmones y mi cerebro terminen de madurar. ¡Ya casi llegamos a la meta!', baby_message_pt = 'Sou do tamanho de uma abóbora-manteiga! Anacan, é incrível — já completámos três quartos (75%) da viagem! Faltam apenas cerca de 10 semanas. Já sou um bebé grande; só os meus pulmões e o meu cérebro ainda precisam de amadurecer completamente. Estamos quase na meta!', baby_message_vi = 'Con lớn bằng một quả bí hồ lô rồi! Anacan ơi, thật khó tin – chúng ta đã hoàn thành ba phần tư (75%) hành trình! Chỉ còn khoảng 10 tuần nữa thôi. Con đã là một em bé lớn rồi; chỉ còn phổi và não cần tiếp tục phát triển hoàn thiện. Chúng ta sắp về đến đích rồi!', baby_message_hi = 'मैं एक बटरनट स्क्वैश जितना/जितनी हो गया/गई हूँ! Anacan, यह अविश्वसनीय है—हमने सफ़र का तीन-चौथाई (75%) हिस्सा पूरा कर लिया है! अब केवल लगभग 10 सप्ताह बाकी हैं। मैं पहले ही बड़ा बच्चा बन गया/गई हूँ; बस मेरे फेफड़ों और मस्तिष्क को अभी पूरी तरह परिपक्व होना है। हम मंज़िल के लगभग करीब पहुँच चुके हैं!', baby_message_ja = 'バターナッツかぼちゃくらいの大きさだよ！ Anacan、すごいね。旅の四分の三（75%）まで来たよ！ あと約10週間だよ。ぼくはもう大きな赤ちゃん。あとは肺と脳が完全に成熟するだけなんだ。もうすぐゴールだよ！', baby_message_ko = '저는 버터넛 스쿼시만 해요! Anacan, 정말 놀라워요. 여정의 사분의 삼(75%)을 마쳤어요! 이제 약 10주밖에 남지 않았어요. 저는 벌써 큰 아기이고, 이제 폐와 뇌가 완전히 성숙하면 돼요. 결승선이 코앞이에요!', baby_message_pl = 'Mam wielkość dyni piżmowej! Anacan, to niewiarygodne — mamy za sobą już trzy czwarte (75%) drogi! Zostało tylko około 10 tygodni. Jestem już dużym dzieckiem; jeszcze tylko moje płuca i mózg muszą w pełni dojrzeć. Meta jest tuż-tuż!', baby_message_nl = 'Ik ben zo groot als een flespompoen! Anacan, het is ongelooflijk: we hebben driekwart (75%) van de reis afgelegd! Nog maar ongeveer 10 weken te gaan. Ik ben al een grote baby; alleen mijn longen en hersenen moeten nog helemaal rijpen. We zijn bijna bij de finish!', baby_message_sv = 'Jag är stor som en butternutpumpa! Anacan, helt otroligt – vi har klarat tre fjärdedelar (75 %) av resan! Det är bara omkring 10 veckor kvar. Jag är redan en stor bebis. Nu är det bara lungorna och hjärnan som behöver mogna färdigt. Vi är nästan framme vid målet!' WHERE id = '54884850-5122-42f5-bad6-cbe7becaf6f6' AND md5(coalesce(baby_message,'')) = '628803ca186680f39354fe1eb5b874f2' AND md5(coalesce(baby_message_en,'')) = 'd55fa1a11fcbc98603bfd3e23c47d464' AND md5(coalesce(baby_message_ru,'')) = '8b7536dd3de37e73708c7fa549cb03ac' AND md5(coalesce(baby_message_tr,'')) = 'ba1fda6c29cfe0b3eebfd10a485fcffc' AND md5(coalesce(baby_message_kk,'')) = '436d9abb495a2edad4b60888b3b83830' AND md5(coalesce(baby_message_de,'')) = '9680e47e9d08685a74b2545a03b12cda' AND md5(coalesce(baby_message_ar,'')) = '1e0e104f79aedc37d759a8a3d7e87c13' AND md5(coalesce(baby_message_uz,'')) = 'ac1a431f96dde23396e24ebed225226d' AND md5(coalesce(baby_message_ka,'')) = '2216182aa803d36a74874ae05755aba9' AND md5(coalesce(baby_message_zh,'')) = '442f4f38ffe93abc110d36e5ac0b0ff9' AND md5(coalesce(baby_message_id,'')) = '7bf70d58714d0363836cc09608035721' AND md5(coalesce(baby_message_fr,'')) = '22316f78a10f81ec51a8391613f0d0e5' AND md5(coalesce(baby_message_es,'')) = '36e855966409eb3d01afe608e922359c' AND md5(coalesce(baby_message_pt,'')) = '6413610f2d28d3c01ae19efabc113183' AND md5(coalesce(baby_message_vi,'')) = 'b0a06842ef4f9c2c132b1494c9813bcf' AND md5(coalesce(baby_message_hi,'')) = 'da08ff54b5873f71c9140e278fe31bcb' AND md5(coalesce(baby_message_ja,'')) = '3a8788df1d0f64ac05906a5dc3e4f1cd' AND md5(coalesce(baby_message_ko,'')) = '279c2c3e020a3fad4689724d7f3957db' AND md5(coalesce(baby_message_pl,'')) = '9c8f0a72f9fbeb47e1ced65c8c39a591' AND md5(coalesce(baby_message_nl,'')) = 'e392d83649628fe5d4a2c1cf82d5c1d6' AND md5(coalesce(baby_message_sv,'')) = '36a24e66f3d4f7e602c9728f13c5469f';
UPDATE public.pregnancy_daily_content SET baby_message = '31 HƏFTƏ! 🥬 Salam, Anacan! Mən bir kələm boydayam. Çəkim 1.6 kq-a çatıb, boyum isə 40 sm-dir. Mən artıq kifayət qədər "ağır çəkili"yəm. İndi əsas məqsədim ağciyərlərimi yetişdirmək və daha çox piy yığmaqdır. Mən dünyaya gəlməyə hazırlaşıram!', baby_message_en = '31 WEEKS! 🥬 Hello, Mommy! I''m the size of a cabbage. My weight has reached 1.6 kg, and my length is 40 cm. I''m already quite "heavy." Now my main goal is to mature my lungs and accumulate more fat. I''m getting ready to come into the world!', baby_message_ru = '31 НЕДЕЛЯ! 🥬 Здравствуйте, мамочка! Я размером с кочан капусты. Мой вес достиг 1.6 кг, а рост 40 см. Я уже достаточно «тяжёлый». Теперь моя главная цель — подготовить лёгкие и накопить ещё больше жира. Я готовлюсь появиться на свет!', baby_message_tr = '31 HAFTA! 🥬 Merhaba, anneciğim! Ben bir lahana büyüklüğündeyim. Kilom 1.6 kg''a ulaştı, boyum ise 40 cm. Artık oldukça "ağır sıklet" sayılırım. Şimdiki temel hedefim akciğerlerimi olgunlaştırmak ve daha fazla yağ depolamak. Dünyaya gelmeye hazırlanıyorum!', baby_message_kk = '31 АПТА! 🥬 Сәлем, анашым! Менің көлемім қырыққабаттай. Салмағым 1.6 кг-ға жетті, ал бойым 40 см. Мен қазір айтарлықтай «салмақтымын». Ендігі басты мақсатым — өкпемді жетілдіріп, көбірек май жинау. Мен дүниеге келуге дайындалып жатырмын!', baby_message_de = '31 WOCHEN! 🥬 Hallo, Mami! Ich bin so groß wie ein Kohlkopf. Ich wiege inzwischen 1.6 kg und bin 40 cm groß. Ich bin schon ein echtes „Schwergewicht“. Mein wichtigstes Ziel ist es jetzt, meine Lunge weiter reifen zu lassen und noch mehr Fettreserven anzulegen. Ich bereite mich auf meine Geburt vor!', baby_message_ar = 'الأسبوع 31! 🥬 مرحبًا يا ماما! أصبح حجمي بحجم حبة ملفوف. بلغ وزني 1.6 كغ، وطولي 40 سم. لقد أصبحت الآن "ثقيل الوزن" بما يكفي. هدفي الأساسي حاليًا هو إنضاج رئتيّ وتخزين المزيد من الدهون. إنني أستعد للمجيء إلى العالم!', baby_message_uz = '31 HAFTA! 🥬 Salom, Onajon! Men karam kattaligiman. Vaznim 1.6 kg ga yetdi, bo‘yim esa 40 sm. Men endi ancha «vaznli» bo‘lib qoldim. Hozirgi asosiy maqsadim — o‘pkamni yetiltirish va ko‘proq yog‘ to‘plash. Men dunyoga kelishga tayyorlanyapman!', baby_message_ka = '31 კვირა! 🥬 გამარჯობა, დედიკო! მე უკვე კომბოსტოს ზომის ვარ. ჩემი წონა 1.6 კგ-ს აღწევს, სიგრძე კი 40 სმ-ია. უკვე საკმაოდ „მძიმეწონიანი“ ვარ. ახლა ჩემი მთავარი მიზანია, ფილტვები მომწიფდეს და მეტი ცხიმი დავაგროვო. ამქვეყნად მოსასვლელად ვემზადები!', baby_message_zh = '31 周啦！🥬 妈妈，你好呀！我现在有卷心菜那么大。体重已经达到 1.6 千克，身长 40 厘米。我已经相当“有分量”了。现在，我的主要目标是让肺部发育成熟，并积累更多脂肪。我正在为来到这个世界做准备！', baby_message_id = '31 MINGGU! 🥬 Halo, Bunda! Ukuranku sebesar kubis. Beratku sudah mencapai 1.6 kg dan panjangku 40 cm. Aku sudah cukup "berat". Sekarang tujuan utamaku adalah mematangkan paru-paru dan menimbun lebih banyak lemak. Aku sedang bersiap untuk lahir ke dunia!', baby_message_fr = '31 SEMAINES ! 🥬 Bonjour, Maman ! J’ai la taille d’un chou. Mon poids atteint maintenant 1.6 kg et je mesure 40 cm. Je suis déjà plutôt « lourd ». Mon objectif principal est désormais de faire mûrir mes poumons et d’accumuler davantage de graisse. Je me prépare à venir au monde !', baby_message_es = '¡31 SEMANAS! 🥬 ¡Hola, mamá! Tengo el tamaño de una col. Ya peso 1.6 kg y mido 40 cm. Ya peso bastante. Ahora mi principal objetivo es que mis pulmones maduren y acumular más grasa. ¡Me estoy preparando para venir al mundo!', baby_message_pt = '31 SEMANAS! 🥬 Olá, mamã! Tenho o tamanho de uma couve. Já peso 1.6 kg e meço 40 cm. Já estou bastante «pesado». Agora, o meu principal objetivo é amadurecer os pulmões e acumular mais gordura. Estou a preparar-me para vir ao mundo!', baby_message_vi = '31 TUẦN! 🥬 Xin chào mẹ! Giờ con có kích thước bằng một cây bắp cải. Con đã nặng 1.6 kg và dài 40 cm. Con đã khá “nặng ký” rồi đấy. Giờ mục tiêu chính của con là hoàn thiện phổi và tích lũy thêm mỡ. Con đang chuẩn bị để chào đời!', baby_message_hi = '31 सप्ताह! 🥬 नमस्ते, मम्मी! अब मेरा आकार एक पत्तागोभी जितना है। मेरा वज़न 1.6 kg और लंबाई 40 cm हो गई है। अब मैं काफ़ी "भारी" हो गया हूँ। अब मेरा मुख्य लक्ष्य अपने फेफड़ों को परिपक्व करना और अधिक वसा जमा करना है। मैं दुनिया में आने की तैयारी कर रहा हूँ!', baby_message_ja = '31週です！🥬 ママ、こんにちは！キャベツくらいの大きさになりました。体重は1.6 kg、身長は40 cmです。もうかなり「重い」ですよ。これからの主な目標は、肺を成熟させ、さらに脂肪を蓄えることです。この世界に出る準備をしています！', baby_message_ko = '31주! 🥬 안녕하세요, 엄마! 나는 양배추만큼 자랐어요. 몸무게는 1.6 kg, 키는 40 cm예요. 이제 제법 "묵직"해졌어요. 지금 내 가장 큰 목표는 폐를 성숙시키고 지방을 더 많이 축적하는 거예요. 세상에 나갈 준비를 하고 있어요!', baby_message_pl = '31 TYGODNI! 🥬 Witaj, Mamusiu! Jestem teraz wielkości kapusty. Moja masa wynosi już 1.6 kg, a długość 40 cm. Mam już całkiem sporą „wagę”. Teraz moim głównym celem jest dojrzewanie płuc i gromadzenie większej ilości tłuszczu. Szykuję się na przyjście na świat!', baby_message_nl = '31 WEKEN! 🥬 Hallo, mama! Ik ben zo groot als een kool. Ik weeg nu 1.6 kg en ben 40 cm lang. Ik ben al behoorlijk ‘zwaar’. Mijn belangrijkste doel is nu om mijn longen verder te laten rijpen en meer vet op te slaan. Ik maak me klaar om ter wereld te komen!', baby_message_sv = '31 VECKOR! 🥬 Hej, mamma! Jag är lika stor som ett kålhuvud. Jag väger nu 1.6 kg och är 40 cm lång. Jag är redan ganska ”tung”. Nu är mitt främsta mål att låta lungorna mogna och samla på mig mer fett. Jag gör mig redo att komma ut i världen!' WHERE id = 'c4869a77-6abd-43f7-8c86-3d05ecb63f8d' AND md5(coalesce(baby_message,'')) = 'fe41b99e455cb51cbe1235c741e58733' AND md5(coalesce(baby_message_en,'')) = '270703f10cf772d7176b2c68f90e7720' AND md5(coalesce(baby_message_ru,'')) = 'b5290c32261ac1c2cbc6849b0afefd87' AND md5(coalesce(baby_message_tr,'')) = 'ac2e1e9c2650744fe09b234692889e7d' AND md5(coalesce(baby_message_kk,'')) = '00d0d42f3cc001e34cd38069d7a056dd' AND md5(coalesce(baby_message_de,'')) = '412894c6cb1debdc13e6abf9c360aa8d' AND md5(coalesce(baby_message_ar,'')) = 'f9a8ff247fa175a65e222a484e47818a' AND md5(coalesce(baby_message_uz,'')) = '34bae0d221e5463fd096fff71e747795' AND md5(coalesce(baby_message_ka,'')) = '4b79ba14ff315996031cecbd1c53edbd' AND md5(coalesce(baby_message_zh,'')) = '9eff659c2276fe0a01bb8cd1ee257462' AND md5(coalesce(baby_message_id,'')) = '12e1bbd02eb6791bc387f97548daf335' AND md5(coalesce(baby_message_fr,'')) = '3d2a3a5ada85700564c6c0f35bf5e01a' AND md5(coalesce(baby_message_es,'')) = '5583dfb34dfd0e4c9bce94fa968d25b1' AND md5(coalesce(baby_message_pt,'')) = 'e49ef579f3d6d3bd8accdf0524078dcd' AND md5(coalesce(baby_message_vi,'')) = '7b9f331b2b727f4817d659e14406f0ce' AND md5(coalesce(baby_message_hi,'')) = '66c04b4a8d470577d412f7117ca4c9e0' AND md5(coalesce(baby_message_ja,'')) = 'f777c46cde64b7d6cc466e83906cad45' AND md5(coalesce(baby_message_ko,'')) = '2d5005aef83b561f10112490560eddcf' AND md5(coalesce(baby_message_pl,'')) = 'cccfab857dba17c7b68b105ddb4d48bb' AND md5(coalesce(baby_message_nl,'')) = '2968ac5ddff3065f769cdb73166751b0' AND md5(coalesce(baby_message_sv,'')) = '02c146bfbdca83efc25889d32023137a';
UPDATE public.pregnancy_daily_content SET baby_message = '32 HƏFTƏ! 🥥 Mən bir kokos boydayam! Mən artıq "ağır çəkili"yəm. İndi uşaqlıq mənə dar gəlir. Ayaqlarımı tam uzada bilmirəm, ona görə də "fetal pozisiya"da dururam. Bu mənim ən rahat duruşumdur.', baby_message_en = '32 WEEKS! 🥥 I''m the size of a coconut! I''m already quite "heavy." My uterus is getting cramped now. I can''t fully stretch my legs, so I stay in the "fetal position." This is my most comfortable posture.', baby_message_ru = '32 НЕДЕЛИ! 🥥 Я размером с кокос! Я уже настоящий "тяжеловес". Теперь мне тесно в матке. Я не могу полностью выпрямить ноги, поэтому нахожусь в "позе эмбриона". Для меня это самое удобное положение.', baby_message_tr = '32 HAFTA! 🥥 Ben bir Hindistan cevizi büyüklüğündeyim! Artık "ağır sıklet"im. Rahim artık bana dar geliyor. Bacaklarımı tamamen uzatamıyorum, bu yüzden "fetal pozisyonda" duruyorum. Bu benim en rahat duruşum.', baby_message_kk = '32 АПТА! 🥥 Менің көлемім кокостай! Мен енді "ауыр салмақтымын". Қазір жатыр маған тарлық етеді. Аяқтарымды толық жаза алмаймын, сондықтан "эмбрион қалпында" жатамын. Бұл — мен үшін ең ыңғайлы қалып.', baby_message_de = '32 WOCHEN! 🥥 Ich bin so groß wie eine Kokosnuss! Ich bin jetzt schon ein echtes „Schwergewicht“. In der Gebärmutter wird es langsam eng für mich. Ich kann meine Beine nicht mehr ganz ausstrecken und liege deshalb in der „Fötalstellung“. Das ist für mich die bequemste Haltung.', baby_message_ar = '32 أسبوعًا! 🥥 أنا بحجم ثمرة جوز هند! لقد أصبحت الآن من «الأوزان الثقيلة». ولم يعد الرحم واسعًا بما يكفي لي. لا أستطيع مد ساقيّ بالكامل، لذلك أبقى في «وضعية الجنين». هذه هي الوضعية الأكثر راحة لي.', baby_message_uz = '32 HAFTA! 🥥 Men kokosdek kattaman! Endi men "og‘ir vaznli"man. Hozir bachadon menga torlik qilyapti. Oyoqlarimni to‘liq uza olmayman, shuning uchun "homila holati"da yotaman. Bu men uchun eng qulay holat.', baby_message_ka = '32 კვირის ვარ! 🥥 უკვე ქოქოსის ზომა ვარ! ახლა უკვე "მძიმე წონოსანი" ვარ. საშვილოსნოში ადგილი აღარ მყოფნის. ფეხებს ბოლომდე ვეღარ ვშლი, ამიტომ "ფეტალურ პოზაში" ვიმყოფები. ეს ჩემთვის ყველაზე კომფორტული პოზაა.', baby_message_zh = '32周啦！🥥 我现在有一个椰子那么大！我已经相当“有分量”了。子宫里的空间越来越挤，我没法完全伸直双腿，所以会保持“胎儿姿势”。这是我最舒服的姿势。', baby_message_id = '32 MINGGU! 🥥 Ukuranku sebesar kelapa! Aku sudah cukup "berat". Rahim Anda kini terasa semakin sempit. Aku tidak bisa meregangkan kaki sepenuhnya, jadi aku tetap dalam "posisi janin". Inilah posisi yang paling nyaman bagiku.', baby_message_fr = '32 SEMAINES ! 🥥 J’ai la taille d’une noix de coco ! Je suis déjà plutôt « lourd ». Je commence à être à l’étroit dans l’utérus. Je ne peux plus étendre complètement mes jambes, alors je reste en « position fœtale ». C’est la posture la plus confortable pour moi.', baby_message_es = '¡32 SEMANAS! 🥥 ¡Tengo el tamaño de un coco! Ya peso bastante. Mi útero se está quedando pequeño. No puedo estirar del todo las piernas, así que permanezco en «posición fetal». Es la postura más cómoda para mí.', baby_message_pt = '32 SEMANAS! 🥥 Tenho o tamanho de um coco! Já estou bastante «pesado». O meu espaço no útero está cada vez mais apertado. Não consigo esticar completamente as pernas, por isso fico na «posição fetal». É a posição mais confortável para mim.', baby_message_vi = '32 TUẦN! 🥥 Con có kích thước tương đương một quả dừa! Giờ con đã khá "nặng" rồi. Tử cung của mẹ ngày càng chật hơn. Con không thể duỗi thẳng chân hoàn toàn nên cứ cuộn mình trong "tư thế bào thai". Đây là tư thế thoải mái nhất của con.', baby_message_hi = '32 सप्ताह! 🥥 मैं एक नारियल जितना बड़ा हूँ! अब मैं काफी "भारी" हो गया हूँ। गर्भाशय में अब जगह कम पड़ने लगी है। मैं अपने पैरों को पूरी तरह सीधा नहीं कर सकता, इसलिए "भ्रूण मुद्रा" में रहता हूँ। यही मेरे लिए सबसे आरामदायक मुद्रा है।', baby_message_ja = '32週！🥥 今の私はココナッツくらいの大きさだよ！もうかなり「重く」なったんだ。子宮の中もだんだん窮屈になってきたよ。脚を完全に伸ばせないから、「胎児姿勢」で過ごしているんだ。これがいちばん楽な姿勢だよ。', baby_message_ko = '32주예요! 🥥 저는 코코넛만 한 크기예요! 벌써 제법 "묵직"해졌어요. 제가 있는 자궁이 이제 비좁아지고 있어요. 다리를 완전히 펼 수 없어서 "태아 자세"로 웅크리고 있어요. 이 자세가 가장 편안해요.', baby_message_pl = '32 TYGODNI! 🥥 Jestem wielkości kokosa! Mam już całkiem sporą „wagę”. W macicy robi się teraz ciasno. Nie mogę całkowicie wyprostować nóg, więc pozostaję w „pozycji płodowej”. Tak jest mi najwygodniej.', baby_message_nl = '32 WEKEN! 🥥 Ik ben zo groot als een kokosnoot! Ik ben al behoorlijk ‘zwaar’. Het wordt nu krap in je baarmoeder. Ik kan mijn benen niet helemaal strekken, dus lig ik in de ‘foetushouding’. Dit is voor mij de prettigste houding.', baby_message_sv = '32 VECKOR! 🥥 Jag är lika stor som en kokosnöt! Jag är redan ganska ”tung”. Det börjar bli trångt i livmodern. Jag kan inte sträcka ut benen helt, så jag ligger i ”fosterställning”. Det är den bekvämaste ställningen för mig.' WHERE id = '33dd2de9-c534-420c-8e3d-e027683ad6e9' AND md5(coalesce(baby_message,'')) = 'e00eb3e1949c195ffbeab44088dff29f' AND md5(coalesce(baby_message_en,'')) = '2ea5657ee8fc0d0e993a0337c0af03c3' AND md5(coalesce(baby_message_ru,'')) = '752f7c153f68fdcd2a0026780b35686d' AND md5(coalesce(baby_message_tr,'')) = '7f89250b7f26430fc8771e69e355a9a5' AND md5(coalesce(baby_message_kk,'')) = 'f01e4482845de4ad390060d690d43c85' AND md5(coalesce(baby_message_de,'')) = 'cccc63f9b3d4f76a175dee5ff971ae22' AND md5(coalesce(baby_message_ar,'')) = '01d50572010fd9db017a6024da91f25f' AND md5(coalesce(baby_message_uz,'')) = 'dc1ba1c75df0eec94dbd06d762de3184' AND md5(coalesce(baby_message_ka,'')) = '133685d53777e50e824f6aeb8a31d71f' AND md5(coalesce(baby_message_zh,'')) = '34bca851d8bde0645cdd2b9eced53e3f' AND md5(coalesce(baby_message_id,'')) = 'bdeb9419a0ad016ada054eaf70003dc6' AND md5(coalesce(baby_message_fr,'')) = 'f9d59bdd69380a20730f2e996c3d96bc' AND md5(coalesce(baby_message_es,'')) = 'ecf89ea0cf1ecbf2b8b69d34cfcc6c64' AND md5(coalesce(baby_message_pt,'')) = '2690001d7044b13758b9da3ce74186e4' AND md5(coalesce(baby_message_vi,'')) = '95e3929d1fac218f31d9b2024f0ddcd3' AND md5(coalesce(baby_message_hi,'')) = '5926bd65d4f1f8aa5df3ca2f2b02f5c7' AND md5(coalesce(baby_message_ja,'')) = 'f69a35eff6e91b48d0241531c0d757a2' AND md5(coalesce(baby_message_ko,'')) = '5bf81f5b5ce0e1d310d9c5b021391ac5' AND md5(coalesce(baby_message_pl,'')) = 'e38919a346bc5afce4624892931d7bd4' AND md5(coalesce(baby_message_nl,'')) = '86b11c5351b668cf08275da22bbc721f' AND md5(coalesce(baby_message_sv,'')) = 'cf608bdf483cba549cd1c1177f1fdb0e';
UPDATE public.pregnancy_daily_content SET baby_message = '🍍 Mən bir ananas boydayam! Bu həftə çox böyük bir mərhələdir. Əgər mən indi doğulsam, ağciyərlərim artıq kifayət qədər inkişaf etdiyi üçün böyük ehtimalla sərbəst nəfəs ala bilərəm. Mən artıq "gecikmiş erkən doğum" kateqoriyasındayam. Risk xeyli azaldı!', baby_message_en = '🍍 I''m the size of a pineapple! This week is a huge milestone. If I were born now, my lungs are developed enough that I could likely breathe on my own. I''m now considered ''late preterm,'' so the risks have significantly decreased!', baby_message_ru = '🍍 Я размером с ананас! Эта неделя — очень важный этап. Если я рожусь сейчас, то, скорее всего, смогу дышать самостоятельно, потому что мои лёгкие уже достаточно развиты. Теперь я отношусь к категории поздней недоношенности. Риск значительно снизился!', baby_message_tr = '🍍 Ben bir ananas büyüklüğündeyim! Bu hafta çok önemli bir dönüm noktası. Şimdi doğarsam akciğerlerim yeterince geliştiği için büyük olasılıkla kendi başıma nefes alabilirim. Artık "geç preterm doğum" kategorisindeyim. Risk önemli ölçüde azaldı!', baby_message_kk = '🍍 Менің көлемім бір ананастай! Бұл апта — өте маңызды кезең. Егер мен қазір дүниеге келсем, өкпем жеткілікті дамығандықтан, өз бетімше тыныс алуым әбден мүмкін. Мен енді "кеш мерзімді шала туу" санатына жатамын. Қауіп айтарлықтай азайды!', baby_message_de = '🍍 Ich bin so groß wie eine Ananas! Diese Woche ist ein sehr wichtiger Meilenstein. Wenn ich jetzt geboren würde, könnte ich sehr wahrscheinlich selbstständig atmen, da meine Lunge bereits ausreichend entwickelt ist. Ich gehöre nun zur Kategorie der „späten Frühgeburt“. Das Risiko ist deutlich gesunken!', baby_message_ar = '🍍 أنا بحجم ثمرة أناناس! هذا الأسبوع يمثل مرحلة مهمة جدًا. إذا وُلدت الآن، فمن المرجح أن أتمكن من التنفس بمفردي لأن رئتيّ أصبحتا متطورتين بما يكفي. أنا الآن ضمن فئة "الخداج المتأخر". لقد انخفضت المخاطر كثيرًا!', baby_message_uz = '🍍 Men ananas kattaligidekman! Bu hafta juda muhim bosqich. Agar hozir tug‘ilsam, o‘pkalarim yetarlicha rivojlangani uchun katta ehtimol bilan mustaqil nafas ola olaman. Endi men "kechki muddatidan oldin tug‘ilish" toifasidaman. Xavf ancha kamaydi!', baby_message_ka = '🍍 მე ანანასის ზომის ვარ! ეს კვირა ძალიან მნიშვნელოვანი ეტაპია. ახლა რომ დავიბადო, დიდი ალბათობით დამოუკიდებლად სუნთქვას შევძლებ, რადგან ჩემი ფილტვები უკვე საკმარისად არის განვითარებული. ახლა უკვე „გვიანი დღენაკლულობის“ კატეგორიაში ვარ. რისკი მნიშვნელოვნად შემცირდა!', baby_message_zh = '🍍 我已经有一个菠萝那么大啦！这一周是一个重要的里程碑。如果我现在出生，我的肺部已经发育到很可能可以自主呼吸的程度。我现在属于“晚期早产儿”，因此风险已经显著降低！', baby_message_id = '🍍 Ukuranku sebesar nanas! Minggu ini adalah pencapaian yang sangat besar. Jika aku lahir sekarang, paru-paruku sudah cukup berkembang sehingga kemungkinan besar aku dapat bernapas sendiri. Kini aku dianggap ''prematur akhir'', jadi risikonya sudah jauh berkurang!', baby_message_fr = '🍍 J’ai la taille d’un ananas ! Cette semaine marque une étape très importante. Si je naissais maintenant, mes poumons seraient probablement assez développés pour que je puisse respirer seul. Je suis désormais considéré comme un bébé « prématuré tardif », les risques ont donc considérablement diminué !', baby_message_es = '🍍 ¡Tengo el tamaño de una piña! Esta semana marca un hito muy importante. Si naciera ahora, mis pulmones estarían lo bastante desarrollados como para que probablemente pudiera respirar por mi cuenta. Ya se me considera «prematuro tardío», por lo que los riesgos han disminuido considerablemente.', baby_message_pt = '🍍 Sou do tamanho de um ananás! Esta semana marca uma etapa muito importante. Se nascesse agora, os meus pulmões já estariam suficientemente desenvolvidos para que provavelmente conseguisse respirar sem ajuda. Agora sou considerado «prematuro tardio», pelo que os riscos diminuíram significativamente!', baby_message_vi = '🍍 Con có kích thước bằng một quả dứa! Tuần này đánh dấu một cột mốc rất quan trọng. Nếu chào đời vào lúc này, phổi của con đã phát triển đủ để nhiều khả năng con có thể tự thở. Giờ con được xem là "sinh non muộn", vì vậy các nguy cơ đã giảm đáng kể!', baby_message_hi = '🍍 मैं एक अनानास जितना बड़ा हूँ! यह सप्ताह एक बहुत बड़ी उपलब्धि है। अगर मेरा जन्म अभी हो जाए, तो मेरे फेफड़े इतने विकसित हो चुके हैं कि संभवतः मैं अपने आप साँस ले सकूँ। अब मुझे ''लेट प्रीटर्म'' माना जाता है, इसलिए जोखिम काफ़ी कम हो गए हैं!', baby_message_ja = '🍍 パイナップルくらいの大きさだよ！今週は大きな節目なんだ。もし今生まれても、自分で呼吸できる可能性が高いくらい肺が発達しているよ。今は「後期早産」の時期とされ、リスクも大きく下がったんだ！', baby_message_ko = '🍍 저는 파인애플만 해요! 이번 주는 아주 중요한 이정표예요. 지금 태어나더라도 스스로 숨을 쉴 수 있을 만큼 폐가 발달했을 가능성이 커요. 이제 ''후기 조산아''에 해당해서 위험도 크게 낮아졌어요!', baby_message_pl = '🍍 Mam wielkość ananasa! Ten tydzień to ogromny kamień milowy. Gdyby poród nastąpił teraz, moje płuca są już na tyle rozwinięte, że prawdopodobnie udałoby mi się oddychać samodzielnie. To już etap późnego wcześniactwa, więc ryzyko znacznie się zmniejszyło!', baby_message_nl = '🍍 Ik ben zo groot als een ananas! Deze week bereiken we een enorme mijlpaal. Als ik nu geboren zou worden, zijn mijn longen waarschijnlijk voldoende ontwikkeld om zelf te kunnen ademen. Ik word nu als ‘laat prematuur’ beschouwd, dus de risico''s zijn aanzienlijk afgenomen!', baby_message_sv = '🍍 Jag är lika stor som en ananas! Den här veckan är en enorm milstolpe. Om jag föddes nu är mina lungor så pass utvecklade att jag troligen skulle kunna andas själv. Jag räknas nu som ”sent prematur”, så riskerna har minskat betydligt!' WHERE id = '5eeb8067-0b28-436d-9bac-19e1ef1b2e15' AND md5(coalesce(baby_message,'')) = '5e3baa84aa40f0b655782cf06ac1cd51' AND md5(coalesce(baby_message_en,'')) = 'd689f09f7a9d6e4a524c2c86e791824c' AND md5(coalesce(baby_message_ru,'')) = 'fe538bf5c4872087fe168f5159fbf462' AND md5(coalesce(baby_message_tr,'')) = 'bfe5bb5e06f5d44d628096d8d961a3d7' AND md5(coalesce(baby_message_kk,'')) = 'ae5e1bb90f19ae70863ec6e5eb80b040' AND md5(coalesce(baby_message_de,'')) = '46e1e2e7814cd5e9ed8aa6803852f7cc' AND md5(coalesce(baby_message_ar,'')) = 'c2c2fe5749534c98f5d7529fc17e3590' AND md5(coalesce(baby_message_uz,'')) = '8eaff702125d9469a4f4e69cfad179d6' AND md5(coalesce(baby_message_ka,'')) = '4a4ee4f4c42db8719029081582df19e6' AND md5(coalesce(baby_message_zh,'')) = '3c02eb1f13d3eec59cdff8e122521438' AND md5(coalesce(baby_message_id,'')) = 'a6de0e58fb88527a28ba6b29879fadc8' AND md5(coalesce(baby_message_fr,'')) = 'e0cd275ba3544d1720d5c42ffe2ed5fc' AND md5(coalesce(baby_message_es,'')) = '8e8138eda63d4dbbed5da63b87e1f711' AND md5(coalesce(baby_message_pt,'')) = 'bf6d473c94c2aac7d6087af05ec0237c' AND md5(coalesce(baby_message_vi,'')) = 'd0384d1936cfa4b386b2a7b7e658fbe4' AND md5(coalesce(baby_message_hi,'')) = 'e5bd44e249be023268764ec6e6279209' AND md5(coalesce(baby_message_ja,'')) = 'f68a9486065bf5d775b840e007e40b1c' AND md5(coalesce(baby_message_ko,'')) = 'dddbef3b8c89e4545052501ea676ef3e' AND md5(coalesce(baby_message_pl,'')) = '6f98aa7946fe349b51445bfba03c0d71' AND md5(coalesce(baby_message_nl,'')) = '91069ff6eec79bc466115b92acb476ff' AND md5(coalesce(baby_message_sv,'')) = '664eba94e63e5a4e05b61549eaa34220';
UPDATE public.pregnancy_daily_content SET baby_development = 'Körpənizin çəkisi bu həftə orta hesabla 2800-3100 qram, boyu isə 47-50 sm aralığındadır; diş ətləri bərkiyir, dərisi isə getdikcə daha hamar və yumşaq bir hal alır. Bu mərhələdə körpənizin qavrama refleksi olduqca inkişaf etmişdir ki, bu da onun sinir sisteminin düzgün işlədiyinin əsas göstəricisidir. Qavrama refleksi xüsusilə əllərdə və ayaqlarda özünü büruzə verir və qıcıqlara qarşı verilən qeyri-iradi bir reaksiyadır. Hələ doğulmamışdan formalaşan bu hərəkət doğuşdan sonrakı ilk iki ay ərzində aktiv olur, daha sonra isə tədricən zəifləyərək yerini şüurlu tutma hərəkətinə verir. Maraqlıdır ki, ayaqlardakı qavrama refleksi əllərə nisbətən daha uzun müddət qalır və onun iradi hərəkətə çevrilməsi 6-cı aya qədər davam edə bilir.', baby_development_en = 'This week, your baby''s weight averages between 2800-3100 grams, and their length is around 47-50 cm. Their gums are firming up, and their skin is becoming progressively smoother and softer. At this stage, your baby''s grasp reflex is quite developed, which is a key indicator of their nervous system functioning correctly. The grasp reflex is particularly evident in the hands and feet and is an involuntary reaction to stimuli. This movement, which forms before birth, remains active for the first two months after birth, then gradually weakens, giving way to conscious grasping. Interestingly, the plantar grasp reflex in the feet persists longer than in the hands, and its transition to voluntary movement can continue until the 6th month.', baby_development_ru = 'На этой неделе вес вашего малыша в среднем составляет 2800–3100 граммов, а рост 47–50 см; дёсны становятся плотнее, а кожа — всё более гладкой и мягкой. На этом этапе хватательный рефлекс малыша уже хорошо развит, что является одним из главных признаков правильной работы его нервной системы. Хватательный рефлекс особенно выражен в кистях и стопах и представляет собой непроизвольную реакцию на раздражители. Этот рефлекс формируется ещё до рождения и остаётся активным в течение первых двух месяцев жизни, после чего постепенно ослабевает, уступая место осознанному захватыванию. Интересно, что хватательный рефлекс стоп сохраняется дольше, чем рефлекс кистей, а его переход в произвольное движение может продолжаться до 6-го месяца.', baby_development_tr = 'Bebeğinizin ağırlığı bu hafta ortalama 2800-3100 gram, boyu ise 47-50 cm aralığındadır; diş etleri sertleşirken cildi giderek daha pürüzsüz ve yumuşak bir hâl alır. Bu aşamada bebeğinizin kavrama refleksi oldukça gelişmiştir ve bu, sinir sisteminin düzgün çalıştığının temel göstergelerinden biridir. Kavrama refleksi özellikle ellerde ve ayaklarda görülür ve uyaranlara karşı verilen istemsiz bir tepkidir. Henüz doğmadan gelişen bu refleks, doğumdan sonraki ilk iki ay boyunca aktif kalır; ardından giderek zayıflayarak yerini bilinçli tutma hareketine bırakır. İlginç bir şekilde, ayaklardaki kavrama refleksi ellerdekine göre daha uzun süre devam eder ve istemli bir harekete dönüşmesi 6. aya kadar sürebilir.', baby_development_kk = 'Осы аптада бөпеңіздің салмағы орта есеппен 2800-3100 грамм, ал бойы 47-50 см аралығында болады; қызыл иегі қатайып, терісі барған сайын тегіс әрі жұмсақ бола түседі. Бұл кезеңде бөпеңіздің қармау рефлексі жақсы дамыған, бұл — оның жүйке жүйесінің дұрыс жұмыс істеп тұрғанының негізгі көрсеткіштерінің бірі. Қармау рефлексі әсіресе қолдары мен аяқтарында байқалады және тітіркендіргіштерге берілетін еріксіз жауап болып саналады. Құрсақта жатқанда-ақ қалыптасатын бұл қимыл туғаннан кейінгі алғашқы екі айда белсенді болады, содан кейін біртіндеп әлсіреп, орнын саналы түрде ұстау қимылына береді. Бір қызығы, аяқтардағы қармау рефлексі қолдарға қарағанда ұзағырақ сақталады және оның ерікті қимылға айналуы 6-шы айға дейін жалғасуы мүмкін.', baby_development_de = 'Das Gewicht deines Babys liegt diese Woche durchschnittlich zwischen 2800-3100 Gramm, seine Größe zwischen 47-50 cm. Sein Zahnfleisch wird fester und seine Haut zunehmend glatter und weicher. In dieser Phase ist der Greifreflex deines Babys bereits sehr gut entwickelt – ein wichtiges Zeichen dafür, dass sein Nervensystem richtig funktioniert. Der Greifreflex zeigt sich besonders an Händen und Füßen und ist eine unwillkürliche Reaktion auf Reize. Dieser Reflex entwickelt sich bereits vor der Geburt, bleibt in den ersten beiden Lebensmonaten aktiv und wird anschließend allmählich schwächer, bis er durch bewusstes Greifen ersetzt wird. Interessanterweise bleibt der Greifreflex an den Füßen länger erhalten als an den Händen. Die Entwicklung hin zu einer willkürlichen Bewegung kann dort bis zum 6. Monat dauern.', baby_development_ar = 'يتراوح وزن طفلكِ هذا الأسبوع في المتوسط بين 2800 و3100 غرام، وطوله بين 47 و50 سم؛ وتزداد لثته صلابة، فيما تصبح بشرته أكثر نعومة وملمسًا حريريًا تدريجيًا. في هذه المرحلة، يكون منعكس القبض لدى طفلكِ متطورًا للغاية، وهو أحد المؤشرات الأساسية على سلامة عمل جهازه العصبي. يظهر منعكس القبض بوضوح في اليدين والقدمين، وهو استجابة لا إرادية للمحفزات. تتكوّن هذه الحركة قبل الولادة، وتظل نشطة خلال الشهرين الأولين بعدها، ثم تضعف تدريجيًا لتحل محلها حركة الإمساك الإرادية. ومن المثير للاهتمام أن منعكس القبض في القدمين يستمر مدة أطول مقارنة باليدين، وقد يستغرق تحوله إلى حركة إرادية حتى الشهر السادس.', baby_development_uz = 'Bu haftada chaqalog‘ingizning vazni o‘rtacha 2800–3100 gramm, bo‘yi esa 47–50 sm atrofida; milklar qattiqlashib, terisi tobora silliq va yumshoq bo‘lib bormoqda. Bu bosqichda chaqalog‘ingizning ushlash refleksi ancha rivojlangan bo‘lib, bu uning asab tizimi to‘g‘ri ishlayotganining asosiy ko‘rsatkichlaridan biridir. Ushlash refleksi, ayniqsa, qo‘l va oyoqlarda namoyon bo‘ladi hamda ta’sirlarga javoban yuzaga keladigan ixtiyorsiz reaksiyadir. Tug‘ilishdan oldin shakllanadigan bu refleks tug‘ilgandan keyingi dastlabki ikki oy davomida faol bo‘ladi, keyin esa asta-sekin susayib, o‘rnini ongli ravishda ushlash harakatiga bo‘shatadi. Qizig‘i shundaki, oyoqlardagi ushlash refleksi qo‘llardagiga qaraganda uzoqroq saqlanadi va uning ixtiyoriy harakatga aylanishi 6-oygacha davom etishi mumkin.', baby_development_ka = 'ამ კვირაში თქვენი ბავშვის წონა საშუალოდ 2800-3100 გრამია, ხოლო სიგრძე 47-50 სმ-ის ფარგლებშია; ღრძილები უმაგრდება, კანი კი თანდათან უფრო გლუვი და რბილი ხდება. ამ ეტაპზე ბავშვის ჩაჭიდების რეფლექსი საკმაოდ განვითარებულია, რაც მისი ნერვული სისტემის გამართული მუშაობის ერთ-ერთი მთავარი მაჩვენებელია. ჩაჭიდების რეფლექსი განსაკუთრებით ხელებსა და ტერფებზე ვლინდება და გამღიზიანებელზე უნებლიე რეაქციაა. ეს მოძრაობა დაბადებამდე ყალიბდება, დაბადებიდან პირველი ორი თვის განმავლობაში აქტიურია, შემდეგ კი თანდათან სუსტდება და ადგილს გააზრებულ ჩაჭიდებას უთმობს. საინტერესოა, რომ ტერფებზე ჩაჭიდების რეფლექსი ხელებთან შედარებით უფრო დიდხანს ნარჩუნდება და მის ნებაყოფლობით მოძრაობად გარდაქმნას შეიძლება მე-6 თვემდე დასჭირდეს.', baby_development_zh = '本周，宝宝的平均体重约为2800-3100克，身长约为47-50厘米。牙龈逐渐变得坚实，皮肤也越来越光滑柔软。此时，宝宝的抓握反射已相当成熟，这是神经系统功能正常的重要标志。抓握反射在手和脚上尤其明显，是受到刺激后产生的无意识反应。这种动作在出生前形成，出生后的头两个月仍会保持活跃，之后逐渐减弱，并被有意识的抓握动作取代。有趣的是，脚部的足底抓握反射会比手部持续更久，向自主运动的过渡可能一直持续到第6个月。', baby_development_id = 'Minggu ini, berat bayi Anda rata-rata berkisar antara 2800-3100 gram, dengan panjang sekitar 47-50 cm. Gusinya semakin kuat, sementara kulitnya makin halus dan lembut. Pada tahap ini, refleks menggenggam bayi Anda sudah berkembang dengan baik, yang menjadi indikator penting bahwa sistem sarafnya berfungsi dengan benar. Refleks menggenggam terutama tampak pada tangan dan kaki serta merupakan reaksi tak sadar terhadap rangsangan. Gerakan yang terbentuk sebelum lahir ini tetap aktif selama dua bulan pertama setelah kelahiran, lalu perlahan melemah dan digantikan oleh gerakan menggenggam secara sadar. Menariknya, refleks menggenggam plantar pada kaki bertahan lebih lama daripada pada tangan, dan peralihannya menjadi gerakan sadar dapat berlangsung hingga bulan ke-6.', baby_development_fr = 'Cette semaine, le poids de votre bébé se situe en moyenne entre 2800-3100 grammes, et sa taille est d’environ 47-50 cm. Ses gencives se raffermissent et sa peau devient progressivement plus lisse et plus douce. À ce stade, son réflexe d’agrippement est déjà bien développé, ce qui constitue un indicateur important du bon fonctionnement de son système nerveux. Ce réflexe, particulièrement marqué dans les mains et les pieds, est une réaction involontaire aux stimuli. Apparu avant la naissance, il reste actif pendant les deux premiers mois après la naissance, puis s’atténue progressivement pour laisser place à une préhension volontaire. Fait intéressant, le réflexe d’agrippement plantaire persiste plus longtemps que celui des mains, et sa transition vers un mouvement volontaire peut se poursuivre jusqu’au 6e mois.', baby_development_es = 'Esta semana, el peso de tu bebé se sitúa de media entre 2800-3100 gramos y su longitud ronda los 47-50 cm. Sus encías se están endureciendo y su piel es cada vez más lisa y suave. En esta etapa, el reflejo de prensión de tu bebé está bastante desarrollado, lo que constituye un indicador importante del correcto funcionamiento de su sistema nervioso. El reflejo de prensión se manifiesta especialmente en las manos y los pies y es una reacción involuntaria ante los estímulos. Este movimiento, que aparece antes del nacimiento, permanece activo durante los dos primeros meses después de nacer y luego se debilita gradualmente para dar paso a la prensión consciente. Curiosamente, el reflejo de prensión plantar persiste durante más tiempo que el de las manos, y su transición al movimiento voluntario puede prolongarse hasta el mes 6.', baby_development_pt = 'Esta semana, o peso do seu bebé situa-se, em média, entre 2800-3100 gramas e o seu comprimento ronda os 47-50 cm. As gengivas estão a ficar mais firmes e a pele cada vez mais lisa e macia. Nesta fase, o reflexo de preensão do seu bebé está bastante desenvolvido, o que é um indicador importante de que o sistema nervoso está a funcionar corretamente. O reflexo de preensão é particularmente evidente nas mãos e nos pés e constitui uma reação involuntária a estímulos. Este movimento, que se forma antes do nascimento, mantém-se ativo durante os primeiros dois meses após o parto. Depois, enfraquece gradualmente e dá lugar à preensão consciente. Curiosamente, o reflexo de preensão plantar persiste durante mais tempo nos pés do que nas mãos, e a sua transição para um movimento voluntário pode prolongar-se até ao 6.º mês.', baby_development_vi = 'Tuần này, cân nặng trung bình của bé nằm trong khoảng 2800-3100 gram và chiều dài khoảng 47-50 cm. Nướu của bé đang cứng cáp hơn, còn làn da ngày càng mịn màng và mềm mại. Ở giai đoạn này, phản xạ cầm nắm của bé đã phát triển khá tốt, đây là một dấu hiệu quan trọng cho thấy hệ thần kinh đang hoạt động bình thường. Phản xạ cầm nắm đặc biệt rõ ở bàn tay và bàn chân, đồng thời là phản ứng không chủ ý trước các kích thích. Cử động này hình thành trước khi chào đời, tiếp tục hoạt động trong hai tháng đầu sau sinh rồi dần yếu đi để nhường chỗ cho động tác cầm nắm có ý thức. Điều thú vị là phản xạ nắm ở lòng bàn chân kéo dài lâu hơn ở bàn tay và quá trình chuyển sang vận động có chủ ý có thể tiếp diễn đến tháng thứ 6.', baby_development_hi = 'इस सप्ताह आपके शिशु का औसत वज़न 2800-3100 ग्राम के बीच और लंबाई लगभग 47-50 सेमी होती है। उनके मसूड़े मज़बूत हो रहे हैं और त्वचा धीरे-धीरे अधिक चिकनी और मुलायम बन रही है। इस चरण में आपके शिशु की पकड़ने की प्रतिवर्ती क्रिया काफ़ी विकसित होती है, जो उनके तंत्रिका तंत्र के सही ढंग से काम करने का एक प्रमुख संकेत है। यह प्रतिवर्ती क्रिया विशेष रूप से हाथों और पैरों में स्पष्ट दिखाई देती है और उत्तेजना के प्रति एक अनैच्छिक प्रतिक्रिया होती है। जन्म से पहले विकसित होने वाली यह गतिविधि जन्म के बाद पहले दो महीनों तक सक्रिय रहती है और फिर धीरे-धीरे कम होकर स्वेच्छा से पकड़ने की क्रिया में बदल जाती है। दिलचस्प बात यह है कि पैरों की तलवों से पकड़ने की प्रतिवर्ती क्रिया हाथों की तुलना में अधिक समय तक बनी रहती है और इसका स्वैच्छिक गतिविधि में बदलाव 6वें महीने तक जारी रह सकता है।', baby_development_ja = '今週の赤ちゃんの体重は平均2800-3100グラム、身長は約47-50 cmです。歯ぐきがしっかりし、皮膚も次第になめらかで柔らかくなっています。この段階では把握反射がかなり発達しており、神経系が正常に働いていることを示す重要な指標です。把握反射は特に手足に現れやすく、刺激に対する無意識の反応です。出生前に形成されるこの反射は、生後最初の二か月間は活発に見られ、その後徐々に弱まり、意識的につかむ動作へと移行します。興味深いことに、足の足底把握反射は手よりも長く残り、随意運動への移行は生後6か月目まで続くことがあります。', baby_development_ko = '이번 주 아기의 평균 체중은 2800-3100그램, 키는 약 47-50cm예요. 잇몸은 단단해지고 피부는 점점 더 매끄럽고 부드러워져요. 이 시기에는 아기의 잡기 반사가 상당히 발달하는데, 이는 신경계가 제대로 기능하고 있음을 보여주는 중요한 지표예요. 잡기 반사는 특히 손과 발에서 뚜렷하며 자극에 대한 불수의적 반응이에요. 출생 전에 형성된 이 반사는 출생 후 첫 두 달 동안 유지되다가 점차 약해지고 의식적인 잡기 동작으로 바뀌어요. 흥미롭게도 발바닥 잡기 반사는 손의 잡기 반사보다 오래 지속되며, 자발적인 움직임으로 전환되는 과정은 6개월까지 이어질 수 있어요.', baby_development_pl = 'W tym tygodniu Twoje dziecko waży średnio 2800-3100 gramów i mierzy około 47-50 cm. Jego dziąsła stają się twardsze, a skóra coraz gładsza i bardziej miękka. Na tym etapie odruch chwytny Twojego dziecka jest już dobrze rozwinięty, co stanowi ważny wskaźnik prawidłowego funkcjonowania układu nerwowego. Odruch ten jest szczególnie wyraźny w dłoniach i stopach i stanowi mimowolną reakcję na bodźce. Pojawia się jeszcze przed narodzinami i pozostaje aktywny przez pierwsze dwa miesiące po porodzie, a następnie stopniowo słabnie, ustępując miejsca świadomemu chwytaniu. Co ciekawe, podeszwowy odruch chwytny utrzymuje się dłużej w stopach niż w dłoniach, a jego przechodzenie w ruch zależny od woli może trwać aż do 6. miesiąca.', baby_development_nl = 'Deze week weegt je baby gemiddeld 2800-3100 gram en is je baby ongeveer 47-50 cm lang. Het tandvlees wordt steviger en de huid steeds gladder en zachter. In deze fase is de grijpreflex van je baby al goed ontwikkeld. Dit is een belangrijke aanwijzing dat het zenuwstelsel goed werkt. De grijpreflex is vooral duidelijk aanwezig in de handen en voeten en is een onbewuste reactie op prikkels. Deze reflex ontstaat al vóór de geboorte en blijft actief tijdens de eerste twee maanden na de geboorte. Daarna neemt hij geleidelijk af en maakt hij plaats voor bewust grijpen. Opvallend is dat de voetzoolgrijpreflex langer blijft bestaan dan de grijpreflex in de handen. De overgang naar bewuste bewegingen kan tot de 6e maand duren.', baby_development_sv = 'Den här veckan väger ditt barn i genomsnitt mellan 2800–3100 gram och är omkring 47–50 cm långt. Tandköttet blir fastare och huden allt slätare och mjukare. I det här skedet är ditt barns gripreflex välutvecklad, vilket är ett viktigt tecken på att nervsystemet fungerar som det ska. Gripreflexen är särskilt tydlig i händer och fötter och är en ofrivillig reaktion på beröring. Reflexen utvecklas före födseln och är aktiv under de första två månaderna efter födseln. Därefter försvagas den gradvis och ersätts av medvetna griprörelser. Intressant nog finns gripreflexen i fotsulan kvar längre än i händerna, och övergången till viljestyrda rörelser kan pågå fram till den 6:e månaden.' WHERE id = 'cca07f51-052d-4eba-bb6f-e780658e5cc2' AND md5(coalesce(baby_development,'')) = 'f5fe366916f7904d24ca6edba33d402c' AND md5(coalesce(baby_development_en,'')) = 'f2138467ca406df28c00dbc4de435bdc' AND md5(coalesce(baby_development_ru,'')) = 'fbd05e9fdd3e3ca3ce133f74e7d1eff7' AND md5(coalesce(baby_development_tr,'')) = '947e79060851b4b0b3f93add455ca7a0' AND md5(coalesce(baby_development_kk,'')) = '1cfd909d07ad625a6b7d42a8c0285567' AND md5(coalesce(baby_development_de,'')) = '0d31d1add404e825e980da0837ea91be' AND md5(coalesce(baby_development_ar,'')) = '516907248491406fe8f4499add328df4' AND md5(coalesce(baby_development_uz,'')) = '9040d2b1e2b31934390041075a99bd9b' AND md5(coalesce(baby_development_ka,'')) = 'bf6d92e360a2d4489bcd7109c66828c9' AND md5(coalesce(baby_development_zh,'')) = '7411ea9aa117ae56eb4c5d951cf7c50e' AND md5(coalesce(baby_development_id,'')) = 'a647775871ed203c386d300b2ceada90' AND md5(coalesce(baby_development_fr,'')) = 'd8887d276f2a61ec4218c5224bb07948' AND md5(coalesce(baby_development_es,'')) = '328920da60c77956d6063102ce3f5220' AND md5(coalesce(baby_development_pt,'')) = '786db79a5e73d1d70286f22f2d240f3f' AND md5(coalesce(baby_development_vi,'')) = '5fc924e8a470e58b94e90da39a655698' AND md5(coalesce(baby_development_hi,'')) = '231d6200f3468d2eac2736498c7bd700' AND md5(coalesce(baby_development_ja,'')) = 'b96f11bf4d3ff1569cfe542f108058df' AND md5(coalesce(baby_development_ko,'')) = '71ed3ed85c5d207d6f00adf0d8fadd93' AND md5(coalesce(baby_development_pl,'')) = '971431e3efad8fd79bf0db75376f67fe' AND md5(coalesce(baby_development_nl,'')) = 'c441eaeff9ce3081dd75f70d50522d0c' AND md5(coalesce(baby_development_sv,'')) = '29b7a1a96b7603f94067b8d4bbfd41f4';
UPDATE public.pregnancy_daily_content SET baby_development = 'Körpənizin çəkisi bu həftə orta hesabla 2900-3200 qram, boyu isə 48-50 sm aralığındadır. Ağciyərlərdə tənəffüsü təmin edən xüsusi maddə- surfaktantın istehsalı tamamlandığı üçün o, artıq doğulduğu andan etibarən heç bir kömək olmadan sərbəst nəfəs ala biləcək vəziyyətdədir.;;;
Körpəniz böyüdüyü və uşaqlıqda yeri daraldığı üçün hərəkətləri əvvəlki həftələrə nisbətən bir qədər azala bilər, lakin bu hərəkətlər daha sərt hiss olunur. Bu vəziyyət 37-ci həftədən etibarən normal sayılsa da, uzun müddət hərəkət hiss etməsəniz, həkiminizlə məsləhətləşməyiniz yaxşı olar. Eyni zamanda, körpə böyüdükcə uşaqlıqdakı suyun miqdarı da bir qədər azalır. Bu, adətən normaldır, lakin suyun miqdarı körpə üçün risk yaradacaq səviyyəyə düşərsə, həkiminiz sizi nəzarət üçün xəstəxanaya yerləşdirə bilər.', baby_development_en = 'This week, your baby''s weight averages between 2900-3200 grams, and their length is around 48-50 cm. The production of surfactant, a special substance that enables breathing in the lungs, is now complete. This means your baby is ready to breathe freely without any assistance from the moment they are born. As your baby grows and space in the uterus becomes more limited, their movements might feel slightly less frequent compared to previous weeks, but they will be felt more intensely. While this is considered normal from 37 weeks onward, it''s always best to consult your doctor if you don''t feel movements for an extended period. At the same time, as the baby grows, the amount of amniotic fluid in the uterus naturally decreases a bit. This is usually normal, but if the fluid level drops to a point that could pose a risk to the baby, your doctor may admit you to the hospital for monitoring.', baby_development_ru = 'На этой неделе вес вашего малыша в среднем составляет 2900–3200 граммов, а рост 48–50 см. Поскольку в лёгких завершилась выработка особого вещества — сурфактанта, обеспечивающего дыхание, после рождения малыш уже сможет дышать самостоятельно, без посторонней помощи.;;;
Поскольку малыш растёт и места в матке становится всё меньше, его движения могут быть немного реже, чем в предыдущие недели, однако ощущаются они сильнее. Начиная с 37-й недели это считается нормальным, но, если вы долго не ощущаете движений малыша, лучше проконсультироваться с врачом. По мере роста малыша количество околоплодных вод также немного уменьшается. Обычно это нормально, но, если их объём снизится до уровня, представляющего риск для малыша, врач может госпитализировать вас для наблюдения.', baby_development_tr = 'Bebeğinizin ağırlığı bu hafta ortalama 2900-3200 gram, boyu ise 48-50 cm aralığındadır. Akciğerlerde solunumu sağlayan özel bir madde olan surfaktanın üretimi tamamlandığı için doğduğu andan itibaren herhangi bir yardıma ihtiyaç duymadan kendi başına nefes alabilecek durumdadır.;;;
Bebeğiniz büyüdüğü ve rahimdeki alanı daraldığı için hareketleri önceki haftalara göre biraz azalabilir; ancak bu hareketler daha güçlü hissedilir. Bu durum 37. haftadan itibaren normal kabul edilse de uzun süre hareket hissetmezseniz doktorunuza danışmanız iyi olur. Ayrıca bebeğiniz büyüdükçe rahimdeki amniyon sıvısının miktarı da bir miktar azalır. Bu genellikle normaldir; ancak sıvı miktarı bebek için risk oluşturacak düzeye düşerse doktorunuz takip amacıyla hastaneye yatmanızı isteyebilir.', baby_development_kk = 'Осы аптада бөпеңіздің салмағы орта есеппен 2900-3200 грамм, ал бойы 48-50 см аралығында болады. Өкпеде тыныс алуды қамтамасыз ететін арнайы зат — сурфактанттың түзілуі аяқталғандықтан, бөпеңіз туған сәттен бастап еш көмексіз өздігінен тыныс ала алатын деңгейге жетті.;;;
Бөпеңіз өскен сайын жатырдағы орын тарылатындықтан, оның қимылдары алдыңғы апталармен салыстырғанда азаюы мүмкін, алайда олар күштірек сезіледі. Бұл жағдай 37-ші аптадан бастап қалыпты саналғанымен, ұзақ уақыт бойы қимылын сезбесеңіз, дәрігеріңізбен кеңескен жөн. Сонымен қатар бөпе өскен сайын жатырдағы қағанақ суының мөлшері де аздап төмендейді. Бұл әдетте қалыпты, бірақ су мөлшері бөпеге қауіп төндіретін деңгейге дейін азайса, дәрігеріңіз бақылау үшін Сізді ауруханаға жатқызуы мүмкін.', baby_development_de = 'Das Gewicht deines Babys liegt diese Woche durchschnittlich zwischen 2900-3200 Gramm, seine Größe zwischen 48-50 cm. Da die Produktion des für die Atmung wichtigen Lungen-Surfactants abgeschlossen ist, kann es nach der Geburt voraussichtlich selbstständig und ohne Unterstützung atmen.;;;
Da dein Baby wächst und der Platz in der Gebärmutter enger wird, können seine Bewegungen im Vergleich zu den vergangenen Wochen etwas weniger werden. Dafür fühlen sie sich möglicherweise kräftiger an. Ab der 37. Woche gilt das als normal. Wenn du jedoch über längere Zeit keine Bewegungen spürst, solltest du deinen Arzt kontaktieren. Mit dem Wachstum des Babys nimmt auch die Fruchtwassermenge etwas ab. Das ist in der Regel normal. Sinkt sie jedoch auf ein Niveau, das für dein Baby riskant sein könnte, kann dein Arzt dich zur Überwachung ins Krankenhaus einweisen.', baby_development_ar = 'يتراوح وزن طفلكِ هذا الأسبوع في المتوسط بين 2900 و3200 غرام، وطوله بين 48 و50 سم. وبما أن إنتاج المادة الخاصة التي تساعد على التنفس في الرئتين، وهي السورفاكتانت، قد اكتمل، فقد أصبح قادرًا على التنفس تلقائيًا من دون مساعدة فور ولادته.;;;
نظرًا إلى نمو طفلكِ وضيق المساحة داخل الرحم، قد تقل حركاته قليلًا مقارنة بالأسابيع السابقة، لكنها تصبح أقوى وأكثر وضوحًا. يُعدّ هذا طبيعيًا ابتداءً من الأسبوع 37، لكن إذا لم تشعري بحركته مدة طويلة، فمن الأفضل استشارة طبيبكِ. كذلك، تقل كمية السائل الأمنيوسي في الرحم قليلًا مع نمو طفلكِ. ويكون ذلك طبيعيًا عادةً، ولكن إذا انخفضت كمية السائل إلى مستوى قد يشكّل خطرًا على طفلكِ، فقد يُدخلكِ طبيبكِ إلى المستشفى للمراقبة.', baby_development_uz = 'Bu haftada chaqalog‘ingizning vazni o‘rtacha 2900–3200 gramm, bo‘yi esa 48–50 sm atrofida. O‘pkada nafas olishni ta’minlaydigan maxsus modda — surfaktant ishlab chiqarilishi yakunlangani sababli u tug‘ilgan zahoti hech qanday yordamsiz mustaqil nafas ola oladigan holatga kelgan.;;;
Chaqalog‘ingiz kattalashib, bachadondagi joy toraygani sababli uning harakatlari oldingi haftalarga qaraganda biroz kamayishi mumkin, ammo ular kuchliroq seziladi. Bu holat 37-haftadan boshlab me’yoriy hisoblansa-da, uzoq vaqt davomida harakat sezmasangiz, shifokoringiz bilan maslahatlashganingiz ma’qul. Shu bilan birga, chaqaloq ulg‘aygani sari bachadondagi homila suvi miqdori ham biroz kamayadi. Bu odatda me’yoriy holat, ammo suv miqdori chaqaloq uchun xavf tug‘diradigan darajagacha kamaysa, shifokoringiz kuzatuv uchun sizni shifoxonaga yotqizishi mumkin.', baby_development_ka = 'ამ კვირაში თქვენი ბავშვის წონა საშუალოდ 2900-3200 გრამია, ხოლო სიგრძე 48-50 სმ-ის ფარგლებშია. რადგან ფილტვებში სუნთქვისთვის აუცილებელი სპეციალური ნივთიერების — სურფაქტანტის — გამომუშავება დასრულებულია, დაბადებისთანავე ის უკვე შეძლებს დამოუკიდებლად, ყოველგვარი დახმარების გარეშე სუნთქვას.;;;
რადგან ბავშვი გაიზარდა და საშვილოსნოში ადგილი შეუმცირდა, მისი მოძრაობები წინა კვირებთან შედარებით შეიძლება ოდნავ შემცირდეს, თუმცა უფრო ძლიერად იგრძნობა. მიუხედავად იმისა, რომ 37-ე კვირიდან ეს ნორმალურად ითვლება, თუ მოძრაობას დიდი ხნის განმავლობაში ვერ იგრძნობთ, უმჯობესია ექიმს მიმართოთ. ამასთანავე, ბავშვის ზრდასთან ერთად საშვილოსნოში სანაყოფე წყლების რაოდენობაც ოდნავ მცირდება. ეს, ჩვეულებრივ, ნორმალურია, თუმცა თუ წყლების რაოდენობა ბავშვისთვის სარისკო დონემდე შემცირდება, ექიმმა შეიძლება მეთვალყურეობისთვის საავადმყოფოში დაგაწვინოთ.', baby_development_zh = '本周，宝宝的平均体重约为2900-3200克，身长约为48-50厘米。帮助肺部进行呼吸的特殊物质——肺表面活性物质现已完成生成。这意味着宝宝从出生那一刻起，就已准备好在无需任何帮助的情况下自主呼吸。随着宝宝长大，子宫内的空间越来越有限，胎动可能会比前几周稍少一些，但你会感觉到胎动更有力。从孕37周起，这通常被视为正常现象；但如果长时间感觉不到胎动，最好及时咨询医生。与此同时，随着宝宝长大，子宫内的羊水量也会自然略有减少。这通常是正常的，但如果羊水量下降到可能危及宝宝的程度，医生可能会安排你住院观察。', baby_development_id = 'Minggu ini, berat bayi Anda rata-rata berkisar antara 2900-3200 gram, dengan panjang sekitar 48-50 cm. Produksi surfaktan, zat khusus yang memungkinkan paru-paru bernapas, kini telah selesai. Artinya, bayi Anda siap bernapas dengan bebas tanpa bantuan sejak lahir. Seiring pertumbuhan bayi dan semakin terbatasnya ruang di dalam rahim, gerakannya mungkin terasa sedikit lebih jarang dibandingkan minggu-minggu sebelumnya, tetapi akan terasa lebih kuat. Meskipun hal ini dianggap normal mulai usia 37 minggu, sebaiknya selalu konsultasikan dengan dokter jika Anda tidak merasakan gerakan dalam waktu lama. Pada saat yang sama, seiring pertumbuhan bayi, jumlah cairan ketuban di dalam rahim secara alami sedikit berkurang. Hal ini biasanya normal, tetapi jika jumlah cairan menurun hingga dapat membahayakan bayi, dokter mungkin akan merawat Anda di rumah sakit untuk pemantauan.', baby_development_fr = 'Cette semaine, votre bébé pèse en moyenne entre 2900-3200 grammes et mesure environ 48-50 cm. La production de surfactant, une substance particulière qui permet aux poumons de respirer, est maintenant terminée. Cela signifie que votre bébé est prêt à respirer librement et sans assistance dès sa naissance. À mesure qu’il grandit et que l’espace disponible dans l’utérus diminue, ses mouvements peuvent vous sembler un peu moins fréquents que les semaines précédentes, mais vous les ressentirez plus intensément. Bien que cela soit considéré comme normal à partir de 37 semaines, il est toujours préférable de consulter votre médecin si vous ne sentez aucun mouvement pendant une période prolongée. Parallèlement, à mesure que votre bébé grandit, la quantité de liquide amniotique présente dans l’utérus diminue naturellement un peu. C’est généralement normal, mais si le niveau de liquide baisse au point de présenter un risque pour votre bébé, votre médecin pourra vous hospitaliser afin de le surveiller.', baby_development_es = 'Esta semana, tu bebé pesa de media entre 2900-3200 gramos y mide alrededor de 48-50 cm. La producción de surfactante, una sustancia especial que permite respirar a los pulmones, ya se ha completado. Esto significa que tu bebé está preparado para respirar libremente y sin ayuda desde el momento de su nacimiento. A medida que crece y disminuye el espacio disponible en el útero, puede que notes sus movimientos con algo menos de frecuencia que en semanas anteriores, pero los sentirás con mayor intensidad. Aunque esto se considera normal a partir de las 37 semanas, siempre es mejor consultar con tu médico si no notas movimientos durante un periodo prolongado. Al mismo tiempo, a medida que el bebé crece, la cantidad de líquido amniótico en el útero disminuye un poco de forma natural. Esto suele ser normal, pero, si el nivel de líquido desciende hasta un punto que pueda suponer un riesgo para el bebé, tu médico podría ingresarte en el hospital para mantenerte bajo observación.', baby_development_pt = 'Esta semana, o peso do seu bebé situa-se, em média, entre 2900-3200 gramas, e o seu comprimento é de cerca de 48-50 cm. A produção de surfactante, uma substância especial que permite a respiração nos pulmões, está agora concluída. Isto significa que o seu bebé está preparado para respirar livremente, sem qualquer assistência, a partir do momento em que nascer. À medida que o bebé cresce e o espaço no útero se torna mais limitado, os seus movimentos podem parecer um pouco menos frequentes do que nas semanas anteriores, mas serão sentidos com maior intensidade. Embora isto seja considerado normal a partir das 37 semanas, é sempre aconselhável consultar o seu médico se não sentir movimentos durante um período prolongado. Ao mesmo tempo, à medida que o bebé cresce, a quantidade de líquido amniótico no útero diminui naturalmente um pouco. Geralmente, isto é normal, mas, se o nível do líquido baixar ao ponto de poder representar um risco para o bebé, o seu médico poderá interná-la no hospital para vigilância.', baby_development_vi = 'Tuần này, bé có cân nặng trung bình khoảng 2900-3200 gam và chiều dài khoảng 48-50 cm. Quá trình sản xuất surfactant, một chất đặc biệt giúp phổi thực hiện chức năng hô hấp, giờ đã hoàn tất. Điều này có nghĩa là bé đã sẵn sàng tự thở mà không cần hỗ trợ ngay từ khi chào đời. Khi bé lớn lên và không gian trong tử cung trở nên hạn chế hơn, bạn có thể cảm thấy bé cử động ít thường xuyên hơn một chút so với những tuần trước, nhưng mỗi cử động sẽ rõ và mạnh hơn. Điều này được xem là bình thường từ tuần thứ 37 trở đi, nhưng nếu không cảm nhận được cử động của bé trong thời gian dài, bạn vẫn nên tham khảo ý kiến bác sĩ. Đồng thời, khi bé lớn lên, lượng nước ối trong tử cung cũng giảm nhẹ một cách tự nhiên. Điều này thường là bình thường, nhưng nếu lượng nước ối giảm đến mức có thể gây nguy hiểm cho bé, bác sĩ có thể yêu cầu bạn nhập viện để theo dõi.', baby_development_hi = 'इस सप्ताह आपके शिशु का औसत वजन 2900-3200 ग्राम और लंबाई लगभग 48-50 cm होती है। फेफड़ों में सांस लेना संभव बनाने वाले विशेष पदार्थ सर्फैक्टेंट का निर्माण अब पूरा हो चुका है। इसका मतलब है कि आपका शिशु जन्म लेते ही बिना किसी सहायता के स्वतंत्र रूप से सांस लेने के लिए तैयार है। जैसे-जैसे आपका शिशु बढ़ता है और गर्भाशय में जगह कम होती जाती है, उसकी हलचल पिछले सप्ताहों की तुलना में थोड़ी कम महसूस हो सकती है, लेकिन वह अधिक तेज महसूस होगी। 37 सप्ताह के बाद इसे सामान्य माना जाता है, फिर भी अगर आपको लंबे समय तक कोई हलचल महसूस न हो, तो डॉक्टर से सलाह लेना सबसे अच्छा है। साथ ही, शिशु के बढ़ने के कारण गर्भाशय में एम्नियोटिक द्रव की मात्रा स्वाभाविक रूप से थोड़ी कम हो जाती है। आमतौर पर यह सामान्य है, लेकिन अगर द्रव का स्तर इतना कम हो जाए कि शिशु के लिए जोखिम पैदा हो सकता हो, तो आपके डॉक्टर निगरानी के लिए आपको अस्पताल में भर्ती कर सकते हैं।', baby_development_ja = '今週の赤ちゃんの体重は平均2900-3200グラム、身長は約48-50 cmです。肺で呼吸を可能にする特殊な物質、サーファクタントの産生が完了しています。つまり赤ちゃんは、生まれた瞬間から補助なしで自由に呼吸する準備ができています。赤ちゃんが成長し、子宮内のスペースがさらに狭くなるため、以前の週より動く回数がやや少なく感じられることがありますが、一回一回の動きはより強く感じられます。妊娠37週以降は正常とされていますが、長時間動きを感じない場合は、必ず医師に相談してください。同時に、赤ちゃんの成長に伴い、子宮内の羊水量も自然に少し減少します。通常は問題ありませんが、赤ちゃんに危険が及ぶ可能性があるほど羊水量が減った場合は、経過観察のため入院となることがあります。', baby_development_ko = '이번 주 아기의 평균 체중은 2900-3200그램, 키는 약 48-50cm예요. 폐에서 호흡을 가능하게 하는 특수 물질인 폐표면활성제의 생성도 완료돼요. 이는 아기가 태어나는 순간부터 도움 없이 스스로 숨 쉴 준비가 되었다는 뜻이에요. 아기가 자라면서 자궁 안의 공간이 줄어들기 때문에 이전보다 움직임이 조금 덜 자주 느껴질 수 있지만, 한 번의 움직임은 더 강하게 느껴질 수 있어요. 37주 이후에는 정상적인 변화로 보지만, 오랫동안 태동이 느껴지지 않는다면 반드시 의사와 상담하세요. 동시에 아기가 자라면서 자궁 안의 양수량도 자연스럽게 조금 줄어들어요. 대부분 정상적인 현상이지만, 양수량이 아기에게 위험할 정도로 감소하면 의사가 경과를 관찰하기 위해 입원을 권할 수 있어요.', baby_development_pl = 'W tym tygodniu Twoje dziecko waży średnio od 2900 do 3200 gramów, a jego długość wynosi około 48–50 cm. Produkcja surfaktantu, specjalnej substancji umożliwiającej oddychanie płucami, jest już zakończona. Oznacza to, że od chwili narodzin dziecko jest gotowe do swobodnego oddychania bez jakiejkolwiek pomocy. W miarę jak dziecko rośnie i ma coraz mniej miejsca w macicy, jego ruchy mogą być nieco rzadsze niż w poprzednich tygodniach, ale będą wyraźniej odczuwalne. Od 37. tygodnia uważa się to za normalne, jednak jeśli przez dłuższy czas nie czujesz ruchów dziecka, najlepiej skonsultować się z lekarzem. Jednocześnie wraz ze wzrostem dziecka ilość płynu owodniowego w macicy w naturalny sposób nieco się zmniejsza. Zazwyczaj jest to normalne, ale jeśli poziom płynu spadnie na tyle, że może stanowić zagrożenie dla dziecka, lekarz może skierować Cię do szpitala na obserwację.', baby_development_nl = 'Deze week weegt je baby gemiddeld tussen de 2900-3200 gram en is die ongeveer 48-50 cm lang. De aanmaak van surfactant, een speciale stof die ademhalen met de longen mogelijk maakt, is nu voltooid. Dit betekent dat je baby vanaf de geboorte zelfstandig kan ademen zonder hulp. Naarmate je baby groeit en de ruimte in de baarmoeder kleiner wordt, voel je de bewegingen mogelijk iets minder vaak dan in eerdere weken, maar wel krachtiger. Hoewel dit vanaf 37 weken als normaal wordt beschouwd, kun je het beste altijd contact opnemen met je arts als je langere tijd geen bewegingen voelt. Tegelijkertijd neemt de hoeveelheid vruchtwater in de baarmoeder door de groei van je baby van nature wat af. Dit is meestal normaal, maar als het vruchtwater zo sterk afneemt dat dit een risico voor je baby kan vormen, kan je arts je ter observatie in het ziekenhuis opnemen.', baby_development_sv = 'Den här veckan väger ditt barn i genomsnitt 2900-3200 gram och är omkring 48-50 cm långt. Produktionen av surfaktant, ett särskilt ämne som gör det möjligt att andas med lungorna, är nu slutförd. Det innebär att barnet är redo att andas fritt utan hjälp från det ögonblick det föds. När barnet växer och utrymmet i livmodern minskar kan rörelserna kännas något mer sällan än under tidigare veckor, men samtidigt bli kraftigare. Detta anses normalt från och med 37 veckor, men kontakta alltid din läkare om du inte känner några rörelser under en längre tid. När barnet växer minskar samtidigt mängden fostervatten i livmodern naturligt något. Det är oftast normalt, men om mängden blir så liten att det kan innebära en risk för barnet kan din läkare lägga in dig på sjukhus för övervakning.' WHERE id = '9bb1bfbd-4fc9-4fdd-8462-715ca0719a8a' AND md5(coalesce(baby_development,'')) = '41d74b40908dc196494651334d007a01' AND md5(coalesce(baby_development_en,'')) = '5886e89c23f8907750ea6afa0248a07b' AND md5(coalesce(baby_development_ru,'')) = 'c3b2b76aa1d741542a920b69a9ab5015' AND md5(coalesce(baby_development_tr,'')) = '2d9f7c7b7e7f3bbce62f9459be420601' AND md5(coalesce(baby_development_kk,'')) = '0268c6aaaf70bf66b01df70f1cf699fc' AND md5(coalesce(baby_development_de,'')) = '71bcb8003c5dc71a43e207f78a31ddd4' AND md5(coalesce(baby_development_ar,'')) = 'c021f4fe52c81385db35be7154c1322a' AND md5(coalesce(baby_development_uz,'')) = 'd40731cc678df316e7a31cf3988f30a1' AND md5(coalesce(baby_development_ka,'')) = '37ca6ad0620f479844247281aa24f6e6' AND md5(coalesce(baby_development_zh,'')) = '73e01141f7c69926cbfbb5f0cfa9a50a' AND md5(coalesce(baby_development_id,'')) = '4253bf1bfae3b9a9ad34a718bfedc639' AND md5(coalesce(baby_development_fr,'')) = 'c502ef2425e5b188f2a8bf042b3d3d2d' AND md5(coalesce(baby_development_es,'')) = 'b2bcf706c52853e9bcf502420896ddf3' AND md5(coalesce(baby_development_pt,'')) = '22bf00776d1e611b50369770cf508415' AND md5(coalesce(baby_development_vi,'')) = '13a69d843c857cd5c36527c403dd62cd' AND md5(coalesce(baby_development_hi,'')) = '261fe2f14b21f2887e857cf4088d42a3' AND md5(coalesce(baby_development_ja,'')) = '3be6c408f42f8ae836190b42fd6d06e0' AND md5(coalesce(baby_development_ko,'')) = '1fce80bd8fc3117ccfa46bc34a8695ad' AND md5(coalesce(baby_development_pl,'')) = 'bce2c29792fd8cb9dc1b4d047a1a304a' AND md5(coalesce(baby_development_nl,'')) = '188dea239284c2416020e9111d404c46' AND md5(coalesce(baby_development_sv,'')) = 'b067917bbe30f6ce093637e90fbcb114';
UPDATE public.pregnancy_daily_content SET baby_message = 'Mən bir pazı boydayam. Mən artıq böyük bir körpəyəm. Yerim o qədər dardır ki, təpik atmaq əvəzinə ancaq gərilirəm. Sən mənim ayağımın dabanını qarnının üstündən görə bilərsən. Mənə toxun!', baby_message_en = 'I''m the size of a bunch of Swiss chard. I''m already a big baby. My space is so tight that instead of kicking, I''m mostly stretching now. You might even see the outline of my heel pushing against your belly. Touch me!', baby_message_ru = 'Я размером с пучок мангольда. Я уже большой малыш. Здесь так тесно, что вместо ударов ножками я могу только потягиваться. Вы даже можете увидеть очертания моей пяточки на животе. Прикоснитесь ко мне!', baby_message_tr = 'Ben bir pazı büyüklüğündeyim. Artık büyük bir bebeğim. Yerim o kadar dar ki tekme atmak yerine sadece gerinebiliyorum. Ayağımın topuğunu karnının üzerinden görebilirsin. Bana dokun!', baby_message_kk = 'Менің көлемім мангольдтай. Мен енді үлкен бөпемін. Мұнда орынның тар болғаны сонша, тебудің орнына тек керіле аламын. Сіз менің өкшемді ішіңіздің сыртынан көре аласыз. Маған қолыңызды тигізіңіз!', baby_message_de = 'Ich bin so groß wie ein Mangold. Ich bin jetzt schon ein großes Baby. Es ist hier so eng, dass ich nicht mehr richtig treten kann und mich stattdessen nur noch strecke. Vielleicht kannst du sogar meine Ferse durch deinen Bauch erkennen. Berühr mich!', baby_message_ar = 'أصبح حجمي بحجم حزمة سلق. لقد أصبحت طفلًا كبيرًا. المكان ضيق جدًا لدرجة أنني لم أعد أستطيع الركل، بل أتمدد فقط. قد تتمكنين من رؤية كعب قدمي بارزًا عبر بطنكِ. المسيني!', baby_message_uz = 'Men mangolddek kattaman. Endi men katta chaqaloqman. Joyim shu qadar torki, tepish o‘rniga faqat cho‘zila olaman. Sen hatto oyog‘imning tovonini qorning ustidan ko‘rishing mumkin. Menga tegib ko‘r!', baby_message_ka = 'მე მანგოლდის ზომის ვარ. უკვე დიდი ბავშვი ვარ. აქ იმდენად ცოტა ადგილი მაქვს, რომ ფეხის დარტყმის ნაცვლად მხოლოდ ვიჭიმები. შეიძლება ჩემი ქუსლიც კი დაინახო შენს მუცელზე. შემეხე!', baby_message_zh = '我已经有一棵瑞士甜菜那么大了。我现在是个大宝宝啦。这里的空间越来越挤，所以相比踢腿，我现在更多是在伸展身体。你甚至可能会看到我的脚后跟顶着肚皮时露出的轮廓。摸摸我吧！', baby_message_id = 'Besarku sekarang seukuran sawi Swiss. Aku sudah menjadi bayi yang besar. Ruang gerakku begitu sempit sehingga sekarang aku lebih sering meregangkan tubuh daripada menendang. Anda bahkan mungkin melihat bentuk tumitku saat mendorong perut Anda. Sentuh aku!', baby_message_fr = 'J''ai la taille d''une blette. Je suis déjà un grand bébé. Je suis tellement à l''étroit qu''au lieu de donner des coups, je m''étire surtout maintenant. Vous pourriez même voir le contour de mon talon appuyer contre votre ventre. Touchez-moi !', baby_message_es = 'Tengo el tamaño de una acelga. Ya soy un bebé grande. Tengo tan poco espacio que ahora, en vez de dar patadas, sobre todo me estiro. Puede que incluso veas la forma de mi talón presionando tu barriga. ¡Tócame!', baby_message_pt = 'Sou do tamanho de uma acelga. Já sou um bebé grande. Tenho tão pouco espaço que, em vez de dar pontapés, agora passo a maior parte do tempo a espreguiçar-me. Talvez até consigas ver o contorno do meu calcanhar a empurrar a tua barriga. Toca-me!', baby_message_vi = 'Con lớn bằng một bó cải cầu vồng rồi. Giờ con đã là một em bé lớn. Không gian chật đến mức thay vì đạp, con chủ yếu duỗi người. Mẹ thậm chí có thể thấy đường nét gót chân con nhô lên trên bụng. Chạm vào con nhé!', baby_message_hi = 'मैं एक स्विस चार्ड जितना/जितनी हो गया/गई हूँ। अब मैं बड़ा बच्चा हूँ। मेरे पास इतनी कम जगह है कि अब लात मारने के बजाय मैं ज़्यादातर अपने शरीर को खींचता/खींचती हूँ। आपको अपने पेट पर मेरी एड़ी की उभरी हुई आकृति भी दिख सकती है। मुझे छूकर देखिए!', baby_message_ja = 'スイスチャードくらいの大きさだよ。もう大きな赤ちゃんなんだ。おなかの中がとても狭いから、今は蹴るよりも体を伸ばすことが多いよ。ママのおなかを押す、ぼくのかかとの形が見えることもあるかも。触ってみてね！', baby_message_ko = '저는 근대만 해요. 벌써 제법 큰 아기예요. 공간이 너무 좁아서 이제 발로 차기보다는 주로 몸을 쭉 펴요. 엄마 배를 밀어내는 제 발뒤꿈치 모양이 보일 때도 있을 거예요. 저를 만져 주세요!', baby_message_pl = 'Mam wielkość boćwiny. Jestem już dużym dzieckiem. Mam tak mało miejsca, że zamiast kopać, teraz głównie się przeciągam. Możesz nawet zobaczyć zarys mojej pięty wypychającej Twój brzuch. Dotknij mnie!', baby_message_nl = 'Ik ben zo groot als een snijbiet. Ik ben al een grote baby. Ik heb zo weinig ruimte dat ik nu vooral rek en strek in plaats van te schoppen. Misschien zie je zelfs de omtrek van mijn hiel tegen je buik duwen. Raak me maar aan!', baby_message_sv = 'Jag är stor som en mangold. Jag är redan en stor bebis. Det är så trångt här inne att jag mest sträcker på mig i stället för att sparka. Du kanske till och med kan se konturen av min häl när jag trycker den mot din mage. Känn på mig!' WHERE id = '01bba5ce-c513-4ffc-af67-bbc602f0ece1' AND md5(coalesce(baby_message,'')) = 'fa9b66bfcf0f7c8a4f9bdac06a3de2fd' AND md5(coalesce(baby_message_en,'')) = 'd8426cf7dac8d82895926d15818601f9' AND md5(coalesce(baby_message_ru,'')) = 'e8f7543c3f80e39693299a56c979e747' AND md5(coalesce(baby_message_tr,'')) = '07929b46ec5a28f469025fe61da50056' AND md5(coalesce(baby_message_kk,'')) = 'f6100aa20bc6a3bd6ee7fc13c21b9ce8' AND md5(coalesce(baby_message_de,'')) = 'ca769822ab79cc03b2f1aea8ebbb08af' AND md5(coalesce(baby_message_ar,'')) = '70749b6dbc67fa87ac61473c4f96cf1d' AND md5(coalesce(baby_message_uz,'')) = '5104dc223a92f08a6b88a3aa0f12bdb4' AND md5(coalesce(baby_message_ka,'')) = '09a7de5ee9494aeb885fae43924c8f3f' AND md5(coalesce(baby_message_zh,'')) = 'a5f61eb218bfe1d166fd72de8a55a66b' AND md5(coalesce(baby_message_id,'')) = 'cd9c5894456065919108897b13d21579' AND md5(coalesce(baby_message_fr,'')) = '43f8509df659bdde767dd600b6b7613a' AND md5(coalesce(baby_message_es,'')) = '6d4d14a70476f93ccb9b69b0562b5a96' AND md5(coalesce(baby_message_pt,'')) = 'fefaa78dbc1692e095e0c9cf634e48ef' AND md5(coalesce(baby_message_vi,'')) = '4f20dcccaea24f96ba2f345c7f73d314' AND md5(coalesce(baby_message_hi,'')) = 'ac037dba9982b325cb3e666743699376' AND md5(coalesce(baby_message_ja,'')) = 'd51a04e797c62fb60a5f3101551dc436' AND md5(coalesce(baby_message_ko,'')) = 'cd6c4710229c78e9141f20221ed96280' AND md5(coalesce(baby_message_pl,'')) = '2a635736b8e64d6d2d5d5cc13632199b' AND md5(coalesce(baby_message_nl,'')) = 'd8785f97065f8f93a7b32895fce50906' AND md5(coalesce(baby_message_sv,'')) = 'af99a17c4055367394d93a567f45797c';
UPDATE public.pregnancy_daily_content SET body_changes = '🌿 Mən bir pırasa boydayam! Həkimlər deyir ki, 39-cu həftə doğuş üçün ən ideal vaxtdır. Beynim, ciyərlərim, qaraciyərim – hər şeyim tam hazırdır. Artıq bəhanəm yoxdur, sadəcə qapının açılmasını gözləyirəm!', body_changes_ru = '🌿 Я размером с лук-порей! Врачи говорят, что 39-я неделя — идеальное время для родов. Мой мозг, лёгкие, печень — всё полностью готово. У меня больше нет оправданий, я лишь жду, когда откроется дверь!', body_changes_tr = '🌿 Ben bir pırasa büyüklüğündeyim! Doktorlar, 39. haftanın doğum için en ideal zaman olduğunu söylüyor. Beynim, akciğerlerim, karaciğerim – her şeyim tamamen hazır. Artık bahanem yok, yalnızca kapının açılmasını bekliyorum!', body_changes_kk = '🌿 Менің көлемім порей пиязындай! Дәрігерлер 39-апта босану үшін ең қолайлы уақыт дейді. Миым, өкпем, бауырым — бәрі толық дайын. Енді сылтауым жоқ, есіктің ашылуын ғана күтіп отырмын!', body_changes_de = '🌿 Ich bin so groß wie eine Lauchstange! Ärztinnen und Ärzte sagen, dass die 39. Woche der ideale Zeitpunkt für die Geburt ist. Mein Gehirn, meine Lunge, meine Leber – alles ist vollständig bereit. Jetzt habe ich keine Ausrede mehr und warte nur noch darauf, dass sich die Tür öffnet!', body_changes_ar = '🌿 أنا بحجم ساق كراث! يقول الأطباء إن الأسبوع 39 هو الوقت المثالي للولادة. دماغي ورئتاي وكبدي – كل شيء لديّ جاهز تمامًا. لم يعد لديّ أي عذر، أنا فقط أنتظر أن يُفتح الباب!', body_changes_uz = '🌿 Men porey piyozdekman! Shifokorlarning aytishicha, 39-hafta tug‘ruq uchun eng maqbul vaqt. Miyam, o‘pkam, jigarim – hammasi to‘liq tayyor. Endi hech qanday bahonam yo‘q, faqat eshik ochilishini kutyapman!', body_changes_ka = '🌿 მე პრასის ზომის ვარ! ექიმები ამბობენ, რომ 39-ე კვირა მშობიარობისთვის ყველაზე ხელსაყრელი დროა. ჩემი ტვინი, ფილტვები, ღვიძლი — ყველაფერი სრულად მზადაა. გასამართლებელი მიზეზი აღარ მაქვს, უბრალოდ კარის გაღებას ველოდები!', body_changes_zh = '🌿 我已经有一根韭葱那么大啦！医生说，第39周是最理想的出生时间。我的大脑、肺、肝脏——一切都已发育成熟。现在再也没有借口啦，只等大门开启！', body_changes_id = '🌿 Ukuranku sebesar bawang prei! Dokter mengatakan bahwa minggu ke-39 adalah waktu yang paling ideal untuk lahir. Otak, paru-paru, dan hatiku—semuanya sudah benar-benar siap. Aku tidak punya alasan lagi, tinggal menunggu pintunya terbuka!', body_changes_fr = '🌿 J’ai la taille d’un poireau ! Les médecins disent que la 39e semaine est le moment idéal pour l’accouchement. Mon cerveau, mes poumons, mon foie : tout est prêt. Je n’ai désormais plus aucune excuse, j’attends simplement que la porte s’ouvre !', body_changes_es = '🌿 ¡Tengo el tamaño de un puerro! Los médicos dicen que la semana 39 es el momento ideal para nacer. Mi cerebro, mis pulmones, mi hígado… todo está completamente preparado. Ya no tengo excusas, ¡solo estoy esperando a que se abra la puerta!', body_changes_pt = '🌿 Sou do tamanho de um alho-francês! Os médicos dizem que a semana 39 é a altura ideal para o parto. O meu cérebro, os meus pulmões, o meu fígado — está tudo completamente pronto. Já não tenho desculpas, só estou à espera que a porta se abra!', body_changes_vi = '🌿 Mình đã lớn bằng một cây tỏi tây rồi! Các bác sĩ nói rằng tuần thứ 39 là thời điểm lý tưởng nhất để chào đời. Não, phổi, gan của mình – mọi thứ đều đã hoàn thiện. Giờ mình không còn lý do để trì hoãn nữa, chỉ đang chờ cánh cửa mở ra thôi!', body_changes_hi = '🌿 मैं एक लीक जितना हूँ! डॉक्टरों का कहना है कि 39वाँ सप्ताह जन्म के लिए सबसे उपयुक्त समय है। मेरा मस्तिष्क, मेरे फेफड़े, मेरा लिवर—सब कुछ पूरी तरह तैयार है। अब मेरे पास कोई बहाना नहीं है, बस दरवाज़ा खुलने का इंतज़ार है!', body_changes_ja = '🌿 私はリーキくらいの大きさだよ！お医者さんによると、第39週が出産に最も理想的な時期なんだって。脳も肺も肝臓も、全部すっかり準備できているよ。もう言い訳はなし。あとは扉が開くのを待つだけ！', body_changes_ko = '🌿 나는 리크만 해요! 의사 선생님들은 39주가 출산하기에 가장 좋은 시기라고 해요. 뇌도, 폐도, 간도 모두 완전히 준비됐어요. 이제 핑계 댈 것도 없이 문이 열리기만 기다리고 있어요!', body_changes_pl = '🌿 Mam wielkość pora! Lekarze mówią, że 39. tydzień to najlepszy czas na poród. Mój mózg, płuca i wątroba – wszystko jest już w pełni gotowe. Nie mam już żadnych wymówek, czekam tylko, aż otworzą się drzwi!', body_changes_nl = '🌿 Ik ben zo groot als een prei! Artsen zeggen dat week 39 het ideale moment is om geboren te worden. Mijn hersenen, longen en lever – alles is er helemaal klaar voor. Ik heb geen excuses meer en wacht alleen nog tot de deur opengaat!', body_changes_sv = '🌿 Jag är lika stor som en purjolök! Läkarna säger att vecka 39 är den bästa tiden för förlossningen. Min hjärna, mina lungor och min lever – allt är helt redo. Nu har jag inga ursäkter kvar, utan väntar bara på att dörren ska öppnas!' WHERE id = '37c59540-1af3-42e8-95c8-2c53b72f2a9f' AND md5(coalesce(body_changes,'')) = '9c5d0bb5c3137a9cfd7fd8d8d789bb11' AND md5(coalesce(body_changes_ru,'')) = '49a4ec51eccaad480225e492b1a73d02' AND md5(coalesce(body_changes_tr,'')) = 'c1bb06b1794c0a8ae3b8a232238cee8a' AND md5(coalesce(body_changes_kk,'')) = 'a879d2f14088c8fcdd950c835b028713' AND md5(coalesce(body_changes_de,'')) = 'ad9afbd20ec3a44c4b45fbac10182042' AND md5(coalesce(body_changes_ar,'')) = '7a1489cb5dbf7789913dc2533abaee73' AND md5(coalesce(body_changes_uz,'')) = '1494dd4fe3cc6d92d5ac35ae5d1ab55a' AND md5(coalesce(body_changes_ka,'')) = '30a20369e4433056f05b4a1f508b7e58' AND md5(coalesce(body_changes_zh,'')) = '0d110ab0bbb54b829f9c0f283430f394' AND md5(coalesce(body_changes_id,'')) = 'f77cd054ae70a6c28e5a31dd876ab310' AND md5(coalesce(body_changes_fr,'')) = 'bca44faea0a036aae7425553bd5592a7' AND md5(coalesce(body_changes_es,'')) = '372ed250d3b3cc308fb6d74fd4d3665c' AND md5(coalesce(body_changes_pt,'')) = '1a0741420e5a78b647fad0bdb4b98659' AND md5(coalesce(body_changes_vi,'')) = 'dd578f3294e3adc0f681fdcdce212070' AND md5(coalesce(body_changes_hi,'')) = 'aaf5578412bb298cc705b446df6b8c2c' AND md5(coalesce(body_changes_ja,'')) = '78ab4887ab7e8a2e1d5433ed87e53dde' AND md5(coalesce(body_changes_ko,'')) = 'ea8fa1db6a550d397cb2b5b87ccc4dc4' AND md5(coalesce(body_changes_pl,'')) = '82cfd626fa27a94b42bac40a15ae61c7' AND md5(coalesce(body_changes_nl,'')) = 'c8e1d8c950091a5259883310bd5fd897' AND md5(coalesce(body_changes_sv,'')) = '57a6195e59e84c8086ffd2e55cbacc5e';
UPDATE public.mommy_daily_messages SET message = 'Artıq 2 aylıq peyvəndlərin vaxtıdır (əgər hələ etməmisənsə). Azərbaycanda tətbiq edilən peyvənd təqviminə əsasən, bu dövrdə körpəyə adətən 5-li və ya 6-lı karma vaksin (Göyöskürək, Difteriya, Tetanus və s.) və Pnevmokok peyvəndi vurulur. Peyvənddən sonra körpənin hərarəti bir az qalxa bilər və ya huzursuz ola bilər; bu, qorxulu deyil, əksinə, immunitetin "işə düşdüyünü" və orqanizmin müdafiə olunduğunu göstərir. Həkimin məsləhəti ilə evdə mütləq körpələr üçün parasetamol tərkibli şam və ya şərbət saxla, lakin 3 aydan kiçik körpədə hərarət 38 dərəcə və ya daha yüksək olarsa, dərman verməyə tələsmə, dərhal həkimə müraciət et.', message_en = 'It''s time for the 2-month vaccinations (if you haven''t done them yet). According to the vaccination schedule in Azerbaijan, your baby usually receives a 5-in-1 or 6-in-1 combination vaccine (for Pertussis, Diphtheria, Tetanus, etc.) and a Pneumococcal vaccine during this period. After vaccination, your baby might develop a slight fever or become fussy; this is not alarming, but rather a sign that their immune system is working and their body is building protection. With your doctor''s advice, make sure to keep paracetamol-based suppositories or syrup for babies at home, but if your baby is under 3 months old and their fever is 38 degrees Celsius or higher, don''t rush to give medication; see a doctor right away.', message_ru = 'Пришло время прививок в 2 месяца (если вы их ещё не сделали). Согласно календарю прививок, применяемому в Азербайджане, в этот период малышу обычно вводят комбинированную 5- или 6-валентную вакцину (коклюш, дифтерия, столбняк и др.) и прививку от пневмококка. После прививки у малыша может немного подняться температура или он может стать беспокойным; это не страшно — наоборот, это показывает, что иммунитет «включился» и организм вырабатывает защиту. По совету врача обязательно держите дома детские свечи или сироп с парацетамолом, но если малышу меньше 3 месяцев и температура 38 градусов или выше, не спешите давать лекарство, а сразу обратитесь к врачу.', message_tr = 'Artık 2 aylık aşıların zamanı geldi (henüz yaptırmadıysanız). Azerbaycan''da uygulanan aşı takvimine göre bu dönemde bebeğe genellikle 5''li veya 6''lı karma aşı (boğmaca, difteri, tetanos vb.) ve Pnömokok aşısı yapılır. Aşıdan sonra bebeğin ateşi biraz yükselebilir ya da huzursuz olabilir; bu korkutucu değildir, aksine bağışıklığın "devreye girdiğini" ve organizmanın korunmaya başladığını gösterir. Doktorunuzun önerisiyle evde mutlaka bebekler için parasetamol içeren fitil veya şurup bulundurun; ancak 3 aydan küçük bebekte ateş 38 derece veya daha yüksekse ilaç vermekte acele etmeyin, hemen doktora başvurun.', message_kk = '2 айлық екпелерді салдыратын уақыт келді (егер әлі жасатпаған болсаңыз). Әзербайжанда қолданылатын екпе күнтізбесіне сәйкес, осы кезеңде бөпеге әдетте 5 немесе 6 компонентті біріктірілген вакцина (көкжөтел, дифтерия, сіреспе және т.б.) мен пневмококқа қарсы екпе салынады. Екпеден кейін бөпенің дене қызуы сәл көтерілуі немесе ол мазасыздануы мүмкін. Бұл қорқынышты емес, керісінше, иммундық жүйенің "іске қосылғанын" және ағзаның қорғаныс қалыптастырып жатқанын көрсетеді. Дәрігердің кеңесімен үйде бөпелерге арналған құрамында парацетамол бар суппозиторий немесе шәрбат міндетті түрде сақтаңыз, алайда 3 айдан кіші бөпенің дене қызуы 38 градус немесе одан жоғары болса, дәрі беруге асықпаңыз, бірден дәрігерге қаралыңыз.', message_de = 'Jetzt sind die Impfungen im Alter von 2 Monaten fällig (falls dein Baby sie noch nicht erhalten hat). Nach dem in Aserbaidschan geltenden Impfkalender bekommt dein Baby in diesem Zeitraum normalerweise einen 5-fach- oder 6-fach-Kombinationsimpfstoff (gegen Keuchhusten, Diphtherie, Tetanus usw.) sowie eine Pneumokokken-Impfung. Nach der Impfung kann die Temperatur deines Babys leicht ansteigen oder es kann unruhig sein. Das ist kein Grund zur Sorge, sondern zeigt, dass das Immunsystem „aktiviert“ wurde und der Körper Abwehrkräfte aufbaut. Halte nach Rücksprache mit deinem Arzt oder deiner Ärztin unbedingt Paracetamol-Zäpfchen oder -Sirup für Babys zu Hause bereit. Wenn dein Baby jünger als 3 Monate ist und die Temperatur 38 Grad oder höher beträgt, gib jedoch nicht vorschnell ein Medikament, sondern wende dich sofort an einen Arzt oder eine Ärztin.', message_ar = 'لقد حان موعد لقاحات عمر شهرين (إذا لم تكوني قد أعطيتِها لطفلكِ بعد). وفقًا لجدول التطعيمات المُطبَّق في أذربيجان، يُعطى الطفل خلال هذه الفترة عادةً اللقاح المركب 5 في 1 أو 6 في 1 (ضد السعال الديكي والدفتيريا والكزاز وغيرها)، بالإضافة إلى لقاح المكورات الرئوية. قد ترتفع حرارة طفلكِ قليلًا أو يصبح منزعجًا بعد التطعيم؛ وهذا ليس مدعاة للخوف، بل يدل على أن جهازه المناعي قد بدأ "بالعمل" وأن جسمه يكوّن الحماية. احتفظي في المنزل، بعد استشارة الطبيب، بتحاميل أو شراب للأطفال يحتوي على الباراسيتامول، لكن إذا بلغت حرارة طفلكِ 38 درجة أو أكثر وهو دون 3 أشهر، فلا تتعجلي في إعطائه الدواء، بل راجعي الطبيب فورًا.', message_uz = 'Endi 2 oylik emlashlar vaqti keldi (agar hali qildirmagan bo‘lsangiz). Ozarbayjonda qo‘llaniladigan emlash taqvimiga ko‘ra, bu davrda chaqaloqqa odatda 5 yoki 6 komponentli kombinatsiyalangan vaksina (ko‘kyo‘tal, difteriya, qoqshol va boshqalarga qarshi) hamda pnevmokokk vaksinasi qilinadi. Emlashdan keyin chaqaloqning harorati biroz ko‘tarilishi yoki u bezovta bo‘lishi mumkin. Bu qo‘rqinchli emas, aksincha, immunitet "ishga tushgani" va organizm himoyalanayotganini ko‘rsatadi. Shifokor tavsiyasiga ko‘ra, uyda chaqaloqlar uchun mo‘ljallangan, tarkibida paratsetamol bo‘lgan shamcha yoki siropni albatta saqlang, ammo 3 oylikdan kichik chaqaloqda harorat 38 daraja yoki undan yuqori bo‘lsa, dori berishga shoshilmang, darhol shifokorga murojaat qiling.', message_ka = 'უკვე 2 თვის ასაკში ჩასატარებელი ვაქცინების დროა (თუ ჯერ არ ჩაგიტარებიათ). აზერბაიჯანში მოქმედი ვაქცინაციის კალენდრის მიხედვით, ამ პერიოდში ბავშვს ჩვეულებრივ უკეთებენ 5-კომპონენტიან ან 6-კომპონენტიან კომბინირებულ ვაქცინას (ყივანახველა, დიფტერია, ტეტანუსი და სხვ.) და პნევმოკოკურ ვაქცინას. ვაქცინაციის შემდეგ ბავშვს შეიძლება ტემპერატურამ ოდნავ აუწიოს ან მოუსვენრად იყოს; ეს საშიში არ არის — პირიქით, მიუთითებს, რომ იმუნიტეტი "ამოქმედდა" და ორგანიზმი თავდაცვას იწყებს. ექიმის რჩევით, სახლში აუცილებლად იქონიეთ ჩვილებისთვის განკუთვნილი პარაცეტამოლის შემცველი სანთელი ან სიროფი, თუმცა თუ 3 თვემდე ასაკის ბავშვს ტემპერატურა 38 გრადუსი ან მეტი აქვს, ნუ იჩქარებთ წამლის მიცემას, დაუყოვნებლივ მიმართეთ ექიმს.', message_zh = '该接种2月龄疫苗了（如果还没有接种）。根据阿塞拜疆的疫苗接种计划，宝宝通常会在此期间接种5联或6联联合疫苗（预防百日咳、白喉、破伤风等）以及肺炎球菌疫苗，其中的联数分别为1和1。接种后，宝宝可能会轻微发热或变得烦躁；这无需担心，反而说明免疫系统正在工作，身体正在建立保护。请遵医嘱在家中备好婴儿用含对乙酰氨基酚的栓剂或糖浆，但如果未满3个月的宝宝体温达到38摄氏度或更高，不要急着用药，应立即就医。', message_id = 'Saatnya menerima vaksinasi usia 2 bulan jika bayi Anda belum mendapatkannya. Menurut jadwal vaksinasi di Azerbaijan, pada periode ini bayi biasanya menerima vaksin kombinasi 5-dalam-1 atau 6-dalam-1 untuk Pertusis, Difteri, Tetanus, dan lainnya, serta vaksin Pneumokokus. Setelah vaksinasi, bayi Anda mungkin mengalami demam ringan atau menjadi rewel. Hal ini tidak perlu dikhawatirkan, tetapi merupakan tanda bahwa sistem kekebalannya sedang bekerja dan tubuhnya sedang membangun perlindungan. Atas saran dokter, sediakan supositoria atau sirop berbahan dasar parasetamol untuk bayi di rumah, tetapi jika suhu tubuh bayi di bawah 3 bulan mencapai 38 derajat Celsius atau lebih, jangan terburu-buru memberikannya, segera hubungi dokter.', message_fr = 'Il est temps d’effectuer les vaccinations prévues à 2 mois, si ce n’est pas encore fait. Selon le calendrier vaccinal de l’Azerbaïdjan, votre bébé reçoit généralement pendant cette période un vaccin combiné 5-en-1 ou 6-en-1, notamment contre la coqueluche, la diphtérie et le tétanos, ainsi qu’un vaccin contre le pneumocoque. Après la vaccination, votre bébé peut avoir une légère fièvre ou être irritable. Cela n’est pas alarmant : c’est le signe que son système immunitaire réagit et que son organisme développe une protection. Sur les conseils de votre médecin, veillez à avoir chez vous des suppositoires ou du sirop pour bébé à base de paracétamol, mais si votre bébé de moins de 3 mois a une température de 38 degrés Celsius ou plus, ne vous précipitez pas pour lui administrer un médicament et consultez immédiatement un médecin.', message_es = 'Es el momento de administrar las vacunas de los 2 meses, si aún no lo has hecho. Según el calendario de vacunación de Azerbaiyán, durante este periodo tu bebé suele recibir una vacuna combinada 5 en 1 o 6 en 1 contra la tosferina, la difteria, el tétanos, etc., y una vacuna antineumocócica. Después de la vacunación, tu bebé puede tener un poco de fiebre o mostrarse irritable. Esto no es alarmante, sino una señal de que su sistema inmunitario está funcionando y su cuerpo está generando protección. Siguiendo las indicaciones de tu médico, procura tener en casa supositorios o jarabe de paracetamol para bebés, pero si tu bebé tiene menos de 3 meses y su temperatura es de 38 grados Celsius o más, no te apresures a darle medicamentos y acude de inmediato al médico.', message_pt = 'Está na altura das vacinas dos 2 meses, caso ainda não tenham sido administradas. De acordo com o plano de vacinação do Azerbaijão, durante este período o seu bebé recebe habitualmente uma vacina combinada 5 em 1 ou 6 em 1, contra a tosse convulsa, a difteria, o tétano, entre outras doenças, e uma vacina pneumocócica. Após a vacinação, o bebé pode ter uma febre ligeira ou ficar mais irritável. Isto não é motivo para alarme, mas sim um sinal de que o sistema imunitário está a funcionar e o organismo está a criar proteção. Seguindo a recomendação do seu médico, tenha em casa supositórios ou xarope para bebé à base de paracetamol, mas, se o bebé tiver menos de 3 meses e uma temperatura de 38 graus Celsius ou mais, não se precipite a dar medicação e procure imediatamente um médico.', message_vi = 'Đã đến lúc tiêm các vắc xin của tháng thứ 2 nếu bé chưa được tiêm. Theo lịch tiêm chủng tại Azerbaijan, trong giai đoạn này, bé thường được tiêm vắc xin phối hợp 5 trong 1 hoặc 6 trong 1 để phòng ho gà, bạch hầu, uốn ván và các bệnh khác, cùng với vắc xin phế cầu. Sau khi tiêm, bé có thể sốt nhẹ hoặc quấy khóc; đây không phải là dấu hiệu đáng lo mà cho thấy hệ miễn dịch đang hoạt động và cơ thể đang tạo khả năng bảo vệ. Theo tư vấn của bác sĩ, bạn nên chuẩn bị sẵn thuốc đặt hoặc siro chứa paracetamol dành cho trẻ tại nhà, nhưng nếu bé dưới 3 tháng tuổi có nhiệt độ từ 38 độ C trở lên, đừng vội cho bé dùng thuốc mà hãy đưa bé đi khám bác sĩ ngay.', message_hi = 'अब 2 महीने में लगने वाले टीके लगवाने का समय है, अगर आपने अभी तक नहीं लगवाए हैं। अज़रबैजान के टीकाकरण कार्यक्रम के अनुसार, इस अवधि में आमतौर पर आपके शिशु को 5-इन-1 या 6-इन-1 संयोजन टीका (काली खाँसी, डिप्थीरिया, टिटनेस आदि के लिए) और न्यूमोकोकल टीका लगाया जाता है। टीकाकरण के बाद आपके शिशु को हल्का बुखार हो सकता है या वह चिड़चिड़ा हो सकता है। यह चिंता की बात नहीं, बल्कि इस बात का संकेत है कि उसकी प्रतिरक्षा प्रणाली काम कर रही है और शरीर सुरक्षा विकसित कर रहा है। अपने डॉक्टर की सलाह से शिशुओं के लिए पैरासिटामोल वाली सपोज़िटरी या सिरप घर पर रखें, लेकिन अगर 3 महीने से कम उम्र के शिशु का तापमान 38 डिग्री सेल्सियस या उससे अधिक हो, तो दवा देने में जल्दबाज़ी न करें, तुरंत डॉक्टर से संपर्क करें।', message_ja = 'まだ受けていない場合は、2か月時の予防接種を受ける時期です。アゼルバイジャンの予防接種スケジュールでは、この時期に通常、百日咳、ジフテリア、破傷風などを対象とする5-in-1または6-in-1の混合ワクチンと、肺炎球菌ワクチンを接種します。接種後に微熱が出たり、機嫌が悪くなったりすることがありますが、心配な反応ではなく、免疫系が働き、体が防御力をつけている証拠です。医師に相談のうえ、乳児用のパラセタモール配合坐薬またはシロップを自宅に用意しておきましょう。ただし、生後3か月未満の赤ちゃんの体温が摂氏38度以上になった場合は、急いで薬を与えず、すぐに医師の診察を受けてください。', message_ko = '아직 접종하지 않았다면 2개월 예방접종을 할 때예요. 아제르바이잔 예방접종 일정에 따르면 이 시기에는 일반적으로 백일해, 디프테리아, 파상풍 등을 예방하는 5가-1 또는 6가-1 혼합백신과 폐렴구균 백신을 접종해요. 접종 후 아기에게 미열이 나거나 보챌 수 있어요. 이는 걱정할 일이 아니라 면역 체계가 작동하며 몸이 방어력을 형성하고 있다는 신호예요. 의사와 상담해 아기용 파라세타몰 성분 좌약이나 시럽을 집에 준비해 두되, 생후 3개월 미만 아기의 체온이 섭씨 38도 이상이라면 서둘러 약을 먹이지 말고 즉시 의사의 진료를 받으세요.', message_pl = 'Czas na szczepienia przewidziane na 2. miesiąc życia, jeśli nie zostały jeszcze wykonane. Zgodnie z kalendarzem szczepień w Azerbejdżanie w tym okresie dziecko zwykle otrzymuje szczepionkę skojarzoną 5 w 1 lub 6 w 1 przeciwko między innymi krztuścowi, błonicy i tężcowi, a także szczepionkę przeciw pneumokokom. Po szczepieniu może pojawić się niewielka gorączka lub rozdrażnienie. Nie jest to powód do niepokoju, lecz oznaka, że układ odpornościowy pracuje, a organizm buduje ochronę. Po konsultacji z lekarzem warto mieć w domu czopki lub syrop dla niemowląt na bazie paracetamolu, ale jeśli u niemowlęcia poniżej 3. miesiąca życia temperatura wynosi 38 stopni Celsjusza lub więcej, nie spiesz się z podawaniem leku, tylko natychmiast skontaktuj się z lekarzem.', message_nl = 'Het is tijd voor de vaccinaties van 2 maanden, als je die nog niet hebt laten geven. Volgens het vaccinatieschema in Azerbeidzjan krijgt je baby in deze periode meestal een 5-in-1- of 6-in-1-combinatievaccin tegen onder andere kinkhoest, difterie en tetanus, plus een pneumokokkenvaccin. Na de vaccinatie kan je baby lichte koorts krijgen of wat huilerig zijn. Dit is niet verontrustend, maar een teken dat het afweersysteem aan het werk is en het lichaam bescherming opbouwt. Zorg er op advies van je arts voor dat je zetpillen of siroop voor baby''s op basis van paracetamol in huis hebt. Heeft een baby jonger dan 3 maanden koorts van 38 graden Celsius of hoger, geef dan niet meteen medicatie, maar neem direct contact op met een arts.', message_sv = 'Det är dags för vaccinationerna vid 2 månaders ålder, om barnet inte redan har fått dem. Enligt vaccinationsprogrammet i Azerbajdzjan får barnet vanligtvis ett 5-i-1- eller 6-i-1-kombinationsvaccin mot bland annat kikhosta, difteri och stelkramp samt vaccin mot pneumokocker under den här perioden. Efter vaccinationen kan barnet få lätt feber eller bli kinkigt. Det är inte oroande, utan ett tecken på att immunförsvaret arbetar och att kroppen bygger upp ett skydd. Se efter samråd med läkare till att ha paracetamolbaserade stolpiller eller flytande läkemedel för barn hemma, men om ett barn under 3 månader har 38 grader Celsius eller mer i feber, ge inte läkemedel för snabbt utan kontakta läkare direkt.' WHERE id = '947283f7-9c09-4c76-a0bb-7ff92f24aad4' AND md5(coalesce(message,'')) = '403a2ffec24e5e11f1198d0c6fe02aae' AND md5(coalesce(message_en,'')) = 'e1c38848bcf535d2f4d466d9efdcae69' AND md5(coalesce(message_ru,'')) = '3bb0317f787b28138d188338f38a5f6f' AND md5(coalesce(message_tr,'')) = 'fa1523b715b1819199c67c00856460e5' AND md5(coalesce(message_kk,'')) = '1ccb9ddaade995307584190e626734e8' AND md5(coalesce(message_de,'')) = 'b9e1da59fd66019e7d73734fbe5a15d4' AND md5(coalesce(message_ar,'')) = 'bdc1c782b39af7df446c030d57ad58dd' AND md5(coalesce(message_uz,'')) = 'c3de47cb8180aa8cbf347514dfc42d8c' AND md5(coalesce(message_ka,'')) = 'c198d3e92ea0512c5c6486f99eee6f2c' AND md5(coalesce(message_zh,'')) = '7f602b13a90602dfd53b21b25dcaebda' AND md5(coalesce(message_id,'')) = '3f0a42cf4d7572d21cc8933d60402f85' AND md5(coalesce(message_fr,'')) = '1eba0548d3146ce3fdb6bd0edc76ccbf' AND md5(coalesce(message_es,'')) = 'f6ee0ae94d04658c63117b9cbfbd7d30' AND md5(coalesce(message_pt,'')) = '635d55b2939af1b37aa6dffa4a9c175f' AND md5(coalesce(message_vi,'')) = '86686eb325ad7f38640c81a1eb331218' AND md5(coalesce(message_hi,'')) = '5104391cee4dd82611478b79cd0abcc3' AND md5(coalesce(message_ja,'')) = 'b2ec06b6fe37a81cc1b5144cec4dc9de' AND md5(coalesce(message_ko,'')) = '77d704e53d471d13060290d497434992' AND md5(coalesce(message_pl,'')) = '26c993cb2a4de0ca6adf3de06faa8a74' AND md5(coalesce(message_nl,'')) = 'd5522e84745a710d49e4eb250c7233aa' AND md5(coalesce(message_sv,'')) = '968117d59577c986dcdc7806fe81b96d';
UPDATE public.pregnancy_daily_content SET body_changes = 'Körpənizin bu mərhələdə sağlam inkişafı üçün kalsium və fosfor olduqca böyük əhəmiyyət kəsb edir. D2 və D3 vitaminləri körpənizin inkişafı üçün çox vacibdir. Hamiləlikdə D vitamini adətən gündəlik 400-600 IU (10-15 mkq) səviyyəsində qəbul edilir, daha yüksək dozanı yalnız həkim təyin etməlidir. D vitamini hüceyrə bölünməsi, sümük inkişafı və immunitet sistemi üçün bədənin ehtiyac duyduğu maddələrdən biridir. Bu vitamin həkim nəzarəti altında və müəyyən analizlərdən sonra istifadə edilməlidir. Körpənizin formalaşma mərhələsində; hüceyrə və toxumaların böyüməsini təmin edən A vitamini, immunitet, sümük və diş sağlamlığı üçün D vitamini, immunitet sistemi üçün C vitamini, qanazlığı və sümük inkişafı üçün isə D vitamini hamiləliyinizin bu dövründə qəbul edilməli olan vitaminlərdir. Həkim nəzarəti altında D vitamini istifadə edərək həm öz sağlığınızı, həm də körpənizin sağlığını qorumuş olursunuz. Lakin şüursuz şəkildə D vitamini qəbul etmək körpənizə zərər verə bilər.', body_changes_en = 'Calcium and phosphorus are incredibly important for your baby''s healthy development at this stage. Vitamins D2 and D3 are also crucial for your baby''s growth. During pregnancy, Vitamin D is usually taken daily at a level of 400-600 IU (10-15 mcg); a higher dose should only be prescribed by a doctor. Vitamin D is essential for cell division, bone development, and a healthy immune system. This vitamin should be used under medical supervision and after specific tests. For your baby''s formation phase, Vitamin A helps ensure cell and tissue growth, while Vitamin D is vital for immunity, bone, and dental health. Vitamin C supports the immune system. By taking Vitamin D under your doctor''s supervision, you protect both your health and your baby''s health. However, taking Vitamin D without proper guidance can be harmful to your baby.', body_changes_ru = 'Для здорового развития вашего малыша на этом этапе чрезвычайно важны кальций и фосфор. Витамины D2 и D3 играют важную роль в развитии малыша. Во время беременности витамин D обычно принимают ежедневно в дозировке 400-600 IU (10-15 мкг), более высокую дозу должен назначать только врач. Витамин D необходим организму для деления клеток, развития костей и работы иммунной системы. Его следует принимать под наблюдением врача и после проведения соответствующих анализов. На этапе формирования малыша необходимы: витамин A, способствующий росту клеток и тканей, витамин D — для иммунитета, здоровья костей и зубов, витамин C — для иммунной системы, а также витамин D — для профилактики анемии и развития костей. Эти витамины следует получать в данный период беременности. Принимая витамин D под наблюдением врача, вы заботитесь как о своём здоровье, так и о здоровье малыша. Однако бесконтрольный приём витамина D может навредить вашему малышу.', body_changes_tr = 'Bebeğinizin bu aşamada sağlıklı gelişimi için kalsiyum ve fosfor son derece büyük önem taşır. D2 ve D3 vitaminleri bebeğinizin gelişimi açısından çok önemlidir. Gebelikte D vitamini genellikle günlük 400-600 IU (10-15 mcg) düzeyinde alınır, daha yüksek dozu yalnızca doktor önermelidir. D vitamini; hücre bölünmesi, kemik gelişimi ve bağışıklık sistemi için vücudun ihtiyaç duyduğu maddelerden biridir. Bu vitamin, doktor kontrolünde ve belirli testler yapıldıktan sonra kullanılmalıdır. Bebeğinizin oluşum aşamasında; hücre ve dokuların büyümesini sağlayan A vitamini, bağışıklık ile kemik ve diş sağlığı için D vitamini, bağışıklık sistemi için C vitamini, kansızlığın önlenmesi için demir ve kemik gelişimi için yine D vitamini gebeliğinizin bu döneminde alınması gereken besin ögeleridir. Doktor kontrolünde D vitamini kullanarak hem kendi sağlığınızı hem de bebeğinizin sağlığını korumuş olursunuz. Ancak bilinçsizce D vitamini almak bebeğinize zarar verebilir.', body_changes_kk = 'Бұл кезеңде бөпеңіздің дені сау дамуы үшін кальций мен фосфордың маңызы өте зор. D2 және D3 дәрумендері бөпеңіздің дамуы үшін аса маңызды. Жүктілік кезінде D дәрумені әдетте тәулігіне 400-600 IU (10-15 мкг) мөлшерінде қабылданады, одан жоғары дозаны тек дәрігер тағайындауы керек. D дәрумені жасушалардың бөлінуіне, сүйектің дамуына және иммундық жүйенің жұмысына қажетті заттардың бірі. Бұл дәруменді дәрігердің бақылауымен және тиісті талдаулардан кейін ғана қабылдау керек. Бөпеңіз қалыптасып жатқан кезеңде жасушалар мен тіндердің өсуін қамтамасыз ететін A дәрумені, иммунитет, сүйек пен тіс саулығы үшін D дәрумені, иммундық жүйе үшін C дәрумені, ал қаназдықтың алдын алу және сүйектің дамуы үшін қажетті дәрумендер қабылдануы тиіс. D дәруменін дәрігердің бақылауымен қабылдау арқылы өз денсаулығыңызды да, бөпеңіздің денсаулығын да қорғайсыз. Алайда D дәруменін дәрігердің кеңесінсіз қабылдау бөпеңізге зиян келтіруі мүмкін.', body_changes_de = 'Für die gesunde Entwicklung deines Babys sind Kalzium und Phosphor in dieser Phase besonders wichtig. Auch die Vitamine D2 und D3 spielen eine bedeutende Rolle für seine Entwicklung. In der Schwangerschaft wird Vitamin D üblicherweise täglich in einer Menge von 400-600 IU (10-15 µg) eingenommen, eine höhere Dosis sollte nur ärztlich verordnet werden. Vitamin D gehört zu den Stoffen, die der Körper für die Zellteilung, die Knochenentwicklung und das Immunsystem benötigt. Es sollte nur nach entsprechenden Untersuchungen und unter ärztlicher Aufsicht eingenommen werden. Während sich dein Baby entwickelt, sind verschiedene Vitamine wichtig: Vitamin A unterstützt das Wachstum von Zellen und Gewebe, Vitamin D trägt zum Immunsystem sowie zur Gesundheit von Knochen und Zähnen bei, Vitamin C unterstützt die Abwehrkräfte, und weitere bedarfsgerecht ausgewählte Vitamine und Mineralstoffe helfen, Blutarmut vorzubeugen und die Knochenentwicklung zu fördern. Wenn du Vitamin D unter ärztlicher Aufsicht einnimmst, schützt du sowohl deine eigene Gesundheit als auch die deines Babys. Eine unkontrollierte Einnahme von Vitamin D kann deinem Baby jedoch schaden.', body_changes_ar = 'للكالسيوم والفوسفور أهمية كبيرة جدًا في نمو طفلكِ بصورة صحية خلال هذه المرحلة. كما يُعد فيتامينا D2 وD3 ضروريين جدًا لنموه. ويُتناول فيتامين D خلال الحمل عادةً بجرعة يومية قدرها 400-600 IU (10-15 ميكروغرام)، ولا ينبغي تناول جرعة أعلى إلا إذا وصفها الطبيب. ويُعد فيتامين D من العناصر التي يحتاج إليها الجسم لانقسام الخلايا ونمو العظام ودعم الجهاز المناعي. ويجب استخدام هذا الفيتامين تحت إشراف الطبيب وبعد إجراء تحاليل محددة. وخلال مرحلة تكوّن طفلكِ، تشمل الفيتامينات التي ينبغي تناولها في هذه الفترة من الحمل فيتامين A الذي يدعم نمو الخلايا والأنسجة، وفيتامين D الضروري للمناعة وصحة العظام والأسنان، وفيتامين C الداعم للجهاز المناعي، وفيتامين D لفقر الدم ونمو العظام. ومن خلال استخدام فيتامين D تحت إشراف الطبيب، تحافظين على صحتكِ وصحة طفلكِ معًا. لكن تناوله عشوائيًا ومن دون إشراف قد يضر طفلكِ.', body_changes_uz = 'Ushbu bosqichda chaqalog‘ingizning sog‘lom rivojlanishi uchun kalsiy va fosfor nihoyatda katta ahamiyatga ega. D2 va D3 vitaminlari chaqalog‘ingiz rivojlanishi uchun juda muhimdir. Homiladorlikda D vitamini odatda kuniga 400-600 IU (10-15 mkg) miqdorida qabul qilinadi, yuqoriroq dozani faqat shifokor tayinlashi kerak. D vitamini hujayralarning bo‘linishi, suyaklarning rivojlanishi va immunitet tizimi uchun organizmga zarur moddalardan biridir. Bu vitaminni shifokor nazorati ostida va tegishli tahlillardan keyin qabul qilish lozim. Chaqalog‘ingiz shakllanayotgan davrda hujayra va to‘qimalarning o‘sishini ta’minlaydigan A vitamini, immunitet, suyak va tishlar salomatligi uchun D vitamini, immunitet tizimi uchun C vitamini, kamqonlikning oldini olish va suyaklar rivojlanishi uchun esa D vitamini homiladorlikning ushbu davrida qabul qilinishi kerak bo‘lgan vitaminlardir. D vitaminini shifokor nazorati ostida qabul qilish orqali siz ham o‘z sog‘lig‘ingizni, ham chaqalog‘ingiz sog‘lig‘ini himoya qilasiz. Biroq D vitaminini nazoratsiz qabul qilish chaqalog‘ingizga zarar yetkazishi mumkin.', body_changes_ka = 'ამ ეტაპზე თქვენი ბავშვის ჯანსაღი განვითარებისთვის კალციუმსა და ფოსფორს ძალიან დიდი მნიშვნელობა აქვს. D2 და D3 ვიტამინები ბავშვის განვითარებისთვის აუცილებელია. ორსულობის დროს D ვიტამინის დღიური დოზა, როგორც წესი, 400-600 IU (10-15 მკგ) შეადგენს, უფრო მაღალი დოზა მხოლოდ ექიმმა უნდა დანიშნოს. D ვიტამინი ერთ-ერთი ნივთიერებაა, რომელიც ორგანიზმს უჯრედების დაყოფის, ძვლების განვითარებისა და იმუნური სისტემის ფუნქციონირებისთვის სჭირდება. ეს ვიტამინი მხოლოდ ექიმის მეთვალყურეობითა და შესაბამისი ანალიზების ჩატარების შემდეგ უნდა მიიღოთ. ბავშვის ჩამოყალიბების ეტაპზე საჭიროა A ვიტამინი, რომელიც უჯრედებისა და ქსოვილების ზრდას უწყობს ხელს; D ვიტამინი — იმუნიტეტისა და ძვლებისა და კბილების ჯანმრთელობისთვის; C ვიტამინი — იმუნური სისტემისთვის; ხოლო D ვიტამინი — ანემიის პრევენციისა და ძვლების განვითარებისთვის. ეს ვიტამინები ორსულობის ამ პერიოდში უნდა მიიღოთ. ექიმის მეთვალყურეობით D ვიტამინის მიღებით როგორც საკუთარ, ისე თქვენი ბავშვის ჯანმრთელობას დაიცავთ. თუმცა D ვიტამინის თვითნებურად მიღებამ შეიძლება ბავშვს ზიანი მიაყენოს.', body_changes_zh = '现阶段，钙和磷对宝宝的健康发育极为重要。维生素D2和D3对宝宝的生长也至关重要。孕期通常每天摄入400-600 IU（10-15微克）维生素D，更高剂量只能由医生开具。维生素D对细胞分裂、骨骼发育和免疫系统健康必不可少。使用这种维生素前应接受特定检查，并在医生指导下服用。在宝宝的形成阶段，维生素A有助于细胞和组织生长，维生素D对免疫力以及骨骼和牙齿健康至关重要，维生素C则有助于支持免疫系统。在医生指导下服用维生素D，可以守护你和宝宝的健康。但如果没有专业指导就自行服用维生素D，可能会伤害宝宝。', body_changes_id = 'Kalsium dan fosfor sangat penting bagi perkembangan sehat bayi Anda pada tahap ini. Vitamin D2 dan D3 juga sangat penting bagi pertumbuhan bayi Anda. Selama kehamilan, Vitamin D biasanya dikonsumsi setiap hari pada dosis 400-600 IU (10-15 mcg). Dosis yang lebih tinggi hanya boleh diresepkan oleh dokter. Vitamin D penting untuk pembelahan sel, perkembangan tulang, dan sistem kekebalan tubuh yang sehat. Vitamin ini harus digunakan di bawah pengawasan medis dan setelah menjalani pemeriksaan tertentu. Dalam tahap pembentukan bayi Anda, Vitamin A membantu memastikan pertumbuhan sel dan jaringan, sedangkan Vitamin D sangat penting bagi kekebalan tubuh serta kesehatan tulang dan gigi. Vitamin C mendukung sistem kekebalan tubuh. Dengan mengonsumsi Vitamin D di bawah pengawasan dokter, Anda melindungi kesehatan diri sendiri dan bayi Anda. Namun, mengonsumsi Vitamin D tanpa panduan yang tepat dapat membahayakan bayi Anda.', body_changes_fr = 'Le calcium et le phosphore sont extrêmement importants pour le bon développement de votre bébé à ce stade. Les vitamines D2 et D3 jouent également un rôle essentiel dans sa croissance. Pendant la grossesse, la vitamine D est généralement prise quotidiennement à raison de 400-600 IU (10-15 mcg) ; une dose plus élevée ne doit être prescrite que par un médecin. La vitamine D est indispensable à la division cellulaire, au développement des os et au bon fonctionnement du système immunitaire. Cette vitamine doit être utilisée sous surveillance médicale et après des examens spécifiques. Pendant la phase de formation de votre bébé, la vitamine A favorise la croissance des cellules et des tissus, tandis que la vitamine D est essentielle à l’immunité ainsi qu’à la santé des os et des dents. La vitamine C soutient le système immunitaire. En prenant de la vitamine D sous la surveillance de votre médecin, vous protégez à la fois votre santé et celle de votre bébé. Toutefois, prendre de la vitamine D sans accompagnement approprié peut être dangereux pour votre bébé.', body_changes_es = 'El calcio y el fósforo son sumamente importantes para el desarrollo saludable de tu bebé en esta etapa. Las vitaminas D2 y D3 también son esenciales para su crecimiento. Durante el embarazo, se suele tomar diariamente vitamina D en una cantidad de 400-600 IU (10-15 mcg); una dosis más alta solo debe indicarla el médico. La vitamina D es esencial para la división celular, el desarrollo óseo y un sistema inmunitario saludable. Esta vitamina debe utilizarse bajo supervisión médica y después de realizar pruebas específicas. Durante la formación de tu bebé, la vitamina A favorece el crecimiento de las células y los tejidos, mientras que la vitamina D es vital para el sistema inmunitario y la salud de los huesos y los dientes. La vitamina C contribuye al buen funcionamiento del sistema inmunitario. Al tomar vitamina D bajo la supervisión de tu médico, proteges tanto tu salud como la de tu bebé. Sin embargo, tomar vitamina D sin la orientación adecuada puede ser perjudicial para tu bebé.', body_changes_pt = 'O cálcio e o fósforo são extremamente importantes para o desenvolvimento saudável do seu bebé nesta fase. As vitaminas D2 e D3 também são essenciais para o crescimento do bebé. Durante a gravidez, a vitamina D é habitualmente tomada diariamente numa dose de 400-600 IU (10-15 mcg); uma dose mais elevada só deve ser prescrita pelo médico. A vitamina D é essencial para a divisão celular, o desenvolvimento dos ossos e um sistema imunitário saudável. Esta vitamina deve ser utilizada sob supervisão médica e após a realização de análises específicas. Na fase de formação do bebé, a vitamina A ajuda a garantir o crescimento das células e dos tecidos, enquanto a vitamina D é vital para a imunidade e para a saúde dos ossos e dos dentes. A vitamina C reforça o sistema imunitário. Ao tomar vitamina D sob a supervisão do seu médico, protege tanto a sua saúde como a do seu bebé. No entanto, tomar vitamina D sem a devida orientação pode ser prejudicial para o bebé.', body_changes_vi = 'Canxi và phốt pho vô cùng quan trọng đối với sự phát triển khỏe mạnh của em bé ở giai đoạn này. Vitamin D2 và D3 cũng rất cần thiết cho sự phát triển của em bé. Trong thai kỳ, Vitamin D thường được bổ sung hằng ngày ở mức 400-600 IU (10-15 mcg); liều cao hơn chỉ nên do bác sĩ chỉ định. Vitamin D cần thiết cho quá trình phân chia tế bào, phát triển xương và duy trì hệ miễn dịch khỏe mạnh. Vitamin này chỉ nên được sử dụng dưới sự giám sát y tế và sau khi thực hiện các xét nghiệm cụ thể. Trong giai đoạn hình thành của em bé, Vitamin A hỗ trợ sự phát triển của tế bào và mô, còn Vitamin D đóng vai trò thiết yếu đối với khả năng miễn dịch cũng như sức khỏe xương và răng. Vitamin C hỗ trợ hệ miễn dịch. Bổ sung Vitamin D dưới sự giám sát của bác sĩ sẽ giúp bảo vệ sức khỏe của cả bạn và em bé. Tuy nhiên, việc tự ý dùng Vitamin D khi chưa được hướng dẫn phù hợp có thể gây hại cho em bé.', body_changes_hi = 'इस चरण में आपके शिशु के स्वस्थ विकास के लिए कैल्शियम और फॉस्फोरस बेहद महत्वपूर्ण हैं। विटामिन D2 और D3 भी आपके शिशु की वृद्धि के लिए बहुत जरूरी हैं। गर्भावस्था के दौरान विटामिन D आमतौर पर प्रतिदिन 400-600 IU (10-15 mcg) की मात्रा में लिया जाता है, इससे अधिक खुराक केवल डॉक्टर द्वारा ही निर्धारित की जानी चाहिए। विटामिन D कोशिका विभाजन, हड्डियों के विकास और स्वस्थ प्रतिरक्षा प्रणाली के लिए आवश्यक है। इस विटामिन का उपयोग चिकित्सकीय निगरानी में और निर्धारित जाँचों के बाद किया जाना चाहिए। आपके शिशु के निर्माण के चरण में विटामिन A कोशिकाओं और ऊतकों की वृद्धि में मदद करता है, जबकि विटामिन D प्रतिरक्षा तथा हड्डियों और दाँतों के स्वास्थ्य के लिए महत्वपूर्ण है। विटामिन C प्रतिरक्षा प्रणाली को सहारा देता है। अपने डॉक्टर की निगरानी में विटामिन D लेकर आप अपने और अपने शिशु, दोनों के स्वास्थ्य की रक्षा करती हैं। हालाँकि, उचित मार्गदर्शन के बिना विटामिन D लेना आपके शिशु के लिए हानिकारक हो सकता है।', body_changes_ja = 'この時期の赤ちゃんの健やかな発育には、カルシウムとリンが非常に重要です。ビタミンD2とD3も、赤ちゃんの成長に欠かせません。妊娠中のビタミンDの摂取量は通常1日400-600 IU（10-15マイクログラム）で、それより多い量は医師が処方する場合に限ります。ビタミンDは、細胞分裂、骨の発達、健康な免疫機能に欠かせません。このビタミンは、所定の検査を受けたうえで、医師の管理下で使用してください。赤ちゃんの形成期には、ビタミンAが細胞や組織の成長を助け、ビタミンDは免疫機能と骨や歯の健康に重要です。ビタミンCは免疫機能を支えます。医師の指導のもとでビタミンDを摂取することで、妊婦自身と赤ちゃんの健康を守ることができます。ただし、適切な指導なしにビタミンDを摂取すると、赤ちゃんに害を及ぼす可能性があります。', body_changes_ko = '이 시기에는 아기의 건강한 발달을 위해 칼슘과 인이 매우 중요해요. 비타민 D2와 D3도 아기의 성장에 꼭 필요해요. 임신 중에는 보통 비타민 D를 매일 400-600 IU(10-15 mcg) 섭취하며, 더 높은 용량은 의사만 처방해야 해요. 비타민 D는 세포 분열, 뼈 발달, 건강한 면역 체계에 필수적이에요. 특정 검사를 받은 후 의료진의 감독 아래 복용해야 해요. 아기가 형성되는 시기에 비타민 A는 세포와 조직의 성장을 돕고, 비타민 D는 면역력과 뼈 및 치아 건강에 중요해요. 비타민 C는 면역 체계를 지원해요. 담당 의사의 지시에 따라 비타민 D를 복용하면 산모와 아기의 건강을 모두 지킬 수 있어요. 하지만 적절한 지침 없이 비타민 D를 복용하면 아기에게 해로울 수 있어요.', body_changes_pl = 'Wapń i fosfor są na tym etapie niezwykle ważne dla prawidłowego rozwoju dziecka. Witaminy D2 i D3 również mają kluczowe znaczenie dla jego wzrostu. W czasie ciąży witaminę D przyjmuje się zwykle codziennie w dawce 400-600 IU (10-15 mcg), a wyższą dawkę może zalecić wyłącznie lekarz. Jest ona niezbędna do podziału komórek, rozwoju kości i prawidłowego funkcjonowania układu odpornościowego. Witaminę tę należy stosować pod nadzorem lekarza i po wykonaniu odpowiednich badań. W okresie kształtowania się organizmu dziecka witamina A wspiera wzrost komórek i tkanek, a witamina D jest niezbędna dla odporności oraz zdrowia kości i zębów. Witamina C wspiera układ odpornościowy. Przyjmując witaminę D pod nadzorem lekarza, chronisz zdrowie swoje i dziecka. Stosowanie jej bez odpowiednich zaleceń może jednak zaszkodzić dziecku.', body_changes_nl = 'Calcium en fosfor zijn in deze fase erg belangrijk voor de gezonde ontwikkeling van je baby. Ook vitamine D2 en D3 zijn essentieel voor de groei van je baby. Tijdens de zwangerschap wordt doorgaans dagelijks 400-600 IU (10-15 mcg) vitamine D ingenomen. Een hogere dosis mag alleen door een arts worden voorgeschreven. Vitamine D is essentieel voor de celdeling, botontwikkeling en een gezond immuunsysteem. Gebruik deze vitamine alleen onder medisch toezicht en na specifieke onderzoeken. Tijdens de ontwikkeling van je baby ondersteunt vitamine A de groei van cellen en weefsels, terwijl vitamine D belangrijk is voor de weerstand en de gezondheid van botten en tanden. Vitamine C ondersteunt het immuunsysteem. Door vitamine D onder toezicht van je arts te gebruiken, bescherm je zowel je eigen gezondheid als die van je baby. Vitamine D innemen zonder de juiste begeleiding kan echter schadelijk zijn voor je baby.', body_changes_sv = 'Kalcium och fosfor är mycket viktiga för att barnet ska utvecklas normalt i det här skedet. Vitaminerna D2 och D3 är också avgörande för barnets tillväxt. Under graviditeten tas D-vitamin vanligtvis dagligen i en dos på 400-600 IU (10-15 mcg), och en högre dos ska bara ordineras av läkare. D-vitamin behövs för celldelning, skelettutveckling och ett välfungerande immunförsvar. Vitaminet ska tas under medicinsk övervakning och efter särskild provtagning. Under barnets utveckling bidrar A-vitamin till att celler och vävnader växer, medan D-vitamin är viktigt för immunförsvaret, skelettet och tänderna. C-vitamin stöttar immunförsvaret. Genom att ta D-vitamin under läkarens övervakning skyddar du både din egen och barnets hälsa. D-vitamin kan däremot vara skadligt för barnet om det tas utan rätt vägledning.' WHERE id = 'b95c279c-175e-4f8c-ab41-1f4ffe11bc78' AND md5(coalesce(body_changes,'')) = 'df97dbe5632f3c9ecad8869eefd630d6' AND md5(coalesce(body_changes_en,'')) = '6836d27dce5c97cd673979cedb592708' AND md5(coalesce(body_changes_ru,'')) = '1bfcaeeba25c3456551dac5b7fc3e6bf' AND md5(coalesce(body_changes_tr,'')) = '2e9446de070e48f7937217ea897af513' AND md5(coalesce(body_changes_kk,'')) = '4e0b9cccdd58a0967da39a64002839e2' AND md5(coalesce(body_changes_de,'')) = '3ae3c0449c0d095d0205499fed0fe31e' AND md5(coalesce(body_changes_ar,'')) = '83bd3f98051556a241e81deb06ca7336' AND md5(coalesce(body_changes_uz,'')) = 'df10ba1aacb437d953dfc3039558a797' AND md5(coalesce(body_changes_ka,'')) = 'c78beccdba30c5ab1ceb87936e0b6c33' AND md5(coalesce(body_changes_zh,'')) = '847f50f27e2c4ef34a3b239f0c98dcfa' AND md5(coalesce(body_changes_id,'')) = '7cbac9e1fa950ce804b9e7b4a1d7c7b4' AND md5(coalesce(body_changes_fr,'')) = 'cbcd6a4096b543ed34f8960091291349' AND md5(coalesce(body_changes_es,'')) = '33c18506a5083af0fa14769f97bb2c1f' AND md5(coalesce(body_changes_pt,'')) = '04607b37c9df7758f22cf950448f6fb1' AND md5(coalesce(body_changes_vi,'')) = 'b1658ddc36b64fe56755c79cce8dfaa1' AND md5(coalesce(body_changes_hi,'')) = 'd525c63e7b9dd37606cabe3a89e2394a' AND md5(coalesce(body_changes_ja,'')) = '7ddc413a7e989d5da91ef0cfa80bf2fb' AND md5(coalesce(body_changes_ko,'')) = 'c9ccb3a750c20f4a969b61e3820ad773' AND md5(coalesce(body_changes_pl,'')) = '885bd57c22ae9961bffe001fd6e92dc2' AND md5(coalesce(body_changes_nl,'')) = 'c8df9e33964a68cda57d1834c72a06c6' AND md5(coalesce(body_changes_sv,'')) = 'db4bcd699c17f6f238ee6f6fcc6f461c';
UPDATE public.blog_posts SET content = 'Hamiləlikdən əvvəl başımız ağrıyanda və ya soyuqdəymə hiss edəndə əlimiz düşünmədən dərman qutusuna uzanardı. Lakin hamiləlik xəbərini aldıqdan sonra vəziyyət dəyişir. Artıq hər bir həbə "potensial düşmən" kimi baxırıq.

Bir tərəfdən dözülməz ağrı və ya yüksək qızdırma, digər tərəfdən isə *"Dərman içsəm, körpəmə zərər gələr?"* qorxusu. Bu dilemma bir çox ana namizədini çarəsiz qoyur. Bəzən isə qorxu o qədər güclü olur ki, qadınlar həkimin təyin etdiyi vacib müalicədən belə imtina edirlər.

Bəs həqiqət haradadır? Hansı dərmanlar "yaşıl işıq", hansılar isə qəti "qadağa"dır? Gəlin, hamiləlikdə ən çox istifadə olunan dərmanlar haqqında tibbi faktları nəzərdən keçirək.

## Qızıl Qayda: Özbaşına müalicəyə YOX deyin!

Məqaləyə başlamazdan əvvəl ən vacib qaydanı xatırladaq: **Hamiləlikdə heç bir dərmanı (hətta bitki mənşəli olsa belə) həkiminizlə məsləhətləşmədən qəbul etməyin.** Qonşuya yaxşı təsir edən dərman, sizin hamiləlik həftənizə və ya vəziyyətinizə uyğun olmaya bilər.

## Parasetamol: Hamilələrin "Xilaskarı"

Hamiləlik dövründə ağrıkəsici və qızdırmasalıcı kimi ən çox tövsiyə olunan dərman **Parasetamol**dur (Panadol, Efferalqan və s.).

### Niyə təhlükəsiz sayılır?

Tibbi araşdırmalar göstərir ki, parasetamol tövsiyə olunan dozada qəbul edildikdə dölün inkişafına mənfi təsir göstərmir. O, plasentadan keçsə də, toksik təsiri yoxdur.

### Nə vaxt içilməlidir?

- **Yüksək qızdırma:** Hamiləlikdə 38°C-dən yuxarı qızdırma körpə üçün dərmandan daha təhlükəlidir. Yüksək hərarət dölün ürək döyüntüsünü sürətləndirə və zülal strukturuna zərər verə bilər. Buna görə də qızdırmanı parasetamolla salmaq **vacibdir**.
- **Ağrılar:** Baş, diş və ya əzələ ağrıları zamanı dözmək əvəzinə parasetamol qəbul etmək, stress hormonlarını azaltmaq üçün daha yaxşıdır.

> Diqqət: Təhlükəsiz olsa da, "konfet kimi" qəbul edilməməlidir. Mümkün olan ən az dozada və ən qısa müddətdə istifadə edin.
> 

## Antibiotiklər: Dost, yoxsa Düşmən?

"Antibiotik ziyandır" fikri cəmiyyətimizdə kök salıb. Lakin hamiləlikdə müalicə olunmayan infeksiyalar (məsələn, böyrək infeksiyası, sətəlcəm, cinsi infeksiyalar) körpə üçün antibiotikdən qat-qat risklidir. İnfeksiya erkən doğuşa, suyun vaxtından əvvəl gəlməsinə və dölün inkişafdan qalmasına səbəb ola bilər.

Həkimlər hamilələrə yalnız **təhlükəsiz qrup** antibiotikləri təyin edirlər:

✅ **İcazəli Antibiotiklər:**

- **Penisislin qrupu:** (Məs: Amoksisillin, Ampisillin). Ən geniş istifadə olunan və təhlükəsiz qrupdur.
- **Makrolidlər:** (Məs: Eritromisin, Azitromisin). Penisislinə allergiyası olanlara yazılır.
- **Sefalosporinlər:** (Məs: Sefaleksin).

❌ **Qadağan Olunan Antibiotiklər:**

- **Tetrasiklinlər:** Körpənin sümük inkişafını pozur və dişlərində qalıcı sarı ləkələr yaradır.
- **Streptomisin:** Dölün eşitmə sinirini zədələyə bilər (karlıq riski).
- **Levomisetin:** "Boz körpə sindromu"na səbəb ola bilər.

**Nəticə:** Əgər həkiminiz sizə antibiotik yazıbsa, deməli, faydası riskindən qat-qat çoxdur. Kursu mütləq tamamlayın.

## İbuprofen və Aspirin: Niyə ehtiyatlı olmalıyıq?

Baş ağrısı üçün ən populyar dərmanlardan olan **İbuprofen (Nurofen)** və digər qeyri-steroid iltihab əleyhinə dərmanlar (QSİƏP) hamiləlikdə həkim təyin etmədikcə tövsiyə olunmur, **20-ci həftədən sonra isə qəbul edilməməlidir**.

- **Risk:** Bu dərmanlar körpənin ürəyindəki vacib bir damarın (Ductus Arteriosus) vaxtından əvvəl bağlanmasına səbəb ola bilər ki, bu da ciddi ürək və ağciyər problemləri yaradır. Həmçinin suyun azalmasına (oliqohidramnion) gətirib çıxara bilər.
- **Aspirin:** Yalnız həkim tərəfindən xüsusi dozada (məsələn, preeklampsiya riskinə qarşı "Kardioaspirin") təyin edilərsə içilə bilər. Özbaşına ağrıkəsici kimi istifadəsi qanaxma riski yaradır.

## Soyuqdəymə və Qrip zamanı nə etməli?

Mövsümi xəstəliklər zamanı aptekdən alınan "paket tozlar" (Teraflu, Ferveks və s.) hamilələr üçün uyğun deyil, çünki tərkiblərində vazokonstriktorlar (damar daraldıcılar) var.

**Təhlükəsiz alternativlər:**

- **Burun tıxanıqlığı üçün:** Dəniz suyu spreyləri (Akvamaris və s.) tam təhlükəsizdir. Ksilometazolin tərkibli damcılar yalnız həkim icazəsi ilə, qısa müddət (maks. 3 gün) istifadə edilə bilər.
- **Boğaz ağrısı üçün:** Duzlu su ilə qarqara, ilıq süd və bal.
- **Öskürək üçün:** Bitki tərkibli siroplar (həkim təyinatı ilə).

## Hamiləlikdə Dərman Kateqoriyaları (FDA)

Dərman qutusunu oxuyarkən bu hərflərə rast gələ bilərsiniz. Bu, ABŞ Qida və Dərman İdarəsinin (FDA) təsnifatıdır:

- **Kateqoriya A:** İnsanlar üzərində yoxlanılıb, tam təhlükəsizdir (Məs: Fol turşusu).
- **Kateqoriya B:** Heyvanlarda zərərsizdir, insanlarda kifayət qədər araşdırma yoxdur, amma təhlükəsiz sayılır (Məs: Parasetamol, Amoksisillin).
- **Kateqoriya C:** Heyvanlarda mənfi təsir göstərib, insanlarda məlumat azdır. Yalnız fayda riskdən çoxdursa istifadə edilir.
- **Kateqoriya D:** İnsan dölünə riski sübut olunub. Yalnız həyati təhlükə olduqda istifadə edilir.
- **Kateqoriya X:** Qəti qadağandır (Teratogen). Dölə ciddi zərər verir.


Hamiləlik, xəstəliklərə qarşı "müdafiəsiz" qalmaq demək deyil. Müasir tibb bizə həm ananı sağaltmaq, həm də körpəni qorumaq üçün kifayət qədər təhlükəsiz vasitələr təqdim edir.

Əgər hər hansı bir dərmanı qəbul etməkdə tərəddüd edirsinizsə, **Anacan tətbiqini** yükləyin. Tətbiqdəki "Təhlükəsizlik Bazası" (Safety Lookup) bölməsində yüzlərlə dərmanın hamiləlikdə istifadə statusunu (Yaşıl/Sarı/Qırmızı) dərhal yoxlaya bilərsiniz.

Sağlam olun ki, körpəniz də sağlam böyüsün!', content_en = 'Before pregnancy, when we had a headache or felt a cold coming on, our hand would reach for the medicine cabinet without thinking. However, after receiving the news of pregnancy, the situation changes. Now we look at every pill as a "potential enemy."

On one hand, there is unbearable pain or high fever, and on the other hand, the fear: *"If I take medicine, will it harm my baby?"* This dilemma leaves many expectant mothers helpless. Sometimes the fear is so strong that women even refuse essential treatments prescribed by a doctor.

So, where does the truth lie? Which medicines are a "green light" and which are strictly "prohibited"? Let''s look at the medical facts about the most commonly used medications during pregnancy.The Golden Rule: Say NO to self-medication!

Before starting the article, let''s recall the most important rule: **Do not take any medication (even herbal ones) during pregnancy without consulting your doctor.** A medicine that worked well for a neighbor may not be suitable for your week of pregnancy or your condition.Paracetamol: The "Savior" of Pregnant Women

The most recommended medication for pain relief and fever reduction during pregnancy is **Paracetamol** (Panadol, Efferalgan, etc.).Why is it considered safe?

Medical research shows that when taken in recommended doses, paracetamol does not negatively affect fetal development. Although it crosses the placenta, it has no toxic effects.When should it be taken?  - **High fever:** A fever above 38°C during pregnancy is more dangerous for the baby than the medication itself. High fever can speed up the fetus''s heart rate and damage protein structures. Therefore, it is **essential** to reduce the fever with paracetamol.
  - **Pain:** Instead of enduring head, tooth, or muscle pain, taking paracetamol is better for reducing stress hormones.Attention: Even though it is safe, it should not be taken "like candy." Use the lowest possible dose for the shortest possible duration.Antibiotics: Friend or Foe?

The idea that "antibiotics are harmful" is deeply rooted in our society. However, untreated infections during pregnancy (e.g., kidney infection, pneumonia, sexual infections) are far riskier for the baby than antibiotics. Infection can lead to premature birth, premature rupture of membranes, and fetal growth restriction.

Doctors prescribe only **safe group** antibiotics to pregnant women:

✅ **Approved Antibiotics:**  - **Penicillin group:** (e.g., Amoxicillin, Ampicillin). This is the most widely used and safest group.
  - **Macrolides:** (e.g., Erythromycin, Azithromycin). Prescribed for those with penicillin allergies.
  - **Cephalosporins:** (e.g., Cephalexin).❌ **Prohibited Antibiotics:**  - **Tetracyclines:** Impair the baby''s bone development and cause permanent yellow staining on teeth.
  - **Streptomycin:** Can damage the fetus''s auditory nerve (risk of deafness).
  - **Chloramphenicol:** Can cause "Gray Baby Syndrome."**Conclusion:** If your doctor has prescribed an antibiotic, it means the benefit far outweighs the risk. Be sure to complete the course.Ibuprofen and Aspirin: Why should we be careful?

One of the most popular medications for headaches, **Ibuprofen (Nurofen)**, and other non-steroidal anti-inflammatory drugs (NSAIDs) are not recommended during pregnancy unless prescribed by a doctor, and **should not be taken after the 20th week**.  - **Risk:** These drugs can cause an important vessel in the baby''s heart (Ductus Arteriosus) to close prematurely, which creates serious heart and lung problems. It can also lead to a decrease in amniotic fluid (oligohydramnios).
  - **Aspirin:** Can only be taken if prescribed by a doctor in a specific dose (e.g., "Cardioaspirin" against the risk of preeclampsia). Self-use as a painkiller creates a risk of bleeding.What to do during Cold and Flu?

"Packet powders" purchased from the pharmacy (Teraflu, Fervex, etc.) during seasonal illnesses are not suitable for pregnant women because they contain vasoconstrictors.

**Safe alternatives:**  - **For nasal congestion:** Sea water sprays (Aquamaris, etc.) are completely safe. Drops containing Xylometazoline can only be used with doctor''s permission for a short period (max. 3 days).
  - **For sore throat:** Gargling with salt water, warm milk, and honey.
  - **For cough:** Herbal syrups (with a doctor''s prescription).Drug Categories in Pregnancy (FDA)

You may come across these letters when reading a medicine box. This is the classification by the US Food and Drug Administration (FDA):  - **Category A:** Tested on humans, completely safe (e.g., Folic acid).
  - **Category B:** Harmless in animals, insufficient research in humans, but considered safe (e.g., Paracetamol, Amoxicillin).
  - **Category C:** Shown negative effects in animals, data in humans is scarce. Used only if benefits outweigh risks.
  - **Category D:** Risk to the human fetus is proven. Used only in life-threatening situations.
  - **Category X:** Strictly prohibited (Teratogenic). Causes serious harm to the fetus.Pregnancy does not mean remaining "defenseless" against illnesses. Modern medicine provides us with enough safe tools to both heal the mother and protect the baby.

If you are hesitant about taking any medication, download the **Anacan app**. You can instantly check the status of hundreds of medicines during pregnancy (Green/Yellow/Red) in the "Safety Lookup" section of the app.

